insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(20001, 2, 201, 1, 'hadith', 'عن أمير المؤمنين أبي حفص عمر بن الخطاب بن نفيل بن عبد العزى بن رياح بن قرط بن رزاح بن عدى بن لؤى ابن غالب القرشى العدوى. رضي الله عنه، قال: سمعت رسول الله صلى الله عليه وسلم يقول: « إنما الأعمال بالنيات، وإنما لكل امرىء ما نوى فمن كانت هجرته إلى الله ورسوله فهجرته إلى الله ورسوله، ومن كانت هجرته لدنيا يصيبها، أو امرأة ينكحها فهجرته إلى ما هاجر إليه».', 'The Messenger of Allah (ﷺ) said, "The deeds are considered by the intentions, and a person will get the reward according to his intention. So whoever emigrated for Allah and His Messenger, his emigration will be for Allah and His Messenger; and whoever emigrated for worldly benefits or for a woman to marry, his emigration would be for what he emigrated for"..', 'أمير المؤمنين أبي حفص عمر بن الخطاب بن نفيل بن عبد العزى بن رياح بن قرط بن رزاح بن عدى بن لؤى ابن غالب القرشى العدوى. رضي الله عنه', '''Umar bin Al-Khattab (May Allah be pleased with him),', 'صحيح', 'رياض الصالحين 1', 'Riyad as-Salihin 1', 'ریاض الصالحین 1', 'متفق على صحته. رواه إماما المحدثين: أبو عبدالله محمد بن إسماعيل بن إبراهيم بن المغيرة بن بَرْدِزْبَهْ الجعفي البخاري، أبو الحسين مسلم بن الحجاج بن مسلم القشيرى النيسابورى رضي الله عنهما في صحيحهما اللذين هما أصح الكتب المصنفة', 'يُبَيِّنُ النبيُّ صلى الله عليه وسلم أنَّ كل الأعمال معتبرة بالنية، وهذا الحكم عام في جميع الأعمال من العبادات والمعاملات، فمن قصد بعمله منفعةً لم يَنَلْ إلا تلك المنفعة ولا ثواب له، ومن قصد بعمله التقرب إلى الله تعالى نال من عمله المثوبة والأجر ولو كان عملًا عاديًّا، كالأكل والشرب.

ثم ضرب صلى الله عليه وسلم مثلًا لبيان تأثير النية في الأعمال مع تساويهما في الصورة الظاهرة، فبَيَّن أنَّ من قصد بهجرته وترك وطنه ابتغاء مرضات ربه، فهجرته هجرة شرعية مقبولة يثاب عليها لصدق نيته، ومن قصد بهجرته منفعةً دنيوية، من مال، أو جاه، أو تجارة، أو زوجة، فلا ينال من هجرته إلا تلك المنفعة التي نواها، ولا نصيب له من الأجر والثواب.', 'الحث على الإخلاص، فإن الله لا يقبل من العمل إلا ما ابتُغي به وجهه.
الأعمال التي يُتَقَرَّبُ بها إلى الله عز وجل إذا فعلها المكلف على سبيل العادة ليس له ثواب عليها، حتى يقصِدَ بها التقرب إلى الله.
النية يفرق بها بين العبادات بعضها عن بعض وأيضًا العبادات عن العادات.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66511', false),
(20002, 2, 201, 2, 'hadith', 'عن أم المؤمنين أم عبد الله عائشة رضي الله عنها قالت: قال رسول الله صلى الله عليه وسلم : "يغزو جيش الكعبة فإذا كانوا ببيداء من الأرض يخسف بأولهم وآخرهم". قالت: قلت: يارسول الله، كيف يخسف بأولهم وآخرهم وفيهم أسواقهم ومن ليس منهم!؟ قال: "يخسف بأولهم وآخرهم، ثم يبعثون على نياتهم".', 'Messenger of Allah (ﷺ) said, "An army will raid the Ka''bah and when it reaches a desert land, all of them will be swallowed up by the earth." She asked; "O Messenger of Allah! Why all of them?" He answered, "All of them will be swallowed by the earth but they will be raised for Judgement according to their intentions.".', 'أم المؤمنين أم عبد الله عائشة رضي الله عنها', 'Narrated ''A''ishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 2', 'Riyad as-Salihin 2', 'ریاض الصالحین 2', 'متفق عليه. هذا لفظ البخاري', 'يخبر صلى الله عليه وسلم عن جيش عظيم يغزو بيت الله الحرام، حتى إذا كانوا في صحراء واسعة خسف الله بهم الأرض، فسألته أم المؤمنين عائشة رضي الله عنها عن الذين جاءوا للبيع والشراء، ليس لهم قصد سيء في غزو الكعبة، وفيهم أناس ليسوا منهم تبعوهم من غير أن يعلموا بخطتهم؛ فأخبرها صلى الله عليه وسلم أنهم سيخسف بهم لأنهم معهم وسيبعثون ويعاملون عند الحساب على نياتهم فيعامل كل بقصده من الخير والشر.', 'الإنسان يعامل بقصده من الخير والشر.
التحذير من مصاحبة أهل الظلم والفجور، والحث على مصاحبة الأخيار.
إخبار النبي -صلى الله عليه وسلم- عما أطلعه الله عليه من المغيبات، وهي مما يجب الإيمان بها كما وردت.', 'ببيداء : البيداء الصحراء؛ سميت بذلك لأنها تُبيد من يحلها؛ أي تهلكه.
الخسف: : الذهاب في الأرض.
أسواقهم : قيل المعنى: أهل أسواقهم.وقيل: السوقة منهم، وهم مَن عدا الحكام.
يبعثون على نياتهم : يبعثهم الله تعالى من قبورهم ويحاسبون على مقاصدهم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4812', false),
(20003, 2, 201, 3, 'hadith', 'عن عائشة رضي الله عنها قالت قال النبي صلى الله عليه وسلم: « لا هجرة بعد الفتح، ولكن جهاد ونية، وإذا استنفرتم فانفروا».', 'A''ishah (May Allah be pleased with her) narrated that the Prophet (ﷺ) said, "There is no emigration after the conquest (of Makkah) but only Jihad ..', 'عائشة رضي الله عنها', null, 'صحيح', 'رياض الصالحين 3', 'Riyad as-Salihin 3', 'ریاض الصالحین 3', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20004, 2, 201, 4, 'hadith', 'عن أبي عبد الله جابر بن عبد الله الأنصارى رضي الله عنهما قال: كنا مع النبي صلى الله عليه وسلم في غزاةٍ فقال: "إن بالمدينة لرجالاً ماسرتم مسيراً، ولا قطعتم وادياً إلا كانوا معكم حبسهم المرض" وفى رواية: "إلا شاركوكم في الأجر" ((رواه مسلم)). ((ورواه البخاري)) عن أنس رضي الله عنه قال: رجعنا من غزوة تبوك مع النبي صلى الله عليه وسلم فقال: " إن أقواماً خلفنا بالمدينة ما سلكنا شعباً ولا وادياً إلا وهم معنا، حبسهم العذر".', 'We accompanied the Prophet (ﷺ) in an expedition when he said, "There are some men in Al-Madinah who are with you wherever you march and whichever valley you cross. They have not joined you in person because of their illness." In another version he said: "They share the reward with you.".It is narrated by Bukhari from Anas bin Malik (May Allah be pleased with him): We were coming back from the battle of Tabuk with the Prophet (ﷺ) when he remarked, "There are people whom we left behind in Al- Madinah who accompanied us in spirit in every pass and valley we crossed. They remained behind for a valid excuse."', 'أبي عبد الله جابر بن عبد الله الأنصارى رضي الله عنهما', 'Jabir bin Abdullah Al-Ansari (May Allah be pleasedwith them)', 'صحيح', 'رياض الصالحين 4', 'Riyad as-Salihin 4', 'ریاض الصالحین 4', null, 'يخبر صلى الله عليه وسلم عن رجال ما حبسهم عن الجهاد في سبيل الله عز وجل إلا المرض ونحوه من الأعذار، فيخبر أنه ما سار الغُزاة سيرا ولا قطعوا واديا ولا شِعبا إلا وكُتِبَ لهؤلاء ثواب ذلك العمل.', 'من حبسه العذر كان كأولي الضرر.
أن من صحت نيته، وعزم على فعل عمل صالح وتركه لعذر، أن له مثل أجر فاعله.
ليس على أولي الضرر كالأعمى والمريض حرج.', 'غزاة : غزوة.
مسيرا : أي: سيرا أو في مكان سير.
قطعتم واديا : سلكتموه.
واديا : الوادي: مفرج ما بين جبال أو تلال أو آكام
حبسهم : منعهم.
شركوكم : شاركوكم.
الأجر : الثواب.
شِعْبًا : الطريق في الجبل.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4557', false),
(20005, 2, 201, 5, 'hadith', 'عن أبي يزيد معن بن يزيد بن الأخنس رضي الله عنهم، وهو وأبوه وجده صحابيون، قال: كان أبي يزيد أخرج دنانير يتصدق بها فوضعها عند رجل في المسجد فجئت فأخذتها فأتيته بها، فقال: والله ما إياك أردت، فخاصمته إلى رسول الله صلى الله عليه وسلم فقال: « لك ما نويت يا يزيد، ولك ما أخذت يامعن».', 'My father set aside some dinars for charity and gave them to a man in the mosque. I went to that man and took back those dinars. He said: "I had not intended you to be given." So we went to Messenger of Allah (ﷺ), and put forth the matter before him. He said to my father, "Yazid, you have been rewarded for what you intended." And he said to me, "Ma''n, you are entitled to what you have taken.".', 'أبي يزيد معن بن يزيد بن الأخنس رضي الله عنهم', 'Ma''n bin Yazid bin Akhnas (May Allah be pleased with them) (he, his father and his grandfather, all were Companions)', 'صحيح', 'رياض الصالحين 5', 'Riyad as-Salihin 5', 'ریاض الصالحین 5', 'رواه البخاري', 'أخرج يزيد بن الأخنس دراهم عند رجل في المسجد؛ ليتصدق بها على الفقراء، فجاء ابنه معن فأخذها، فقال له: ما أردتُ أن أتصدق بهذه الدراهم عليك، فذهبا ليتحاكما إلى رسول الله صلى الله عليه وسلم ، فقال النبي صلى الله عليه وسلم : "لك يا يزيد ما نويتَ لأنك أوصلت الصدقة إلى فقير من فقراء المسلمين فوجب لك الأجر على نيتك، ولك يا معن ما أخذت" لأنك أخذته بوجه صحيح وقد كان ابنه من المستحقين لهذه الصدقة.', 'جواز دفع صدقة التطوع للأبناء.
جواز التوكيل في توزيع الصدقة.
جواز التحدث بنعم الله -تعالى-.
جواز التحاكم بين الأب والابن وأن ذلك لا يُعد عقوقا.
للمتصدق أجر ما نواه سواء صادف المستحق أم لا.
لا يحق للأب الرجوع في الصدقة على ولده بخلاف الهبة.', 'فأخذتها : من الرجل المأذون له في التصدق بها بإذنه لا بطريق الاعتداء.
فأتيته : أتيت أبي بالدنانير المذكورة.
فخاصمته : فتحاكمت وإياه.
لك ما نويت : أي: لك ثوابه؛ لأنك نويت الصدقة على محتاج، وابنك محتاج وإن لم تقصده.
ولك ما أخذت : لك مِلك ما أخذت؛ لأنك قبضته بطريق صحيح شرعي.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4719', false),
(20006, 2, 201, 6, 'hadith', 'عن أبي إسحاق سعد بن أبي وقاص مالك بن أهيب بن عبد مناف بن زهرة بن كلاب بن مرة بن كعب بن لؤى القرش الزهرى رضي الله عنه، أحد العشرة المشهود لهم بالجنة، رضي الله عنهم، قال: « جاءنى رسول الله صلى الله عليه وسلم يعودنى عام حجة الوداع من وجع اشتد بى فقلت: يارسول الله إني قد بلغ بى من الوجع ما ترى، وأنا ذو مال ولا يرثنى إلا ابنة لي، أفاتصدق بثلثى ما لي؟ قال: لا، قلت: فالشطر يارسول الله؟ فقال: لا، قلت: فالثلث يا رسول الله؟ قال الثلث والثلث كثير- أو كبير- إنك أن تذر ورثتك أغنياء خير من أن تذرهم عالة يتكففون الناس، وإنك لن تنفق نفقة تبتغى بها وجه الله إلا أجرت عليها حتى ما تجعل في فيّ امرأتك قال: فقلت: يارسول الله أخلف بعد أصحابي؟ قال: إنك لن تخلف فتعمل عملا تبتغي بهوجه الله إلا ازددت به درجة ورفعةً، ولعلك أن تخلف حتى ينتفع بك أقوام ويضرّ بك آخرون. اللهم امض لآصحابى هجرتهم، ولا تردهم على أعقابهم، لكن البائس سعد بن خولة» يرثى له رسول الله صلى الله عليه وسلم أن مات بمكة.', 'Messenger of Allah (ﷺ) visited me in my illness which became severe in the year of Hajjat-ul-Wada'' (Farewell Pilgrimage). I said, "O Messenger of Allah, you can see the pain which I am suffering and I am a man of means and there is none to inherit from me except one daughter. Should I give two-thirds of my property in charity?" He (ﷺ) said, "No". I asked him, "Then half?" He said, "No". Then I asked, "Can I give away one-third". He said, "Give away one-third, and that is still too much. It is better to leave your heirs well-off than to leave them poor, begging people. You will not expend a thing in charity for the sake of Allah, but you will be rewarded for it; even the morsel of food which you feed your wife". I said, "O Messenger of Allah, would I survive my companions?" He said, "If you survive others and accomplish a thing for the sake of Allah, you would gain higher ranking and standing. You will survive them ... your survival will be beneficial to people (the Muslim) and harmful to others (the enemies of Islam). You will survive others till the people will derive benefit from you, and others would be harmed by you." Messenger of Allah (ﷺ) further said, "O Allah, complete for my Companions their emigration and do not cause them to retract." Sa''d bin Khaulah was unfortunate. Messenger of Allah (ﷺ) lamented his death as he died in Makkah..', 'أبي إسحاق سعد بن أبي وقاص مالك بن أهيب بن عبد مناف بن زهرة بن كلاب بن مرة بن كعب بن لؤى القرش الزهرى رضي الله عنه', 'Abu Ishaq Sa''d bin Abu Waqqas (May Allah be pleased with him) (one of the ten who had been given the glad tidings of entry into Jannah)', 'صحيح', 'رياض الصالحين 6', 'Riyad as-Salihin 6', 'ریاض الصالحین 6', 'متفق عليه', 'مرض سعد بن أبي وقاص -رضى الله عنه- في حجة الوداع مرضًا شديدًا خاف من شدته الموت، فعاده النبي صلى الله عليه وسلم كعادته في تفقد أصحابه ومواساته إياهم، فذكر سعد للنبي صلى الله عليه وسلم من الدواعي، ما يعتقد أنها تسوغ له التصدق بالكثير من ماله، فقال: يا رسول الله، إنني قد اشتد بي الوجع الذي أخاف منه الموت، وإني صاحب مال كثير، وإنه ليس من الورثة الضعفاء الذين أخشى عليهم العيلة والضياع إلا ابنة واحدة، فبعد هذا هل أتصدق بثلثي مالي، لأقدمه لصالح عملي؟ فقال النبي صلى الله عليه وسلم : لا. قال: فالشطر يا رسول الله؟ قال: لا. قال: فالثلث؟ فقال: لا مانع من التصدق بالثلث مع أنه كثير. فالنزول إلى ما دونه من الربع والخمس أفضل. ثم بين له النبي صلى الله عليه وسلم الحكمة في النزول في الصدقة من أكثر المال إلى أقله بأمرين:
1- وهو أنه إن مات وقد ترك ورثته أغنياء منتفعين ببره وماله فذلك خير من أن يخرجه منهم إلى غيرهم، ويدعهم يعيشون على إحسان الناس.
2- وإما أن يبقى ويجد ماله، فينفقه في طرقه الشرعية، ويحتسب الأجر عند الله فيؤجر على ذلك، حتى في أوجب النفقات عليه وهو ما يطعمه زوجه.
ثم خاف سعد بن أبي وقاص أن يموت بمكة التي هاجر منها وتركها لوجه الله تعالى، فينقص ذلك من ثواب هجرته، فأخبره النبي صلى الله عليه وسلم أنه لن يخلف قهرا في البلد التي هاجر منها، فيعمل فيه عملا ابتغاء ثواب الله إلا ازداد به درجة، ثم بشره صلى الله عليه وسلم بما يدل على أنه سيبرأ من مرضه، وينفع الله به المؤمنين، ويضر به الكافرين، فكان كما أخبر الصادق المصدوق، فقد بريء من مرضه، وصار القائد الأعلى في حرب الفرس، فنفع الله به الإسلام والمسلمين، وفتح الفتوح وضر به الله الشرك والمشركين، ثم دعا النبي صلى الله عليه وسلم لعموم أصحابه أن يحقق لهم درجتهم، وأن يقبلها منهم، وألا يردهم عن دينهم أو إلى البلاد التي هاجروا منها، فقبل الله منه ذلك، وله الحمد والمنة، والحمد لله الذي أعز بهم الإسلام.
ثم ذكر سعد بن خولة، وهو من المهاجرين الذين هاجروا من مكة ولكن الله قدر أن يموت فيها؛ فمات فيها، فرثى له النبي -عليه الصلاة والسلام-؛ أي: توجع له أن مات بمكة؛ وقد كانوا يكرهون للمهاجر أن يموت في الأرض التي هاجر منها.', 'استحباب عيادة المريض، وتتأكد لمن له حق من قريب وصديق ونحوهما.
جواز إخبار المريض بمرضه، وبيان شدته إذا لم يقصد التشكي والسخط، وينبغي ذكره للفائدة، كطبيب يعينه على تشخيص مرضه أو مسعف يتسبب له العلاج.
استشارة العلماء واستفتاؤهم في سائر أموره.
إباحة جمع المال إذا كان من طرقه المشروعة.
استحباب الوصية وأن تكون بالثلث من المال فأقل ولو ممن هو صاحب مال كثير.
الأفضل أن يكون بأقل من الثلث ، وذلك لحق الورثة.
أن إبقاء المال للورثة -مع حاجتهم إليه- أحسن من التصدق به على البعداء لكون الوارث أولى ببره من غيره.
أن النفقة على الأولاد والزوجة عبادة جليلة مع النية الحسنة.
أن من هاجر من بلد لوجه الله تعالى ولإعلاء كلمته، فلا يرجع إليها للإقامة، فإن أقام بغير قصده، فلا حرج عليه.
في الحديث معجزة النبي -صلى الله عليه وسلم- حيث أشار إلى أن سعدا سيبرأ من مرضه وينتفع به أناس، ويضر آخرون، فكان كما قال، حيث فتح بلاد فارس وعز به المسلمون، وانضر به المشركون، الذين ماتوا على شركهم.
أن الله كمل للصحابة هجرتهم من مكة إلى المدينة، بسبب عزمهم الصادق، ودعوات النبي -صلى الله عليه وسلم- المباركات.', 'يعودني : يزورني.
وجع : مرض.
اشتد بي : قوي علي.
فالشطر : النصف.
والثلث كثير : فالأولى أن ينقص عن الثلث ولا يزاد عليه.
أن تذر : تترك.
عالة : جمع "عائل" و "العالة" الفقراء.
يتكففون الناس : يسألون الناس بأكفهم أي أيديهم.
في في امرأتك : في فم زوجتك.
أخلف بعد أصحابي : المنصرفين من مكة لأجل مرضي وكانوا يكرهون الإقامة بمكة لأنهم هاجروا منها وتركوها لله.
أمض : أتمم.
ولا تردهم على أعقابهم : بتركهم هجرتهم ورجوعهم عن استقامتهم.
البائس : الشديد الحاجة.
يرثي : يتوجع ويحزن.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5885', false),
(20007, 2, 201, 7, 'hadith', 'عن أبي هريرة عبد الرحمن بن صخر رضي الله عنه قال قال رسول الله صلى الله عليه وسلم: « إن الله لا ينظر إلى أجسامكم ، ولا إلى صوركم، ولكن ينظر إلى قلوبكم وأعمالكم».', 'Messenger of Allah (ﷺ) said, "Allah does not look at your figures, nor at your attire but He looks at your hearts and accomplishments"..', 'أبي هريرة عبد الرحمن بن صخر رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 7', 'Riyad as-Salihin 7', 'ریاض الصالحین 7', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20008, 2, 201, 8, 'hadith', 'عن أبي موسى عبد الله بن قيس الأشعرى رضي الله عنه قال: سئل رسول الله صلى الله عليه وسلم عن الرجل يقاتل شجاعة، ويقاتل حميةً، ويقاتل رياء، أى ذلك في سبيل الله؟ فقال رسول الله صلى الله عليه وسلم: « من قاتل لتكون كلمة الله هى العليا فهو في سبيل الله».', '"He who fights in order that the Word of Allah remains the supreme, is considered as fighting in the cause of Allah"..', 'أبي موسى عبد الله بن قيس الأشعرى رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him) reported that Messenger of Allah (ﷺ) was asked about who fights in the battlefield out of valour, or out of zeal, or out of hypocrisy, which of this is considered as fighting in the cause of Allah? He said:', 'صحيح', 'رياض الصالحين 8', 'Riyad as-Salihin 8', 'ریاض الصالحین 8', 'متفق عليه', 'سُئلَ النبيُّ صلى الله عليه وسلم عن اختلاف مقاصد المقاتلين؛ مَن قاتَل شجاعة أو حَميَّة أو ليرى مكانه من الناس أو غير ذلك، أيُّها في سبيل الله؟ 
فأخبرَ النبيُّ صلى الله عليه وسلم أن المقاتل في سبيل الله هو: مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللهِ هِيَ الْعُلْيَا.', 'الأصل في صلاح الأعمال وفسادها النية وإخلاص العمل لله.
إذا كان القصد من الجهاد إعلاء كلمة الله، وانضم إليه قصد آخر مشروع كالحصول على المغنم، فإنه لا يضر أصلَ نيته.
مدافعة الأعداء عن الأوطان والحرمات من القتال في سبيل الله.
الفضل الوارد في المجاهدين يختص بمن قاتل لتكون كلمة الله تعالى هي العليا.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/2969', false),
(20009, 2, 201, 9, 'hadith', 'عن أبي بكرة نفيع بن الحارث الثقفى رضي الله عنه أن النبي صلى الله عليه وسلم قال: "إذ التقى المسلمان بسيفيهما فالقاتل والمقتول في النار" قلت يارسول الله، هذا القاتل فما بال المقتول؟ قال: "إنه كان حريصاً على قتل صاحبه".', 'The Prophet (ﷺ) said: "When two Muslims are engaged in a combat against each other with their sword''s and one is killed, both are doomed to Hell". I said, "O Messenger of Allah! As to the one who kills, it is understandable, but why the slain one?" He (ﷺ) replied: "He was eager to kill his opponent"..', 'أبي بكرة نفيع بن الحارث الثقفى رضي الله عنه', 'Abu Bakrah Ath-Thaqafi (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 9', 'Riyad as-Salihin 9', 'ریاض الصالحین 9', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20010, 2, 201, 10, 'hadith', 'عن أبي هريرة رضي الله عنه قال رسول الله صلى الله عليه وسلم : «صلاة الرجل في جماعة تزيد على صلاته في سوقه وبيته بضعاً وعشرين درجه وذلك أن أحدهم إذا توضأ فأحسن الوضوء ثم أتى المسجد لا يريد إلا الصلاة، لا ينهزه إلا الصلاة، لم يخط خطوة إلا رفع له بها درجة، وحط عنه بها خطيئة حتى يدخل المسجد، فإذا دخل المسجد كان في الصلاة ما كانت الصلاة هى تحبسه، والملائكة يصلون على أحدكم ما دام في مجلسه الذى صلى فيه، ما لم يحدث فيه» ((متفق عليه، وهذا لفظ مسلم)). وقوله صلى الله عليه وسلم: '' ينهزه هو بفتح الياء والهاء وبالزاى: أى يخرجه وينهضه ''', 'The Messenger of Allah (ﷺ) said: "The reward for Salat performed by a person in congregation is more than 20 times greater than that of the Salat performed in one''s house or shop. When one performs Wudu'' perfectly and then proceeds to the mosque with the sole intention of performing Salat, then for every step he takes towards the mosque, he is upgraded one degree in reward and one of his sins is eliminated until he enters the mosque, and when he enters the mosque, he is considered as performing Salat as long as it is the Salat which prevents him (from leaving the mosque); and the angels keep on supplicating Allah for him as long as he remains in his place of prayer. They say: ''O Allah! have mercy on him; O Allah! forgive his sins; O Allah! accept his repentance''. This will carry on as long as he does not pass wind"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) reported that:', 'صحيح', 'رياض الصالحين 10', 'Riyad as-Salihin 10', 'ریاض الصالحین 10', null, 'يُخْبِرُ النبيُّ صلى الله عليه وسلم أنه إذا صَلَّى المسلم في جماعةٍ، كانت صلاتُه تلك أفضلَ مِن صلاتِهِ في بيتِهِ أو سوقِه بضعًا وعشرين مَرّة. 
ثم ذَكَرَ السبب في ذلك: وهو أنَّ الرجل إذا توضأ فأتمَّ الوضوءَ وأحسنَه، ثم خرج إلى المسجد لا يُخرجه إلا إرادة الصلاة، لم يَخْطُ خُطوةً إلا رُفع له بها مرتبة ومنزلة، ومُحِيَ عنه بها خطيئة، 
فإذا دخل المسجد وجلس ينتظر الصلاة، فإنه يأخذ أجرَ الصلاة وثوابَها ما انتظر الصلاة، والملائكة تدعو له ما دام في مجلسه الذي صلى فيه، تقول: 
"اللهم اغفر له، اللهم ارحمه، اللهم تُبْ عليه" ما لم يُفسِدْ وضوءَه، أو يفعل ما يتأذى به الناس أو الملائكة.', 'صلاةُ المنفرد في بيتِه أو سوقِه صحيحةٌ، ولكنه يأثمُ لترك الجماعة بلا عذر.
صلاة الجماعة في المسجد أفضل من صلاة الإنسان منفردًا بخمس أو ست أو سبع وعشرين درجة.
من وظائف الملائكة الدعاء للمؤمنين.
فضل الذهاب للمسجد متوضئًا.', 'بِضعا: البضع: من الثلاثة إلى العشرة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4566', false),
(20011, 2, 201, 11, 'hadith', 'عن أبي العباس عبد الله بن عباس بن عبد المطلب رضي الله عنهما، عن رسول الله، صلى الله عليه وسلم، فيما يروى عن ربه، تبارك وتعالى قال: « إن الله كتب الحسنات والسيئات ثم بين ذلك: فمن همّ بحسنة فلم يعملها كتبها الله تبارك وتعالى عنده حسنة كاملة، وإن هم بها فعملها كتبها الله عشر حسنات إلى سبعمائه ضعف إلى أضعاف كثيرة، وإن هم بسيئة فلم يعملها كتبها الله عنده حسنة كاملة، وإن همّ بها فعملها كتبها الله سيئة واحدة ».', 'Messenger of Allah (ﷺ) said that Allah, the Glorious, said: "Verily, Allah (SWT) has ordered that the good and the bad deeds be written down. Then He explained it clearly how (to write): He who intends to do a good deed but he does not do it, then Allah records it for him as a full good deed, but if he carries out his intention, then Allah the Exalted, writes it down for him as from ten to seven hundred folds, and even more. But if he intends to do an evil act and has not done it, then Allah writes it down with Him as a full good deed, but if he intends it and has done it, Allah writes it down as one bad deed"..', 'أبي العباس عبد الله بن عباس بن عبد المطلب رضي الله عنهما', '''Abdullah bin ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 11', 'Riyad as-Salihin 11', 'ریاض الصالحین 11', 'متفق عليه', 'يُبَيِّنُ الرسولُ صلى الله عليه وسلم أنَّ الله قَدَّر الحسناتِ والسيئاتِ ثم بَيَّنَ للمَلَكين كيف يكتبانها: فمَن أراد وقصد وعَزَم على فعل الحسنة كُتبتْ له حسنة واحدة وإن لم يعملْها، فإن عَمِلها فإنها تُضاعف بعشر أمثالها إلى سبعمائة ضِعفٍ إلى أضعاف كثيرة، والزيادة بحسب ما في القلب من الإخلاص وتَعَدِّي النَّفْع ونحو ذلك. ومَن أراد وقصد وعزم على فعل السيئة ثم تَرَكها لله كُتبت له حسنة، وإن تركها تشاغلًا عنها مع عدم فعل أسبابها لم تُكتب شيئًا، وإن تركها عَجزًا عنها كُتبتْ عليه نِيَّتُه، وإن عملها كُتبت له سيئة واحدة.', 'هذا الحديث مما يرويه النبي صلى الله عليه وسلم عن ربه، ويسمى بالحديث القدسي أو الإلهي، وهو الذي لفظه ومعناه من الله، غير أنه ليست فيه خصائص القرآن التي امتاز بها عما سواه ، من التعبد بتلاوته والطهارة له والتحدي والإعجاز وغير ذلك.
إثبات كتابة الله تعالى الحسنات والسيئات، ثم بيانه ذلك لعباده حتى يعلموا ذلك، ويكونوا على بصيرة من أمرهم، فيمتثلوا أمره ويجتنبوا نهيه على هدى من ربّهم.
بيانُ فضل الله تعالى العظيم على هذه الأمة في كتابة الحسنات ومضاعفتها، وعدم كتابة السيئات إلا بعد فعلها وكتابتها سيئة واحدة.
الزيادة في مضاعفة الحسنات بحسب ما في القلب من الإخلاص وتَعَدِّي النَّفْع ونحو ذلك، فيضاعفها الله برحمته وفضله.
بيان الفضل الذي يترتب للعبد على ترك السيئة وهِجران لذته، وترك شهوته من أجل ربه عز وجل رغبةً في ثوابه، ورهبةً من عقابه.
من لطف الله تعالى بالأمة أن ضاعف لها حسناتها ولم يضاعف سيئاتها.
كتابة الملائكة لجميع الأعمال من أعمال القلوب والجوارح.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66533', false),
(20012, 2, 201, 12, 'hadith', 'عن أبي عبد الرحمن عبد الله بن عمر بن الخطاب، رضي الله عنهما قال: سمعت رسول الله صلى الله عليه وسلم يقول: " انطلق ثلاثة نفر ممن كان قبلكم حتى آواهم المبيت إلى غار فدخلوه، فانحدرت صخرة من الجبل فسدت عليهم الغار، فقالوا: إنه لا ينجيكم من هذه الصخرة إلا أن تدعوا الله بصالح أعمالكم. قال رجل منهم: اللهم كان لي أبوان شيخان كبيران، وكنت لا أغبق قبلهما أهلاً ولا مالاً. فنأى بى طلب الشجر يوماً فلم أرح عليهما حتى ناما فحلبت لهما غبوقهما فوجدتهما نائمين فكرهت أن أوقظهما وأن أغبق قبلهما أهلاً أو مالاً، فلبثت- والقدح على يدى- أنتظر استيقاظهما حتى برق الفجر والصبية يتضاغون عند قدمى- فاستيقظا فشربا غبوقهما. اللهم إن كنت فعلت ذلك ابتغاء وجهك ففرج عنا ما نحن فيه من هذه الصخرة، فانفرجت شيئاً لا يستطيعون الخروج منه. قال الآخر: اللهم إنه كانت لي ابنة عم كانت أحب الناس إلىّ " وفى رواية: "كنت أحبها كأشد ما يحب الرجال النساء، فأردتها على نفسها فامتنعت منى حتى ألمّت بها سنة من السنين فجاءتنى فأعطيتها عشرين ومائة دينار على أن تخلى بينى وبين نفسها ففعلت، حتى إذا قدرت عليها" وفى رواية: "فلما قعدت بين رجليها، قالت: اتق الله ولا تفض الخاتم إلا بحقه، فانصرفت عنها وهى أحب الناس إلى وتركت الذهب الذى أعطيتها، اللهم إن كنت فعلت ذلك ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرة غير أنهم لا يستطيعون الخروج منها. وقال الثالث: اللهم استأجرت أجراء وأعطيتهم أجرهم غير رجل واحد ترك الذى له وذهب، فثمرت أجره حتى كثرت منه الأموال، فجاءنى بعد حين فقال: يا عبد الله أدّ إلى أجرى، فقلت: كل ما ترى من أجرك: من الإبل والبقر والغنم والرقيق. فقال: يا عبد الله لا تستهزئ بى! فقلت: لا أستهزئ بك، فأخذه كله فاستاقه فلم يترك منه شيئاً، اللهم إن كنتُ فعلت ذلك ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرة فخرجوا يمشون".', 'He heard Messenger of Allah (ﷺ) as saying: "Three men, amongst those who came before you, set out until night came and they reached a cave, so they entered it. A rock fell down from the mountain and blocked the entrance of the cave. They said: ''Nothing will save you from this unless you supplicate to Allah by virtue of a righteous deed you have done.'' Thereupon, one of them said: ''O Allah! I had parents who were old, and I used to offer them milk before any of my children or slaves. One day, I went far away in search of grazing and could not come back until they had slept. When I milked as usual and brought the drink I found them both asleep. I hated to disturb them and also disliked to give milk to my children before them. My children were crying out of hunger at my feet but I awaited with the bowl in my hand for them to wake up. When they awoke at dawn, they drank milk. O Allah! If I did so to seek Your Pleasure, then deliver us from the distress caused by the rock''. The rock moved slightly but they were unable to escape. The next said: ''O Allah! I had a cousin whom I loved more than any one else (in another version he said: as a man can love a woman). I wanted to have sexual intercourse with her but she refused. Hard pressed in a year of famine, she approached me. I gave her one hundred and twenty dinars on condition that she would yield herself to me. She agreed and when we got together (for sexual intercourse), she said: Fear Allah and do not break the seal unlawfully. I moved away from her in spite of the fact that I loved her most passionately; and I let her keep the money I had given her. O Allah! If I did that to seek Your Pleasure, then, remove the distress in which we are.'' The rock moved aside a bit further but they were still unable to get out. The third one said: ''O Allah! I hired some labourers and paid them their wages except one of them departed without taking his due. I invested his money in business and the business prospered greatly. After a long time, he came to me and said: O slave of Allah! Pay me my dues. I said: All that you see is yours - camels, cattle, goats and slaves. He said: O slave of Allah! Do not mock at me. I assured him that I was not joking. So he took all the things and went away. He spared nothing. O Allah! If I did so seeking Your Pleasure, then relieve us of our distress.'' The rock slipped aside and they got out walking freely"..', 'أبي عبد الرحمن عبد الله بن عمر بن الخطاب رضي الله عنهما', '''Abdullah bin ''Umar bin Al-Khattab (May Allah be pleased with them) narrated that:', 'صحيح', 'رياض الصالحين 12', 'Riyad as-Salihin 12', 'ریاض الصالحین 12', 'متفق عليه', 'انطلق ثلاثة رجال، فدفعهم طلب البيات إلى أن يلجأوا إلى الكهف، فانحدَرَتْ صخرةٌ من الجبل فسَدَّتْ عليهم الكهف، ولم يستطيعوا أن يزحزحوها؛ لأنها صخرة كبيرة، فرأوا أن يتوسلوا إلى الله سبحانه وتعالى بصالح أعمالهم.
أما الأول فذكر أن له أبوين شيخين كبيرين وكان له غنم، فكان يسرح فيها ثم يرجع في آخر النهار، ويحلب الغنم، ويعطي أبويه- الشيخين الكبيرين- ثم يعطي بقية أهله وماله، فيقول: بعد بي طلب الشجر الذي يرعاه. فرجع، فوجد أبويه قد ناما، فنظر، هل يسقي أهله وماله قبل أبويه، أو ينتظر حتى برق الفجر، فاختار أن ينتظر حتى يطلع الفجر -وهو ينتظر استيقاظ أبويه-، فلما استيقظا وشربا اللبن سقى أهله وماله، ثم قال: اللهم إن كنت مخلصاً في عملي هذا- فعلته من أجلك- فافرج عنا ما نحن فيه، انفرجت الصخرة، لكن انفراجًا لا يستطيعون الخروج منه.
أما الثاني: فتوسل إلى الله عز وجل بالعفة التامة، وذلك أنه كان له ابنة عم، وكان يحبها حبًّا شديدًا كأشد ما يحب الرجال النساء "فأرادها على نفسها"، أي أرادها- والعياذ بالله- بالزنا؛ ليزني بها، ولكنها لم توافق وأبت، ثم أصابها فقر وحاجة فاضطرت إلى أن تجود بنفسها في الزنا من أجل الضرورة، وهذا لا يجوز، ولكن على كل حال، هذا الذي حصل، فجاءت إليه، فأعطاها مائة وعشرين دينارا من أجل أن تمكنه من نفسها، ففعلت من أجل الحاجة والضرورة، فلما جلس منها مجلس الرجل من امرأته على أنه يريد أن يفعل بها، قالت له هذه الكلمة العجيبة العظيمة: "اتق الله، ولا تفض الخاتم إلا بحقه"، فقام عنها وهي أحب الناس إليه، لكن أدركه خوف الله عز وجل وترك لها الذهب الذي أعطاها، ثم قال: "اللهم إن كنت فعلت هذا لأجلك فافرج عنا ما نحن فيه، فانفرجت الصخرة، إلا أنهم لا يستطيعون الخروج".
وأما الثالث: فتوسل إلى الله سبحانه وتعالى بالأمانة والإصلاح والإخلاص في العمل، فإنه يذكر أنه استأجر أجراء على عمل من الأعمال، فأعطاهم أجورهم، إلا رجلًا واحدًا ترك أجره فلم يأخذه، فقام هذا المستأجر فثمر المال، فصار يتكسب به بالبيع والشراء وغير ذلك، حتى نما وصار منه إبل وبقر وغنم ورقيق وأموال عظيمة. فجاءه بعد حين، فقال له: يا عبد الله أعطني أجري، فقال له: كل ما ترى فهو لك، من الإبل والبقر والغنم والرقيق، فقال: لا تستهزئ بي، الأجرة التي لي عندك قليلة، كيف لي كل ما أرى من الإبل والبقر والغنم والرقيق؟ لا تستهزيء بي. فقال: هو لك، فأخذه واستاقه كله ولم يترك له شيئًا، ثم قال: "اللهم إن كنت فعلت ذلك من أجلك فافرج عنا ما نحن فيه، فانفرجت الصخرة، وانفتح الباب، فخرجوا يمشون"؛ لأنهم توسلوا إلى الله بصالح أعمالهم التي فعلوها إخلاصاً لله عز وجل .', 'استحباب الدعاء وقت الكرب وغيره، والتوسل إلى الله -تعالى- بصالح العمل.
فضيلة بر الوالدين وفضل خدمتهما وإيثارهما على من سواهما من الولد والزوجة.
الحض على العفاف عن المحرمات، ولا سيما بعد القدرة عليها، وترك ذلك لله -تعالى- خالصًا.
فضل حسن العهد وأداء الأمانة، والسماحة في المعاملة.
استجابة دعاء من توجه إلى الله -تعالى- بصدق وإخلاص في الشدائد، ولا سيما من سبق له عمل صالح.
إثبات كرامات أولياء الله الصالحين.', 'نفر : ما بين الثلاثة إلى العشرة.
آواهم المبيت إلى غار : أي دفعهم طلب البيات إلى أن يلجأوا إلى الغار.والغار: الكهف.
لا أغبق : الغَبوق: شرب اللبن وقت العشاء.
فنأى بي طلب الشجر : نأى: بعد، والمراد: أنه بعد به طلب الشجر لغنمه عن المكان الذي اعتاده.
فلم أُرِح عليهما : فلم أرجع إليهما.
القَدَح : إِنَاء يشرب بِهِ المَاء ونَحْوه.
برق الفجر : طلع وظهر.
يتضاغَون : يصيحون ويستغيثون من الجوع.
ابتغاء وجهك : طلبا لرضاك بإخلاص وتجرد.
ففرج : دعاء من التفريج؛ أي: افتح.
فأردتها : كناية عن طلب الجماع، والمراد الزنا.
ألمت : نزلت.
السنة : الجدب والفقر.
قدرت عليها : تمكنت من الوقاع بها من غير معارض.
لا تفض : الفض: الكسر والفتح.
الخاتم : كناية عن البكارة.
إلا بحقه : بزواج مشروع.
فثمرت أجره : كثرت أجره بتنميته حتى أصبح مالا كثيرا.
أغبق أهلا : أسقيهم الغبوق.
ولا مالا : أي: من رقيق وخدم.ويُحتمل المال: الإبل، يعني: يُرضع صغارها من أمهاتها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6465', false),
(20013, 2, 201, 13, 'hadith', 'عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «والله إني لأستغفر الله وأتوب إليه في اليوم أكثر من سبعين مرة ».', 'I heard Messenger of Allah (ﷺ) saying: "By Allah, I seek Allah''s forgiveness and repent to Him more than seventy times a day.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 13', 'Riyad as-Salihin 13', 'ریاض الصالحین 13', 'رواه البخاري', 'النبي صلى الله عليه وسلم الذي غفر الله له ما تقدم من ذنبه وما تأخر: يقسم أنه يستغفر الله ويتوب إليه في اليوم أكثر من سبعين مرة، واستغفار النبي صلى الله عليه وسلم لا يلزم أن يكون لذنوب ارتكبها ولكن ذلك لكمال عبوديته وتعلقه بذكره سبحانه ، واستشعاره عظم حق الله تعالى وتقصير العبد مهما عمل في شكر نعمه، وهو من باب التشريع للأمة من بعده، إلى غير ذلك من الحكم.', 'جواز القسم على الشيء تأكيدا له، وإن لم يكن عند السامع فيه شك.
حض الأمة على التوبة والاستغفار اقتداء بالنبي -صلى الله عليه وسلم-؛ فإنه -صلى الله عليه وسلم- مع كونه معصوما، وخير الخلق، وقد غفر له ما تقدم من ذنبه وما تأخر، يستغفر الله ويتوب إليه في اليوم أكثر من سبعين مرة.
الإكثار من الاستغفار والتوبة؛ فإن العبد لا ينفك عن ذنب أو تقصير.
استغفار النبي -صلى الله عليه وسلم- لا يلزم أن يكون لذنوب ارتكبها ولكن ذلك لكمال عبوديته وتعلقه بذكره -سبحانه-، واستشعاره عظم حق الله -تعالى- وتقصير العبد مهما عمل في شكر نعمه، وهو من باب التشريع للأمة من بعده، إلى غير ذلك من الحكم.', 'أستغفر : أي: أطلب المغفرة، وهي الصفح عن الذنب.
وأتوب إليه : أي: أعزم على التوبة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4808', false),
(20014, 2, 201, 14, 'hadith', 'عن الأغر بن يسار المزنى رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: « ياأيها الناس توبوا إلى الله واستغفروه فإنى أتوب في اليوم مائه مرة».', 'The Messenger of Allah (ﷺ) said: "Turn you people in repentance to Allah and beg pardon of Him. I turn to Him in repentance a hundred times a day"..', 'الأغر بن يسار المزنى رضي الله عنه', 'Al-Agharr bin Yasar Al-Muzani (May Allah be pleased with him) narrated that:', 'صحيح', 'رياض الصالحين 14', 'Riyad as-Salihin 14', 'ریاض الصالحین 14', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20015, 2, 201, 15, 'hadith', 'عن أبي حمزة أنس بن مالك الأنصارى خادم رسول الله صلى الله عليه وسلم، رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : " لله أفرح بتوبة عبده من أحدكم سقط على بعيره وقد أضله في أرض فلاة " ((متفق عليه)). وفى رواية لمسلم: لله أشد فرحا بتوبة عبده حين يتوب إليه من أحدكم كان على راحلته بأرض فلاة، فانفلتت منه وعليها طعامه وشرابه فأيس منها، فأتى شجرة فاضطجع في ظلها، وقد أيس من راحلته، فبينما هو كذلك إذا هو بها، قائمة عنده ، فأخذ بخطامها ثم قال من شدة الفرح: اللهم أنت عبدي وأنا ربك، أخطأ من شدة الفرح".', 'Messenger of Allah (ﷺ) said, "Verily, Allah is more delighted with the repentance of His slave than a person who lost his camel in a desert land and then finds it (unexpectedly)"..In another version of Muslim, he said: "Verily, Allah is more pleased with the repentance of His slave than a person who has his camel in a waterless desert carrying his provision of food and drink and it is lost. He, having lost all hopes (to get that back), lies down in shade and is disappointed about his camel; when all of a sudden he finds that camel standing before him. He takes hold of its reins and then out of boundless joy blurts out: ''O Allah, You are my slave and I am Your Rubb''.He commits this mistake out of extreme joy".', 'أبي حمزة أنس بن مالك الأنصارى خادم رسول الله صلى الله عليه وسلم رضي الله عنه', 'Anas bin Malik Al-Ansari (MayAllah be pleased with him) the servant of the Messenger of Allah', 'صحيح', 'رياض الصالحين 15', 'Riyad as-Salihin 15', 'ریاض الصالحین 15', null, 'يخبر صلى الله عليه وسلم أن الله أشد فرحًا برجوع عبده إليه بطاعته وامتثال أمره مخلصا من قلبه، من فرح أحدكم كان في أرض فلاة، ليس حوله أحد، لا ماء ولا طعام ولا أناس، وضاع بعيره، فجعل يطلبه فلم يجده، فذهب إلى شجرة ونام تحتها ينتظر الموت! قد أيس من بعيره، وأيس من حياته؛ لأن طعامه وشرابه على بعيره، والبعير قد ضاع، فبينما هو كذلك وجد بعيره فجأة عنده قد تعلق خطامه بالشجرة التي هو نائم تحتها، فبأي شيء يقدر هذا الفرح؟ هذا الفرح لا يمكن أن يتصوره أحد إلا من وقع في مثل هذه الحال! لأنه فرح عظيم، فرح بالحياة بعد الموت، ولهذا أخذ بالخطام، وقال: "اللهم أنت عبدي وأنا ربك"! أراد أن يثني على الله فيقول: "اللهم أنت ربي وأنا عبدك" لكن من شدة فرحه أخطأ.', 'إثبات صفة الفرح لله -عز وجل- على ما يليق بجلال الله سبحانه.
رحمة الله تعالى بعباده بقبول توبتهم، وحبه إياهم.
الترغيب في التوبة والحث عليها.
عدم المؤاخذة في الخطأ غير المتعمد.
الحض على محاسبة النفس.
جواز استعمال ضرب المثل لتقريب المعنى في التعليم، اقتداء بالنبي -صلى الله عليه وسلم-.
جواز القسم للتأكيد على ما فيه فائدة ومصلحة.', 'أفرح : أشد فرحا.
سقط على بعيره : عثر عليه من غير قصد.
وقد أضله : ذهب منه بغير قصده، ولم يعرف موضعه.
أرض فلاة : أرض واسعة لا نبات بها ولا ماء.
راحلته : الراحلة ما يركبه المسافر من ناقة أو غيرها.
انفلتت : تخلصت.
أيس منها : يئس وانقطع رجاؤه.
خطامها : الخطام: حبل من ليف أو شعر أو كتان يُجعل في أحد طرفيه حلقة ثم يشد في الطرف الآخر؛ حتى يصير كالحلقة ثم يقلد للدابة ثم يثنى على مخطمه، وهو: مقدم الأنف والفم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4313', false),
(20016, 2, 201, 16, 'hadith', 'عن أبي موسى عبد الله بن قيس الأشعرى رضي الله عنه عن النبي صلى الله عليه وسلم قال: « إن الله تعالى يبسط يده بالليل ليتوب مسيء النهار، ويبسط يده بالنهار ليتوب مسيء الليل حتى تطلع الشمس من مغربها».', 'The Prophet (ﷺ) said: "Allah, the Exalted, will continue to stretch out His Hand in the night so that the sinners of the day may repent, and continue to stretch His Hand in the daytime so that the sinners of the night may repent, until the sun rises from the west"..', 'أبي موسى عبد الله بن قيس الأشعرى رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 16', 'Riyad as-Salihin 16', 'ریاض الصالحین 16', 'رواه مسلم', 'يُخبِرُ النبيُّ صلى الله عليه وسلم: أنَّ الله تعالى يقبل التوبة من عباده، 
فإن أذنب العبد ذنبًا بالنهار وتاب بالليل قَبِلَ الله توبته، وإن أذنب ذنبًا بالليل وتاب بالنهار قَبل الله توبته، 
ويبسط يده سبحانه للتوبة فرحًا بها، وقبولًا لها، ولا يزال باب التوبة مفتوحًا حتى تطلع الشمس من مغربها إيذانًا بانتهاء الدنيا، فإذا طلعت فإن باب التوبة يُغلق.', 'قبول التوبة مستمر ما دام بابها مفتوحًا، ويغلق بابها بمطلع الشمس من مغربها، وأن يتوب الإنسان قبل غرغرة الموت، وهي وصول الروح إلى الحلقوم.
عدم اليأس والقنوط بسبب الذنب، فإن عفو الله سبحانه ورحمته واسعة، وباب التوبة مفتوح.
 شروط التوبة: الأول: الإقلاع عن المعصية، والثاني: الندم على فعلها، والثالث: العزم على ألّا يعود إليها أبدًا، هذا إن كانت في حقوق الله تعالى، وإن كانت متعلِّقة بحق من حقوق العباد، فيشترط لصحة التوبة أن يؤدي ذلك الحق إلى صاحبه، أو يعفو عنه صاحب الحق.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4318', false),
(20017, 2, 201, 17, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : « من تاب قبل أن تطلع الشمس من مغربها تاب الله عليه».', 'Messenger of Allah (ﷺ) said, "He who repents before the sun rises from the west, Allah will forgive him"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 17', 'Riyad as-Salihin 17', 'ریاض الصالحین 17', 'رواه مسلم', 'يفيد الحديث أن الله سبحانه وتعالى يقبل التوبة من عبده المذنب ما لم تطلع الشمس من مغربها؛ لأنها نهاية وقت قبول التوبة وهي من علامات الساعة الكبرى.', 'الله تعالى يقبل التوبة من عباده تفضلا منه إذا كانت مستجمعة لشروطها، ومن شروطها: أن تقع من التائب قبل طلوع الشمس من مغربها.
الله- سبحانه وتعالى- يقبل توبة العبد وإن تأخرت، لكن المبادرة بالتوبة هي الواجب.
بقي من شروط التوبة:- الندم على الذنب.- العزم على عدم العودة إليه.- الإقلاع والترك للذنب.- إن كان لآدمي حق أن يعيده لصاحبه.', 'من تاب : رجع عن المعصية.
تاب الله عليه : أي: قَبِلَ توبته.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4797', false),
(20018, 2, 201, 18, 'hadith', 'عن أبي عبد الرحمن عبد الله بن عمر بن الخطاب رضي الله عنهما عن النبي صلى الله عليه وسلم قال: « إن الله عز وجل يقبل توبة العبد ما لم يغرغر».', 'The Prophet (ﷺ) said, "Allah accepts a slave''s repentance as long as the latter is not on his death bed (that is, before the soul of the dying person reaches the throat)"..', 'أبي عبد الرحمن عبد الله بن عمر بن الخطاب رضي الله عنهما', '''Abdullah bin ''Umar bin Al-Khattab (May Allah be pleased with them) reported that:', 'حسن', 'رياض الصالحين 18', 'Riyad as-Salihin 18', 'ریاض الصالحین 18', 'رواه الترمذي وقال: حديث حسن', 'الله عز وجل يقبل توبة العبد ما لم تصل الروحُ الحلقومَ، فإذا وصلت الروحُ الحلقومَ فلا توبة، ولقوله تعالى : {وَلَيْسَتِ التَّوْبَةُ لِلَّذِينَ يَعْمَلُونَ السَّيِّئَاتِ حَتَّى إِذَا حَضَرَ أَحَدَهُمُ الْمَوْتُ قَالَ إِنِّي تُبْتُ الْآن}، [النساء: 18].', 'من شروط التوبة أن تقع من المكلف قبل أن يصل إلى حالة لا تمكنُ الحياة بعدها عادة.
لا تقبل التوبة في حالة الغرغرة.', 'توبة العبد : التوبة: الاعتراف والندم والإقلاع والعزم على ألا يعاود الإنسان ما اقترفه.
ما لم يغرغر : المراد: الاحتضار.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4315', false),
(20019, 2, 201, 19, 'hadith', 'عن زر بن حبيش قال: أتيت صفوان بن عسال رضي الله عنه أسأله عن المسح على الخفين فقال: ما جاء بك يازر؟ فقلت: ابتغاء العلم، فقال: إن الملائكة تضع أجنحتها لطالب العلم رضي بما يطلب، فقلت: من أصحاب النبي صلى الله عليه وسلم ، فجئت أسألك: هل سمعته يذكر في ذلك شيئاً؟ قال: نعم، كان يأمرنا إذا كنا سفراً- أو مسافرين- أن لا ننزع خفافناً ثلاثة أيام ولياليهن إلا من جنابة، ولكن من غائط وبول ونوم. فقلت: سفر، فبينا نحن عنده إذ ناداه أعرابى بصوت له جهورى: يا محمد، فأجابه رسول الله صلى الله عليه وسلم نحواً من صوته: "هاؤم" فقلت له: ويحك اغضض من صوتك فإنك عند النبي صلى الله عليه وسلم ، وقد نهيت عن هذا! فقال: والله لا أغضض. قال الأعرابى: المرء يحب القوم ولما يلحق بهم؟ قال النبي صلى الله عليه وسلم: " المرء مع من أحب يوم القيامة" فما زال يحدثنا حتى ذكر باباً من المغرب مسيرة عرضه أو يسير الراكب في عرضه أربعين أو سبعين عاماً. قال سفيان أحد الرواة قبل الشام خلقه الله تعالى يوم خلق السماوات والأرض مفتوحاً للتوبة لا يغلق حتى تطلع الشمس منه".', 'I went to Safwan bin ''Assal (May Allah be pleased with him) to inquire about wiping with wet hands over light boots while performing Wudu''. He asked me, "What brings you here, Zirr?" I answered: "Search for knowledge". He said, "Angels spread their wings for the seeker of knowledge out of joy for what he seeks". I told him, "I have some doubts in my mind regarding wiping of wet hands over light boots in the course of performing Wudu'' after defecation or urinating. Now since you are one of the Companions of the Prophet (ﷺ), I have come to ask you whether you heard any saying of the Prophet (ﷺ) concerning it?". He replied in the affirmative and said, "He (ﷺ) instructed us that during a journey we need not take off our light boots for washing the feet up to three days and nights, except in case of major impurity (after sexual intercourse). In other cases such as sleeping, relieving oneself or urinating, the wiping of wet hands over light boots will suffice." I, then, questioned him, "Did you hear him say anything about love and affection?" He replied, "We accompanied the Messenger of Allah (ﷺ) in a journey when a bedouin called out in a loud voice, ''O Muhammad.'' The Messenger of Allah (ﷺ) replied him in the same tone, ''Here I am.'' I said to him (the bedouin), ''Woe to you, lower your voice in his presence, because you are not allowed to do so.'' He said, ''By Allah! I will not lower my voice,'' and then addressing the Prophet (ﷺ) he said, ''What about a person who loves people but has not found himself in their company.'' Messenger of Allah (ﷺ) replied, ''On the Day of Resurrection, a person will be in the company of those whom he loves.'' The Messenger of Allah then kept on talking to us and in the course of his talk, he mentioned a gateway in the heaven, the width of which could be crossed by a rider in forty or seventy years".Sufyan, one of the narrators of this tradition, said: "This gateway is in the direction of Syria. Allah created it on the day He created the heavens and the earth. It is open for repentance and will not be shut until the sun rises from that direction (i.e., the West) (on Doomsday)".', 'زر بن حبيش قال: أتيت صفوان بن عسال رضي الله عنه', 'Zirr bin Hubaish', 'صحيح', 'رياض الصالحين 19', 'Riyad as-Salihin 19', 'ریاض الصالحین 19', 'رواه الترمذي وغيره وقال: حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20020, 2, 201, 20, 'hadith', 'عن أبي سعيد سعد بن مالك بن سنان الخدري رضي الله عنه أن نبي الله صلى الله عليه وسلم قال: « كان فيمن كان قبلكم رجل قتل تسعة وتسعين نفساً، فسأل عن أعلم أهل الأرض، فدل على راهب، فأتاه فقال: إنه قتل تسعه وتسعين نفساً، فهل له من توبة؟ فقال: لا، فقتله فكمل به مائةً، ثم سأل عن أعلم أهل الأرض، فدل على رجل عالم فقال: إنه قتل مائة نفس فهل له من توبة؟ فقال: نعم، ومن يحول بينه وبين التوبة؟ انطلق إلى أرض كذا وكذا، فإن بها أناساً يعبدون الله تعالى فاعبد الله معهم، ولا ترجع إلى أرضك فإنها أرض سوءٍ، فانطلق حتى إذا نصف الطريق أتاه الموت، فاختصمت فيه ملائكة الرحمة وملائكة العذاب. فقالت ملائكة الرحمة: جاء تائبا مقبلا بقلبه إلى الله تعالى، وقالت ملائكة العذاب: إنه لم يعمل خيرا قط، فأتاهم ملك في صورة آدمي فجعلوه بينهم- أي حكماً- فقال: قيسوا ما بين الأرضين فإلى أيتهما كان أدنى فهو له، فقاسوا فوجدوه أدنى إلى الأرض التي أراد، فقبضته ملائكة الرحمة».', 'Prophet of Allah (ﷺ) said: "There was a man from among a nation before you who killed ninety-nine people and then made an inquiry about the most learned person on the earth. He was directed to a monk. He came to him and told him that he had killed ninety-nine people and asked him if there was any chance for his repentance to be accepted. He replied in the negative and the man killed him also completing one hundred. He then asked about the most learned man in the earth. He was directed to a scholar. He told him that he had killed one hundred people and asked him if there was any chance for his repentance to be accepted. He replied in the affirmative and asked, ''Who stands between you and repentance? Go to such and such land; there (you will find) people devoted to prayer and worship of Allah, join them in worship, and do not come back to your land because it is an evil place.'' So he went away and hardly had he covered half the distance when death overtook him; and there was a dispute between the angels of mercy and the angels of torment. The angels of mercy pleaded, ''This man has come with a repenting heart to Allah,'' and the angels of punishment argued, ''He never did a virtuous deed in his life.'' Then there appeared another angel in the form of a human being and the contending angels agreed to make him arbiter between them. He said, ''Measure the distance between the two lands. He will be considered belonging to the land to which he is nearer.'' They measured and found him closer to the land (land of piety) where he intended to go, and so the angels of mercy collected his soul"..', 'أبي سعيد سعد بن مالك بن سنان الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 20', 'Riyad as-Salihin 20', 'ریاض الصالحین 20', 'متفق عليه', 'قال النبي صلى الله عليه وسلم : كان في أمة من الأمم قبلنا رجل قتل تسعة وتسعين نفسًا، ثم إنه ندم وسأل عن أعلم أهل الأرض يسأله: هل له من توبة؟ فدل على رجل، فوجد عابدًا ولكنه ليس عنده علم، فلما سأله قال إنه قتل تسعة وتسعين نفسًا، فهل له من توبة؟ فاستعظم الراهب هذا الذنب وقال: ليس لك توبة! فغضب الرجل وانزعج وقتل الراهب، فأتم به مائة نفس، ثم إنه سأل عن أعلم أهل الأرض، فدل على رجل عالم فقال له: إنه قتل مائة نفس فهل له من توبة؟ قال: نعم! ومن الذي يحول بينه وبين التوبة؟ باب التوبة مفتوح، ولكن اذهب إلى القرية الفلانية؛ فإن فيها قومًا يعبدون الله، والأرض التي كان فيها كأنها -والله أعلم- دار كفر فأمره هذا العالم أن يهاجر بدينه إلى هذه القرية التي يعبد فيها الله سبحانه وتعالى ، فخرج تائبا نادمًا مهاجرًا بدينه إلى الأرض التي فيها القوم الذين يعبدون الله عز وجل، وفي منتصف الطريق أتاه الموت، فاختصمت فيه ملائكة العذاب وملائكة الرحمة، تقول ملائكة الرحمة: إنه تاب وجاء نادمًا تائبًا، فحصل بينهما خصومة، فبعث الله إليهم ملكًا ليحكم بينهم، فقال: قيسوا ما بين الأرضين فإلى أيتها كان أقرب فهو من أهلها.
 فإن كانت أرض الكفر أقرب إليه فملائكة العذاب تقبض روحه، وإن كان إلى بلد الإيمان أقرب فملائكة الرحمة تقبض روحه.
فقاسوا ما بينهما؛ فإذا البلد التي اتجه إليها -وهي بلد الإيمان-أقرب من البلد التي هاجر منها بنحو شبر -مسافة قريبة- فقبضته ملائكة الرحمة.', 'حسن أسلوب النبي -صلى الله عليه وسلم- واستعماله أسلوب القصة في التوجيه والموعظة.
جواز التحدث عن الأمم السابقة مما لم يأت الإسلام بما يخالفه.
النفوس التي فيها استعداد للخير والحق ترجع إلى الاستقامة وإن انحرفت بها الأهواء حينًا عن طريق الهدى.
فضل العلم مع قلة العبادة على كثرة العبادة مع الجهل.
العالم يهتدي بنور الحق والعلم فيوفق للهدى فينتفع وينفع.
باب التوبة مفتوح، والتائب مقبول مهما عظُم منه الذنب وكثُر.
على الداعي إلى الخير أن يكون ذا حكمة بالغة؛ بحيث يفطن إلى ما يصلح النفوس، ويسلك بها سبيل الأمل وفتح باب الرجاء.
قبول توبة القاتل عمدًا.
مجانبة أهل المعاصي ومقاطعتهم ما داموا على حالهم، ومصاحبة أهل التقوى والعلم والصلاح.
حب الله تعالى لتوبة عباده وإخباره الملائكة بذلك مباهاة بهم.
بذل الجهد وتحمل المشقة من أجل اللحاق بالصالحين، وفعل عمل المقربين دليل صدق الرغبة في التوبة إلى الله -عز وجل-.
قدرة الملائكة على التشكل.
إذا تعارضت الأدلة والأحوال وتعددت البينات عند الحاكم، فله أن يستدل بالقرائن على الترجيح.
جواز التحكيم.
من خرج مهاجرًا في سبيل الله فمات فقد وقع أجره على الله.', 'راهب : المتخلي عن أشغال الدنيا والتارك لملاذها والزاهد فيها، والمعتزل لأهلها للعبادة.
توبة : الاعتراف بالذنب والندم والإقلاع والعزم على ألا يعاوده.
من يحول : من يمنعك؟
أرض كذا وكذا : روي أن اسمها بصرى.
نصف الطريق : أي: بلغ نصفها.
الأرضين : أي: التي خرج منها والتي ذهب إليها.
أدنى : أقرب.
نأى : نهض بجهد ومشقة رغم ثقل ما أصابه من الموت.
قبضته : أخذته.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4310', false),
(20021, 2, 201, 21, 'hadith', 'عن عبد الله بن كعب بن مالك، وكان قائد كعب رضي الله عنه من بنيه حين عمي قال: سمعت كعب بن مالك رضي الله عنه يحدث بحديثه حين تخلف عن رسول الله صلى الله عليه وسلم في غزوة تبوك. قال كعب: لم اتخلف عن رسول الله، صلى الله عليه وسلم ، في غزوة غزاها قط إلا في غزوة تبوك، غير أني قد تخلفت في غزوة بدر، ولم يعاتب أحد تخلف عنه، إنما خرج رسول الله صلى الله عليه وسلم والمسلمون يريدون عير قريش حتى جمع الله تعالى بينهم وبين عدوهم على غير ميعاد. ولقد شهدت مع رسول الله صلى الله عليه وسلم ليلة العقبة حين تواثقنا على الإسلام، وما أحب أن لي بها مشهد بدرٍ، وإن كانت بدر أذكر في الناس منها. وكان من خبري حين تخلف عن رسول الله، صلى الله عليه وسلم، في غزوة تبوك أني لم أكن قط أقوى ولا أيسر مني حين تخلفت عنه في تلك الغزوة، والله ما جمعت قبلها راحلتين قط حتى جمعتهما في تلك الغزوة، ولم يكن رسول الله صلى الله عليه وسلم يريد غزوة إلا ورى بغيرها حتى كانت تلك الغزوة، فغزاها رسول الله صلى الله عليه وسلم في حر شديد، واستقبل سفراً بعيداً ومفازاً، واستقبل عدداً كثيراً، فجلى للمسلمين أمرهم ليتأهبوا أهبة غزوهم فأخبرهم بوجههم الذي يريد، والمسلمون مع رسول الله كثير ولا يجمعهم كتاب حافظ "يريد بذلك الديوان" قال كعب: فقل رجل يريد أن يتغيب إلا ظن أن ذلك سيخفى به مالم ينزل فيه وحي من الله، وغزا رسول الله صلى الله عليه وسلم تلك الغزوة حين طابت الثمار والظلال فأنا إليها أصعر فتجهز رسول الله صلى الله عليه وسلم والمسلمون معه، وطفقت أغدو لكي أتجهز معه، فأرجع ولم أقض شيئاً، وأقول في نفسي: أنا قادر على ذلك إذا أردت، فلم يزل يتمادى بي حتى استمر بالناس الجد، فأصبح رسول الله صلى الله عليه وسلم غادياً والمسلمون معه، ولم أقض من جهازي شيئاً، ثم غدوت فرجعت ولم أقض شيئاً، فلم يزل يتمادى بي حتى أسرعوا وتفارط الغرو، فهممت أن أرتحل فأدركهم، فياليتني فعلت، ثم لم يقدر ذلك لي، فطفقت إذا خرجت في الناس بعد خروج رسول الله صلى الله عليه وسلم يحزنني أني أرى لي أسوة، إلا رجلاً مغموصاً عليه في النفاق، أو رجلاً ممن عذر الله تعالى من أسوة، إلا رجلاً مغموصاً عليه في النفاق، أو رجلاً ممن عذر الله تعالى من الضعفاء، ولم يذكرني رسول الله صلى الله عليه وسلم حتى بلغ تبوك، فقال وهو جالس في القوم بتبوك: ما فعل كعب بن مالك؟ قَالَ رَجُلٌ مِنْ بَنِي سَلِمَةَ يَا رَسُولَ اللَّهِ حَبَسَهُ بُرْدَاهُ وَالنَّظَرُ فِي عِطْفَيْهِ.فقال له معاذ بن جبل رضي الله عنه بئس ما قلت! والله يارسول الله ما علمنا عليه إلا خيراً ، فسكت رسول الله صلى الله عليه وسلم فبينا هو على ذلك رأى رجلا مبيضا يزول به السراب فقال رسول الله صلى الله عليه وسلم: كن أبا خيثمة، فإذا أبو خيثمة الأنصاري وهو الذي تصدق بصاع التمر حين لمزه المنافقون، قال كعب: فلما بلغني أن رسول الله صلى الله عليه وسلم قد توجه قافلاً من تبوك حضرني بثي، فطفقت أتذكر الكذب وأقول: بم أخرج من سخطه غداً وأستعين على ذلك بكل ذي رأى من أهلي، فلما قيل: إن رسول الله صلى الله عليه وسلم قد أظل قادماً زاح عني الباطل حتى عرفت أني لم أنج منه بشيء أبداً، فأجمعت صدقه، وأصبح رسول الله صلى الله عليه وسلم قادماً، وكان إذا قدم من سفر بدأ بالمسجد فركع فيه ركعتين ثم جلس للناس، فلما فعل فعل ذلك جاءه المخلفون يعتذرون إليه ويحلفون له، وكانوا بضعا وثمانين رجلاً فقبل منهم علانيتهم وبايعهم واستغفر لهم ووكل سرائرهم إلى الله تعالى حتى جئت. فلما سلمت تبسم تبسم المغضب ثم قال: تعال، فجئت أمشي حتى جلست بين يديه، فقال لي: ما خلفك؟ ألم تكن قد ابتعت ظهرك! قال قلت: يارسول الله إني والله لو جلست عند غيرك من أهل الدنيا لرأيت أني سأخرج من سخطه بعذر، لقد أعطيت جدلاً، ولكنني والله لقد علمت لئن حدثتك اليوم حديث كذب ترضي به ليوشكن الله يسخطك علي، وإن حدثتك حديث صدق تجد علي فيه إني لأرجو فيه عقبى الله عز وجل، والله ما كان لي من عذر، والله ما كنت قط أقوى ولا أيسر مني حين تخلفت عنك. قال: فقال رسول الله صلى الله عليه وسلم " أما هذا فقد صدق، فقم حتى يقضي الله فيك" وسار رجال من بني سلمة فاتبعوني، فقالوا لي: والله ما علمناك أذنبت ذنبا قبل هذا، لقد عجزت في أن لا يكون اعتذرت إلى رسول الله صلى الله عليه وسلم بما اعتذر إليه المخلفون فقد كان كافيك ذنبك استغفار رسول الله صلى الله عليه وسلم لك. قال: فوالله ما زالوا يؤنبونني حتى أردت أن أرجع إلى رسول الله صلى الله عليه وسلم فأكذب نفسي، ثم قلت لهم: هل لقي هذا معي من أحد؟ قالوا: نعم لقيه معك رجلان قالا مثل ما قلت، وقيل لهما مثل ما قيل لك، قال قلت: من هما؟ قالوا: مرارة بن الربيع العمري، وهلال بن أمية الواقفي؟ قال: فذكروا لي رجلين صالحين قد شهدا بدراً فيهما أسوة. قال: فمضيت حين ذكروهما لي. ونهى رسول صلى الله عليه وسلم عن كلامنا أيها الثلاثة من بين من تخلف عنه، قال: فاجتنبنا الناس- أو قال: تغيروا لنا- حتى تنكرت لي في نفس الأرض، فما هي بالأرض التي أعرف، فلبثنا على ذلك خمسين ليلة. فأما صاحباي فاستكانا وقعدا في بيوتهما يبكيان، وأما أنا فكنت أشب القوم وأجلدهم، فكنت أخرج فأشهد الصلاة مع المسلمين، وأطوف في الأسواق ولا يكلمني أحد، وآتي رسول الله صلى الله عليه وسلم فأسلم عليه، وهو في مجلسه بعد الصلاة، فأقول في نفسي : هل حرك شفتيه برد السلام أم ؟ ثم أصلي قريباً منه وأسارقه النظر، فإذا أقبلت على صلاتي نظر إلي، وإذا التفت نحوه أعرض عني، حتى إذا طال ذلك علي من جفوة المسلمين مشيت حتى تسورت جدار حائط أبي قتادة وهو ابن عمي وأحب الناس إلي، فسلمت عليه فوالله ما ردّ علي السلام، فقلت له: يا أبا قتادة أنشدك بالله هل تعلمني أُحب الله ورسوله صلى الله عليه وسلم ؟ فسكت، فعدت فناشدته فسكت، فعدت فناشدته فقال: الله ورسوله أعلم. ففاضت عيناي، وتوليت حتى تسورت الجدار، فبينما أنا أمشى في سوق المدينة إذا نبطى من نبط أهل الشام ممن قدم بالطعام ببيعه بالمدينة يقول: من يدل على كعب بن مالك؟ فطفق الناس يشيرون له إلي حتى جاءنى فدفع إلي كتاب من ملك غسان، وكنت كاتباً. فقرأته فإذا فيه: أما بعد فإنه قد بلغنا أن صاحبك قد جفاك، ولم يجعلك الله بدار هوان ولا مضيعة، فالحق بنا نواسك، فقلت حين قرأتها، وهذه أيضاً من البلاء فتيممت بها التنور فسجرتها، حتى إذا مضت أربعون من الخمسين واستلبث الوحى إذا رسول رسول الله صلى الله عليه وسلم يأتينى، فقال: إن رسول الله صلى الله عليه وسلم يأمرك أن تعتزل امرأتك، فقلت: أطلقها، أم ماذا أفعل؟ قال: لا، بل اعتزلها فلا تقربنها، وأرسل إلى صاحبي بمثل ذلك. فقلت لامرأتي: ألحقي بأهلك فكوني عندهم حتى يقضي الله في هذا الأمر، فجاءت امرأة هلال بن أمية رسول الله صلى الله عليه وسلم فقالت له : يا رسول الله إن هلال بن أمية شيخ ضائع ليس له خادم، فهل تكره أن أخدمه؟ قال : لا، ولكن لا يقربنك. فقالت: إنه والله ما به من حركة إلى شيء، ووالله ما زال يبكي منذ كان من أمره ما كان إلى يومه هذا. فقال لي بعض أهلي: لو استأذنت رسول الله صلى الله عليه وسلم في امرأتك، فقد أذن لامرأة هلال بن أمية أن تخدمه؟ فقلت: لا أستأذن فيها رسول الله صلى الله عليه وسلم، وما يدريني ماذا يقول رسول الله صلى الله عليه وسلم، إذا استأذنته فيها وأنا رجل شاب! فلبثت بذلك عشر ليالٍ، فكمل لنا خمسون ليلة من حين نهى عن كلامنا. ثم صليت صلاة الفجر صباح خمسين ليلة على ظهر بيت من بيوتنا، فبينما أنا جالس على الحال التى ذكر الله تعالى منا، قد ضافت علي نفسي وضاقت علي الأرض بما رحبت، سمعت صوت صارخ أوفى على سلع يقول بأعلى صوته: يا كعب بن مالك أبشر فخررت ساجداً، وعرفت أنه قد جاء فرج. فآذن رسول الله صلى الله عليه وسلم الناس بتوبة الله عز وجل علينا حين صلى صلاة الفجر فذهب الناس يبشروننا، فذهب قبل صاحبي مبشرون، وركض رجل إلي فرساً وسعى ساع من أسلم قبلي وأوفى على الجبل، فكان الصوت أسرع من الفرس، فلما جاءني الذى سمعت صوته يبشرني نزعت له ثوبي فكسوتهما إياه ببشراه، والله ما أملك غيرهما يومئذ، واستعرت ثوبين فلبستهما وانطلقت أتأمم رسول الله صلى الله عليه وسلم يتلقانى الناس فوجاً فوجاً يهنئوني بالتوبة ويقولون لي: لتهنك توبة الله عليك، حتى دخلت المسجد فإذا رسول الله صلى الله عليه وسلم جالس حوله الناس، فقام طلحة بن عبيد الله رضي الله عنه يهرول حتى صافحني وهنأني، والله ما قام رجل من المهاجرين غيره، فكان كعب لا ينساها لطلحة. قال كعب: فلما سلمت على رسول الله صلى الله عليه وسلم قال: وهو يبرق وجهه من السرور : أبشر بخير يوم مرّ عليك مذ ولدتك أمك، فقلت: أمن عندك يا رسول الله أم من عند الله؟ قال : لا ، بل من عند الله عز وجل، وكان رسول الله صلى الله عليه وسلم إذا سر استنار وجهه حتى كأن وجهه قطعة قمر، وكنا نعرف ذلك منه، فلما جلست بين يديه قلت: يا رسول الله إن من توبتي أن أنخلع من مالي صدقة إلى الله وإلى رسوله. فقال رسول الله صلى الله عليه وسلم : أمسك عليك بعض مالك فهو خير لك، فقلت: إني أمسك سهمي الذى بخيبر. وقلت: يا رسول الله إن الله تعالى إنما أنجاني بالصدق، وإن من توبتي أن لا أحدثَ إلا صدقاً ما بقيت ، فو الله ما علمت أحداً من المسلمين أبلاه الله في صدق الحديث منذ ذكرت ذلك لرسول الله صلى الله عليه وسلم أحسن مما أبلاني الله تعالى ، والله ما تعمدت كذبة منذ قلت ذلك لرسول الله صلى الله عليه وسلم إلى يومي هذا، وإني لأرجو أن يحفظني الله تعالى فيما بقي، قال: فأنزل الله تعالى: {لقد تاب الله على النبي والمهاجرين والأنصار الذين اتبعوه في ساعة العسرة) حتى بلغ: {إنه بهم رؤوف رحيم . وعلى الثلاثة الذين خلفوا حتى إذا ضاقت عليهم الأرض بما رحبت} حتى بلغ : {اتقوا الله وكونوا مع الصادقين} ((التوبة 117، 119)) قال كعب : والله ما أنعم الله علي من نعمة قط بعد إذ هداني الله للإسلام أعظم في نفسي من صدقي رسول الله صلى الله عليه وسلم أن لا أكون كذبته، فأهلك كما هلك الذين كذبوا، إن الله تعالى قال للذين كذبوا حين أنزل الوحي شر ما قال لأحد، فقال الله تعالى : {سيحلفون بالله لكم إذا انقلبتم إليهم لتعرضوا عنهم فأعرضوا عنهم إنهم رجس ومأواهم جهنم جزاء بما كانوا يكسبون يحلفون لكم لترضوا عنهم فإن ترضوا عنهم فإن الله لا يرضى عن القوم الفاسقين} ((التوبة: 95،96)) . قال كعب : كنا خلفنا أيها الثلاثة عن أمر أولئك الذين قبل منهم رسول الله صلى الله عليه وسلم حين حلفوا له ، فبايعهم واستغفر لهم، وأرجأ رسول الله صلى الله عليه وسلم أمرنا حتى قضى الله تعالى فيه بذلك، قال الله تعالى : {وعلى الثلاثة الذين خلفوا} وليس الذي ذكر مما خلفنا تخلفنا عن الغزو، وإنما هو تخليفه إيانا وإرجاؤه أمرنا عمن حلف له واعتذر إليه فقبل منه. متفق عليه. وفى رواية "أن النبي صلى الله عليه وسلم خرج في غزوة تبوك يوم الخميس، وكان يحب أن يخرج يوم الخميس" وفى رواية: "وكان لا يقدم من سفر إلا نهاراً في الضحى، فإذا قدم بدأ بالمسجد فصلى فيه ركعتين ثم جلس فيه" .', 'I heard Ka''b bin Malik (May Allah be pleased with him) narrating the story of his remaining behind instead of joining Messenger of Allah (ﷺ) when he left for the battle of Tabuk. Ka''b said: "I accompanied Messenger of Allah (ﷺ) in every expedition which he undertook excepting the battle of Tabuk and the battle of Badr. As for the battle of Badr, nobody was blamed for remaining behind as Messenger of Allah (ﷺ) and the Muslims, when they set out, had in mind only to intercept the caravan of the Quraish. Allah made them confront their enemies unexpectedly. I had the honour of being with Messenger of Allah (ﷺ) on the night of ''Aqabah when we pledged our allegiance to Islam and it was dearer to me than participating in the battle of Badr, although Badr was more well-known among the people than that. And this is the account of my staying behind from the battle of Tabuk. I never had better means and more favourable circumstances than at the time of this expedition. And by Allah, I had never before possessed two riding-camels as I did during the time of this expedition. Whenever Messenger of Allah (ﷺ) decided to go on a campaign, he would not disclose his real destination till the last moment (of departure). But on this expedition, he set out in extremely hot weather; the journey was long and the terrain was waterless desert; and he had to face a strong army, so he informed the Muslims about the actual position so that they should make full preparation for the campaign. And the Muslims who accompanied Messenger of Allah (ﷺ) at that time were in large number but no proper record of them was maintained." Ka''b (further) said: "Few were the persons who chose to remain absent believing that they could easily hide themselves (and thus remain undetected) unless Revelation from Allah, the Exalted, and Glorious (revealed relating to them). And Messenger of Allah (ﷺ) set out on this expedition when the fruit were ripe and their shade was sought. I had a weakness for them and it was during this season that Messenger of Allah (ﷺ) and the Muslims made preparations. I also would set out in the morning to make preparations along with them but would come back having done nothing and said to myself: ''I have means enough (to make preparations) as soon as I like''. And I went on doing this (postponing my preparations) till the time of departure came and it was in the morning that Messenger of Allah (ﷺ) set out along with the Muslims, but I had made no preparations. I would go early in the morning and come back, but with no decision. I went on doing so until they (the Muslims) hastened and covered a good deal of distance. Then I wished to march on and join them. Would that I had done that! But perhaps it was not destined for me. After the departure of Messenger of Allah (ﷺ) whenever I went out, I was grieved to find no good example to follow but confirmed hypocrites or weak people whom Allah had exempted (from marching forth for Jihad). Messenger of Allah (ﷺ) made no mention of me until he reached Tabuk. While he was sitting with the people in Tabuk, he said, ''What happened to Ka''b bin Malik?'' A person from Banu Salimah said: "O Messenger of Allah, the (beauty) of his cloak and an appreciation of his finery have detained him.'' Upon this Mu''adh bin Jabal (MatAllah be pleased with him) admonished him and said to Messenger of Allah (ﷺ): "By Allah, we know nothing about him but good.'' Messenger of Allah (ﷺ), however, kept quiet. At that time he (the Prophet (ﷺ)) saw a person dressed in white and said, ''Be Abu Khaithamah.'' And was Abu Khaithamah Al- Ansari was the person who had contributed a Sa'' of dates and was ridiculed by the hypocrites." Ka''b bin Malik further said: "When the news reached me that Messenger of Allah (ﷺ) was on his way back from Tabuk, I was greatly distressed. I thought of fabricating an excuse and asked myself how I would save myself from his anger the next day. In this connection, I sought the counsels of every prudent member of my family. When I was told that Messenger of Allah (ﷺ) was about to arrive, all the wicked ideas vanished (from my mind) and I came to the conclusion that nothing but the truth could save me. So I decided to tell him the truth. It was in the morning that Messenger of Allah (ﷺ) arrived in Al-Madinah. It was his habit that whenever he came back from a journey, he would first go to the mosque and perform two Rak''ah (of optional prayer) and would then sit with the people. When he sat, those who had remained behind him began to put forward their excuses and take an oath before him. They were more than eighty in number. Messenger of Allah (ﷺ) accepted their excuses on the very face of them and accepted their allegiance and sought forgiveness for them and left their insights to Allah, until I appeared before him. I greeted him and he smiled and there was a tinge of anger in that. He then said to me, ''Come forward''. I went forward and I sat in front of him. He said to me, ''What kept you back? Could you not afford to go in for a ride?'' I said, ''O Messenger of Allah, by Allah, if I were to sit before anybody else, a man of the world, I would have definitely saved myself from his anger on one pretext or the other and I have a gifted skill in argumentation, but, by Allah, I am fully aware that if I were to put forward before you a lame excuse to please you, Allah would definitely provoke your wrath upon me. In case, I speak the truth, you may be angry with me, but I hope that Allah would be pleased with me (and accept my repentance). By Allah, there is no valid excuse for me. By Allah, I never possessed so good means, and I never had such favourable conditions for me as I had when I stayed behind.'' Thereupon, Messenger of Allah (ﷺ) said, ''This man spoke the truth, so get up (and wait) until Allah gives a decision about you.'' I left and some people of Banu Salimah followed me. They said to me, ''By Allah, we do not know that you committed a sin before. You, however, showed inability to put forward an excuse before Messenger of Allah (ﷺ) like those who stayed behind him. It would have been enough for the forgiveness of your sin that Messenger of Allah (ﷺ) would have sought forgiveness for you.'' By Allah, they kept on reproaching me until I thought of going back to Messenger of Allah (ﷺ) and retract my confession. Then I said to them, ''Has anyone else met the same fate?'' They said, ''Yes, two persons have met the same fate. They made the same statement as you did and the same verdict was delivered in their case.'' I asked, ''Who are they?'' They said, ''Murarah bin Ar-Rabi'' Al-''Amri and Hilal bin Umaiyyah Al- Waqifi.'' They mentioned these two pious men who had taken part in the battle of Badr and there was an example for me in them. I was confirmed in my original resolve. Messenger of Allah (ﷺ) prohibited the Muslims to talk to the three of us from amongst those who had stayed behind. The people began to avoid us and their attitude towards us changed and it seemed as if the whole atmosphere had turned against us, and it was in fact the same atmosphere of which I was fully aware and in which I had lived (for a fairly long time). We spent fifty nights in this very state and my two friends confined themselves within their houses and spent (most of their) time weeping. As I was the youngest and the strongest, I would leave my house, attend the congregational Salat, move about in the bazaars, but none would speak to me. I would come to Messenger of Allah (ﷺ) as he sat amongst (people) after the Salat, greet him and would ask myself whether or not his lips moved in response to my greetings. Then I would perform Salat near him and look at him stealthily. When I finish my Salat, he would look at me and when I would cast a glance at him he would turn away his eyes from me. When the harsh treatment of the Muslims to me continued for a (considerable) length of time, I walked and I climbed upon the wall of the garden of Abu Qatadah, who was my cousin, and I had a great love for him. I greeted him but, by Allah, he did not answer to my greeting. I said to him, ''O Abu Qatadah, I adjure you in the Name of Allah, are you not aware that I love Allah and His Messenger (ﷺ)?'' I asked him the same question again but he remained silent. I again adjured him, whereupon he said, ''Allah and His Messenger (ﷺ) know better.'' My eyes were filled with tears, and I came back climbing down the wall.As I was walking in the bazaars of Al-Madinah, a man from the Syrian peasants, who had come to sell food grains in Al-Madinah, asked people to direct him to Ka''b bin Malik. People pointed towards me. He came to me and delivered a letter from the King of Ghassan, and as I was a scribe, I read that letter whose purport was: ''It has been conveyed to us that your friend (the Prophet (ﷺ)) was treating you harshly. Allah has not created you for a place where you are to be degraded and where you cannot find your right place; so come to us and we shall receive you graciously.'' As I read that letter I said: ''This is too a trial,'' so I put it to fire in an oven. When forty days had elapsed and Messenger of Allah (ﷺ) received no Revelation, there came to me a messenger of the Messenger of Allah and said, ''Verily, Messenger of Allah (ﷺ) has commanded you to keep away from your wife.'' I said, ''Should I divorce her or what else should I do?'' He said, ''No, but only keep away from her and don''t have sexual contact with her.'' The same message was sent to my companions. So, I said to my wife: ''You better go to your parents and stay there with them until Allah gives the decision in my case.'' The wife of Hilal bin Umaiyyah came to Messenger of Allah (ﷺ) and said: ''O Messenger of Allah, Hilal bin Umaiyyah is a senile person and has no servant. Do you disapprove if I serve him?'' He said, ''No, but don''t let him have any sexual contact with you.'' She said, ''By Allah, he has no such desire left in him. By Allah, he has been in tears since (this calamity) struck him.'' Members of my family said to me, ''You should have sought permission from Messenger of Allah (ﷺ) in regard to your wife. He has allowed the wife of Hilal bin Umaiyyah to serve him.'' I said, ''I would not seek permission from Messenger of Allah (ﷺ) for I do not know what Messenger of Allah might say in response to that, as I am a young man''. It was in this state that I spent ten more nights and thus fifty days had passed since people boycotted us and gave up talking to us. After I had offered my Fajr prayer on the early morning of the fiftieth day of this boycott on the roof of one of our houses, and had sat in the very state which Allah described as: ''The earth seemed constrained for me despite its vastness'', I heard the voice of a proclaimer from the peak of the hill Sal'' shouting at the top of his voice: ''O Ka''b bin Malik, rejoice.'' I fell down in prostration and came to know that there was (a message of) relief for me. Messenger of Allah (ﷺ) had informed the people about the acceptance of our repentance by Allah after he had offered the Fajr prayer. So the people went on to give us glad tidings and some of them went to my companions in order to give them the glad tidings. A man spurred his horse towards me (to give the good news), and another one from the tribe of Aslam came running for the same purpose and, as he approached the mount, I received the good news which reached me before the rider did. When the one whose voice I had heard came to me to congratulate me, I took off my garments and gave them to him for the good news he brought to me. By Allah, I possessed nothing else (in the form of clothes) except these garments, at that time. Then I borrowed two garments, dressed myself and came to Messenger of Allah (ﷺ) On my way, I met groups of people who greeted me for (the acceptance of) repentance and they said: ''Congratulations for acceptance of your repentance.'' I reached the mosque where Messenger of Allah (ﷺ) was sitting amidst people. Talhah bin ''Ubaidullah got up and rushed towards me, shook hands with me and greeted me. By Allah, no person stood up (to greet me) from amongst the Muhajirun besides him." Ka''b said that he never forgot (this good gesture of) Talhah. Ka''b further said: "I greeted Messenger of Allah (ﷺ) with ''As-salamu ''alaikum'' and his face was beaming with pleasure. He (ﷺ) said, ''Rejoice with the best day you have ever seen since your mother gave you birth. ''I said: ''O Messenger of Allah! Is this (good news) from you or from Allah?'' He said, ''No, it is from Allah.'' And it was common with Messenger of Allah (ﷺ) that when ever he was happy, his face would glow as if it were a part of the moon and it was from this that we recognized it (his delight). As I sat before him, I said, I have placed a condition upon myself that if Allah accepts my Taubah, I would give up all of my property in charity for the sake of Allah and His Messenger (ﷺ)!'' Thereupon Messenger of Allah (ﷺ) said, ''Keep some property with you, as it is better for you.'' I said, ''I shall keep with me that portion which is in Khaibar''. I added: ''O Messenger of Allah! Verily, Allah has granted me salvation because of my truthfulness, and therefore, repentance obliges me to speak nothing but the truth as long as I am alive." Ka''b added: "By Allah, I do not know anyone among the Muslims who has been granted truthfulness better than me since I said this to the Prophet (ﷺ). By Allah! Since the time I made a pledge of this to Messenger of Allah (ﷺ), I have never intended to tell a lie, and I hope that Allah would protect me (against telling lies) for the rest of my life. Allah, the Exalted, the Glorious, revealed these Verses:''Allah has forgiven the Prophet (ﷺ), the Muhajirun (Muslim Emigrants who left their homes and came to Al-Madinah) and the Ansar (Muslims of Al- Madinah) who followed him (Muhammad (ﷺ)) in the time of distress (Tabuk expedition), after the hearts of a party of them had nearly deviated (from the Right Path), but He accepted their repentance. Certainly, He is unto them full of kindness, Most Merciful. And (He did forgive also) the three who did not join Another version adds: "Messenger of Allah (ﷺ) set out for Tabuk on Thursday. He used to prefer to set out on journey on Thursday." Another version says: "Messenger of Allah (ﷺ) used to come back from a journey in the early forenoon and went straight to the mosque where he would perform two Rak''ah prayer. Afterwards he would seat himself there".', 'عبد الله بن كعب بن مالك، وكان قائد كعب رضي الله عنه', 'Abdullah bin Ka''b, who served as the guide of Ka''b bin Malik (May Allah be pleased with him) when he became blind,', 'صحيح', 'رياض الصالحين 21', 'Riyad as-Salihin 21', 'ریاض الصالحین 21', null, 'هذا حديث كعب بن مالك رضي الله عنه ، في قصة تخلفه عن غزوة تبوك، وكانت غزوة تبوك في السنة التاسعة من الهجرة.
وكانت هذه الغزوة في أيام الحر حين طابت الثمار وصار المنافقون يحبون الدنيا على الآخرة، فتخلف المنافقون عن هذه الغزوة ولجأوا إلى الظل والرطب والتمر، وبعدت عليهم الشُّقة والعياذ بالله، كما أخبر الله سبحانه في القرآن وكما في هذا الحديث.
أما المؤمنون الخلص، فإنهم خرجوا مع النبي -عليه الصلاة والسلام- ولم يُضعف عزمهم بعد المسافة ولا طيب الثمار.
إلا أن كعب بن مالك رضي الله عنه تخلف عن غزوة تبوك بلا عذر، وهو من المؤمنين الخلص، ولهذا قال: "إنه ما تخلف عن رسول الله صلى الله عليه وسلم عن غزوة غزاها قط، كل غزوات الرسول صلى الله عليه وسلم قد شارك فيها كعب رضي الله عنه فهو من المجاهدين في سبيل الله، إلا في غزوة بدر، فقد تخلف فيها كعب وغيره، لأن النبي -عليه الصلاة والسلام- خرج من المدينة لا يريد القتال، ولذلك لم يخرج معه إلا ثلاثمائة وبضعة عشر رجلًا فقط؛ لأنهم كانوا يريدون أن يأخذوا إبلًا لقريش مُحملة قدمت من الشام تريد مكةَ وتَمُرُّ بالمدينة.
ثم ذكر بَيعته النبيَّ صلى الله عليه وسلم ليلة العقبة في مِنى، قبل الهجرة، حيث بايعوا النبي صلى الله عليه وسلم على الإسلام وقال: إنني لا أحب أن يكون لي بدلها شهود بدر؛ وإن كانت بدر أكثر ذكرًا، لأن الغزوة اشتهرت بخلاف البيعة.
كان رضي الله عنه قوي البدن، ياسر الحال، حتى إنه كان عنده راحلتان في تلك الغزوة، وما جمع راحلتين في غزوة قبلها أبدًا، وقد استعد وتجهز رضي الله عنه وكان من عادة النبي صلى الله عليه وسلم أنه إذا أراد غزوة وَرَّى بغيرها فيظهر خلاف ما يريد، وهذا من حكمته وحنكته في الحرب؛ لأنه لو أظهر ما يقصده تبين ذلك لعدوه، فربما يستعد له أكثر، وربما يذهب عن مكانه الذي قصده النبي صلى الله عليه وسلم فيه؛ إلا في غزوة تبوك، فإن النبي صلى الله عليه وسلم بين أمرها ووضحها وجَلَّاها لأصحابه، وأخبر أنه خارج إلى تبوك إلى عدوٍّ كثير، وإلى مكان بعيد حتى يستعد الناس.
فخرج المسلمون مع رسول الله صلى الله عليه وسلم ولم يتخلف إلا من خذله الله بالنفاق، وثلاثة رجال فقط من المؤمنين، هم: كعب بن مالك، ومرارة بن الربيع، وهلال بن أمية رضي الله عنهم ، لكن تخلفوا لأمر أراده الله عز وجل أما غيرهم ممن تخلف فإنهم منافقون منغمسون في النفاق، نسأل الله العافية.
فخرج النبي -عليه الصلاة والسلام- بأصحابه وهم كثير، إلى جهة تبوك حتى نزل بها، ولكن الله تعالى لم يجمع بينه وبين عدوه، بل بقي عشرين يوماً في ذلك المكان، ثم انصرف بغير حرب.
يقول كعب بن مالك رضي الله عنه إن الرسول صلى الله عليه وسلم تجهز هو والمسلمون وخرجوا من المدينة، أما هو رضي الله عنه فتأخر وجعل يغدو كل صباح يرحِّل راحلته ويقول: سوف ألحق بهم، ولكنه لا يفعل شيئًا، ثم يفعل كل يوم كذلك، حتى تمادى به الأمر ولم يدرك.
يقول: فكان يحز في نفسه أنه إذا خرج إلى سوق المدينة، وإذا المدينة ليس فيها أحد من المهاجرين ولا الأنصار، وليس فيها إلا رجل مغموس في النفاق -والعياذ بالله- قد غمسه نفاقه فلم يخرج، أو رجل معذور عذره الله عز وجل. فكان يعتب على نفسه: كيف لا يبقى في المدينة إلا هؤلاء وأقعد معهم، ورسول الله صلى الله عليه وسلم لم يذكره ولم يسأل عنه حتى وصل إلي تبوك.
فبينما هو جالس وأصحابه في تبوك سأل عنه، فقال رسول الله: أين كعب بن مالك؟ فتكلم فيه رجل من بني سلمة وغمزه، ولكن دافع عنه معاذ بن جبل رضي الله عنه فسكت النبي صلى الله عليه وسلم ولم يجب بشيء، لا على الذي غمزه ولا على الذي رد.
فبينما هو كذلك إذ رأى رجلا لابسا البياض يتحرك به السراب من بعيد، فقال النبي صلى الله عليه وسلم: "كن أبا خيثمة الأنصاري" فكان أبا خيثمة، وهذا معناه الفراسة والتمني أن يصبح هذا القادم من بعيد هو أبو خيثمة.
وأبو خثيمة هذا هو الذي تصدق بصاع عندما حث النبي صلى الله عليه وسلم على الصدقة، فتصدق الناس كل بحسب حاله. فكان الرجل إذا جاء بالصدقة الكثيرة قال المنافقون: هذا مُراءٍ ما أكثر الصدقة ابتغاء وجه الله، وإذا جاء الرجل الفقير بالصدقة اليسيرة قالوا: إن الله غَنِيٌّ عن صاعِ هذا.
يقول رضي الله عنه : إنه لما بلغه أن النبي صلى الله عليه وسلم رجع قافلًا من الغزو، بدأ يفكر ماذا يقول لرسول الله صلى الله عليه وسلم إذا رجع؟ يريد أن يتحدث بحديث وإن كان تورية، من أجل أن يعذره النبي صلى الله عليه وسلم فيه، وجعل يشاور ذوي الرأي من أهله ماذا يقول، ولكن يقول رضي الله عنه : فلما بلغه قرب النبي صلى الله عليه وسلم زال عنه الباطل، وعزم على أن يبين للنبي صلى الله عليه وسلم الحق، يقول: فقدم النبي صلى الله عليه وسلم المدينة ودخل المسجد، وكان من عادته وسنته أنه إذا قدم بلده فأول ما يفعل أن يصلي في المسجد عليه الصلاة والسلام.
فدخل المسجد وصلى وجلس للناس فجاءه المخلفون الذين تخلفوا من غير عذر من المنافقين، وجعلوا يحلفون له إنهم معذورون، فيبايعهم ويستغفر لهم؛ ولكن ذلك لا يفيدهم والعياذ بالله؛ لأن الله تعالى قال: {اسْتَغْفِرْ لَهُمْ أَوْ لا تَسْتَغْفِرْ لَهُمْ إِنْ تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً فَلَنْ يَغْفِرَ اللَّهُ لَهُمْ} (التوبة: من الآية80)، فيقول: أما أنا فعزمت أن أصدق النبي -عليه الصلاة والسلام- وأخبره بالصدق، فدخلت المسجد فسلمت عليه، فتبسم تبسم المغضب ثم قال: "تعال" فلما دنوت منه قال لي: "ما خلفك؟". فقال رضي الله عنه : يا رسول الله إني لم أتخلف لعذر، وما جمعت راحلتين قبل غزوتي هذه، وإني لو جلست عند أحد من ملوك الدنيا لخرجت منه بعذر، فلقد أوتيت جدلًا- يعني لو أني جلست عند شخص من الملوك لعرفت كيف أتخلص منه لأن الله أعطاني جدلًا- ولكني لا أحدثك اليوم حديثا ترضى به عني فيوشك أن يسخطك الله علي في ذلك.
فصدقه القول وأخبره أنه لا عذر له لا في بدنه ولا في ماله، بل إنه لم يجمع راحلتين في غزوة قبل هذه.
فقال النبي صلى الله عليه وسلم : "أما هذا فقد صدق" ويكفي له فخرًا أن وصفه النبي -عليه الصلاة والسلام- بالصدق: "أما هذا فقد صدق، فاذهب حتى يقضي الله فيك ما شاء". 
فذهب الرجل مستسلمًا لأمر الله عز وجل مؤمناً بالله، وأنه ما شاء الله كان، وما لم يشأ لم يكن.
فلحقه قوم من بني سلمة من قومه وجعلوا يزينون له أن يرجع عن إقراره، وقالوا له: إنك لم تذنب ذنبًا قبل هذا، ويكفيك أن يستغفر لك رسول الله صلى الله عليه وسلم وإذا استغفر لك الرسول صلى الله عليه وسلم غفر الله لك، فارجع كذب نفسك، قل إني معذور، حتى يستغفر لك الرسول -عليه الصلاة والسلام- فيمن استغفر لهم ممن جاؤوا يعتذرون إليه، فهم أن يفعل- رضي الله عنه- ولكن الله سبحانه أنقذه وكتب له هذه المنقبة العظيمة التي تتلى في كتاب الله إلى يوم القيامة.
فسال قومه: هل أحد صنع مثلما صنعت؟ قالوا: نعم، هلال بن أمية ومرارة بن الربيع، قالا مثلما قلت، وقيل لهما مثلما قيل لك، قال: فذكروا لي رجلين صالحين شهدا بدرًا لي فيهما أسوة.
فأمر النبي -عليه الصلاة والسلام- الناس أن يهجروهم فلا يكلموهم.
فهجرهم المسلمون، ولكنهم بعد ذلك صاروا يمشون وكأنهم بلا عقول، قد ذهلوا، وتنكرت لهم الأرض فما هي بالأرض التي كانوا يعرفونها؛ لأنهم يمشون إن سلموا لا يرد عليهم السلام، وإن قابلهم أحد لم يبدأهم بالسلام. وحتى النبي -عليه الصلاة والسلام- وهو أحسن الناس خلقاً لا يسلم عليهم.
يقول كعب: كنت أحضر وأسلم على النبي صلى الله عليه وسلم فلا أدري: أحرك شفتيه برد السلام أم لا.
فضاقت عليهم الأرض وضاقت عليهم أنفسهم وظنوا أن لا ملجأ من الله إلا إليه، وبقوا على هذه الحال مدة خمسين يوما والناس قد هجروهم فلا يسلمون عليهم، ولا يردون السلام إذا سلموا.
فضاقت عليهم الأمور وصعبت عليهم الأحوال، وفروا إلى الله عز وجل ، ولكن مع ذلك لم يكن كعب بن مالك يدع الصلاة مع الجماعة.
فكان يحضر ويسلم على النبي -عليه الصلاة والسلام- ولكن في آخر الأمر ربما يتخلف عن الصلوات؛ لما يجد في نفسه من الضيق والحرج؛ لأنه يخجل أن يأتي إلى قوم يصلي معهم وهم لا يكلمونه أبدًا، لا بكلمة طيبة ولا بكلمة تأنيب.
قال: "فأما صاحباي فاستكانا في بيوتهما يبكيان"؛ لأنهما لا يستطيعان أن يمشيا في الأسواق، والناس قد هجروهم لا يلتفت إليهم أحد، ولا يسلم عليهم أحد، وإذا سلموا لا يرد عليهم السلام، فعجزوا عن تحمل هذه الحال، فبقيا في بيوتهما يبكيان.
يقول: وكنت أنا أقواهم وأصبرهم لأنه كان أصغرهم سنا؛ فكان يشهد صلاة الجماعة مع المسلمين، ويطوف بأسواق المدينة لا يكلمه أحد؛ لأن النبي صلى الله عليه وسلم أمر بهجرهم، وكان الصحابة رضي الله عنهم أطوع الناس لرسول الله صلى الله عليه وسلم .
يقول: كنت أصلي وأسارق النبي صلى الله عليه وسلم النظر، يعني: أنظر إليه أحيانًا وأنا أصلي، فإذا أقبلت على صلاتي نظر إلي وإذا التفت إليه أعرض عني، كل هذا من شدة الهجر.
يقول: "فبينما أنا أمشي ذات يوم في أسواق المدينة وطال علي جفوة الناس، تسورت حائطًا –أي: دخله من فوق الجدار- لأبي قتادة رضي الله عنه ، فسلمت عليه، فوالله ما رد علي السلام"، وهو ابن عمه وأحب الناس إليه، ومع ذلك لم يرد عليه السلام، كل هذا طاعة لله ورسوله. فقال له: أنشدك الله، هل تعلم أني احب الله ورسوله؟ فلم يرد عليه. مرتين يناشده وأبو قتادة لم يرد عليه، وهو يعلم أن كعب بن مالك يحب الله ورسوله. فلما رد عليه الثالثة وقال: أنشدك الله هل تعلم أني أحب الله ورسوله؟ فقال: الله ورسوله أعلم. لم يكلمه، فلم يقل: نعم؟ ولا قال: لا. يقول: فبكى ثم خرج إلى السوق، فبينما هو يمشي إذا برجل نبطي من أنباط الشام يقول: من يدلني على كعب بن مالك؟ قلت: أنا هو، فأعطاني الورقة، وكنت كاتباً؛ لأن الكتاب في ذلك العهد قليلون جدًّا.
يقول: "فقرأت الكتاب، فإذا فيه: أما بعد، فقد بلغنا أن صاحبك جفاك -يعني الرسول عليه الصلاة والسلام، وكان هذا الملك: ملك غسان كافرًا- وإنك لست بدار هوان ولا مضيعة، فتعال إلينا نواسك بأموالنا، وربما نواسيك بملكنا. ولكن الرجل رجل مؤمن بالله تعالى ورسوله، ومحب لله ورسوله صلى الله عليه وسلم ، فقال: هذا أيضا من البلاء، ثم ذهب إلى التنور فأحرقها. 
ولما تمت لهم أربعون ليلة وأبطأ الوحي فلم ينزل أرسل إليهم النبي -عليه الصلاة والسلام- أن يعتزلوا نساءهم.
فقال كعب: أطلقها أم ماذا؟ لأنه لو قال طلِّقها لطلقها بكل سهولة؛ طاعة لله ورسوله، فسأل فقال: أطلقها أم ماذا؟ فقال له رسول الرسول: إن الرسول -عليه الصلاة والسلام- يأمرك أن تعتزل أهلك. وبقي على ظاهر اللفظ.
فقال كعب لزوجته الحقي بأهلك حتى يقضي الله هذا الأمر. فلحقت بأهلها.
وجاءت زوجة هلال بن أمية إلى رسول الله صلى الله عليه وسلم وأخبرته بأنه في حاجة إليها لتخدمه؛ لأنه ليس له خادم، فأذن لها النبي صلى الله عليه وسلم بشرط أن لا يقربها، فقالت: "إنه والله ما به من حركة إلي شيء" يعني أنه ليس له شهوة في النساء، وأنه يبكي رضي الله عنه منذ أمر النبي صلى الله عليه وسلم بهجرهم إلي يومه هذا، أربعون يومًا يبكي؛ لأنه ما يدري ماذا ستكون النهاية.
فقال لي بعض أهلي: لو استأذنت رسول الله صلى الله عليه وسلم في امرأتك فقد أذن لامرأة هلال بن أمية أن تخدمه؟ فقلت: لا أستأذن فيها رسول الله صلى الله عليه وسلم وما يدريني ماذا يقول رسول الله صلى الله عليه وسلم إذا استأذنته، وأنا رجل شاب! فلبثت بذلك عشر ليال فكمل لنا خمسون ليلة من حين نُهِيَ عن كلامنا.
يقول: "وكنت ذات يوم أصلي الصبح على سطح بيت من بيوتنا، فسمعت صارخًا يقول وهو على سَلْع -وهو جبل معروف في المدينة- أوفى عليه وصاح بأعلى صوته يقول: "يا كعب بن مالك أبشر"، يقول: "فخررت ساجدًا، وعرفت أنه قد جاء فرج"، وركب فارس من المسجد يؤم بيت كعب بن مالك ليبشره، وذهب مبشرون إلى هلال بن أمية ومرارة بن الربيع يبشرونهما بتوبة الله عليهما.
يقول: فجاء الصارخ الماشي على قدميه، وجاء صاحب الفرس، فكانت البشرى للصارخ؛ لأن الصوت أسرع من الفرس، يقول: فأعطيته ثوبي الإزار والرداء، وليس يملك غيرهما، لكن استعار من أهله أو من جيرانه ثوبين فلبسهما، وأعطى ثوبيه للذي بشره.
ثم نزل متوجها إلى الرسول صلى الله عليه وسلم في المسجد، وإذا رسول الله صلى الله عليه وسلم قد بشر الناس بعد صلاة الصبح بأن الله أنزل توبته على هؤلاء الثلاثة.
يقول: فذهبت أتأمم رسول الله صلى الله عليه وسلم يعني أقصده، فجعل الناس يلاقونني أفواجًا يهنئونني بتوبة الله عليَّ حتى دخلت المسجد.
يقول: فإذا رسول الله صلى الله عليه وسلم جالس وحوله أصحابه، فقام إلي طلحة بن عبيد الله رضي الله عنه فصافحني وهنأني بتوبة الله عليَّ.
يقول: والله ما قام إلي أحد من المهاجرين رجل غير طلحة، فكان لا ينساها له.
حتى وقف على النبي صلى الله عليه وسلم وإذا وجهه يبرق؛ لأنه -عليه الصلاة والسلام- سره أن يتوب الله على هؤلاء الثلاثة الذين صدقوا الله ورسوله، وأخبروا بالصدق عن إيمان، وحصل عليهم ما جرى من الأمر العظيم، من هجر الناس لهم خمسين يومًا، حتى نسائهم بعد الأربعين أَمَرَ الرسول -عليه الصلاة والسلام- أن يعتزلوهن.
ثم قال له النبي صلى الله عليه وسلم : "أبشر بخير يوم مر عليك مذ ولدتك أمك".
فقال له: "أمن عندك يا رسول الله أم من عند الله؟ قال: "لا بل من عند الله عز وجل"؛ لأنه إذا كان من عند الله كان أشرف وأفضل وأعظم.
فقال كعب: إن من توبته أن يتخلى عن ماله، ويجعله صدقة لله تعالى.
فقال النبي صلى الله عليه وسلم : "أمسك عليك بعض مالك فهو خير لك". قال: فإني أمسك سهمي الذي بخيبر.
ثم ذكر كعب بن مالك أن من توبته أن لا يحدث بحديث كذب بعد إذ نجاه الله تعالى بالصدق، وما زال كذلك ما حدث بحديث كذب أبدًا بعد أن تاب الله عليه، فكان رضي الله عنه مضرب المثل في الصدق، حتى إن الله أنزل فيه وفي صاحبيه: {يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ} (التوبة: 119).
وأنزل الله تعالى الآيات في بيان منته عليهم بالتوبة من قوله تعالى: {لَقَدْ تَابَ اللَّهُ عَلَى النَّبِيِّ وَالْمُهَاجِرِينَ وَالْأَنْصَارِ الَّذِينَ اتَّبَعُوهُ فِي سَاعَةِ الْعُسْرَةِ مِنْ بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ إِنَّهُ بِهِمْ رَءُوفٌ رَحِيمٌ (117) وَعَلَى الثَّلَاثَةِ الَّذِينَ خُلِّفُوا حَتَّى إِذَا ضَاقَتْ عَلَيْهِمُ الْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنْفُسُهُمْ وَظَنُّوا أَنْ لَا مَلْجَأَ مِنَ اللَّهِ إِلَّا إِلَيْهِ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُوا إِنَّ اللَّهَ هُوَ التَّوَّابُ الرَّحِيمُ (118) يَاأَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ (119)} (التوبة: 117: 119).
قال كعب: والله ما أنعم الله علي من نعمة قط، بعد إذ هداني الله للإسلام، أعظم في نفسي، من صدقي رسول الله صلى الله عليه وسلم ، أن لا أكون كذبته فأهلك كما هلك الذين كذبوا، إن الله قال للذين كذبوا، حين أنزل الوحي، شر ما قال لأحد، قال سبحانه : {سَيَحْلِفُونَ بِاللهِ لَكُمْ إِذَا انْقَلَبْتُمْ إِلَيْهِمْ لِتُعْرِضُوا عَنْهُمْ، فَأَعْرِضُوا عَنْهُمْ، إِنَّهُمْ رِجْسٌ، وَمَأْوَاهُمْ جَهَنَّمُ جَزَاءً بِمَا كَانُوا يَكْسِبُونَ، يَحْلِفُونَ لَكُمْ لِتَرْضَوْا عَنْهُمْ، فَإِنْ تَرْضَوْا عَنْهُمْ، فَإِنَّ اللهَ لَا يَرْضَى عَنِ الْقَوْمِ الْفَاسِقِينَ} [التوبة: 96]، قال: كنا خُلِّفنا أيها الثلاثة عن أمر أولئك الذين قبل منهم رسول الله صلى الله عليه وسلم حين حَلَفوا له، فبايعهم واستغفر لهم وأرجأ رسول الله صلى الله عليه وسلم أمرَنَا حتى قضى الله فيه بذلك، قال الله عز وجل: وعلى الثلاثة الذين خلفوا، وليس الذي ذكر الله مما خُلِّفْنا، تخلفنا عن الغزو، وإنما هو تخليفه إيانا، وإرجاؤه أمرنا، عمن حلف له واعتذر إليه فقبل منه".
وذكر رضي الله عنه أن النبي صلى الله عليه وسلم خرج من المدينة في يوم الخميس، وكان يحب أن يخرج في يوم الخميس.
وذكر أن النبي صلى الله عليه وسلم عاد إلى المدينة ضحى، وأنه دخل المسجد فصلى فيه ركعتين، وكان هذا من سنته صلى الله عليه وسلم أنه إذا قدم بلده لم يبدأ بشيء قبل المسجد.', 'أهمية صراحة المسلم وصدقه.
جواز إخبار الرجل عن تفريطه وتقصيره في طاعة الله ورسوله وعن سبب ذلك.
إباحة الغنيمة لهذه الأمة المرحومة حيث كانت محرَّمة على من قبلها من الأمم.
القتال يوم بدر لم يكن فرضًا عينيًّا.
جواز التحديث بنعمة الله عز وجل إذا لم يكن على سبيل الفخر والترفع والرياء.
بيعة العقبة كانت من أفضل مشاهد الصحابة -رضي الله عنهم- حتى إن كعبًا كان لا يراها دون مشهد بدر.
خطته صلى الله عليه وسلم الحكيمة على الصعيد العسكري، كمحافظته على سرية الخطط وحسن تقديره للموقف، وعدم تغريره بجنده ووضعهم في الصورة الواقعية حتى يكونوا على مستوى المهمة الملقاة على عاتقهم.
الإمام إذا راى مصلحة في أن يستر على الرعية بعض ما يهِم به، ويقصده من العدو؛ استحب له ذلك أو يتعين لحسب المصلحة.
الستر والكتمان إذا تضمن مفسدة لم يجُز.
اندفاع المسلمين إلى الجهاد في سبيل الله -عز وجل- عن رضا وطواعية رغم ما كانوا عليه من شدة.
تألم المسلم من تقصيره في أداء الواجب، وحرصه أن لا يكون من المتخلفين أو المنافقين.
لم يكن يتخلف عن رسول الله -صلى الله عليه وسلم- إلا أحد ثلاثة: إما منافق، أو رجل من أهل الأعذار، أو من خلفه رسول الله -صلى الله عليه وسلم- لمصلحة أو استعمله على المدينة.
الإمام والمطاع لا ينبغي أن يهمل من تخلف عنه في بعض الأمور بل يُذَكِّرْه ليراجع الطاعة ويتوب.
جواز الطعن في الرجل بما يغلب على اجتهاد الطاعن حمية أو ذبا عن الله ورسوله.
جواز الرد على الطاعن إذا غلب على ظن الرادِّ أنه وهم وغلط.
السنة للقادم من السفر أن يبدأ ببيت الله قبل بيته فيصلي فيه ركعتين.
يعامل الإنسان على ظاهره ويترك أمر باطنه إلى الله -عز وجل-.
تشديد الإسلام في هجر العصاة ولو بعزلهم عن المجتمع ليكون أبلغ في التأديب، وهذا إذا كان في الهجر مصلحة وفائدة للمهجور وللمجتمع.
حسن خلقه صلى الله عليه وسلم ورأفته في صحبه وإشفاقه عليهم وسروره بسرورهم وفرحه بخيرهم.
المؤمن يبتلى في دينه ودنياه، ومن أراد الله به خيرا صدق مع الله وثبت على ما عاهد عليه.
خير أيام العبد على الإطلاق وأفضلها يوم توبته إلى الله، وقبول الله لتوبته، ولكن في حقنا أمر غيبي، لكن المرجو أن كل تائب حقق شروط التوبة وأخلص أن الله -تعالى- يتوب عليه.', 'تخلَّف عن رسول الله صلى الله عليه وسلم : لم يخرج معه إلى الجهاد.
بدر : اسم لماء بين مكة والمدينة، وبه سمي المكان الذي وقعت فيه المعركة المشهورة بين رسول الله -صلى الله عليه وسلم- والمشركين.
العير : الإبل التي عليها أحمالها.
ميعاد : موعد واتفاق.
ليلة العقبة : هي الليلة التي بايع فيها الأنصار النبي -صلى الله عليه وسلم- على الإسلام وأن يؤيدوه وينصروه، وهي بيعة العقبة الثانية.
تواثقنا : تبايعنا عليه وتعاهدنا.
ما أحب أن لي بها مشهد بدر : لا أتمنى أني شهدت بدرا ولم أشهد ليلة العقبة.
أَذْكَر في الناس : أشهر ذكرا في الفضيلة.
وَرَّى بغيرها : أي أوهم أنه يريد غزوة غيرها.
مفازًا : هي الصحراء التي لا ماء فيها، سميت بذلك تفاؤلا بالفوز في اجتيازها.
فجلَّى : كشف وأوضح مقصده الذي يريده من غير تورية.
ليتأهبوا : ليستعدوا بما يحتاجون إليه في سفرهم.
الأُهبة : العُدة.
بوجههم : بمقصدهم الذي يتجهون إليه.
طابت : أينعت ونضجت.
الديوان : الدفتر الذي يكتب فيه أسماء الجيش وأهل العطاء.
أصْعَرُ : أميل.
طَفِقتُ : جعلتُ.
يتمادى بي : تمادى به الأمر: تطاول وتأخر.
الجِد : الاجتهاد في أمر السفر وشؤونه.
جهازي : حاجيات سفري.
تفارط الغزو : فات وقته وتقدم.
مغموصًا : مطعونا في دينه.
رجل من بني سلمة : بنو سلمة: بطن من الأنصار، والرجل هو عبد الله بن أنيس.
حبسه : منعه
برداه : مثنى برد، وهو الإزار أو الرداء، والبرود ثياب من اليمن فيها خطوط.
عِطفيه : جانبيه.
مُبَيِّضًا : لابس البياض.
يزول به السراب : يتحرك.
السراب : ما يظهر للإنسان من بُعد كالماء وقت اشتداد الحر.
لَمَزه : طعن فيه.
قافلا : راجعا.
بَثِّي : البث: أشد الحزن.
أظل قادما : أقبل ودنا.
زاح : زال وذهب
أجمعتُ : عزمت على أن أصدقه.
المخلفون : هم الذين لم يخرجوا مع النبي -صلى الله عليه وسلم- إلى تبوك وتخلفوا عنه.
بِضعا : البِضع: ما بين الثلاثة والعشرة.
المغضب : الغضبان.
ابتعت : اشتريت.
جدلا : فصاحة وقوة في الكلام.
تجد عليَّ : تغضب.
إني لأرجو فيه عقبى الله : أن يعقبني خيرًا وأن يثيبني عليه.
ثار : وثب ونهض.
يؤنبونني : يلومونني أشد اللوم.
تنكرت : تغيرت.
فاستكانا : ذلَّا وخضعا.
أشبُّ القوم : أصغرهم سِنًا.
أجلَدُهم : أقواهم.
أطوف : أمشي دائرا.
أسارقه النظر : أنظر إليه في خفية.
جفوة : إعراض.
تسورت : علوت سورا.
حائط : بستان.
أنشدك : أسألك.
توليت : رجعت من حيث أتيت.
نَبَطِي : فلاح.
طفق : أخذ.
ملك غسان : هو جبلة بن الأيهم.
دار هوان : دار تهان فيها.
ولا مضيعة : دار يضيع فيها حقك.
نواسيك : من المواساة، أي: نخفف عنك.
البلاء : الابتلاء والاختبار من الله -تعالى-.
فتيممت : قصدت.
التنور : ما يُخبز فيه.
فسجرتها : أوقدتها وأحرقتها.
استلبث : أبطأ.
اعتزلها : لا تخالطها مخالطة الأزواج من الجماع ومقدماته.
شيخ : من أدْرك الشيخوخة وَهِي غَالِبا عِنْد الْخمسين.
لا يقربنك : إشارة إلى منع الجماع.
رحبت : وسعت.
أوفى : صعد وارتفع.
سلع : جبل في المدينة.
فآذن : أعْلَمَ.
قِبَلَ صاحِبَيَّ : جهتهما.
ركض فرسا : ضربها برجله يستحثها على العَدْو.
أتأمم : أقصد.
لتهنك توبة الله عليك : لتفرح وتسعد.
يبرق : يلمع، وهو كناية عن السرور.
استنار : زاد نورا على نوره.
الفوج : الجماعة.
أنخلع : أخرج، والمراد: أتصدق.
سهمي : نصيبي.
أبلاه الله : أنعم عليه.
ساعة العسرة : وقت الشدة.
أرجأ : أخَّرَ.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4820', false),
(20022, 2, 201, 22, 'hadith', 'عن أبي نجيد- ضم النون وفتح الجيم - عمران بن الحصين الخزاعى رضي الله عنهما أن امرأة من جهينة أتت رسول الله صلى الله عليه وسلم وهى حبلى من الزنى، فقالت: يا رسول الله أصبت حداً فأقمه علي، فدعا نبي الله صلى الله عليه وسلم وليها فقال: أحسن إليها، فإذا وضعت فأتني، ففعل فأمر بها نبي الله صلى الله عليه وسلم، فشدت عليها ثيابها، ثم أمر بها فرجمت، ثم صلى الله عليه وآله وسلم عليها. فقال له عمر: تصلى عليها يا رسول الله وقد زنت، قال: لقد تابت توبة لو قمست بين سبعين من أهل المدينة لوستعتهم، وهل وجدت أفضل من أن جادت بنفسها لله عز وجل ؟! " رواه مسلم.', 'A woman from the tribe Juhainah came to Messenger of Allah (ﷺ) while she was pregnant from (Zina) adultery and said to him: "O Messenger of Allah! I have committed an offense liable to Hadd (prescribed punishment), so exact the execution of the sentence." Messenger of Allah (ﷺ) called her guardian and said to him, "Treat her kindly. Bring her to me after the delivery of the child." That man complied with the orders. At last the Prophet (ﷺ) commanded to carry out the sentence. Her clothes were secured around her and she was stoned to death. The Prophet (ﷺ) led her funeral prayers. ''Umar submitted: "O Messenger of Allah! She committed Zina and you have performed funeral prayer for her?" He replied, "Verily, she made repentance which would suffice for seventy of the people of Al-Madinah if it is divided among them. Can there be any higher degree of repentance than that she sacrificed her life voluntarily to win the Pleasure of Allah, the Exalted?"..', 'أبي نجيد- ضم النون وفتح الجيم - عمران بن الحصين الخزاعى رضي الله عنهما', 'Imran bin Al-Husain Al-Khuza''i (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 22', 'Riyad as-Salihin 22', 'ریاض الصالحین 22', null, 'جاءت امرأة من جهينة إلى النبي صلى الله عليه وسلم وهي حاملٌ قد زنت رضي الله عنها، فأخبرته أنها قد أصابت شيئا يوجب عليها الحد؛ ليقيمه عليها، فدعا النبي صلي الله عليه وسلم وليها، وأمره أن يحسن إليها، فإذا وضعت فليأت بها إليه، فلما وضعت أتى بها وليها إلى النبي صلي الله عليه وسلم، فلفت ثيابها وربطت لئلا تنكشف، ثم أمر بها فرجمت بالحجارة حتى ماتت، ثم صلى عليها النبي صلى الله عليه وسلم ودعا لها دعاء الميت، فقال له عمر رضي الله عنه: تصلي عليها يا رسول الله وقد زنت؟ فأخبره النبي صلى الله عليه وسلم أنها قد تابت توبة واسعة لو قسمت على سبعين من المذنبين لوسعتهم ونفعتهم، فإنها جاءت سلمت نفسها من أجل التقرب إلى الله عز وجل والخلوص من إثم الزنى؛ فهل هناك أعظم من هذا؟.', 'من خلق المؤمن التألم والندم إذا فرط منه الذنب، وحرصه على تطهير نفسه من لوثة الإثم ولو كان في ذلك هلاك نفسه، ليلقى الله عز وجل وهو عنه راض.
العقوبة الدنيوية تكفر ذنب المعصية إذا اقترن ذلك بالندم والتوبة.
لا يقام حد الزنى على الحامل حتى تضع حملها، فإن كان حدها الجلد فحتى تطهر من نفاسها، وإن كان الرجم فحتى يستغني الولد عنها ولو بلبن غيرها.
أنه يصلى على المرجوم؛ لأنه مسلم.', 'امرأة من جهينة : هي خولة بنت خويلد، وعند مسلم: (من غامد) وهي بطن من جهينة، كما ذكر النووي.
أصبت حدا : أي: فعلت ما يعاقب عليه بحد، والحد العقوبة المقدرة شرعًا لحق الله -تعالى-.
فشدت : أي: جمعت أطرافها لتستر.
توبة : التوبة: الاعتراف والندم والإقلاع والعزم على ألا يعاود الإنسان ما اقترفه.
سبعين : أي من العصاة.
لوسعتهم : لكفتهم في رفع آثامهم.
أفضل : أعظم.
جادت بنفسها : بذلتها لمرضاة الله تعالى.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3380', false),
(20023, 2, 201, 23, 'hadith', 'عن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: « لو أن لابن آدم وادياً من ذهب أحب أن يكون له واديان، ولن يملأ فاه إلا التراب، ويتوب الله على من تاب».', 'Messenger of Allah (ﷺ) said, "If a son of Adam were to own a valley full of gold, he would desire to have two. Nothing can fill his mouth except the earth (of the grave). Allah turns with mercy to him who turns to Him in repentance"..', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas and Anas bin Malik (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 23', 'Riyad as-Salihin 23', 'ریاض الصالحین 23', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20024, 2, 201, 24, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «يضحك الله سبحانه وتعالى إلى رجلين يقتل أحدهما الآخر يدخلان الجنة، يقاتل هذا في سبيل الله فيقتل، ثم يتوب الله على القاتل فيسلم فيستشهد».', 'Messenger of Allah (ﷺ) said, "Allah, the Exalted, smiles at two men, one of them killed the other and both will enter Jannah. The first is killed by the other while he is fighting in the Cause of Allah, and thereafter Allah will turn in mercy to the second and guide him to accept Islam and then he dies as a Shaheed (martyr) fighting in the Cause of Allah."', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 24', 'Riyad as-Salihin 24', 'ریاض الصالحین 24', 'متفق عليه', 'يضحك الله إلى رجلين يقتل أحدهما الآخر يدخلان الجنة، يقاتل المسلم في سبيل الله لإعلاء كلمة الله فيقتله كافر فيدخل الجنة، ثم يتوب الله على القاتل فيُسلم فيقاتل في سبيل الله فيستشهد.', 'إثبات صفة الضحك لله -تعالى-.
وجوب التوبة من الذنب مهما كبر، وعدم اليأس من رحمة الله -تعالى-.
الإسلام يمحو ما قبله من جريمة الكفر، والتوبة تمحو ما قبلها من الآثام.
الاستشهاد في سبيل الله من موجبات الجنة.
فيه دليل على أن الأعمال بالخواتيم.', 'يضحك الله : الضحك معلوم، وإثباته يكون على ما يليق بجلاله سبحانه وتعالى، من غير تكييف ولا تمثيل، ومن غير تعطيل ولا تشبيه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5461', false),
(20025, 2, 201, 25, 'hadith', 'عن أبي مالك الحارث بن عاصم الأشعري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «الطهور شطر الإيمان، والحمد لله تملأ الميزان، وسبحان الله والحمد لله تملآن -أو تملأ- ما بين السماوات والأرض، والصلاة نور، والصدقة برهان، والصبر ضياء، والقرآن حجة لك أو عليك. كل الناس يغدو، فبائع نفسه فمعتقها، أو موبقها».', 'The Messenger of Allah (ﷺ) said: "Purity is half of faith, and the praise of Allah fills the scale. Glorification and praise fill up what is between the heavens and the earth. Prayer is a light, charity is proof, and patience is illumination. The Quran is a proof for you or against you. All people go out early in the morning and sell themselves, either setting themselves free or ruining themselves."..', 'أبي مالك الحارث بن عاصم الأشعري رضي الله عنه', 'Abu Malik Al-Harith bin Asim Al-Ash''ari (May Allah be pleased with him) reported that:', 'صحيح', 'رياض الصالحين 25', 'Riyad as-Salihin 25', 'ریاض الصالحین 25', 'رواه مسلم', 'يخبر النبي صلى الله عليه وسلم: أن طهارة الظاهر تكون بالوضوء والغسل وهي شرط في الصلاة. 
وأن قول: " الحمد لله تملا الميزان" وهو الثناء عليه سبحانه، ووصفه بصفات الكمال توزن يوم القيامة فتملأ ميزان الأعمال. 
وأن قول: "سبحان الله والحمد لله" وهو تنزيهه عن كل نَقْصٍ ووصفه بالكمال التام الذي يليق بجلاله مع محبته وتعظيمه تملأ ما بين السموات والأرض. 
وأن "الصلاة نور" للعبد في قلبه، وفي وجهه، وفي قبره، وفي حشره. 
وأن "الصدقة برهان" ودليل على صدق إيمان المؤمن، واختلافه عن المنافق الذي يمتنع منها لكونه لا يصدق بموعودها. 
وأن "الصبر ضياء" -وهو حبس النفس عن الجَزَع والتَّسَخُّط - نور يحصل معه حرارة وإحراق، كضياء الشمس؛ لأنه شاق ويحتاج إلى مجاهدة النفس وحبسها عما تهواه؛ فلا يزال صاحبه مستضيئًا مهتديًا مستمرًّا على الصواب. وهو صبر على طاعة الله، وعن معصيته، وصبر على المصائب وأنواع المكاره في الدنيا. 
وأن "القرآن حجة لك" بتلاوته والعمل به، أو "حجة عليك" بتركه دون عمل أو تلاوة. 
ثم أخبر صلى الله عليه وسلم أن كل الناس يسعون وينتشرون ويقومون من نومهم ويخرجون من بيوتهم لأعمالهم المختلفة، 
فمنهم من يستقيم على طاعة الله فيُعْتِق نفسَه من النار، ومنهم من ينحرف عن ذلك ويقع في المعاصي فيهلكها بدخولها النار.', 'الطهارة طهارتان: طهارة الظاهر تكون بالوضوء والغسل، وطهارة الباطن تكون بالتوحيد والإيمان والعمل الصالح.
أهمية المحافظة على الصلاة فهي نور للعبد في الدنيا ويوم القيامة.
الصدقة دليل على صدق الإيمان.
أهمية العمل بالقرآن وتصديقه ليكون حجة لك لا عليك.
النفس إن لم تشغلها بالطاعة شغلتك بالمعصية.
كل إنسان لا بد أن يعمل؛ فإما أن يعتق نفسه بالطاعة، أو يوبقها بالمعصية.
الصبر يحتاج إلى تَحَمُّلٍ واحتسابٍ وفيه مشقة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65004', false),
(20026, 2, 201, 26, 'hadith', 'عن أبي سعيد سعد بن مالك بن سنان الخدري رضي الله عنهما: "أن ناساً من الأنصار سألوا رسول الله صلى الله عليه وسلم فأعطاهم، ثم سألوه فأعطاهم ، حتى نفد ما عنده، فقال لهم حين أنفق كل شيء بيده : "ما يكن عندي من خير فلن أدخره عنكم ، ومن يستعفف يعفه الله، ومن يستغن يغنه الله، ومن يتصبر يصبره الله. وما أعطي أحد عطاءً خيراً وأوسع من الصبر".', 'Certain people of the Ansar asked the Messenger of Allah (ﷺ) and he gave them; then they again asked him and he gave them until all what he possessed was exhausted. Then the Prophet (ﷺ) said, "Whatever wealth I have, I will not withhold from you. Whosoever would be chaste and modest; Allah will keep him chaste and modest and whosoever would seek self-sufficiency, Allah will make him self-sufficient; and whosoever would be patient, Allah will give him patience, and no one is granted a gift better and more comprehensive than patience"..', 'أبي سعيد سعد بن مالك بن سنان الخدري رضي الله عنهما', 'Abu Sa''id Al-Khudri (May Allah be pleased with him) reported that:', 'صحيح', 'رياض الصالحين 26', 'Riyad as-Salihin 26', 'ریاض الصالحین 26', 'متفق عليه', 'سأل ناس من الأنصار رسول الله صلى الله عليه وسلم فأعطاهم ثم سألوه فأعطاهم، حتى نفد ما عنده، ثم أخبرهم أنه لا يمكن أن يدخر شيئا عنهم فيمنعهم، ولكن ليس عنده شيء، وحثهم على الاستعفاف والاستغناء والصبر.
فأخبرهم أنه من يستغن بما عند الله عما في أيدي الناس؛ يغنه الله عز وجل، فالغنى غنى القلب، فإذا استغنى الإنسان بما عند الله عما في أيدي الناس؛ أغناه الله عن الناس، وجعله عزيز النفس بعيدًا عن السؤال.
وأنه من يستعفف عما حرم الله عليه من النساء يعفه الله عز وجل ويحميه ويحمي أهله أيضًا.
وأنه من يتصبر يصبره الله، أي يعطيه الله الصبر.
وما من الله على أحد بعطاء من رزق، أو غيره؛ خيرًا وأوسع من الصبر.', 'كرم النبي صلى الله عليه وسلم وما جُبل عليه من مكارم الأخلاق.
ليس الغنى الممدوح في الشرع بكثرة المال والمتاع في يد صاحبه ولكن الغنى المحمود أن يكون الإنسان غني النفس بالله -تعالى-.
الترغيب بالقناعة والاستعفاف.
تُنال مكارم الأخلاق ومعالي الصفات بالصبر.
جواز إعطاء السائل مرتين.
جواز الاعتذار إلى السائل.
جواز السؤال للحاجة، وإن كان الأولى تركه والصبر حتى يأتي الله بالفرج.', 'نفذ : فني وذهب.
فلن أدخره : أي: لا أجعله ذخيرة لغيركم معرضا عنكم، أو لا أخبئه وأمنعكم إياه.
ومن يستعفف : أي: من طلب العفة عن سؤال الناس والاستشراف إلى ما في أيديهم.
يعفه الله : يرزقه الله العفة فيصير عفيفًا قنوعًا.
يغنه الله : أي: يجعله غني النفس ويفتح له أبواب الرزق.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4967', false),
(20027, 2, 201, 27, 'hadith', 'عن أبي يحيى صهيب بن سنان رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم «عجبا لأمر المؤمن إن أمره كله له خير، وليس ذلك لأحد إلا للمؤمن : إن أصابته سراء شكر فكان خيراً له، وإن أصابته ضراء صبر فكان خيراً له».', 'The Messenger of Allah (ﷺ) said, "How wonderful is the case of a believer; there is good for him in everything and this applies only to a believer. If prosperity attends him, he expresses gratitude to Allah and that is good for him; and if adversity befalls him, he endures it patiently and that is better for him"..', 'أبي يحيى صهيب بن سنان رضي الله عنه', 'Abu Yahya Suhaib bin Sinan (May Allah be pleased with him) reported that:', 'صحيح', 'رياض الصالحين 27', 'Riyad as-Salihin 27', 'ریاض الصالحین 27', 'رواه مسلم', 'يَتَعَجَّبُ صلى الله عليه وسلم مِن شأن المؤمن وأحواله على وجه الاستحسان؛ وذلك لأن أحواله كلها خير، وليس ذلك لأحد إلا للمؤمن؛ 
إن أصابته سرّاءُ شكرَ اللهَ عليها؛ فيحصل له الأجر بالشكر، 
وإن أصابته ضراءُ صبرَ واحتسب الأجر على الله، فيحصل له الأجر بالصبر، فهو في أجر على كل حال.', 'فضل الشكر على السراء والصبر على الضراء، فمَن فعَلَ ذلك حصل له خير الدارين، ومن لم يشكر على النعمة، ولم يصبر على المصيبة، فاته الأجر، وحصل له الوزر.
فضل الإيمان، وأنّ الأجر في كل حال لا يكون إلا لأهل الإيمان.
الشكر عند السراء، والصبر على الضراء من خصال المؤمنين.
الإيمان بقضاء الله وقدره يجعل المؤمن في رضا كامل على كل أحواله، بخلاف غير المؤمن الذي يكون في سخط دائم عند وقوع ضرر عليه، وإذا ما حاز نعمة من الله عز وجل انشغل بها عن طاعة الله، فضلًا عن صرفها في معصيته.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3298', false),
(20028, 2, 201, 28, 'hadith', 'عن أنس رضي الله عنه قال: لما ثقل النبي صلى الله عليه وسلم جعل يتغشاه الكرب فقالت فاطمة رضي الله عنها: واكرب أبتاه. فقال : «ليس على أبيك كرب بعد اليوم» فلما مات قالت : يا أبتاه أجاب رباً دعاه، يا أبتاه جنة الفردوس مأواه، يا أبتاه إلى جبريل ننعاه، فلما دفن قالت : فاطمة رضي الله عنها: أطابت أنفسكم أن تحثوا على رسول الله صلى الله عليه وسلم التراب؟.', 'When the last illness of Messenger of Allah (ﷺ) made him unconscious, Fatimah (May Allah be pleased with her) exclaimed: "Ah, the distress of my dear father." He (ﷺ) said, "There will be no distress for your father after today". When he died she said: "My father, Allah has called you back and you have responded to His Call. O father! Garden of Firdaus is your abode. O father! We announce to Jibril your death." When he was buried, she said: "Are you satisfied now that you put earth over (the grave of) Messenger of Allah (ﷺ)?"', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 28', 'Riyad as-Salihin 28', 'ریاض الصالحین 28', 'رواه البخاري', 'يُصوِّر هذا الحديث صبر نبينا صلى الله عليه وسلم على سكرات الموت، فلمَّا ثقل في مرضه الذي مات فيه جعل يغشى عليه من الكرب من شدة ما يصيبه؛ لأنه -عليه الصلاة والسلام- يتشدد عليه الألم والمرض، وهذا لحكمة بالغة: حتى ينال ما عند الله من الدرجات العلى جزاء صبره، فإذا غشيه الكرب تقول فاطمة رضي الله عنها : "وأكرب أبتاه" تتوجع له من كربه، لأنها امرأة، والمرأة لا تطيق الصبر.
فقال النبي -عليه الصلاة والسلام-: "لا كرب على أبيك بعد اليوم"؛ لأنه صلى الله عليه وسلم لما انتقل من الدنيا انتقل إلى الرفيق الأعلى، كما كان -صلى الله عليه وسلم -وهو يغشاه الموت- يقول "اللهم في الرفيق الأعلى، اللهم في الرفيق الأعلى وينظر إلى سقف البيت صلى الله عليه وسلم ".
توفي الرسول -عليه الصلاة والسلام-، فجعلت رضي الله عنها تندبه، لكنه ندب خفيف، لا يدل على التسخط من قضاء الله وقدره.
وقولها "أجاب ربا دعاه"؛ لأن الله تعالى هو الذي بيده ملكوت كل شيء، وآجال الخلق بيده.
فأجاب داعي الله، وهو أنه صلى الله عليه وسلم إذا توفي صار كغيره من المؤمنين، يصعد بروحه حتى توقف بين يدي الله سبحانه فوق السماء السابعة. 
وقولها: "وابتاه جنة الفردوس مأواه" صلى الله عليه وسلم ؛ لأنه -عليه الصلاة والسلام- أعلى الخلق منزلة في الجنة، كما قال النبي صلى الله عليه وسلم : "اسألوا الله لي الوسيلة؛ فإنها منزلة في الجنة لا تنبغي إلا لعبد من عباد الله، وأرجو أن أكون أنا هو"، ولا شك أن النبي صلى الله عليه وسلم مأواه جنة الفردوس، وجنة الفردوس هي أعلي درجات الجنة، وسقفها الذي فوقها عرش الرب جل جلاله، والنبي -عليه الصلاة والسلام- في أعلى الدرجات منها.
قولها: "يا أبتاه إلى جبريل ننعاه" وقالت: إننا نخبر بموته جبريل لأن جبريل هو الذي كان يأتيه ويدارسه بالوحي زمن حياته، والوحي مرتبط بحياة النبي -عليه الصلاة والسلام-.
ثمَّ لمَّا حُمِل ودفِن، قالت رضي الله عنها : "أطابت أنفسكم أن تحثوا على رسول الله صلى الله عليه وسلم التراب؟" يعني من شدة حزنها عليه، وحزنها وألمها على فِراق والدها، ومعرفتها بأن الصحابة رضي الله عنهم قد ملأ الله قلوبهم محبة الرسول -عليه الصلاة والسلام- سألتهم هذا السؤال، لكن الله سبحانه هو الذي له الحكم، وإليه المرجع، وكما قال الله تعالى في كتابة: (إِنَّكَ مَيِّتٌ وَإِنَّهُمْ مَيِّتُونَ).', 'في هذا الحديث بيان أن رسول الله -صلى الله عليه وسلم- كغيره من البشر، يمرض ويجوع، ويعطش، ويموت.
في الحديث رد على الذين يشركون بالرسول -صلى الله عليه وسلم-؛ يدعون الرسول -عليه الصلاة والسلام-، ويستغيثون به وهو في قبره، فهو عليه السلام ميت ولا يملك لهم شيئاً.
في الحديث دليل على جواز الندب اليسير إذا لم يكن مؤذنا بالتسخُّط على الله -عز وجل-؛ لأن فاطمة ندَبَت النبي عليه -الصلاة والسلام-، لكنه نَدْب يسير، وليس فيه اعتراض على قدر الله -عز وجل-.
في الحديث دليل: على أن فاطمة بنت محمد -صلى الله عليه وسلم- و -رضي الله عنها- بقيت بعد حياته -صلى الله عليه وسلم-، ولكن ليس لها ميراث؛ لأن الأنبياء لا يورثون.
جواز التوجُّع للميت عند احتضاره.
يجوز ذكر الميت بصفاته بعد موته دون رفع صوت ولا تسخط.
صبر النبي -عليه الصلاة والسلام- على ما هو فيه من سكرات الموت وشدائده.
ما بعد الحياة الدنيا خير للأنبياء -صلوات الله عليهم وسلامه- وكذلك أتباعهم.
الدنيا دار تعب ونصب، والآخرة لا شيء فيها من هذا للمؤمن.', 'ثَقُل : من شدة المرض.
يَتَغَشَّاه الكَرب : تنزل به الشدة من سكرات الموت، لعلو درجته وشرف رتبته، فإن أشد الناس بلاء الأنبياء.
واكَربَ أَبَتَاه : أي ما أشد وجع أبي، لم ترفع صوتها -رضي الله عنها- بذلك، كما يفعله بعض النساء عند المصيبة.
لَيسَ عَلَى أَبِيك كَرب : لا يصيبه نصب ولا وصب يجد له ألما؛ لأنه ينتقل من دار البلاء إلى دار الخلود والصفاء.
أجاب ربًّا دَعَاه : لبى نداءه، وفيه إشارة إلى ما ثبت عنه -صلى الله عليه وسلم- أنه خُيِّر؛ فاختار جوار ربه ولِقَاه.
الفِردَوس : بستان يجمع كل ما في البساتين من شجر وزهر، وجنة الفردوس أعلى الجنان.
مَأوَاه : منزله.
نَنعَاه : نرفع خبر وفاته -صلى الله عليه وسلم- إلى جبريل.
جبريل : هو اسم خاص لملك كريم خصَّه الله -تعالى- بالوحي.
تحثوا : حثو التراب: دفعه باليد، والمراد دفنه عليه -صلى الله عليه وسلم- بالتراب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3306', false),
(20029, 2, 201, 29, 'hadith', 'عن أبي زيد أسامة بن زيد بن حارثة مولى رسول الله صلى الله عليه وسلم وحبه وابن حبه، رضي الله عنهما، قال: أرسلت بنت النبي صلى الله عليه وسلم : إن ابني قد احتضر فاشهدنا، فأرسل يقرئ السلام ويقول: "إن لله ما أخذ، وله ما أعطى، وكل شيء عنده بأجل مسمى، فلتصبر ولتحتسب" فأرسلت إليه تقسم عليه ليأتينها. فقام ومعه سعد بن عبادة، ومعاذ بن جبل، وأبي بن كعب، وزيد بن ثابت، ورجال رضي الله عنهم، فرفع إلى رسول الله صلى الله عليه وسلم الصبي فأقعده في حجره ونفسه تقعقع، ففاضت عيناه، فقال سعد: يا رسول الله ماهذا؟ فقال: "هذه رحمة جعلها الله تعالى في قلوب عباده" وفى رواية : "في قلوب من شاء من عباده وإنما يرحم الله من عباده الرحماء".', 'The daughter of the Prophet (ﷺ) sent for him as her child was dying, but the Prophet (ﷺ) returned the messenger and sent her good wishes saying, "Whatever Allah takes away or gives, belongs to Him, and everything with Him has a limited fixed term (in this world), and so she should be patient and anticipate Allah''s reward." She again sent for him adjuring him for the sake of Allah to come. The Messenger of Allah, accompanied with Sa''d bin ''Ubadah, Mu''adh bin Jabal, Ubayy bin Ka''b, Zaid bin Thabit and some other men went to see her. The child was lifted up to the Messenger of Allah while his breath was disturbed in his chest. On seeing that, the eyes of the Prophet (ﷺ) streamed with tears. Sa''d said, "O Messenger of Allah! What is this?" He replied, "It is compassion which Allah has placed in the hearts of His slaves, Allah is Compassionate only to those among His slaves who are compassionate (to others)".Another version says: Messenger of Allah (ﷺ) said, "Allah shows compassion only to those among His slaves who are compassionate"..', 'أبي زيد أسامة بن زيد بن حارثة مولى رسول الله صلى الله عليه وسلم وحبه وابن حبه رضي الله عنهما', 'Usamah bin Zaid (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 29', 'Riyad as-Salihin 29', 'ریاض الصالحین 29', 'متفق عليه', 'ذكر أسامة بن زيد رضي الله عنهما أن إحدى بنات رسول الله صلى الله عليه وسلم أرسلت إليه رسولاً، تقول له إن ابنها قد احتضر، أي: حضره الموت. وأنها تطلب من النبي صلى الله عليه وسلم أن يحضر، فبلَّغ الرسول رسول الله صلى الله عليه وسلم فقال له النبي صلى الله عليه وسلم "مرها فلتصبر ولتحتسب، فإن لله ما أخذ وله ما أعطى، وكل شيء عنده بأجل مسمى".
أمر النبي -عليه الصلاة والسلام- الرجل الذي أرسلته ابنته أن يأمر ابنته -أم هذا الصبي- بهذه الكلمات:
قال: "فلتصبر" يعني على هذه المصيبة "ولتحتسب": أي: تحتسب الأجر على الله بصبرها؛ لأن من الناس من يصبر ولا يحتسب، لكن إذا صبر واحتسب الأجر على الله، يعني: أراد بصبره أن يثيبه الله ويأجره، فهذا هو الاحتساب.
قوله: "فإن لله ما أخذ وله ما أعطى": هذه الجملة عظيمة؛ إذا كان الشيء كله لله، إن أخذ منك شيئاً فهو ملكه، وإن أعطاك شيئاً فهو ملكه، فكيف تسخط إذا أخذ منك ما يملكه هو؟
ولهذا يسن للإنسان إذا أصيب بمصيبة أن يقول "إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ" يعني: نحن ملك لله يفعل بنا ما يشاء، وكذلك ما نحبه إذا أخذه من بين أيدينا فهو له سبحانه له ما أخذ وله ما أعطى، حتى الذي يعطيك أنت لا تملكه، هو لله، ولهذا لا يمكن أن تتصرف فيما أعطاك الله إلا على الوجه الذي أذن لك فيه؛ وهذا دليل على أن ملكنا لما يعطينا الله ملك قاصر، ما نتصرف فيه تصرفا مطلقاً.
ولهذا قال: "لله ما أخذ وله ما أعطى" فإذا كان لله ما أخذ، فكيف نجزع؟ كيف نتسخط أن يأخذ المالك ما ملك سبحانه وتعالى؟ هذا خلاف المعقول وخلاف المنقول!
قال: "وكل شيء عنده بأجل مسمى" كل شيء عنده بمقدار.
"بأجل مسمى" أي: معين، فإذا أيقنت بهذا؛ إن لله ما أخذ وله ماأعطى، وكل شيء عنده بأجل مسمى؛ اقتنعت. وهذه الجملة الأخيرة تعني أن الإنسان لا يمكن أن يغير المكتوب المؤجل لا بتقديم ولا بتأخير، كما قال الله تعالى: (لِكُلِّ أُمَّةٍ أَجَلٌ إِذَا جَاءَ أَجَلُهُمْ فَلا يَسْتَأْخِرُونَ سَاعَةً وَلا يَسْتَقْدِمُون) ، فإذا كان الشيء مقدراً لا يتقدم ولا يتأخر، فلا فائدة من الجزع والتسخط؛ لأنه وإن جزعت أو تسخطت لن تغير شيئاً من المقدور.
ثم إن الرسول أبلغ بنت النبي صلى الله عليه وسلم ما أمره أن يبلغه إياها، ولكنها أرسلت إليه تطلب أن يحضر، فقام -عليه الصلاة والسلام- هو وجماعة من أصحابه، فوصل إليها، فرفع إليه الصبي ونفسه تصعد وتنزل، فبكى الرسول -عليه الصلاة والسلام- ودمعت عيناه. فظن سعد بن عباده أن الرسول صلى الله عليه وسلم بكى جزعاً، فقال النبي -عليه الصلاة والسلام-: "هذه رحمة" أي بكيت رحمة بالصبي لا جزعاً بالمقدور.
ثم قال -عليه الصلاة والسلام-: "إنما يرحم الله من عباده الرحماء" ففي هذا دليل على جواز البكاء رحمة بالمصاب.', 'الحديث دليل على وجوب الصبر؛ لأن الرسول -صلى الله عليه وسلم- قال: "مرها فلتصبر ولتحتسب".
جواز طلب الحضور من ذوي الفضل للمحتضر، والدعاء للميت.
استحباب إبرار المقسم إذا اقسم عليك في فعل أمر جائز.
الترغيب في الشفقة على خلق الله والرحمة لهم.
الرهبة من قسوة القلب وجمود العين.
جواز البكاء من غير نوح.
تسلية من نزلت به المصيبة بما يخفف من ألم مُصابه.
جواز المشي مع الشخص المدعو إلى التعزية وإلى عيادة المريض من غير إذن الداعي، بخلاف الوليمة؛ لأنه قد لا يكون الطعام كافيًا.
استحباب أمر صاحب المصيبة بالصبر قبل وقوع الموت؛ ليقع وهو راض بقدر الله.
إخبار من يستدعى لأمر بالأمر الذي يستدعى من أجله.
جواز تكرار الدعوة.
وجوب تقديم السلام على الكلام.
عيادة المريض ولو كان مفضولا أو صبيا صغيرا من مكارم الأخلاق، ولذلك ينبغي على أهل الفضل ألا يقطعوا الناس عن فضلهم.
جواز استفهام التابع من إمامه وشيخه عما يشكل عليه.
تقديم حسن الأدب على السؤال ظاهر في قول سعد بن عبادة: يا رسول الله ما هذا.', 'احتُضِر : اقترب موته.
اشهدنا : تطلب منه الحضور.
لتَحتَسِب : تنوي بصبرها طلب الثواب من ربِّها؛ ليحسب لها ذلك من العمل الصالح.
تَقَعقَع : تتحرك وتضطرب.
فاضت عيناه : امتلأت عيناه بالدموع حتى سالت على وجهه -صلى الله عليه وسلم-.
بنت النبي : هي زينب -رضي الله عنها-
بأجل مسمى : معلوم مقدر، والأجل يطلق على الجزء الأخير، وعلى مجموع العمر.
الرحماء : جمع رحيم، وهو من صيغ المبالغة من الرحمة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3290', false),
(20030, 2, 201, 30, 'hadith', 'عن صهيب رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: « كان ملك فيمن كان قبلكم، وكان له ساحرٌ، فلما كبر قال للملك : إني قد كبرت فابعث إلى غلاماً أعلمه السحر؛ فبعث إليه غلاماً يعلمه، وكان في طريقه إذا سلك راهبٌ، فقعد إليه وسمع كلامه فأعجبه، وكان إذا أتى الساحر مر بالراهب وقعد إليه، فإذا أتى الساحر ضربه، فشكا ذلك إلى الراهب فقال: إذا خشيت الساحر فقال: حبسني أهلي، وإذا خشيت أهلك فقل: حبسني الساحر. فبينما هو على ذلك إذ أتى على دابةٍ عظيمةٍ قد حبست الناس فقال: اليوم أعلم آلساحر أفضل أم الراهب أفضل؟ فآخذ حجراً فقال: اللهم إن كان أمر الراهب أحب إليك من أمر الساحر فاقتل هذه الدابة حتى يمضي الناس، فرماها فقتلها ومضى الناس، فأتى الراهب فأخبره. فقال له الراهب: أي بني أنت اليوم أفضل مني، قد بلغ أمرك ما أرى، وإنك ستبتلى، فإن ابتليت فلا تدل علي؛ وكان الغلام يبرئ الأكمه والأبرص، ويداوي الناس من سائر الأدواء. فسمع جليس للملك كان قد عمي، فأتاه بهدايا كثيرةٍ فقال: ما هاهُنا لك أجمع إن أنت شفيتنى، فقال: إني لا أشفي أحداً إنما يشفى الله تعالى، فإن آمنت بالله دعوت الله فشفاك، فآمن بالله تعالى فشفاه الله تعالى، فأتى الملك فجلس إليه كما كان يجلس فقال له الملك: من ردّ عليك بصرك؟ فقال: ربي قال: ولك رب غيري ؟( قال: ربي وربك الله، فأخذه فلم يزل يعذبه حتى دل على الغلام، فجئ بالغلام فقال له الملك: أى بني قد بلغ من سحرك ما تبرئ الأكمه والأبرص وتفعل وتفعل فقال: إني لا أشفي أحداً، إنما يشفي الله تعالى، فأخذه فلم يزل يعذبه حتى دل على الراهب؛ فجيء بالراهب فقيل له: ارجع عن دينك، فأبى ، فدعا بالمنشار فوضع المنشار في مفرق رأسه، فشقه حتى وقع شقاه، ثم جيء بجليس الملك فقيل له: ارجع عن دينك فأبى، فوضع المنشار في مفرق رأسه، فشقه به حتى وقع شقاه، ثم جيء بالغلام فقيل له ارجع عن دينك فأبى، فدفعه إلى نفر من أصحابه فقال: اذهبوا به إلى جبل كذا وكذا فاصعدوا به الجبل فقال: اللهم اكفنيهم بما شئت، فرجف بهم الجبل فسقطوا، وجاء يمشي إلى الملك، فقال له الملك: ما فعل أصحابك؟ فقال: كفانيهم الله تعالى، فدفعه إلى نفر من أصحابه فقال : اذهبوا به فاحملوه في قرقور وتوسطوا به البحر، فإن رجع عن دينه وإلا فاقذفوه، فذهبوا به فقال: اللهم اكفنيهم بما شئت، فانكفأت بهم السفينة فغرقوا، وجاء يمشي إلى الملك. فقال له الملك : ما فعل أصحابك؟ فقال: كفانيهم الله تعالى. فقال الملك إنك لست بقاتلي حتى تفعل ما آمرك به. قال : ما هو؟ قال : تجمع الناس في صعيد واحد، وتصلبني على جذع ، ثم خذ سهماً من كنانتي، ثم ضع السهم في كبد القوس ثم قل: بسم الله رب الغلام ثم ارمني، فإنك إن فعلت ذلك قتلتني . فجمع الناس في صعيد واحد، وصلبه على جذع، ثم أخذ سهما من كنانته، ثم وضع السهم في كبد القوس، ثم قال: بسم الله رب الغلام، ثم رماه فوقع السهم في صدغه، فوضع يده في صدغه فمات. فقال الناس آمنا برب الغلام، فأتى الملك فقيل له: أرأيت ما كنت تحذر قد والله نزل بك حذرك. قد آمن الناس. فأمر بالأخدود بأفواه السكك فخدت وأضرم فيها النيران وقال: من لم يرجع عن دينه فأقحموه فيها أو قيل له : اقتحم ، ففعلوا حتى جاءت امرأة ومعها صبى لها، فتقاعست ان تقع فيها، فقال لها الغلام: يا أماه اصبري فإنك على الحق».', '''I have grown old, so send me a young boy in order to teach him magic.'' The king sent him a young boy to serve the purpose. And on his way (to the magician) the young boy met a monk to whom he listened to and liked it. It became his habit that on his way to the magician, he would meet the monk and sit there and would come to the magician (late). The magician used to beat him because of this delay. He complained about this to the monk who said to him: ''When you feel afraid of the magician, say: Members of my family detained me. And when you fear your family, say: The magician detained me.'' It so happened that there came a huge beast and it blocked the way of the people, and the young boy said: ''I will know today whether the magician or the monk is better.'' He picked up a stone and said: ''O Allah, if the way of the monk is dearer to You than the way of the magician, bring about death to the animal so that the people be able to move about freely.'' He threw that stone at it and killed it and the people began to move about freely. He then came to the monk and told him the story. The monk said: ''Son, today you are superior to me. You have come to a stage where I feel that you would be soon put to a trial, and in case you are put to a trial, do not reveal me.'' That young boy began to heal those born blind and the lepers and he, in fact, began to cure people from all kinds of illnesses. When a courtier of the king who had gone blind heard about him, he came to him with numerous gifts and said, ''If you cure me, all these things will be yours.'' He said, ''I myself do not cure anyone. It is Allah, the Exalted, Alone Who cures; and if you affirm faith in Allah, I shall also supplicate to Allah to cure you.'' This courtier affirmed his faith in Allah and Allah cured him. He came to the king and sat by his side as he used to sit before. The king said to him, ''Who restored your eyesight?'' He said, ''My Rubb.'' Thereupon he said, ''Do you have another lord besides me?'' He said, ''My Rubb and your Rubb is Allah.'' So the king kept torturing him untill he revealed the young boy. The young boy was thus summoned and the king said to him, ''O boy, it has been conveyed to me that you have become so much proficient in your magic that you cure the blind and the lepers and you do such and such.'' Thereupon he said, ''I do not cure anyone; it is Allah Alone Who cures,'' and the king took hold of him and began to torture him until he revealed of the monk. The monk was summoned and it was said to him: ''You should turn back from your religion.'' But he refused. The king sent for a saw, placed it in the middle of his head and cut him into two parts that fell down. Then the courtier of the king was brought forward and it was said to him: ''Turn back from your religion.'' He, too, refused, and the saw was placed in the midst of his head and he was torn into two parts. Then the boy was sent for and it was said to him: ''Turn back from your religion.'' He refused. The king then handed him over to a group of his courtiers, and said to them: ''Take him to such and such mountain; make him climb up that mountain and when you reach its peak ask him to renounce his Faith. If he refuses to do so, push him to his death.'' So they took him and made him climb up the mountain and he said: ''O Allah, save me from them in any way you like,'' and the mountain began to shake and they all fell down (dead) and that young boy came walking to the king. The king said to him, ''What happened to your companions?'' He said, ''Allah has saved me from them.'' He again handed him to some of his courtiers and said: ''Take him and carry him in a boat and when you reach the middle of the sea, ask him to renounce his religion. If he does not renounce his religion throw him (into the water).'' So they took him and he said: ''O Allah, save me from them.'' The boat turned upside down and they all drowned except the young boy who came walking to the king. The king said to him, ''What happened to your companions?'' He said, ''Allah has saved me from them,'' and he said to the king: ''You cannot kill me until you do what I command you to do.'' The king asked, ''What is that?'' He said, ''Gather all people in one place and tie me up to the trunk of a tree, then take an arrow from my quiver and say: With the Name of Allah, the Rubb of the boy; then shoot me. If you do that you will be able to kill me.'' ''The king called the people in an open field and tied the young boy to the trunk of a tree. He took out an arrow from his quiver, fixed in the bow and said, ''With the Name of Allah, the Rubb of the young boy,'' he then shot the arrow and it hit the boy''s temple. The young boy placed his hand upon the temple where the arrow had hit him and died. The people then said: ''We believe in the Rubb of this young boy.'' The king was told: ''Do you see what you were afraid of, by Allah it has taken place; all people have believed.'' The king then commanded that trenches be dug and fire lit in them, and said: ''He who would not turn back from his (the young boy''s) religion, throw him in the fire'' or ''he would be ordered to jump into it.'' They did so till a woman came with her child. She felt hesitant in jumping into the fire. The child said to her: ''O mother! Endure (this ordeal) for you are on the Right Path"..', 'صهيب رضي الله عنه', 'Suhaib (May Allah be pleased with him) reported that the Messenger of Allah (ﷺ) said, "There lived a king before you and he had a court magician. As he (the magician) grew old, he said to the king:', 'صحيح', 'رياض الصالحين 30', 'Riyad as-Salihin 30', 'ریاض الصالحین 30', 'رواه مسلم', 'أخبر النبي صلى الله عليه وسلم أنه كان ملك فيمن كان قبلنا من الأمم، وكان له ساحر، فلما كبر الساحر، قال للملك: 

إني قد كبرت، فأرسل إلي شابًا أعلمه السحر. 

فبعث الملك إليه شابًا يعلمه، فكان في طريق الشاب إذا ذهب للساحر راهبٌ فقعد إليه مرة وسمع كلامه، فأعجبه، فكان إذا أتى الساحر مر بالراهب وقعد إليه، فإذا أتى الساحر ضربه لتأخره، فشكا ذلك إلى الراهب، فقال: إذا خشيت الساحر، فقل: حبسني أهلي، وإذا خشيت أهلك فقل: حبسني الساحر، فبينما هو كذلك إذ أتى على دابة عظيمة قد منعت الناس من المضي، فقال: اليوم أعلم آلساحر أفضل أم الراهب أفضل؟ 

فأخذ حجرًا، فقال: اللهم إن كان أمر الراهب أحب إليك من أمر الساحر فاقتل هذه الدابة، حتى يمضي الناس، فرماها فقتلها، ومضى الناس، فأتى الراهب فأخبره، فقال له الراهب: 

أي بني أنت اليوم أفضل مني، قد بلغ من أمرك ما أرى، وإنك ستبتلى، فإن ابتليت فلا تدل علي، وكان الغلام يبرئ الأكمه والأبرص، ويداوي الناس من سائر الأمراض بإذن الله، فسمع جليس للملك كان قد فقد بصره، فأتاه بهدايا كثيرة، فقال للغلام: 

كل ما هاهنا من الهدايا لك إن أنت شفيتني. 

فقال: إني لا أشفي أحدًا إنما يشفي الله، فإن أنت آمنت بالله دعوت الله فشفاك، فآمن بالله فشفاه الله، فأتى الملك فجلس إليه كما كان يجلس، فقال له الملك: من رد عليك بصرك؟ 

قال: ربي، قال: ولك رب غيري؟ 

قال: ربي وربك الله. 

فأخذه فلم يزل يعذبه حتى دل على الغلام، فجيء بالغلام، فقال له الملك: 

أي بني قد بلغ من سحرك ما تبرئ الأكمه والأبرص، وتفعل وتفعل. 

فقال: إني لا أشفي أحدًا، إنما يشفي الله، فأخذه فلم يزل يعذبه حتى دل على الراهب. 

فجيء بالراهب، فقيل له: ارجع عن دينك، فأبى، فدعا بالمنشار، فوضعه في مفرق رأسه، فشقه به نصفين. 

ثم جيء بجليس الملك فقيل له: ارجع عن دينك، فأبى فوضع المنشار في مفرق رأسه، فشقه به نصفين. 

ثم جيء بالغلام فقيل له ارجع عن دينك، فأبى فدفعه إلى رجال من أصحابه بين الثلاثة والعشرة. 

فقال: اذهبوا به إلى جبل كذا وكذا، فاصعدوا به الجبل، فإذا بلغتم أعلاه، فإن رجع عن دينه، وإلا فاطرحوه، فذهبوا به فصعدوا به الجبل. 

فقال الغلام: اللهم اكفنيهم بما شئت، فرجف بهم الجبل وتحرك حركة شديدة فسقطوا، وجاء يمشي إلى الملك. 

فقال له الملك: ما فعل أصحابك؟ 

قال: كفانيهم الله. 

فدفعه إلى نفر من أصحابه، فقال: اذهبوا به فاحملوه في سفينة صغيرة، فتوسطوا به البحر، فإن رجع عن دينه وإلا فاقذفوه في البحر. 

فذهبوا به، فقال: اللهم اكفنيهم بما شئت، فانقلبت بهم السفينة فغرقوا، وجاء يمشي إلى الملك. 

فقال له الملك: ما فعل أصحابك؟ 

قال: كفانيهم الله، فقال الغلام للملك: إنك لا تستطيع قتلي حتى تفعل ما آمرك به. 

قال: وما هو؟ 

قال: تجمع الناس في أرض بارزة، وتصلبني على جذع شجرة، ثم خذ سهمًا من كنانتي، ثم ضع السهم في مقبض القوس، ثم قل: باسم الله رب الغلام، ثم ارمني، فإنك إذا فعلت ذلك قتلتني، فجمع الناس في مكان واحد، وصلبه على جذع، ثم أخذ سهمًا من كنانته، ثم وضع السهم في وسط القوس، ثم قال: باسم الله رب الغلام، ثم رماه فوقع السهم في صدغه بين عينه وأذنه، فوضع يده في صدغه في موضع السهم فمات.

 فقال الناس: آمنا برب الغلام، آمنا برب الغلام، آمنا برب الغلام. 

فأُتي الملك فقيل له: أرأيت ما كنت تخاف؟ 

قد والله نزل بك ما خفت وهو اتباع الناس للغلام وإيمانهم بربه أجمعون، فأمر بشق الأرض شقوقًا عظيمة مستطيلة في أبواب الطرق، وأوقد وأشعل النيران فيها، وقال: من لم يرجع عن دينه فاطرحوه فيها، ففعلوا ما أمرهم الملك به، حتى جاءت امرأة ومعها صبي لها فتوقفت ولزمت موضعها وكرهت الدخول في النار، فقال لها صبيها: 

يا أمه اصبري فإنك على الحق.', 'إثبات كرامات الأولياء، ومن ذلك قتل الدابة العظيمة برمية الغلام، وإجابة دعاء الغلام مرتين، وكلام الطفل الرضيع.
نصر من توكل على الله سبحانه.
بيان شرف الصبر والثبات على الدين.
الحكمة في التعلّم في أول العُمر؛ لأنَّ الشاب في الغالب أسرع حفظًا من الكبير.
قُوَّة إيمان هذا الغلام، وأنه لم يتزحزح عن إيمانه ولم يتحول.
الله عز وجل يجيب دعوة المضطر إذا دعاه.
الإنسان يجوز أن يُغَرِّر بنفسه في مصلحة عامة للمسلمين، فإن هذا الغلام دل الملك على أمر يقتله به ويهلك به نفسه، وهو أن يأخذ سهمًا من كنانته ويضعه في كبد القوس ويقول: باسم الله رب الغلام.
جواز الكذب في الحرب ونحوها، وفي إنقاذ النفس من الهلاك.
المؤمن يُختَبر في صدق إيمانه والثبات على قول الحق، وإن وصل به الأمر إلى إزهاق نفسه.
التضحية في سبيل الدعوة إلى الله وإظهار الحق.
قلوب العباد بيد الله فيهدي من يشاء ويضل من يشاء، فقد اهتدى الغلام وهو في أحضان الساحر وعناية الملك العاثر.
جواز سؤال الله تعالى أن يري العبد علامة يعرف بها الصواب ويحصل له اليقين.
أهل الإيمان يسخرون كل ما أتاهم الله وتفضل به عليهم لخدمة دينه والدعوة إلى سبيله.
أسباب الهلاك بيد الله، فإن شاء أنفذها وإن شاء قطعها.
أهل الكفر لا تنقصهم الحجج والبراهين ليؤمنوا، وإنما سبب كفرهم هو العناد والكبر.
الطواغيت والظالمون عندهم الاستعداد لقتل الناس جميعًا ليبقوا على ما هم فيه من نعيم الدنيا.
الله يعاقب الذين ظلموا من حيث لم يحتسبوا، فقد آمن الناس برب الغلام عندما رأوا ثباته وصدق دعوته وعدم خشيته في الله لومة لائم.
هناك من تكلم في المهد غير المسيح عليه السلام، وهذا الحديث يشرح قول رسول الله صلى الله عليه وسلم: "لم يتكلم في المهد إلا ثلاثة..."، وذكرهم، وحصرهم في بني إسرائيل دون غيرهم.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3303', false),
(20031, 2, 201, 31, 'hadith', 'عن أنس رضي الله عنه قال: مر النبي صلى الله عليه وسلم بامرأة تبكي عند قبر فقال : "اتقي الله واصبري" فقالت : إليك عني ، فإنك لم تصب بمصيبتي ( ولم تعرفه، فقيل لها : إنه النبي صلى الله عليه وسلم ، فأتت باب النبي صلى الله عليه وسلم، فلم تجد عنده بوابين، فقالت: لم أعرفك، فقال: "إنما الصبر عند الصدمة الأولى".', 'The Prophet (ﷺ) passed by a woman who was crying over a grave and said, "Fear Allah and be patient." She said, "Away from me! My calamity has not befallen you and you are not aware of it." The woman was later told that it was the Prophet (ﷺ) (who had advised her). She came to his door where she found no doorkeeper. She said, "(I am sorry) I did not know you." Messenger of Allah (ﷺ) said, "Patience is (becoming) only at the first (stroke) of grief"..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 31', 'Riyad as-Salihin 31', 'ریاض الصالحین 31', 'متفق عليه', 'مر النبي صلى الله عليه وسلم بامرأة وهي عند قبر صبي لها قد مات، وكانت تحبه حبًّا شديدًا، فلم تملك نفسها أن تخرج إلى قبره لتبكي عنده. فلما رآها النبي صلي الله عليه وسلم أمرها بتقوى الله والصبر.
فقالت: ابعد عني فإنك لم تصب بمثل مصيبتي.
ثم قيل لها: إن هذا رسول الله صلى الله عليه وسلم فندمت وجاءت إلى رسول الله، إلى بابه، وليس على الباب بوابون يمنعون الناس من الدخول عليه. فأخبرته وقالت: إنني لم أعرفك، فأخبرها النبي صلى الله عليه وسلم، أن الصبر الذي يثاب عليه الإنسان هو أن يصبر عند أول ما تصيبه المصيبة.', 'من أُمِر بمعروف عليه أن يتقبله بقبول حسن ويخضع للحق ولو لم يعرف الآمر له، وذلك لأن الحق لا يعرف بالرجال وإنما يعرف الرجال بالحق، ولذلك كانت المرأة في موضع اللوم حقيقة؛ لأنها لم تستجب لموعظة رسول الله  صلى الله عليه وسلم بادئ ذي بدء، حيث إنها لم تعرفه ولكنها عندما عرفته ذهبت لتستميحه العذر، فأخبرها أن صبرها الآن لا ينفعها.
الترغيب في احتمال الأذى عند بذل النصيحة ونشر الموعظة، ولذلك احتمل الرسول صلى الله عليه وسلم تعنت المرأة وكلامها الذي يحمل التعنيف.
على الحاكم ومن ولاه الله أمرا من أمور المسلمين أن يتفقد ما استرعاه الله عنه.
عدم الصبر ينافي التقوى
ثواب الصبر إنما يحصل عند مفاجأة المصيبة، بخلاف ما بعدها.
حسن خلق النبي عليه الصلاة والسلام ودعوته إلى الحق وإلى الخير، فإنه لما رأى هذه المرأة تبكي عند القبر أمرها بتقوى الله والصبر.ولما قالت: "إليك عني" لم ينتقم لنفسه، ولم يضربها، ولم يُقِمها بالقوة؛ لأنَّه عرف أنَّه أصابها من الحزن ما لا تستطيع أن تملك نفسها، ولهذا خرجت من بيتها لتبكي عند هذا القبر
الإنسان يعذر بالجهل، سواء أكان جهلا بالحكم الشرعي أم جهلاً بالحال، فإن هذه المرأة قالت للنبي صلى الله عليه وسلم: إليك عني، أي: ابعد عني، مع أنَّه يأمرها بالخير والتقوى والصبر. ولكنها لم تعرف أنه رسول الله صلى الله عليه وسلم فلهذا عذرها النبيَّ عليه الصلاة والسلام.
لا ينبغي للإنسان المسؤول عن حوائج المسلمين أن يجعل على بيته بوابًا يمنع الناس إذا كان الناس يحتاجون إليه
الحديث دليل على: أنَّ البكاء عند القبر ينافي الصبر؛ ولهذا قال لها الرسول صلى الله عليه وسلم: "اتقي الله واصبري"
تواضع النبي صلى الله عليه وسلم ورفقه بالجاهل.
ملازمة الأمر بالمعروف والنهي عن المنكر.
مسامحة المصاب وقبول اعتذاره، ولذلك انصرف عنها النبي صلى الله عليه وسلم عندما قالت له: إليك عني فإنك لم تصب بمصيبتي.
المرء لا يؤجر على المصيبة؛ لأنها ليست من صنعه، وإنما يؤجر على حسن نيته وثباته، وجميل صبره، ورضاه بقضاء الله وقدره، ولذلك أمر رسول الله المرأة بتقوى الله والصبر.', 'اتقي الله واصبري : الظاهر أن في بكائها قدر زائد من نوح وغيره
إليك عني : تنحَّ وابتعد
الصَّدمة الأولى : مفاجأة المصيبة عند ذروتها وحموتها', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3295', false),
(20032, 2, 201, 32, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال : « يقول الله تعالى : ما لعبدي المؤمن عندي جزاء إذا قبضت صفيه من أهل الدنيا ثم احتسبه إلا الجنة».', 'The Messenger of Allah (ﷺ) said, "Allah, the Exalted, says: ''I have no reward other than Jannah for a believing slave of Mine who remains patient for My sake when I take away his beloved one from among the inhabitants of the world"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 32', 'Riyad as-Salihin 32', 'ریاض الصالحین 32', 'رواه البخاري', 'يخبر النبي -عليه السلام- في هذا الحديث القدسي، أنَّ من ابتلي بفقد حبيبه من قريب ونحو ذلك إذا صبر الإنسان على قبض من يصطفيه الإنسان ويختاره ويرى أنه ذو صلة منه قوية، من ولد، أو أخ، أو عم، أو أب، أو أم، أو صديق، إذا أخذه الله عز وجل ثم احتسبه الإنسان فليس له جزاء إلا الجنة.', 'أن من صبر على المصيبة واحتسب ثوابها عند الله -تعالى-، فإن جزاءه الجنة.
أن من أعظم المصائب التي تنزل بالإنسان فقد الأحبة.
أن الكافر مهما عمل من عمل صالح، فليس له به عند الله شيء، لعدم الإيمان.
يوفى الصابرون أجرهم بغير حساب وخاتمة ذلك دخول الجنة.
فضيلة الصبر على قبض الحبيب من الدنيا، وأن الله -عز وجل- يجازي الإنسان إذا صبر على ذلك رجاء ما عند الله الجنة.
في الحديث دليل على سعة فضل الله -سبحانه وتعالى- وكرمه على عباده، فإن الملك ملكه، والأمر أمره، ومع ذلك فإذا قبض الله صفي الإنسان واحتسب، فإن له هذا الجزاء العظيم.
الإشارة إلى أفعال الله، من قوله: "إذا قبضت صفيه".', 'صَفِيَّه : حبيبه لأنه يصافيه المحبة والود.
احْتَسَبه : صبر على فقده راجيا الأجر من الله على ذلك.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3162', false),
(20033, 2, 201, 33, 'hadith', 'عن عائشة رضي الله عنها أنها سألت رسول الله صلى الله عليه وسلم عن الطاعون، فأخبرها أنه كان عذاباً يبعثه الله تعالى على من يشاء، فجعله الله تعالى رحمة للمؤمنين، فليس من عبد يقع في الطاعون فيمكث في بلده صابراً محتسباً يعلم أنه لا يصيبه إلا ما كتب الله له إلا كان له مثل أجر الشهيد".', 'I asked the Messenger of Allah (ﷺ) about pestilence and he said, "It is a punishment which Allah sends upon whomsoever He wills, but Allah has made it as a mercy to the believers. Anyone who remains in a town which is plagued with pestilence maintaining patience expecting the reward from Allah, and knowing that nothing will befall him other than what Allah has foreordained for him, he would receive a reward of Shaheed"..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 33', 'Riyad as-Salihin 33', 'ریاض الصالحین 33', 'رواه البخاري', 'في حديث عائشة رضي الله عنها أنها سألت رسول الله صلى الله عليه وسلم عن الطاعون، فأخبرها أن الطاعون عذاب يرسله الله سبحانه وتعالى على من يشاء من عباده.
وسواء كان الطاعون معيناً أم كان وباء عاما مثل الكوليرا وغيرها؛ فإن هذا الطاعون عذاب أرسله الله عز وجل، ولكنه رحمة للمؤمن إذا نزل بأرضه وبقي فيها صابراً محتسباً، يعلم أنه لا يصيبه إلا ما كتب الله له، فإن الله تعالى يكتب له مثل أجر الشهيد، ولهذا جاء في الحديث الصحيح عن عبد الرحمن بن عوف رضي الله عنه أنه قال: قال رسول الله صلى الله عليه وسلم : "إذا سمعتم به بأرض فلا تقدموا عليه، وإذا وقع بأرض وأنتم بها فلا تخرجوا فراراً منه".
إذا وقع الطاعون بأرض فإننا لا نقدم عليها؛ لِأنَّ الإقدام عليها إلقاء بالنفس إلى التهلكة، ولكنه إذا وقع في أرض فإِنَّنا لا نخرج منها فراراً منه، لأنك مهما فررت من قدر الله إذا نزل بالأرض فإن هذا الفرار لن يغني عنك من الله شيئاً؛ لأنه لا مفر من قضاء الله إلا إلى الله.
وأما سر نيل درجة الشهداء للصابر المحتسب على الطاعون: هو أن الإنسان إذا نزل الطاعون في أرضه فإن الحياة غالية عنده، سوف يهرب، يخاف من الطاعون، فإذا صبر وبقي واحتسب الأجر وعلم أنه لن يصيبه إلا ما كتب الله له، ثم مات به، فإنه يكتب له مثل أجر الشهيد، وهذا من نعمة الله عز وجل .', 'أصل الطاعون عذاب ورجز على الأمم السابقة.
رحمة الله بهذه الأمة الإسلامية وما خصَّها الله من خير فقد جعل الله ما كان عذاباً لغيرها رحمة بها.
الأجر على ما يصيب العبد من هم وحزن وغم وأذى خاص بأهل الإيمان دون غيرهم.
لا يقتصر أجر الشهيد على من مات في الحرب، وإنما يشمل أناسا كثيرين.
من مات بالطاعون صابرًا محتسبًا كان له أجر الشهيد.
من مات مطعونا أو مبطونا -بسبب مرض في البطن- أو غريقا أو النفساء ممن عدَّهم الإسلام في زمرة الشهداء لا يعاملون معاملة شهيد الحرب بل لهم أجر الشهداء.
إذا وقع الطاعون بأرض والعبد فيها، فلا يجوز له الخروج منها، بل عليه أن يبقى فيها محتسبا راضيا بأمر الله وقدره.
حرص الإسلام على محاصرة الأمراض الخبيثة والمعدية وعدم انتشارها، وهذا هو مبدأ "الحَجر الصحي".', 'الطاعون : مرض وبائي سريع الانتشار، وقيل: بثر مؤلم يخرج غالبا في الآباط، مع حرارة شديدة واسوداد ما حوله وخفقان القلب والقيء، وقيل: إنه كل وباء عام يحل بالأرض فيصيب أهلها ويموت الناس منه.
على من يشاء : أي من كافر أو عاص بارتكاب الكبيرة، أو إصرارا على صغيرة.
محتَسَبًا : راجيا للأجر والثواب من الله -تعالى-.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3161', false),
(20034, 2, 201, 34, 'hadith', 'عن أنس رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول : «إن لله عزوجل قال: إذا ابتليت عبدي بحبيبتيه فصبر عوضته منهما الجنة».', 'I heard the Messenger of Allah (ﷺ) saying, "Allah, the Glorious and Exalted said: ''When I afflict my slave in his two dear things (i.e., his eyes), and he endures patiently, I shall compensate him for them with Jannah."..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 34', 'Riyad as-Salihin 34', 'ریاض الصالحین 34', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20035, 2, 201, 35, 'hadith', 'عن عطاء بن أبي رباح قال: قال لي ابن عباس رضي الله عنهما: ألا أريك امرأة من أهل الجنة " فقلت: بلى، قال: هذه المرأة السوداء أتتت النبي صلى الله عليه وسلم فقالت : إني أصرع، و إني أتكشف، فادع الله تعالى لي قال: "إن شئت صبرت ولك الجنة، وإن شئت دعوت الله تعالى أن يعافيك" فقالت: أصبر، فقالت: إني أتكشف ، فادع الله أن لا أتشكف ، فدعا لها.', 'Ibn ''Abbas (May Allah be pleased with them) asked him whether he would like that he should show him a woman who is from the people Jannah. When he replied that he certainly would, he said, "This black woman, who came to the Prophet (ﷺ) and said, ''I suffer from epilepsy and during fits my body is exposed, so make supplication to Allah for me.'' He (ﷺ) replied: ''If you wish you endure it patiently and you be rewarded with Jannah, or if you wish, I shall make supplication to Allah to cure you?'' She said, ''I shall endure it.'' Then she added: ''But my body is exposed, so pray to Allah that it may not happen.'' He (Prophet (ﷺ)) then supplicated for her"..', 'عطاء بن أبي رباح قال: قال لي ابن عباس رضي الله عنهما', '''Ata'' bin Abu Rabah', 'صحيح', 'رياض الصالحين 35', 'Riyad as-Salihin 35', 'ریاض الصالحین 35', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20036, 2, 201, 36, 'hadith', 'عن أبي عبد الرحمن عبد الله بن مسعود رضي الله عنه قال: كأني انظر إلى رسول الله صلى الله عليه وسلم يحكي نبياً من الأنبياء، صلوات الله وسلامه عليهم، ضربه قومه فأدموه وهو يمسح الدم عن وجهه، يقول : «اللهم اغفر لقومى فإنهم لا يعلمون».', 'I can still recall as if I am seeing the Messenger of Allah (ﷺ) resembling one of the Prophets whose people scourged him and shed his blood, while he wiped blood from his face, he said: "O Allah! Forgive my people, because they certainly do not know"..', 'أبي عبد الرحمن عبد الله بن مسعود رضي الله عنه', '''Abdullah bin Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 36', 'Riyad as-Salihin 36', 'ریاض الصالحین 36', 'متفق عليه', 'حكى نبيُّنا صلى الله عليه وسلم عن نبيٍّ من الأنبياء: أن قومه ضربوه؛ فجعل يمسح الدم عن وجهه، وهو يدعو لهم بالمغفرة، وهذا غاية ما يكون من الصبر والحلم، ولم يقتصر على الدعاء لهم بل واعتذر عنهم من باب الإشفاق عليهم؛ لجهلهم بحقائق الأمور.', 'أن المحُدِّث أو المُخبِر يُخبر بما يؤيد ضبطه للخبَر والحديث "كأني أنظر..".
التأسي بأخلاق النبي -صلى الله عليه وسلم- في تحمل الأذى؛ فقد شج وجهه وسال دمه يوم أحد، ولم يزد على أن قال: "اللهم اغفر لقومي؛ فإنهم لا يعلمون".
صبر الأنبياء، وتحملهم الأذى في سبيل تبليغ دعوتهم للناس.
من أخلاق الأنبياء: مقابلة الجهل بالغفران والمسامحة.
فضل الصبر على الأذى.
عدم معاملة الجاهلين بمثل أعمالهم، ولا بالدعاء عليهم، بل بطلب الهداية لهم والحرص عليهم.', 'يحكي نبيًّا : يصف نبيًّا.
أدموه : ضربوه؛ حتى خرج منه الدم.
اغفر لقومي : المغفرة: هي التجاوز عن الذنب والستر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3594', false),
(20037, 2, 201, 37, 'hadith', 'عن أبي سعيد وأبي هريرة رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «ما يصيب المسلم من نصب ولا وصب ولا هم ولا حزن ولا أذى ولا غم، حتى الشوكة يشاكها إلا كفر الله بها من خطاياه» ((متفق عليه)) . ''و الوصب '': المرض .', '"Never a believer is stricken with a discomfort, an illness, an anxiety, a grief or mental worry or even the pricking of a thorn but Allah will expiate his sins on account of his patience"..', 'أبي سعيد وأبي هريرة رضي الله عنهما', 'Abu Sa''id and Abu Hurairah (May Allah be pleased with him) reported that the Prophet (ﷺ) said:', 'صحيح', 'رياض الصالحين 37', 'Riyad as-Salihin 37', 'ریاض الصالحین 37', null, 'يُبَيِّنُ الرسولُ صلى الله عليه وسلم أنَّ ما يُصاب به المسلمُ مِن أمراضٍ وهمومٍ وأحزانٍ وكروبٍ ومصائبَ وشدائدَ وخوفٍ وجوعٍ -حتى لو كانت شوكة تُصيبه فَتُؤْلِمُه-، يكونُ ذلك كفارةً لذنوبه وحطًّا لخطاياه.', 'بيان فضل الله على عباده المؤمنين ورحمته بهم بغفران الذنوب بأقل ضرر يصيبهم.
ينبغي للمسلم أن يَحْتَسِبَ عند الله ما يُصيبه، ويَصبر على كل صغيرة وكبيرة، لتكون له رفعة في الدرجات وكفارة للسيئات.', 'نصب: التعب.
وصب: المرض .', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3701', false),
(20038, 2, 201, 38, 'hadith', 'عن ابن مسعود رضي الله عنه قال: دخلت على النبي صلى الله عليه وسلم وهو يوعك فقلت: يارسول الله إنك توعك وعكاً شديداً قال: "أجل إني أوعك كما يوعك رجلان منكم" قلت: ذلك أن لك أجرين ؟ قال: "أجل ذلك كذلك ما من مسلم يصيبه أذى؛ شوكة فما فوقها إلا كفر الله بها سيئاته ، وحطت عنه ذنوبه كما تحط الشجرة ورقها".', 'I visited the Prophet (ﷺ) when he was suffering fever. I said, "You seem to be suffering greatly, O Messenger of Allah." The Prophet (ﷺ) replied, "Yes, I suffer as much as two persons." I said, "Is that because you have a double reward?" He replied that that was so and then said, "No Muslim is afflicted by a harm, be it the pricking of a thorn or something more (painful than that), but Allah thereby causes his sins to fall away just as a tree sheds its leaves"..', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 38', 'Riyad as-Salihin 38', 'ریاض الصالحین 38', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20039, 2, 201, 39, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم « من يرد الله به خيراً يصب منه» :.', 'The Messenger of Allah (ﷺ) said: "He whom Allah intends good, He makes him to suffer from some affliction"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) reported that:', 'صحيح', 'رياض الصالحين 39', 'Riyad as-Salihin 39', 'ریاض الصالحین 39', 'رواه البخاري', 'يُخبِرُ النبيُّ صلى الله عليه وسلم أنَّ الله إذا أراد بأحدٍ من عباده المؤمنين خيرًا ابتلاهم في أنفسهم وأموالهم وأهلهم، لِمَا يحصل فيه للمؤمن من اللجوء إلى الله تعالى بالدعاء، وتكفير السيئات، ورِفْعَة الدرجات.', 'أن المؤمن مُعرَّض لأنواع من البلاء.
الابتلاء قد يكون أمارة حُبِّ الله لعبده، حتى يرفع درجته، ويُعْلِي مَرتبته، ويكفِّر خطيئته.
 الحث على الصبر عند المصائب وعدم الجزع.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4204', false),
(20040, 2, 201, 40, 'hadith', 'عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : « لا يتمنين أحدكم الموت لضر أصابه، فإن كان لابد فاعلاً فليقل: اللهم أحيني ما كانت الحياة خيراً لي وتوفني إذا كانت الوفاة خيراً لي».', 'The Messenger of Allah (ﷺ) said, "Let not one of you wish for death because of a misfortune which befalls him. If he cannot help doing so, he should say: ''O Allah, keep me alive as long as You know that life is better for me, and make me die when death is better for me"..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) reported that:', 'صحيح', 'رياض الصالحين 40', 'Riyad as-Salihin 40', 'ریاض الصالحین 40', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false)
