insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(20041, 2, 201, 41, 'hadith', 'عن أبي عبد الله خباب بن الأرت رضي الله عنه قال: شكونا إلى رسول الله صلى الله عليه وسلم وهو متوسد بردة له في ظل الكعبة، فقلنا : ألا تستنصر لنا ألا تدعو لنا؟ فقال: قد كان من قبلكم يؤخذ الرجل فيحفر له في الأرض فيجعل فيها ثم يؤتى بالمنشار فيوضع على رأسه فيجعل نصفين، ويمشط بأمشاط من الحديد ما دون لحمه وعظمه، ما يصده ذلك عن دينه، والله ليتمن الله هذا الأمر حتى يسير الراكب من صنعاء إلى حضرموت لا يخاف إلا الله والذئب على غنمه، ولكنكم تستعجلون".', 'We complained to the Messenger of Allah (ﷺ) regarding the persecution inflicted upon us by the disbelievers while he was lying in the shade of the Ka''bah, having made a pillow of his cloak. We submitted: "Why do you not supplicate for our prevalence (over the opponents)?". He (ﷺ) replied, "Among those people before you, a man would be seized and held in a pit dug for him in the ground and he would be sawed into two halves from his head, and his flesh torn away from his bones with an iron comb; but, in spite of this, he would not wean away from his Faith. By Allah, Allah will bring this matter to its consummation until a rider will travel from San''a'' to Hadramout fearing none except Allah, and except the wolf for his sheep, but you are in too much of a hurry"..', 'أبي عبد الله خباب بن الأرت رضي الله عنه', 'Khabbab bin Al-Aratt (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 41', 'Riyad as-Salihin 41', 'ریاض الصالحین 41', 'رواه البخاري', 'في هذا الحديث يحكي خباب رضي الله عنه ما وجده المسلمون من الأذية من كفار قريش في مكة، فجاؤوا يشكون إلى النبي صلى الله عليه وسلم وهو متوسد بردة له في ظل الكعبة، فبين النبي -عليه الصلاة والسلام- أن من كان قبلنا ابتلي في دينه أعظم مما ابتلي به هؤلاء، يُحفر له حفرة، ثم يُلقى فيها، ثم يؤتى بالمنشار على مفرق رأسه ويشق نصفين، ويمشط بأمشاط الحديد ما بين جلده وعظمه، وهذه أذية عظيمة.
ثم أقسم -صلوات الله وسلامه عليه- أن الله سبحانه سيتم هذا الأمر، يعني: سيتم ما جاء به الرسول -عليه الصلاة والسلام- من دعوة الإسلام، حتى يسير الراكب من صنعاء إلى حضرموت لا يخشى إلا الله والذئب على غنمه،
ثم أرشد -عليه الصلاة والسلام- صحبه الكرام إلى ترك العجلة؛ فقال: "ولكنكم تستعجلون" أي: فاصبروا وانتظروا الفرج من الله، فإن الله سيتم هذا الأمر، وقد صار الأمر كما أقسم النبي -عليه الصلاة والسلام-.', 'جواز ذِكر ما يتعرض له المسلم من البلاء من باب الإخبار، لا من باب الشكوى.
صبر أصحاب النبي -صلى الله عليه وسلم- على ما يجدونه من العذاب في سبيل الله -تعالى-.
الاستنصار بالقوي.
جواز طلب الدعاء ممن هو مجاب الدعوة، أو من أهل الخير والصلاح، بشرط ألا يترك الدعاء اعتمادًا على دعائهم.
الدعاء على الكفار وطلب ذلك.
تثبيت النبي -صلى الله عليه وسلم- أصحابه وأن ما يصيبهم قد أصيب به أمم من قبلهم.
مدح الصبر على العذاب في الدين، وأن مع العسر يسرًا.
التأسي بالصالحين الذين امتحنوا في دينهم، فصبروا.
العداوة بين أهل الحق والباطل قديمة.
ثبات أهل الإيمان من الأمم السابقة على دينهم وعدم تركه، مع ما يتعرضون له من أنواع الأذى.
الابتلاء من لوازم الإيمان.
أن العاقبة لهذا الدِّين، ولو كره الكافرون.
الإسلام دِين الأمن والسلام.
صدق رسالته -صلى الله عليه وسلم-، فقد أخبر بأمور مستقبلية غيبية، وتحقق ذلك بوعد من الله -تعالى-.
تحقق ما أخبر به النبي -صلى الله عليه وسلم-، من انتشار الإسلام، واستتباب الأمن والسلام.
كراهية الاستعجال بالنصر، وأن النصر يأتي مع الصبر.', 'مُتَوَسِّدٌ بُرْدَةً : جاعل البُرْدَة تحت رأسه.
البُرْدَة : كِسَاء مخطط يلتحف به.
تَسْتَنْصِرُ لنا : تسأل الله النصر لنا.
ما يَصُدُّهُ : ما يمنعه أو يصرفه.
المِنْشَار : آلة يقطع بها الخشب.
دون لحمه : تنفذ إلى ما تحت اللحم، من عظم وعصب.
لَيُتِمَّنَّ : ليكمُلن.
هذا الأمر : دِين الإسلام.
الراكب : المسافر.
من صنعاء : بلد باليمن.
حضرموت : موضع بأقصى اليمن.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4246', false),
(20042, 2, 201, 42, 'hadith', 'عن ابن مسعود رضي الله عنه قال : لما كان يوم حنين آثر رسول الله صلى الله عليه وسلم ناساً في القسمة، فأعطى الأقرع بن حابس مائة من الإبل، وأعطى عيينة بن حصن مثل ذلك، وأعطى ناساً من أشراف العرب وآثرهم يومئذ في القسمة. فقال رجل: والله إن هذه قسمة ما عدل فيها، وما أريد فيها وجه الله، فقلت : والله لأخبرن رسول الله صلى الله عليه وسلم ، فأتيته فأخبرته بما قال: فتغير وجههه حتى كان كالصرف . ثم قال « فمن يعدل إذا لم يعدل الله ورسوله؟ ثم قال: يرحم الله موسى قد أوذي بأكثر من هذا فصبر». فقلت: لا جرم لا أرفع إليه بعدها حديثاً.', 'After the battle of Hunain, Messenger of Allah (ﷺ) favoured some people in the distribution of spoils (for consolation). He gave Al-Aqra'' bin Habis and ''Uyainah bin Hisn a hundred camels each and showed favour also to some more honourable persons among the Arabs. Someone said: "This division is not based on justice and it was not intended to win the Pleasure of Allah." I said to myself: "By Allah! I will inform Messenger of Allah (ﷺ) of this." I went to him and informed him. His face became red and he said, "Who will do justice if Allah and His Messenger do not?" Then he said, "May Allah have mercy on (Prophet) Musa (Moses); he was caused more distress than this but he remained patient." Having heard this I said to myself: "I shall never convey anything of this kind to him in future"..', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 42', 'Riyad as-Salihin 42', 'ریاض الصالحین 42', 'متفق عليه', 'يخبر عبد الله بن مسعود رضي الله عنه أنهم كانوا في غزوة حنين، وهي: غزوة الطائف التي كانت بعد فتح مكة، غزاهم الرسول صلى الله عليه وسلم وغنم منهم غنائم كثيرة جدا: من إبل، وغنم، ودراهم، ودنانير، ثم إن النبي صلى الله عليه وسلم نزل بالجعرانة، وهي محل عند منتهى الحرم من جهة الطائف، نزل بها وقسم صلى الله عليه وسلم الغنائم بين من حضر هذه الغزوة، فأعطى الأقرع بن حابس مائة من الإبل، وأعطى عيينة بن حصن مائة من الإبل، وأعطى ناسًا من أشراف العرب؛ يتألفهم على الإسلام؛ فإذا حسن إسلام هؤلاء بسبب العطايا والمال أسلم من وراءهم ممن يتبعهم، وكان في ذلك قوة وعزة للإسلام، وأما أقوياء الإيمان فقد تركهم صلى الله عليه وسلم اعتمادًا على ما عندهم من الإيمان. 
فقال رجل بعد أن رأى حال النبي صلى الله عليه وسلم في تقسيم الغنائم على رؤساء القبائل وأشراف القوم، وترك بعض القوم: والله إن هذه قسمة ما عُدل فيها وما أريد فيها وجه الله.
فلما سمع ابن مسعود رضي الله عنه هذه الكلمة ذهب مسرعا إلى النبي صلى الله عليه وسلم وأقسم قبل لأن يأتيه أنه سيخبره بها، ولما أخبره بالخبر، اشتد غضبه -عليه الصلاة والسلام-، وتغير وجه حتى كان كالصبغ الأحمر الخالص، ثم قال: فمن يعدل إذا لم يعدل الله ورسوله؟ يستنكر قوله.
ثم قال -عليه الصلاة والسلام-: يرحم الله موسى، لقد أوذي بأكثر من هذا فصبر.
ولما رأى ابن مسعود رضي الله عنه من حال النبي -صلى الله عليه وسلم-، قال رضي الله عنه : إذا سمعتُ قولا من أولئك القوم، من الأقوال المنكرة، فلن أخبر بها النبي صلى الله عليه وسلم بذلك؛ لما رآه من شدة غضبه صلى الله عليه وسلم ، ما دام أنه لا يعود على النبي صلى الله عليه وسلم ولا على الإسلام بضرر.', 'حكمة النبي -صلى الله عليه وسلم- في تأليف القلوب.
فعل هذا الرجل لما تكلم بهذا الكلام على الملأ من باب نشر الفوضى بين المسلمين.
عداوة المنافقين للنبي -صلى الله عليه وسلم-.
تأكيد الفعل بالقسم.
جواز نقل الخبر على غير وجه الإفساد، لبيان حال القائل والتحذير منه.
الرسول -صلى الله عليه وسلم- بشرٌ، يتأثر بما يتأثر به البشر، من غضب ونحو ذلك.
أعظم الناس عدلا وأشدهم خوفا من الله -تعالى- وأكثرهم علما به هم أنبياء الله ورسله.
سعة حلمه -صلى الله عليه وسلم-، وكذلك الأنبياء من قبله.
تأسي النبي -صلى الله عليه وسلم- بإخوانه الأنبياء؛ تحقيقا لقوله -تعالى-: (فبهداهم اقتده).
استحباب الإِعراض عن الجاهلين.
حرص ابن مسعود -رضي الله عنه- على عدم إغضاب النبي -صلى الله عليه وسلم-.', 'يوم حنين : أي: زمن غزوتها.
حنين : واد في مكة والطائف وراء عرفات، وهو أقرب إلى مكة.
ناسا : من المؤلفة قلوبهم، ومن الطلقاء، ومن رؤساء العرب، يتألفهم.
في الغنائم : في قسمة غنائم قبيلة هوازن.
آثرهم : أعطاهم عطايا نفيسة لم يعطها لغيرهم.
يومئذ : يوم حنين.
فقال رجل : هو: ذو الخويصرة.
الصِّرْفِ : صبغ أحمر، يصبغ به الجلود.
لا جرم : هذه كلمة ترد بمعنى تحقيق الشيء، وتقديرها: أصلها التبرئة بمعنى لا بد، ثم استعملت في معنى حقًّا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3743', false),
(20043, 2, 201, 43, 'hadith', 'عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم :"إذا أراد الله بعبده خيراً عجل له العقوبة في الدنيا، وإذا أراد الله بعبده الشر أمسك عنه بذنبه حتى يوافي به يوم القيامة". وقال النبي صلى الله عليه وسلم : "إن عظم الجزاء مع عظم البلاء، وإن الله تعالى إذا أحب قوماً ابتلاهم، فمن رضي فله الرضى، ومن سخط فله السخط".', 'The Messenger of Allah (ﷺ) said, "When Allah intends good for His slave, He punishes him in this world, but when He intends an evil for His slave, He does not hasten to take him to task but calls him to account on the Day of Resurrection.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) reported that:', 'صحيح', 'رياض الصالحين 43', 'Riyad as-Salihin 43', 'ریاض الصالحین 43', 'رواه الترمذي وقال : حديث حسن', 'يخبرنا النبي صلى الله عليه وسلم في هذا الحديث أن المؤمن قد يحل به شيء من المصائب في نفسه أو ماله أو غير ذلك، وأن الله سيثيبه على تلك المصائب إذا هو صبر، وأنه كلما عظمت المصيبة وعظم خطرها عظم ثوابها من الله، ثم يبين صلى الله عليه وسلم بأن المصائب من علامات حب الله للمؤمن، وأن قضاء الله وقدره نافذان لا محالة، ولكن من صبر ورضي، فإن الله سيثيبه على ذلك برضاه عنه وكفى به ثوابا، وأن من سخط وكره قضاء الله وقدره، فإن الله يسخط عليه وكفى به عقوبة.', 'أن المصائب مكفرات للذنوب ما لم يترتب عليها ترك واجب كترك الصبر أو فعل محرم كشق الجيوب أو لطم الخدود.
إثبات صفة المحبة لله على وجه يليق بجلاله.
أن البلاء للمؤمن من علامات الإيمان.
إثبات صفة الرضا والسخط لله على وجه يليق بجلاله.
استحباب الرضا بقضاء الله وقدره.
تحريم السخط من قضاء الله وقدره.
الحث على الصبر على المصائب.
الإنسان قد يكره الشيء وهو خيرٌ له.
إثبات الحكمة لله سبحانه في أفعاله.
الجزاء من جنس العمل.', 'إن عظم الجزاء مع عظم البلاء : أي كلما عظم بلاؤه عظم ثوابه.
ابتلاهم : أي اختبر إيمانهم بالمصائب.
فمن رضي : أي رضي بقضاء الله وقدره.
فله الرضا : أي له الرضا من الله -تعالى-.
سخط : السخط من الشيء الكراهية له وعدم الرضا به.
فله السخط : أي فله السخط من الله -تعالى-.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3339', false),
(20044, 2, 201, 44, 'hadith', 'عن أنس رضي الله عنه قال: كان ابن لأبي طلحة رضي الله عنه يشتكي، فخرج أبو طلحة، فقبض الصبي، فلما رجع أبو طلحة قال: ما فعل ابني؟ قالت أم سليم وهى أم الصبي : هو أسكن ما كان، فقربت إليه العشاء فتعشى، ثم أصاب منها، فلما فرغ قالت: واروا الصبي، فلما أصبح أبو طلحة أتى رسول الله صلى الله عليه وسلم فأخبره، فقال: "أعرستم الليلة ؟" قال: نعم ، قال: "اللهم بارك لهما، فولدت غلاماً، فقال لي أبو طلحة: احمله حتى تأتى به النبي صلى الله عليه وسلم، وبعث معه بتمرات، فقال: "أمعه شيء؟" قال: نعم، تمرات فأخذها النبي صلى الله عليه وسلم فمضغها ، ثم أخذها من فيه فجعلها في فيّ الصبي ، ثم حنكه وسماه عبد الله. ((متفق عليه)) . وفى رواية لمسلم: مات ابن لأبي طلحة بن أم سليم ، فقالت لأهلها لا تحدثوا أبا طلحة بابنه حتى أكون أنا أحدثه، فجاء فقربت إليه عشاءً فأكل وشرب، ثم تصنعت له أحسن ما كانت تصنع قبل ذلك، فوقع بها، فلما أن رأت أنه قد شبع وأصاب منها قالت: يا أبا طلحة، أرأيت لو أن قوماً أعاروا عاريتهم أهل بيت فطلبوا عاريتهم، ألهم أن يمنعوهم؟ قال: لا، فقالت : فاحتسب ابنك. قال: فغضب، ثم قال: تركتني حتى إذا تلطخت أخبرتني بابني؟! فانطلق حتى أتى رسول الله صلى الله عليه وسلم فأخبره بما كان ، فقال رسول الله صلى الله عليه وسلم. "بارك الله في ليلتكما" قال: فحملت، قال وكان رسول الله صلى الله عليه وسلم في سفر وهي معه، وكان رسول الله صلى الله عليه وسلم إذا أتى المدينة من سفر لا يطرقها طروقاً فدنوا من المدينة، فضربها المخاض، فاحتبس عليها أبو طلحة، وانطلق رسول الله صلى الله عليه وسلم قال: يقول أبو طلحة: إنك لتعلم يارب أنه يعجبني أن أخرج مع رسول الله صلى الله عليه وسلم إذا خرج، وأدخل معه إذا دخل، وقد احتبست بما ترى، تقول أم سليم: يا أبا طلحة ما أجد الذى كنت أجد، انطلق، فانطلقنا، وضربها المخاض حين قدما فولدت غلاماً. فقالت لي أمي : يا أنس لا يرضعه أحد حتى تغدو به على رسول الله صلى الله عليه وسلم، فلما أصبح احتملته فانطلقت به إلى رسول الله صلى الله عليه وسلم. وذكر تمام الحديث.', 'One of the sons of Abu Talhah (May Allah be pleased with him) was ailing. Abu Talhah went out and the boy died in his absence. When he came back, he inquired, "How is the boy?". Umm Sulaim, the mother of the boy, replied, "Better than before". Then she placed his evening meal before him and he ate it; and thereafter slept with her. At last, she said to him: "Arrange for the burial of the boy". In the morning, Abu Talhah went to Messenger of Allah (ﷺ) and informed him of the event. He enquired, "Did you sleep together last night?" Abu Talhah replied in the affirmative, on which the Prophet (ﷺ) supplicated, "O Allah bless them." Thereafter, she gave birth to a boy. Abu Talhah said to me: "Take up the boy and carry him to the Prophet (ﷺ)"; and he sent some dates with him. The Prophet (ﷺ) enquired, "Is there anything with him?" He said; "Yes, some dates". The Prophet (ﷺ) took a date, chewed it and put it in the mouth of the baby and rubbed the chewed date around the baby''s gum and named him ''Abdullah..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 44', 'Riyad as-Salihin 44', 'ریاض الصالحین 44', null, 'حديث أنس بن مالك عن أبي طلحة أنه كان له ابن يشتكي، يعني مريضا، وأبو طلحة كان زوج أم أنس بن مالك رضي الله عنهم، تزوج بها بعد والد أنس، فخرج أبو طلحة لبعض حاجاته، فمات الصبي، فلما رجع سأل أمه عنه فقال: كيف ابني؟ قالت: هو أسكن ما يكون. وصدقت في قولها، هو أسكن ما يكون؛ لأنه مات، وأبو طلحة ـرضي الله عنهـ فهم أنه أسكن ما يكون من المرض، وأنه في عافية، فقدمت له العشاء فتعشى على أن أبنه برئ. ثم أصاب منها، يعني جامعها، فلما انتهى قالت: واروا الصبي. أي: ادفنوا الصبي؛ فإنه قد مات، -على الرواية الأولى- فلما أصبح أبو طلحة رضي الله عنه وارى الصبي وعلم بذلك النبي صلي الله عليه وسلم، وسأل: (هل أعرستم الليلة؟) قال: "نعم"، فدعا لهما -عليه الصلاة والسلام- بالبركة فولدت رضي الله عنها غلاما مباركًا. قال أنس: فقال لي أبو طلحة: احمله حتى تأتي به النبيّ صلى الله عليه وسلم وبعث معه بتمرات ليحنكه بها، ليكون أو ل ما ينزل في جوف الصبي ريق النبي صلى الله عليه وسلم ، فتحل عليه البركة.
فلما أتى به النبي صلى الله عليه وسلم قال: (أمعه شيء؟) أي: مما يحنك به ، فأجابه أنس رضي الله عنه بأن معه تمرات فأخذها النبي صلى الله عليه وسلم فمضغها؛ لتختلط بريقه الشريف ويقدر الصبي على إساغتها، فيكون أول ما يدخل جوفه الممتضغ بريق المصطفى صلى الله عليه وسلم فيسعد ويبارك فيه، ثم أخرج النبي صلى الله عليه وسلم التمرات الممضوغات من فيه فجعلها في فم الصبي، ثم دلكها بحنكه وسماه عبد الله، وكان لهذا الغلام تسعة من الولد كلهم يقرأون القرآن ببركة دعاء النبي ـصلى الله عليه وسلم-
وأما على رواية مسلم : فقالت لأهلها: "لا تُحَدِّثُوا أبا طلحة بابنه حتى أكون أنا من أخبره الخبر" ، فلما دخل جاء أبو طلحة ، قربت له العشاء فأكل وشرب، ثُم تجملت له وتطيبت وتصنعت، فوقع عليها ولما فرغ من جماعها ضربت له مثلا لابنه بالعارية التي تُرد إلى أصحابها فقالت له : يا أبا طلحة، أرأيت لو أن قوما أعاروا عاريتهم أهل بيت، ثم طلبوا عاريتهم ألهم أن يمنعوهم؟ قال : لا. فقالت: فاحتسب ابنك، فلما سمع منها ما سمع غضب رضي الله عنه ، ثم قال: تَرَكْتِنِي حتى إذا تَلَطَّخْتُ ثم أخبرتني بابني؟! فانطلق إلى النبي -صلى الله عليه سلم- شاكيا زوجته وما كان منها ، فقال رسول الله صلى الله عليه وسلم داعياً لهما بما يعود نفعه عليهما الجميل فعلهما: (بارك الله لكما في ليلتكما) أي فيما فعلتماه فيها؛ بأن يجعله نتاجاً طيباً وثمرة حسنة.
ثم حملت -رضي الله عنها- بعد ذلك وكانت هي وزوجها مع النبي صلى الله عليه وسلم في بعض أسفاره، فلما أرادوا دخول المدينة ضربها المخاض، أي : شعرت رضي الله عنها بآلام الولادة، وكان من عادته صلى الله عليه وسلم لا يدخل المدينة ، حتى يُرسل رسولا يخبرهم بقدوم القافلة، فَاحْتُبِسَ عَلَيْهَا أبو طلحة رضي الله عنه عند ذلك لاشتغاله بشأنها، وانطلق رسول الله صلى الله عليه وسلم . 
ثم دعا أبو طلحة ربه بقوله: إنك لَتَعْلَمُ يا رب أنه يعجبني أن أخرج مع رسول الله صلى الله عليه وسلم إذا خرج وأدخل معه إذا دخل وَقَدِ احْتَبَسْتُ بِمَا تَرَى، فقالت له أم سليم رضي الله عنها : يا أبا طلحة، ما أجد الذي كنت أجد. أي: ما أجد ألم الوضع الذي كنت أجده من قبل، ثم قالت له: انطلق.
فلما قدموا المدينة ضربها المخاض، فولدت غلامًا ، ثم أمرت أنسًا رضي الله عنه أن يذهب به إلى النبي صلى الله عليه وسلم وأن لا يرضعه أحد من المرضعات ؛ ليكون أول ما ينزل في جوفه ريق النبي صلى الله عليه وسلم فيعود عليه بخير الدارين، وقد ظهر أثره في هذا الغلام بتكثير بنيه الصالحين الأتقياء الفالحين. 
ومما يختم به هذا الشرح أن التبرك بما انفصل من الجسد من خصائص النبي صلى الله عليه وسلم ، التي لا يشركه أحد من هذه الأمة، وأكبر دليل على ذلك أن الصحابة رضي الله عنهم الذين شاهدوا التنزيل ووقفوا على حقائق الدين، لم يتبركوا بالخلفاء الراشدين، ولا بغيرهم من أهل العشرة.', 'فضل الصبر والتسليم لأمر الله -تعالى-، وأن فاعل ذلك رجي له الإخلاف في الدنيا والأجر في الآخرة، كما في الدعاء المأثور: "اللهم أجرني في مصيبتي واخلف لي خيرا منها".
في الحديث مثال واقعي للمرأة المسلمة والزوجة الصالحة في عقلها الكبير وذكائها الوقاد.
صبر أم سليم -رضي الله عنها- على موت ولدها مثال يحتذى به في الصبر على المصائب.
التلطف في الإخبار عند وجود المصيبة.
إيثار إرضاء الزوج على حزنه، وهذا من وفاء الزوجة لزوجها.
حُبُّ الصحابة للنبي -صلى الله عليه وسلم- والحرص على ملازمته واستشارته.
من السنة أن يخفف كل من الزوجين مصيبة الآخر.
اختيار الأسماء الكريمة للأبناء، وأفضل الأسماء عبدالله وعبد الرحمن.
من ترك شيئاً لله عوضه الله خيراً منه؛ فعندما احتسب أبو طلحة ولده أخلفه الله آخر، وأصلح له ذريته وبارك فيها.
تزيين المرأة لزوجها أدعى لدوام العشرة وتمكين المودة، كما صنعت أم سليم لأبي طلحة -رضي الله عنهما- وأقرها الرسول -صلى الله عليه وسلم- بدعائه لهما بالبركة.
اجتهاد المرأة في عمل مصالح زوجها والقيام على خدمته، كما صنعت أم سليم حيث قربت له العشاء فتعشى، وتهيأت له ثم بلغته الخبر بحكمة وحسن رأي.
جواز المعاريض عند الحاجة إليها، وأن ذلك لا يعدُّ من الكذب، وهي أن يقول كلامًا يحتمل وجهًا يقصده في نفسه ويوهم السامع به احتمالًا آخر، وشرط جوازها: أن لا تبطل حقاً، ولا تمكن لباطل، وأن يحتمل اللفظ ذلك المعنى في اللغة.
بركة دعاء النبي -صلى الله عليه وسلم-، حيث كان للمولود تسعة من الولد كلهم يقرأون القرآن، ببركة دعاء النبي -صلى الله عليه وسلم-.
إجابة دعوة النبي -صلى الله عليه وسلم-.
كرامة لأبي طلحة، فإن الله تعالى استجاب له دعائه: (إنك لَتَعْلَمُ يَا رَبِّ أنه يُعْجِبُنِي أن أخرج مع رسول الله -صلى الله عليه وسلم- إذا خرج وأدخل معه إذا دخل وقد احْتَبَسْتُ بما ترى).
مشروعية تحنيك الصَّبي عند الولادة.
اللجوء إلى الله عند طلب مرغوب أو صرف مرهوب، فإن أبا طلحة -رضي الله عنه- دعاء ربه ؛ ليكون برفقة النبي -صلى الله وسلم- ذهابا وإيابا ولا يتخلف عنه.
جواز التوسل بالأعمال الصالحة.', 'يشتكي : يُعاني المرض.
هو أسكن ما كان : المقصود: أنه مات.
أصَاب منها : جامعها.
وارُوا الصَّبي : ادفنوه.
أعَرَّسْتُمُ : أوقع منكم جماع.
حنَّكَه : التحنيك: مَضْغُ الشيء، ووضعه في فَمِّ الصَّبي ودلك حَنَكَه به.
تَصَنَّعَتْ له : تزيَّنت وتجمَّلت له، وفي رواية: "ثم تَطَيَّبَت".
وقَعَ بها : جامعها.
أرأيت : أخْبِرْني.
احْتَسِبْ : اطلب ثواب مصيبتك في ابنك من الله -تعالى-.
عَارِيَتَهُمْ : العارية: ما تعطيه غيرك على أن يعيده إليك.
تَلطَّخْتُ : تقذَّرت بالجماع.
لا يَطْرُقُهَا طُرُوقًا : لا يدخل عليها ليلاً.
المَخَاضُ : وجع الطلق والولادة.
احْتَبَسَ عليها : حبس نَفْسَه عليها، فأقام معها وتأخر عن ركْبِ الرسول -صلى الله عليه وسلم -.
احْتَبَسْتُ بما ترى : مُنعت من الدخول بسبب ما نَزَل بأم سليم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6612', false),
(20045, 2, 201, 45, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «ليس الشديد بالصرعة، إنما الشديد الذى يملك نفسه عند الغضب».', 'Messenger of Allah (ﷺ) said, "The strong man is not one who is good at wrestling, but the strong man is one who controls himself in a fit of rage.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 45', 'Riyad as-Salihin 45', 'ریاض الصالحین 45', 'متفق عليه', 'يُبَيِّنُ النبيُّ صلى الله عليه وسلم أنَّ القوةَ الحقيقيةَ ليست قوةَ الجَسَد، أو الذي يَصْرَعُ غيرَه من الأقوياء، وإنما القويُّ الشديدُ هو الذي جاهَدَ نفسَه وقَهَرَها حينما يَشتدُّ به الغضبُ؛ لأنَّ هذا يدل على قوّة تَمَكُّنِهِ من نفسه وتَغَلُّبِه على الشيطان.', 'فضيلة الحِلْم وضَبْط النفس عند الغضب، وأنه من الأعمال الصالحة التي حَثَّ عليها الإسلام.
مجاهدة النفس عند الغضب أشدُّ من مجاهدة العدو.
تغيير الإسلام لمفهوم القوة الجاهلي إلى أخلاق كريمة، فأشد الناس قوّة هو مَن مَلَكَ زِمَام نفسِه.
الابتعاد عن الغضب؛ لما يسبِّبُه من الأضرار على الأفراد والمجتمع.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5351', false),
(20046, 2, 201, 46, 'hadith', 'عن سليمان بن صرد رضي الله عنه قال: كنت جالساً مع النبي صلى الله عليه وسلم، ورجلان يستبان، وأحدهما قد احمر وجهه، وانتفخت أوداجه. فقال رسول الله صلى الله عليه وسلم: " إني لأعلم كلمة لو قالها لذهب عنه ما يجد، لو قال: أعوذ بالله من الشيطان الرجيم ذهب منه ما يجد". فقال له: إن النبي صلى الله عليه وسلم قال: " تعوذ بالله من الشيطان الرجيم".', 'I was sitting with the Prophet (ﷺ) when two men began to quarrel and curse each other and the face of one of them turned red and the veins of his neck were swollen (from rage). Messenger of Allah (ﷺ) said, "I know of a word, if he were to utter that, his rage would vanish and that is: A''udhu billahi minash-Shaitan nir-rajim (I seek refuge with Allah from Satan, the accursed)." So they (Companions) said to him: "The Prophet (ﷺ) tells you to utter: ''I seek refuge with Allah from Satan, the accursed"..', 'سليمان بن صرد رضي الله عنه', 'Sulaiman bin Surad (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 46', 'Riyad as-Salihin 46', 'ریاض الصالحین 46', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20047, 2, 201, 47, 'hadith', 'عن معاذ بن أنس رضي الله عنه أن النبي صلى الله عليه وسلم قال: « من كظم غيظاً ، وهو قادر على أن ينفذه، دعاه الله سبحانه وتعالى على رؤوس الخلائق يوم القيامة حتى يخيره من الحور العين ما شاء».', 'The Prophet (ﷺ) said, "The one who suppresses anger and has the power to give effect to it, will be called out by Allah, the Exalted, to the forefront of the creatures on the Day of Resurrection and he will be asked to choose any of the virgins (Hur) of his liking"..', 'معاذ بن أنس رضي الله عنه', 'Mu''adh bin Anas (May Allah be pleased with him)', 'حسن لغيره', 'رياض الصالحين 47', 'Riyad as-Salihin 47', 'ریاض الصالحین 47', 'رواه أبو داود، والترمذي وقال: حديث حسن', 'في الحديث أن الإنسان إذا غَضِب من شخص وهو قادر على أن يفتك به، ولكنه ترك ذلك ابتغاء وجه الله، وصبر على ما حصل له من أسباب الغيظ فله هذا الثواب العظيم، وهو أنه يدعى على رؤوس الخلائق يوم القيامة ويخيَّر من أي نساء الجنة الحسناوات شاء.', 'الحث على كظم الغيظ؛ لأنه من صفات المؤمنين الكُمَّل؛ لقوله تعالى: (والكاظمين الغيظ والعافين عن الناس والله يحب المحسنين).
العفو عند القدرة على الانتصار، وما فيه من الثواب.
علو مكانة الكاظمين الغيظ يوم القيامة.', 'كظم غيظًا : تحمل القهر وكتم سببه وصبر عليه، والكظم الحبس والمنع من الظهور.
الحُور العِيْن : الحور جمع حوراء، وهي شديدة البياض في العين وشديدة السواد.والعِيْن: جمع عيناء، وهي واسعة العين، والمراد هنا الحسان من النساء في الجنة.', 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3287', false),
(20048, 2, 201, 48, 'hadith', 'عن أبي هريرة رضي الله عنه ، أن رجلاً قال للنبي صلى الله عليه وسلم: أوصني، قال: "لا تغضب" فردد مراراً، قال: " لاتغضب" رواه البخاري.', 'A man asked the Prophet (ﷺ) for an advice and he (ﷺ) said, "Do not get angry". The man repeated that several times and he replied, "Do not get angry"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 48', 'Riyad as-Salihin 48', 'ریاض الصالحین 48', null, 'طَلبَ أحدُ الصحابة رضوان الله عليهم من النبي صلى الله عليه وسلم أن يَدُلَّه على شيء ينفعه، فأمره ألّا يغضب، ومعنى ذلك أن يَجتنبَ الأسبابَ التي تحمله على الغضب، وأن يَضبطَ نفسَه إذا حَصَل له الغضب، فلا يَتَمادى مع غضبه بالقتل أوالضرب أوالسب ونحو ذلك. 

وردَّدَ الرجلُ طَلَبَ الوصيةِ مَرَّات، فلم يَزِدْه صلى الله عليه وسلم في الوصية على "لا تغضب".', 'التحذير من الغضب وأسبابه، فإنه جِماعُ الشر، والتحرُّزُ منه جماعُ الخير.
الغضب لله كالغضب عند انتهاك محارم الله من الغضب المحمود.
تَكرار الكلام عند الحاجة حتى يَعِيَه السامعُ ويُدرك أهميتَه.
فضيلة طلب الوصية من العالِم.', '---', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4709', false),
(20049, 2, 201, 49, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : « ما يزال البلاء بالمؤمن والمؤمنة في نفسه وولده ة وماله حتى يلقى الله تعالى وما عليه خطيئة».', 'Messenger of Allah (ﷺ) said, "A Muslim, male or female, continues to remain under trial in respect of his life, property and offspring until he faces Allah, the Exalted, with no sin record"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 49', 'Riyad as-Salihin 49', 'ریاض الصالحین 49', 'رواه الترمذي وقال حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20050, 2, 201, 50, 'hadith', 'عن ابن عباس رضي الله عنهما قال: قدم عيينة بن حصن فنزل على ابن أخيه الحر بن قيس، وكان من النفر الذين يدنيهم عمر رضي الله عنه، وكان القراء أصحاب مجلس عمر رضي الله عنه ومشاورته كهولاً كانوا أو شباناً، فقال عيينة لابن أخيه : يا ابن أخي لك وجه عند هذا الأمير فاستأذن لي عليه، فاستأذن فأذن عمر. فلما دخل قال: هِىَ يا ابن الخطاب، فوالله ما تعطينا الجزل ولا تحكم فينا بالعدل، فغضب عمر رضي الله عنه حتى همّ أن يوقع به، فقال له الحر: يا أمير المؤمنين إن الله تعالى قال لنبيه صلى الله عليه وسلم: {خذ العفو وأمر بالعرف وأعرض عن الجاهلين}.', '''Uyainah bin Hisn came to Al-Madinah and stayed with his nephew Hurr bin Qais who was among those whom Umar (May Allah be pleased with him) showed favour to. The knowledgeable people (Qurra''), whether they were old or young, had the privilege of joining Umar''s council and he used to consult them. ''Uyainah said to Hurr: "My nephew, the Leader of the Believers shows favour to you. Will you obtain permission for me to sit with him?" Hurr asked ''Umar and he accorded permission. When ''Uyainah came into the presence of ''Umar, he addressed him thus: "O son of Khattab, you neither bestow much on us nor deal with us justly." ''Umar (May Allah be pleased with him) got angry and was about to beat him up when Hurr said: ''''O Leader of the Believers, Allah said to His Prophet (ﷺ): '' Show forgiveness, enjoin what is good, and turn away from the foolish (i.e., don''t punish them).'' (7:199) This one is from the ignorants. When Hurr recited this, ''Umar became quite motionless in his seat. He always adhered strictly to the Book of Allah..', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 50', 'Riyad as-Salihin 50', 'ریاض الصالحین 50', 'الأعراف: 199)). وإن هذا من الجاهلين، والله ما جاوزها عمر حين تلاها، وكان وقافاً عند كتاب الله تعالى. ((رواه البخاري', 'يُحدِثُنا الصحابي الجليل عبد الله بن عباس رضي الله عنهما عما حصل لأمير المؤمنين عمر بن الخطاب رضي الله عنه ، حيث قدم عليه عيينة بن حصن رضي الله عنه ، وكان من كبار قومه، فبدأ كلامه الفض بالتهجُّم والاستنكار، ثم عقَّبه بالمُعاتبة قائلاً: إِنَّك لا تُعطِينا الجزل، ولا تحكم فينا بالعدل، فغضب عمر رضي الله عنه غضبا حتى كاد يضربه، ولكن قام بعض القُرَّاء ومنهم ابن أخي عيينة وهو الحر بن قيس مخاطبا الخليفة الراشد رضي الله عنه : يا أمير المؤمنين، إن الله تعالى قال لنبيه صلى الله عليه وسلم : "خذ العفو وأمر بالعرف وأعرض عن الجاهلين" ، وإن هذا من الجاهلين، فوقف عمر عندها وكتم غضبه، ولم يتجاوزها؛ لأنه كان وقَّافا عند كتاب الله -رضي الله عنه وأرضاه-، فوقف وما ضرب الرجل؛ لأجل الآية التي تُلِيت على مسامعه.
فهذا هو أدب الصحابة رضي الله عنهم عند كتاب الله؛ لا يتجاوزونه، إذا قيل لهم هذا قول الله وَقَفُوا، مهما كان الأمر.', 'منزلة قُرَّاء القرآن، وهم العلماء العاملون بأحكامه، لا المتكسبون بتلاوته في المآتم والأفراح.
أنه ينبغي لولي الأمر مجالسة القراء والفقهاء ليذكروه إذا نسي، ويعينوه إذا ذكر.
رأي أهل العلم لا يكون بهوى ولا لمصلحة، بل يكون نصرة لله ورسوله -صلى الله عليه وسلم-، فالحق أحب إليهم من أنفسهم وآبائهم وأبنائهم وعشيرتهم.
تحبب الحاكم لأهل العلم وأهل مشورته بأن يستجيب لطلباتهم ما لم يكن فيه معصية.
منقبة عمر بن الخطاب -رضي الله عنه- بأنه كان وقَّافا عند حدود الله ممتثلا لأوامره، لا يتجاوزها ولا يتعدَّاها.
استحباب صبر الإمام على الرعية، والحرص على مصالحها؛ فقد ظهر صبر أمير المؤمنين عمر بن الخطاب -رضي الله عنه- في مواطن من هذا الحديث.
حكمة العالم في تذكير إمامه.
فضل الحلم والصفح عن الجهال.', 'القُرَّاء : العلماء العباد.
هِيَ : وفيها لغات: هيه، وإيه، وهي كلمة تقال لغرضين: 1. الاستزادة من عمل أو قول. 2. الزجر والتهديد، وهو المراد من الحديث.
الجَزلَ : الكثير العظيم من كل شيء.
همَّ أن يُوقِع به : يضربه.
كان وقَّافًا عند كتاب الله تعالى : يعمل بما فيه، ولا يتجاوزه أو يتركه.
النفر : ما دون العشرة من الرجال.
أصحاب مجلِس عمر : أي الملازمين لمجلسه.
كُهُولا : من زاد عمره على ثلاث وثلاثين سنة في رأي أغلب أهل اللغة.
لَكَ وجه : لك جاه ومنزلة.
العُرف : المعروف.
أعرِض عن الجاهلين : لا تُقابلهم بِسَفَهِهِم.
خُذِ العَفو : ما عفا وتيسر من أخلاق الناس ولا تبحث عنها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3155', false),
(20051, 2, 201, 51, 'hadith', 'عن ابن مسعود رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: « إنها ستكون بعدي أثرة وأمور تنكرونها ! قالوا: يا رسول الله فما تأمرنا؟ قال: تؤدون الحق الذى عليكم ، وتسألون الله الذى لكم».', 'Messenger of Allah (ﷺ) said, "You will see after me favouritism and things which you will disapprove of." They submitted: "What do you order us to do (under such circumstances)?" He replied, "Discharge your obligations and ask your rights from Allah"..', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 51', 'Riyad as-Salihin 51', 'ریاض الصالحین 51', 'متفق عليه', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أنه سيتولى على المسلمين وُلاةٌ يَستأثِرون بأموال المسلمين وغيرِها مِن أمور الدنيا، يَصْرِفُونها كما شاؤوا ويمنعون المسلمين حقَّهم فيها. 
وسيكون منهم في الدِّين أمورٌ تُنْكَر. 
فسَألَ الصحابةُ رضي الله عنهم: ماذا يفعلون في تلك الحال؟ 
فأخبرهم صلى الله عليه وسلم أنه لا يمنعكم انفرادُهم بالمال أنْ تَمْنَعوا ما يجب عليكم نحوَهم من السمع والطاعة، بل اصبروا واسمعوا وأطيعوا ولا تنازعوهم الأمر، واسألوا الحق الذي لكم من الله، وأن يُصلحَهم ويَدفعَ شرَّهم وظلمَهم.', 'الحديثُ من دلائل نبوَّتِه صلى الله عليه وسلم حيث أخبر بما سيكون في أمته فوقع كما أخبر.
جوازُ إعلام المُبتلى بما يُتَوَقَع له من البلاء؛ لِيُوَطِّنَ نفسَه فإذا أتاه كان صابرًا محتسبًا.
الاعتصام بالكتاب والسنة مخرج من الفتن والاختلاف.
الحث على السمع والطاعة لولاة الأمور بالمعروف، وعدم الخروج عليهم، وإنْ وقع منهم ظلم.
استعمال الحكمة واتباع السنة في زمن الفتن.
على الإنسان القيام بالحق الذي عليه وإنْ حَصَل عليه شيء من الظلم.
فيه دليلٌ على القاعدة: يختار أهون الشرين أو أخف الضررين.', 'الأَثَرَة: الاستئثار عليهم بأمور الدنيا والانفراد بها، عمن له فيه حق.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3156', false),
(20052, 2, 201, 52, 'hadith', 'عن أبي يحيى أسيد بن حضير رضي الله عنه أن رجلاً من الأنصار قال: يا رسول الله ألا تستعملني كما استعملت فلاناً فقال: «إنكم ستلقون بعدي أثرة، فاصبروا حتى تلقوني على الحوض».', 'A person from among the Ansar said, "O Messenger of Allah! You appointed such and such person and why do you not appoint me?" Messenger of Allah (ﷺ) said, "After me you will see others given preference to you, but you should remain patient till you meet me at the Haud (Al- Kauthar in Jannah)"..', 'أبي يحيى أسيد بن حضير رضي الله عنه', 'Usaid bin Hudhair (May Allah be pleased with him) reported that:', 'صحيح', 'رياض الصالحين 52', 'Riyad as-Salihin 52', 'ریاض الصالحین 52', 'متفق عليه', 'جاء رجل ٌ إلى النبي صلى الله عليه وسلم وطلب منه أن يجعله عاملاً على منصب من المناصب كبقية الذين ولاهم، فإنّه أخبره النبي -عليه السلام- بأمر وهو أنه عليه وعلى أصحابه أن يصبروا على ما يلقونه من ظلم وجور في المستقبل من حكام ينفردون بالمال والخيرات دون رعيتهم، فأمرهم بالصبر حتى يردوا عليه حوضه -عليه السلام-.', 'معجزة النبي -صلى الله عليه وسلم- في الإخبار عما سيقع في المستقبل.
الأفضل عدم طلب الولاية إلا إذا كان أهلا لها وليس من أحد ينافسه عليها.
بُعد نظره -صلى الله عليه وسلم- وعدم ترشيحه أحدًا لولاية لا يكون كفؤًا لها.
الصبر عند فساد الأمور، وعدم تولية أصحاب الكفاءة.
أفاد قوله "سَتَلقَون بَعدِي أَثَرَة" نفي ظن السائل أن رسول الله -صلى الله عليه وسلم- آثر الذي ولاَّه عليه؛ فبيَّن -صلى الله عليه وسلم- أن ذلك لا يقع في زمانه، وأنه لم يخصه بذلك لذاته وإنما لمصلحة المسلمين وإن الاستئثار للحظ الدنيوي إنما يقع بعده.
الصبر على ظلم الحاكم إذا استأثر بدنيا، وعدم الخروج عليه ما لم يأت بكفر بَوَاح.
فيه بيان منقبة للأنصار وأنهم ممن يرد الحوض على رسول الله -صلى الله عليه وسلم-.', 'ألا : أداة عرض.
تَستَعمِلُنِي : تُصيّرني عاملاً.
فلانا : لفظ يُكَنَّى به عن اسم شخص ما، وهو خاص بالناس دون الحيوانات غالبا.
الأَثَرَة : الانفراد بالشيء عمن له فيه حق.
الحوض : الحوض المورود الذي خُصَّ به نبينا -صلى الله عليه وسلم- في الجنة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3305', false),
(20053, 2, 201, 53, 'hadith', 'عن أبي إبراهيم عبد الله بن أبي أوفى رضي الله عنهما أن رسول الله صلى الله عليه وسلم في بعض أيامه التي لقي فيها العدو، انتظر حتى إذا مالت الشمس قام فيهم فقال: " يا أيها الناس لا تتمنوا لقاء العدو، واسألوا الله العافية، فإذا لقيتموهم فاصبروا، واعلموا أن الجنة تحت ظلال السيوف" ثم قال النبي صلى الله عليه وسلم : " اللهم منزل الكتاب ومجري السحاب ، وهازم الأحزاب، اهزمهم وانصرنا عليهم" ((متفق عليه)) وبالله التوفيق.', 'The Messenger of Allah (ﷺ) at one time when he confronted the enemy, and was waiting for the sun to set, stood up and said, "O people! Do not long for encountering the enemy and supplicate to Allah to grant you security. But when you face the enemy, show patience and steadfastness; and keep it in mind that Jannah lies under the shade of the swords." Then he invoked Allah, saying, "O Allah, Revealer of the Book, Disperser of the clouds, Defeater of the Confederates, put our enemy to rout and help us in over-powering them"..', 'أبي إبراهيم عبد الله بن أبي أوفى رضي الله عنهما', '''Abdullah bin Abu Aufa (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 53', 'Riyad as-Salihin 53', 'ریاض الصالحین 53', null, 'يخبر عبد الله بن أبي أوفى الصحابي رضي الله عنه أن النبي صلى الله عليه وسلم لقي العدو في بعض أيامه فانتظر ولم يبدأ بالقتال إلا بعد أن زالت الشمس، ولما زالت الشمس قام فيهم -والمعتاد أن يكون ذلك بعد الصلاة- قام فيهم خطيباً فنهاهم عن تمني لقاء العدو لما فيه من الإعجاب بالنفس، وأن يسألوا الله العافية، ثم قال: فإذا لقيتموهم فاصبروا. أي إن حقق الله ذلك وابتليتم بلقاء العدو فاصبروا عند ذلك واتركوا الجزع، واعلموا أن لكم إحدى الحسنيين إما أن ينصركم الله على عدوكم وتكون لكم الغلبة، ويجمع الله لكم بين قهر العدو في الدنيا والثواب في الآخرة، وإما أن تُغلبوا بعد أن بذلتم المجهود في الجهاد فيكون لكم الثواب الأخروي، أما قوله: واعلموا أن الجنة تحت ظلال السيوف. فمعناه أن الجهاد يؤدي إلى الجنة
ن ثم دعا رسول الله صلى الله عليه وسلم ربه بشرعه المنزل وقدرته الكاملة أن ينصر المسلمين على عدوهم وبالله التوفيق.', 'اختيار الوقت المناسب للقتال، فإما أن يكون أول النهار، وإلا بعد الزوال.
كراهية تَمنِّي قتال الأعداء؛ لعواقبه الوخيمة، كـ: الجهل بعاقبة الأمر؛ لما فيه من الغرور وقلة الحزم الجالب للخذلان والهزيمة.
سؤال العافية، وهي شاملة لعافية الدين والدنيا والأبدان.
الصبر عند لقاء العدو، لأنه السبب الأكبر في الظفر والانتصار.
فضيلة الجهاد، وأنه سبب قريب في دخول الجنة.
الدعاء بهذه الدعوات المناسبات، عند لقاء الأعداء، كما كان النبي صلى الله عليه وسلم يفعله.
الدعاء بصفات الله التي تناسب طلب الداعي، لقوله: "وهازم الأحزاب، اهزمهم".', 'في بعض أيامه : في بعض غزواته.
مالت الشمس : زالت عن وسط السماء.
لا تتمنوا لقاء العدو : لا تتمنوا القتال؛ لأن المرء لا يعلم ما يؤول إليه الأمر.
تحت ظلال السيوف : في حضور المعركة وقتال الكفار وجهادهم في سبيل الله.
منزل الكتاب : منزل القرآن.
ومجري السحاب : محرك ومسير الغيوم، بقدرته سبحانه وفيه إِشارة إلى سرعة جريه.
هازم الأحزاب : المجتمعون من أهل الكفر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/2953', false),
(20054, 2, 201, 54, 'hadith', 'فالأول عن ابن مسعود رضي الله عن النبي صلى الله عليه وسلم قال: «إن الصدق يهدي إلى البر وإن البر يهدي إلى الجنة، وإن الرجل ليصدق حتى يكتب عند الله صديقاً، وإن الكذب يهدي إلى الفجور، وإن الفجور يهدي إلى النار، وإن الرجل ليكذب حتى يكتب عند الله كذاباً».', 'The Prophet (ﷺ) said, "Truth leads to piety and piety leads to Jannah. A man persists in speaking the truth till he is enrolled with Allah as a truthful. Falsehood leads to vice and vice leads to the Fire (Hell), and a person persists on telling lies until he is enrolled as a liar".''.', null, 'Abdullah bin Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 54', 'Riyad as-Salihin 54', 'ریاض الصالحین 54', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20055, 2, 201, 55, 'hadith', 'عن أبي محمد الحسن بن علي بن أبي طالب، رضي الله عنهما ، قال : حفظت من رسول الله، صلى الله عليه وسلم : «دع ما يريبك إلى ما لا يريبك؛ فإن الصدق طمأنينة، والكذب ريبةٌ».', 'I remember (these words) from Messenger of Allah (ﷺ): "Give up what is doubtful to you for that which is not doubtful; for truth is peace of mind and falsehood is doubt"..', 'أبي محمد الحسن بن علي بن أبي طالب رضي الله عنهما', 'Hasan bin ''Ali (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 55', 'Riyad as-Salihin 55', 'ریاض الصالحین 55', 'رواه الترمذي وقال حديث حسن صحيح', 'أَمَرَ النبيُّ صلى الله عليه وسلم بِتَرْك ما تَشُكُّ فيه مِن الأقوال والأعمال أنه مَنهيٌّ عنه أو لا، أهو حرام أو حلال، إلى ما لا شَكَّ فيه مما تَيَقَّنت حُسْنَه وحِلَّه.', 'على المسلم بناء أموره على اليقين وترك المشكوك فيه، وأن يكون في دينه على بصيرة.
النهي عن الوقوع في الشبهات.
إذا أردتَ الطمأنينةَ والاستراحة فاترك المشكوك فيه واطرحه جانبًا.
رحمة الله بعباده إذ أمرَهم بما فيه راحة النفس والبال ونهاهم عمّا فيه قَلَقٌ وحَيْرة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66519', false),
(20056, 2, 201, 56, 'hadith', 'عن أبي سفيان صخر بن حرب ، رضي الله عنه، في حديثه الطويل في قصة هرقل، قال هرقل: فماذا يأمركم -يعنى النبي صلى الله عليه وسلم- قال أبو سفيان: قلت :يقول : « اعبدوا الله وحده لا تشركوا به شيئاً، واتركوا ما يقول آباؤكم ، ويأمرنا بالصلاة، والصدق، والعفاف، والصلة».', 'He (ﷺ) told (us): "Worship Allah Alone and do not associate a thing with Him; and give up all that your ancestors said. "He also commands us to perform Salat (prayers), to speak the truth, to observe modesty and to strengthen the ties of kinship..', 'أبي سفيان صخر بن حرب رضي الله عنه', 'Abu Sufyan (May Allah be pleased with him) reported, in course of his detailed narration about Heraclius when the latter questioned him about the teachings of the Prophet (ﷺ) He said that:', 'صحيح', 'رياض الصالحين 56', 'Riyad as-Salihin 56', 'ریاض الصالحین 56', 'متفق عليه', 'هذا حديث أبي سفيان صخر بن حرب رضي الله عنه المشهور مع هرقل، كان أبو سفيان وقتئذ مشركًا، حيث لم يسلم إلا متأخرًا، فيما بين صلح الحديبية وفتح مكة، قَدِم أبو سفيان ومعه جماعة من قريش إلى هرقل في الشام، وهرقل كان ملك النصارى في ذلك الوقت، وكان قد قرأ في التوراة والإنجيل وعرف الكتب السابقة، وكان ملكًا ذكيًا، فلما سمع بأبي سفيان ومن معه وهم قادمون من الحجاز دعا بهم، وجعل يسألهم عن حال النبي صلى الله عليه وسلم وعن نسبه، وعن أصحابه، وعن توقيرهم له، وعن وفائه صلى الله عليه وسلم ، وكلما ذكر شيئا أخبروه عرف أنه النبي الذي أخبرت به الكتب السابقة، ولكنه - والعياذ بالله- شح بملكه فلم يسلم للحكمة التي أرادها الله عز وجل .
وكان فيما سأل أبا سفيان سؤاله عمَّا كان يأمرهم به النبي صلى الله عليه وسلم فأخبره بأنه يأمرهم أن يعبدوا الله ولا يشركوا به شيئا، فلا يعبدوا غير الله، لا ملكًا ولا رسولاً، ولا شجرًا ولا حجرًا، ولا شمساً ولا قمرًا، ولا غير ذلك، فالعبادة لله وحده، وهذه دعوة الرسل، فجاء النبي صلى الله عليه وسلم بما جاءت به الأنبياء من قبله بعبادة الله وحده لا شريك له.
ويقول: "اتركوا ما كان عليه آباؤكم" وهذا من الصدع بالحق، فكل ما كان آباؤهم من عبادة الأصنام أمرهم النبي صلى الله عليه وسلم بتركه، وأما ما كان عليه آباؤهم من الأخلاق الفاضلة؛ فإنه لم يأمرهم بتركه.
وقوله: "وكان يأمرنا بالصلاة" الصلاة صلة بين العبد وبين ربه، وهي آكد أركان الإسلام بعد الشهادتين، وبها يتميز المؤمن من الكافر، فهي العهد الذي بيننا وبين المشركين والكافرين، كما قال النبي -عليه الصلاة والسلام-: "العهد الذي بيننا وبينهم الصلاة، فمن تركه فقد كفر" 
وقوله: "وكان يأمرنا بالصدق" كان النبي صلى الله عليه وسلم يأمر أمته بالصدق، وهذا كقوله تعالى : (يا أيها الذين آمنوا اتقوا الله وكونوا مع الصادقين). والصدق خلق فاضل، ينقسم إلى قسمين:
صدق مع الله، وصدق مع عباد الله، وكلاهما من الأخلاق الفاضلة. 
وقوله "العفاف" أي: العفة، والعفة نوعان: عفة عن شهوة الفرج، وعفة عن شهوة البطن.
أما العفة الأولى: فهي أن يبتعد الإنسان عما حرم عليه من الزنى ووسائله وذرائعه.
أما النوع الثاني من العفاف: فهو العفاف عن شهوة البطن، أي: عما في أيدي الناس، والتعفف عن سؤالهم، بحيث لا يسأل الإنسانُ أحدًا شيئًا؛ لأن السؤال مذلة، والسائل يده دنيا، سفلى، والمعطي يده عليا، فلا يجوز أن تسأل أحدا إلا ما لابد منه.
أما قوله: "الصلة": فهي أن يصل المرء ما أمر الله به أن يوصل من الأقارب الأدنى فالأدنى، وأعلاهم الوالدان، فإن صلة الوالدين بر وصلة، والأقارب لهم من الصلة بقدر ما لهم من القرب، فالأخ أوكد صلة من العم، والعم أشد صلة من عم الأب، وصلة الرحم تحصل بكل ما تعارف عليه الناس.', 'الصدق من أشرف مكارم الأخلاق، وهو محبوب عند الخالق والمخلوق.
ملازمة الرسول -صلى الله عليه وسلم- للصدق وشهرته به، وشهادة الأعداء له بذلك.
رأس هذا الدين توحيد الله -عز وجل- وعدم الإشراك به، وهو أصل الفضائل.
التحذير من التقليد في الباطل، ويتأكَّد ذلك في أمور الدين.
الرسل جميعا أرسلوا من أجل بيان التوحيد الحق، والتحذير من الشرك وإزالته.
الله -سبحانه- يأمر بكل ما يصلح البشر ويعود عليهم بالخير في الدنيا والآخرة.
الحديث يؤكد على شمول الإسلام ودعوته إلى العبادة والتوحيد ومكارم الأخلاق.', 'هِرَقل : ملك الروم، ولقبه قيصر، وكتب إليه رسول الله -صلى الله عليه وسلم- يدعوه للإسلام، وكان ذلك سنة ست من الهجرة.
أبو سفيان : أبو سفيان صخر بن حرب بن أمية بن عبد شمس بن عبد مناف القرشي الأموي المكي، ولد قبل الفيل بعشر سنين، وأسلم ليلة الفتح وكان من المؤلفة، ثم حسن إسلامه، وشهد حنيناً، ثم شهد الطائف وفُقِئَت عينه يومئذٍ، وفقئت عينه الأخرى يوم اليرموك، استعمله النبي -صلى الله عليه وسلم- على نجران.
ما يَقُول آبَاؤُكُم : جميع ما كانوا عليه في أمور الجاهلية، أما مكارم الأخلاق فقد جاء رسول الله -صلى الله عليه وسلم- ليتمها.
العَفَاف : الكف عن المحارم وخوارم المروءة.
الصِّلَة : صلة الأرحام، وكل ما أمر الله -تعالى- به أن يوصل، وذلك بالبر والإكرام.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3154', false),
(20057, 2, 201, 57, 'hadith', 'عن أبي ثابت، وقيل أبي سعيد، وقيل أبي الوليد، سهل بن حنيف ، وهو بدري، رضي الله عنه، أن النبي ، صلى الله عليه وسلم، قال: «من سأل الله، تعالى، الشهادة بصدق بلغه الله منازل الشهداء، وإن مات على فراشه».', 'The Prophet (ﷺ) said: "He who asks Allah for martyrdom, Allah will raise him to the high status of the martyrs, even if he dies on his bed"..', 'أبي ثابت، وقيل أبي سعيد، وقيل أبي الوليد، سهل بن حنيف ، وهو بدري رضي الله عنه', 'Abu Thabit from Sahl bin Hunaif (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 57', 'Riyad as-Salihin 57', 'ریاض الصالحین 57', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20058, 2, 201, 58, 'hadith', 'عن أبي هريرة ، رضي الله عنه ، قال: قال رسول الله صلى الله عليه وسلم : «غزا نبي من الأنبياء صلوات الله وسلامه عليهم فقال لقومه: لا يتبعني رجل ملك بضع امرأة. وهو يريد أن يبني بها ولما يبن بها، ولا أحد بنى بيوتا لم يرفع سقوفها، ولا أحد اشترى غنما أو خلفات وهو ينتظر أولادها. فغزا فدنا من القرية صلاة العصر أو قريباً من ذلك، فقال للشمس: إنك مأمورة وأنا مأمور، اللهم احبسها علينا، فحبست حتى فتح الله عليه، فجمع الغنائم، فجائت -يعني النار- لتأكلها فلم تطعمها، فقال : إن فيكم غلولاً، فليبايعني من كل قبيلةٍ رجل، فلزقت يد رجل بيده فقال: فيكم الغلول، فلتبايعني قبيلتك، فلزقت يد رجلين أو ثلاثة بيده فقال: فيكم الغلول: فجاؤوا برأس مثل رأس بقرة من الذهب، فوضعها فجاءت النار فأكلتها، فلم تحل الغنائم لأحد قبلنا، ثم أحل الله لنا الغنائم لما رأى ضعفنا وعجزنا فأحلها لنا».', '"One of the earlier Prophets who was out on an expedition proclaimed among his people that no man should follow him who had married a woman with whom he wished to cohabit but had not yet done so, or who had built houses on which he had not yet put the roofs, or who had bought sheep or pregnant she-camels and was expecting them to produce young. He, then, went on the expedition and approached the town at the time of the ''Asr prayer or little before it. He then told the sun that both it and he were under command and prayed Allah to hold it back for them, so it was held back till Allah gave him victory. He collected the spoils and it (meaning fire) came to devour these, but did not. He said that among the people there was a man who stole from the booty. He told them that a man from every tribe must swear allegiance to him, and when a man''s hand stuck to his, he said: "There is thief among you and every individual of your tribe must swear allegiance to me". (In course of swearing of allegiance,) hands of two or three persons stuck to his hand. He said: "The thief is among you". They brought him a head of gold like a cow''s head and when he laid it down, the fire came and devoured the spoils. Spoils were not allowed to anyone before us, then Allah allowed spoils to us as He saw our weakness and incapacity and allowed them to us"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) reported that the Messenger of Allah (ﷺ) said:', 'صحيح', 'رياض الصالحين 58', 'Riyad as-Salihin 58', 'ریاض الصالحین 58', 'متفق عليه', 'أخبر النبي صلى الله عليه وسلم عن نبي من الأنبياء -عليهم الصلاة والسلام- أنه غزا قومًا أُمِر بجهادهم، لكنه -عليه الصلاة والسلام- مَنَع كل إنسان عَقَد على امرأة ولم يَدخُل بها، وكل إنسان بنى بيتًا ولم يرفع سقفه، وكل إنسان اشترى غنمًا أو خَلِفَات وهو ينتظر أولادها، وذلك لأَنَّ هؤلاء يكونون مشغولين بما أهمهم، فالرجل المتزوج مشغول بزوجته التي لم يدخل بها، فهو في شوق إليها، وكذلك الرجل الذي رفع بيتًا ولم يُسَقِّفه، هو أيضا مشتغل بهذا البيت الذي يريد أن يسكنه هو وأهله، وكذلك صاحب الخلفات والغنم مشغول بها ينتظر أولادها.
والجهاد ينبغي أن يكون الإنسان فيه مُتَفَرِّغًا، ليس له همٌّ إلا الجهاد، ثم إن هذا النبي غزا، فنَزَل بالقوم بعد صلاة العصر، وقد أَقْبَل اللَّيل، وخاف إن أظلَم اللَّيلُ أن لا يكون هناك انتصار، فجعل يخاطب الشمس يقول: أنت مأمورة وأنا مأمور، لكن أمر الشمس أمر كوني وأما أمره فأمر شرعي.
فهو مأمور بالجهاد والشمس مأمورة أن تسير حيث أمرها الله عز وجل، قال الله: (والشمس تجري لمستقر لها ذلك تقدير العزيز العليم)، منذ خلقها الله عز وجل وهي سائرة حيث أمرت لا تتقدم ولا تتأخر ولا تنزل ولا ترتفع.
قال: "اللهم فاحبسها عنا" فحبس الله الشمس ولم تغب في وقتها، حتى غزا هذا النبي وغنم غنائم كثيرة، ولما غنم الغنائم وكانت الغنائم في الأمم السابقة لا تحل للغزاة، بل حل الغنائم من خصائص هذه الأمة ولله الحمد، أما الأمم السابقة فكانوا يجمعون الغنائم فتنزل عليها نار من السماء فتحرقها إذا كان الله قد تقبلها، فجُمِعَت الغنائم فنزلت النار ولم تأكلها، فقال هذا النبي: فيكم الغلول.
ثم أمر من كل قبيلة أن يتقدَّم واحد يبايعه على أنَّه لا غُلُول، فلمَّا بايعوه على أنَّه لا غلول لَزِقَت يد أحد منهم بيدِ النبي -عليه الصلاة والسلام-، فلمَّا لَزِقَت قال: فيكم الغلول -أي: هذه القبيلة- ثم أمر بأن يبايعه كل واحد على حدة من هذه القبيلة، فلزقت يد رجلين أو ثلاثة منهم، فقال: فيكم الغلول: فجاؤوا به، فإذا هُم قد أخفوا مثل رأس الثور من الذهب، فلمَّا جيء به ووضع مع الغنائم أكلتها النار.', 'الجهاد مشروع في الأمم السابقة، كما هو مشروع في هذه الأمة.
نهي النبي قومه عن اتباعه على أحد هذه الأحوال؛ لأن أصحابها يكونون متعلقي النفوس بهذه الأسباب، فتضعف عزائمهم وتفتر رغباتهم في الجهاد والشهادة.
مقصود النبي من توجيهاته تفرغ أصحابه من العوائق والأشغال ليقبلوا على الجهاد بنية صادقة وعزم حازم.
كفاية المجاهدين أمور الدنيا ليتفرغوا للجهاد بصدق.
تنوُّع الأمر إلى نوعين: أمر تكويني قدري وآخر تكليفي شرعي، فأمر الجمادات أمر تسخير وتكوين، أي قول النبي للشمس: احتبسي وانتظري، أي بتقدير الله، فهو مثل الدعاء لله بحصول هذا الشيء، وأمر العقلاء أمر تكليف، مثل قوله تعالى: (كتب عليكم القتال) (أطيعوا الله).
ثبوت المعجزات للأنبياء عليهم الصلاة والسلام.
كان للغلول أثر في قبول الغنائم في الأمم السالفة من رَدِّها، فمتى وُجِد الغُلُول لم يقبلها الله سبحانه، ومتى لم يوجد قبُلِت، وأباح الله لهذ الأمة الغنائم بدون شرط.
شهوات الدنيا تدعو النفس إلى محبة البقاء فيها.
الأمور المهمة لا ينبغي أن تُفَوَّض سياستها إلا لحازم فارغ البال، ولذلك كان مقصود النبي تفرغهم من العوائق والأشغال ليقبلوا على الجهاد بنية صادقة وعزم حازم.
سَتَر الله هذه الأمة ورحمها بخلاف الأمم السابقة، فقد كان من يفعل غلولا أو معصية يفضحه الله، فلله الحمد والمنة على الإسلام والسنة.
ينبغي للإنسان إذا أراد طاعة أن يفرغ قلبه وبدنه لها، حتى يأتيها وهو مشتاق إليها، وحتى يؤديها على مهل وطمأنينة وانشراح صدر.
الدلالة على عظمة الله عز وجل، وأنه هو مدبر الكون، وأنه تعالى يجري الأمور على غير طبائعها، إما لتأييد الرسول، أو لدفع شر عنه، وإما لمصلحة في الإسلام.
الحديث رد على أهل الطبيعة الذين يقولون: إن الأفلاك لا تتغير؟! .
الأنبياء لا يعلمون الغيب إلا ما أطلعهم الله عليه.
الدلالة على قدرة الله من جهة أن هذه النار لا يدرى كيف أوقدت، بل تنزل من السماء، لا هي من أشجار الأرض، ولا من حطب الأرض، بل من السماء يأمرها الله فتنزل فتأكل هذه الغنيمة التي جمعت.', 'نَبِي : وهو يوشع بن نون.
بُضْعَ : يطلق على عقد النكاح، والجماع، والفرج.
وَلَمَّا يَبْنِ بِهَا : لم يدخل بها، وسبب التسمية بالبناء: أن الرجل كان إذا تزوج امرأة بنى عليها قبة ليدخل بها.
خَلِفَات : جمع خَلِفَة: وهي الناقة الحامل.
غُلُولاً : الغلول: الخِيَانة في المَغْنَم والسرقة من الغنيمة قبل القسمة.
من القرية : وهي أريحاء.
لَم تَطعَمهَا : للمبالغة، والمعنى: لم تذق طعمها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3288', false),
(20059, 2, 201, 59, 'hadith', 'عن أبي خالد حكيم بن حزام. رضي الله عنه ، قال: قال رسول الله صلى الله عليه وسلم : « البيعان بالخيار مالم يتفرقا، فإن صدقاً وبينا بورك لهما في بيعهما، وإن كتما وكذبا محقت بركة بيعهما».', 'Messenger of Allah (ﷺ) said: "Both parties in a business transaction have a right to annul it so long as they have not separated; and if they tell the truth and make everything clear to each other (i.e., the seller and the buyer speak the truth, the seller with regard to what is purchased, and the buyer with regard to the money) they will be blessed in their transaction, but if they conceal anything and lie, the blessing on their transaction will be eliminated.".', 'أبي خالد حكيم بن حزام. رضي الله عنه', 'Hakim bin Hizam (May Allah be pleased with him) reported that:', 'صحيح', 'رياض الصالحين 59', 'Riyad as-Salihin 59', 'ریاض الصالحین 59', 'متفق عليه', 'قال النبي صلى الله عليه وسلم: البائع والمشتري بالخيار في المجلس ما لم يفترقا بأبدانهما عن مكانهما الذي تبايعا فيه، فإن صدقا فيما يتعلق بالثمن ووصف المبيع ونحو ذلك وبيّنا ما يحتاج إليه بيانه من عيب ونحوه في السلعة والثمن، كثر نفع المبيع والثمن، وإن كتم البائع عيب السلعة والمشتري عيب الثمن، وكذبا في وصف السلعة والثمن أُذهبت بركة بيعهما أي زيادته ونماؤه، فإن فعله أحدهما دون الآخر محقت بركة بيعه وحده، ويحتمل أن يعود شؤم أحدهما على الآخر بأن تنزع البركة من المبيع إذا وجد الكذب أو الكتم.', 'حرمة الكذب والكتمان في البيع من العيوب.

تحل البركة في البيع بالصدق والبيان بين البائع والمشتري.', 'محقت: زالت ومُحيت.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66126', false),
(20060, 2, 201, 60, 'hadith', 'وأما الأحاديث ؛ فالأول: عن عمر بن الخطاب، رضي الله عنه ، قال « بينما نحن جلوس عند رسول الله، صلى الله عليه وسلم ذات يوم إذ طلع عينا رجل شديد بياض الثياب ، شديد سواد الشعر، لا يرى عليه أثر السفر، ولا يعرفه منا أحد، حتى جلس إلى النبي ،صلى الله عليه وسلم ، فأسند ركبتيه إلى ركبتيه، ووضع كفيه على فخذيه وقال: يا محمد أخبرني عن الإسلام، فقال: رسول الله صلى الله عليه وسلم: الإسلام أن تشهد أن لا إله إلا الله ، وأن محمداً رسول الله وتقيم الصلاة، وتؤتي الزكاة ، وتصوم رمضان ، وتحج البيت إن استطعت إليه سبيلاً. قال صدقت. فعجبنا له يسأله ويصدقه! قال : فأخبرني عن الإيمان. قال أن تؤمن بالله، وملائكته، وكتبه ورسله، واليوم الآخر، وتؤمن بالقدر خيره وشره. قال صدقت. قال فأخبرني عن الإحسان . قال أن تعبد الله كأنك تراه؛ فإن لم تكن تراه فإنه يراك. قال: فأخبرني عن الساعة. قال: ما المسؤول عنها بأعلم من السائل. قال : فأخبرني عن أماراتها قال: أن تلد الأمة ربتها، وأن ترى الحفاة العراة العالة رعاء الشاء يتطالون في البنيان. ثم انطلق، فلبثت ملياً، ثم قال: يا عمر أتدري من السائل؟ قلت: الله ورسوله أعلم. قال: فإنه جبريل أتاكم يعلمكم أمر دينكم».', 'Once we were sitting in the company of Messenger of Allah (ﷺ) when there appeared a man dressed in very white clothes and having extraordinary black hair. No signs of fatigue of journey appeared on him and he was known to none of us. He sat down facing the Prophet (ﷺ) leaning his knees against the knees of the Prophet (ﷺ) and placing both of his palms over his two thighs and said, "O Muhammad (ﷺ)! Tell me about Islam". He (ﷺ) replied, "Islam is to testify that none has the right to be worshipped but Allah, and that Muhammad (ﷺ) is the Messenger of Allah; that you observe Salat (prayers), pay Zakat, observe Saum (fasting) of Ramadan and perform Hajj (pilgrimage) of the House, provided you have resources of making journey to it." He replied: "You have spoken the truth." We were surprised to see that he had asked him and confirmed the correctness of the answers. He then enquired: "Tell me about Iman." He (ﷺ) said: "It is to believe in Allah, His angels,  His Books, His Messengers and the Last Day and that you believe in preordainment (destiny), its bad and good consequences." He said, "You have spoken the truth." He then enquired: "Tell me about Ihsan." He (ﷺ) said, "It is to worship Allah as if you are seeing Him; and although you do not see Him, He sees you." He enquired: "Inform me about the Hour (i.e., the Day of Resurrection)." He (ﷺ) replied, "I have no more knowledge thereof than you". He said, "Inform me about some of its signs." He (ﷺ) said, "They are - that a bondswoman gives birth to her own master, and that you will find the barefooted, naked, poor shepherds competing one another in the construction of higher buildings." Then he departed. The Messenger of Allah kept silent for a while then he said to me, "O ''Umar! Do you know who the questioner was?" I replied, "Allah and His Messenger know better." The Prophet (ﷺ) said, "He was Jibril (Gabriel); he came to you to teach you your religion."', null, '''Umar bin Al-Khattab (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 60', 'Riyad as-Salihin 60', 'ریاض الصالحین 60', 'رواه مسلم', 'يُخبِرُ عمر بن الخطاب رضي الله عنه أنّ جبريل عليه السلام خرج على الصحابة رضي الله عنهم بصورةِ رجلٍ لا يُعرف، ومن صفاته أنّ ثيابَه شديدة البياض، وشعرَه شديد السواد، لا يُرى عليه أَثَرُ السَّفَر من ظهور التعب، والغبار، وتفرُّق الشَّعَر، واتساخ الثياب، ولا يَعرفه أحدٌ من الحاضرين، وهم جلوس عند النبي صلى الله عليه وسلم، فَجَلسَ بين يدي النبي صلى الله عليه وسلم جِلْسَة المُتَعلِّم، فسأله عن الإسلام، فأجابه بهذه الأركان التي تتضمن الإقرار بالشهادتين، والمحافظة على الصلوات الخمس، وأداء الزكاة لمستحقيها، وصيام شهر رمضان، وأداء فريضة الحج على المستطيع.

فقال السائل: صدقت، فاستغرب الصحابةُ من سؤالِه الدَّالِّ على عَدَمِ معرفتِه فيما يَظهر ثم تصديقِه.

ثم سأله عن الإيمان، فأجابه بهذه الأركان الستة المتضمنة الإيمان بوجود الله تعالى وصفاته، وإفراده بأفعاله كالخلق، وإفراده بالعبادة، وأن الملائكة التي خلقها الله من نور عباد مُكْرَمون لا يعصون الله تعالى وبأمره يعملون، والإيمان بالكتب المنزلة على الرُّسُل من عند الله تعالى، كالقرآن والتوراة والإنجيل وغيرها، وبالرسل المبلِّغين عن الله دينَه، ومنهم نوح وإبراهيم وموسى وعيسى وآخرهم محمد صلى الله عليهم وسلم، وغيرهم من الأنبياء والرسل، والإيمان باليوم الآخر، ويدخل فيه ما بعد الموت من القبر والحياة البرزخية، وأن الإنسان يُبعث بعد الموت ويُحاسب، ويكون مصيره إما إلى الجنة أو النار، والإيمان بأنَّ الله قدَّرَ الأشياء حسبما سَبَق به علمُه واقتضته حكمتُه وكتابته لذلك، ومشيئته له، ووقوعها على حسب ما قدَّرها، وخلقَه لها.
 
ثم سأله عن الإحسان، فأخبره أن الإحسان أن يَعبُدَ اللهَ كأنه يراه، فإن لم يَتَحقَّق له الوصولُ إلى هذه المنزلة فلْيَعبُدِ اللهَ تعالى كأنَّ اللهَ يُشاهدُه، فالأولى منزلة المشاهدة، وهي أعلى، والثانية منزلة المراقبة.

ثم سأله متى الساعة؟ فبيَّن النبيُّ صلى الله عليه وسلم أنَّ عِلْمَ الساعة ممّا استأثر الله بعلمه، فلا يعلمه أحد من الخلق، لا المسؤول عنها ولا السائل.

ثم سأله عن علامات الساعة؟ فبين أنَّ مِن علاماتِها كثرةَ السراري وأولادِها، أو كثرةَ عقوقِ الأولاد لأمهاتِهم يعاملونهن معاملة الإماء، وأن رعاةَ الغنم والفقراء تُبسط لهم الدنيا في آخر الزمان، فيتفاخرون في زخرفة المباني وتشييدِها.

ثم أخبر النبيُّ صلى الله عليه وسلم أنَّ السائل هو جبريل جاء لتعليم الصحابة هذا الدين الحنيف.', 'حُسْن خُلُقِ النبي صلى الله عليه وسلم، وأنه يجلس مع أصحابه ويجلسون إليه.
مشروعية الرفق بالسائل وتقريبه، ليتمكن من السؤال غير مُنْقَبِضٍ ولا خائف.
الأدب مع المعلِّم كما فعل جبريل عليه السلام، حيث جلس أمام النبي صلى الله عليه وسلم جِلْسَة المتأدِّب ليأخذ منه.
أركان الإسلام خمسة، وأصولَ الإيمان ستة.
عند اجتماع الإسلام والإيمان يُفسَّر الإسلام بالأمور الظاهرة، والإيمان بالأمور الباطنة.
بيان أن الدين درجات متفاوتة، فالدرجة الأولى :الإسلام، والثانية :الإيمان، والثالثة: الإحسان، وهو أعلاها.
الأصل في السائل عدم العلم، والجهل هو الباعث على السؤال، لذلك عَجِب الصحابةُ من سؤالِه وتصديقِه.
البدء بالأهمِّ فالأهمِّ؛ لأنَّه بُدىء بالشهادَتين في تفسير الإسلام، وبُدىء بالإيمان بالله في تفسير الإيمان.
سؤال أهل العلم ما لا يجهله السائل، ليعلم غيره.
علم الساعة مِمَّا استأثر الله بعلمه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4563', false),
(20061, 2, 201, 61, 'hadith', 'عن أبي ذر جندب بن جنادة، وأبي عبد الرحمن معاذ بن جبل، رضي الله عنهما، عن رسول الله صلى الله عليه وسلم، قال: « اتق الله حيثما كنت واتبع السيئة الحسنة تمحها، وخالق الناس بخلق حسن».', 'Messenger of Allah (ﷺ) said, "Fear Allah wherever you are, do good deeds after doing bad ones, the former will wipe out the latter, and behave decently towards people"..', 'أبي ذر جندب بن جنادة، وأبي عبد الرحمن معاذ بن جبل رضي الله عنهما', 'Abu Dharr and Mu''adh bin Jabal (May Allah be pleased with them) reported that:', 'قال الترمذي: حديث حسن', 'رياض الصالحين 61', 'Riyad as-Salihin 61', 'ریاض الصالحین 61', 'رواه الترمذي وقال حديث حسن', 'يأمر النبي صلى الله عليه وسلم بثلاثة أمور:

الأول: تقوى الله وذلك بفعل الواجبات، وترك المحرمات، في كل مكان وزمان وحال، في السر والعلانية، وفي العافية والبلاء وغير ذلك.

الثاني: إذا وقعت في سيئة، فافعل بعدها حسنة من صلاة وصدقة وبر وصلة وتوبة وغير ذلك، فإن ذلك يمحو السيئة. 

الثالث: عامل الناس بأخلاق حسنة، مِنْ تبسم في وجوههم، ورفق ولين وبذل معروف وكف أذى.', 'فضل الله عزّ وجل على العباد في رحمته ومغفرته وعفوه.
اشتمل الحديث على الحقوق الثالثة: حق الله بالتقوى، وحق النفس بفعل الحسنات بعد السيئات، وحق الناس بالمعاملة بالأخلاق الحسنة.
الترغيب في فعل الحسنات بعد السيئات، وحسن الخلق من خصال التقوى، وإنما أفرد بالذكر للحاجة إلى بيانها.', null, 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4302', false),
(20062, 2, 201, 62, 'hadith', 'عن ابن عباس، رضي الله عنهما، قال: " كنت خلف النبي، صلى الله عليه وسلم، يوماً فقال: " يا غلام إني أعلمك كلمات: "احفظ الله يحفظك، احفظ الله تجده تجاهك، إذا سألت فاسأل الله ، وإذا استعنت فاستعن بالله، واعلم: أن الأمة لو اجتمعت على أن ينفعوك بشيء، لم ينفعوك إلا بشيء قد كتبه الله لك، وإن اجتمعوا على أن يضروك بشيء، لم يضروك بشيء إلا بشيء قد كتبه الله عليك؛ رفعت الأقلام، وجفت الصحف".', 'One day, I was riding behind the Prophet (ﷺ) when he said, "O boy! I will instruct you in some matters. Be watchful of Allah (Commandments of Allah), He will preserve you. Safeguard His Rights, He will be ever with you. If you beg, beg of Him Alone; and if you need assistance, supplicate to Allah Alone for help. And remember that if all the people gather to benefit you, they will not be able to benefit you except that which Allah had foreordained (for you); and if all of them gather to do harm to you, they will not be able to afflict you with anything other than that which Allah had pre-destined against you. The pens had been lifted and the ink had dried up"..', 'ابن عباس رضي الله عنهما', 'Ibn Abbas (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 62', 'Riyad as-Salihin 62', 'ریاض الصالحین 62', 'رواه الترمذي وقال حديث حسن صحيح', 'يُخبرُ ابنُ عباس رضي الله عنه أنه كان صغيرًا راكبًا مع النبي صلى الله عليه وسلم، فقال له عليه الصلاة والسلام: إني أُعلِّمك أمورًا وأشياءَ ينفعك الله بها:

احفظ الله بِحفظِ أوامرِه واجتنابِ نواهيه، بحيث يَجِدُكَ في الطاعات والقربات، ولا يجدُكَ في المعاصي والآثام، فإن فعلتَ ذلك كان جزاؤك أن يحفظَك الله من مكاره الدنيا والآخرة، وينصرَك في مُهماتِك أينما توجَّهتَ.

وإذا أردتَ أن تسأل شيئًا، فلا تسألْ إلا الله فإنه وحده الذي يُجيب السائلين.

وإذا أردتَ العونَ فلا تستعنْ إلا بالله.

ولْيكُن عندك يقينٌ أنه لن تحصل لك منفعة ولو اجتمع على منفعتِك أهلُ الأرض جميعًا إلا ما كتبه الله لك، ولن يحصُلَ عليك ضرر ولو اجتمع على ضرك أهلُ الأرض جميعًا إلا ما قدَّره الله عليك.

وأن هذا الأمر قد كَتَبه الله عز وجل وقدّره وِفْقَ ما اقتضته حكمته وعلمه، ولا تبديل لما كتبه الله.', 'أهمية تعليم الصغار والأطفال أمورَ الدين من التوحيد والآداب وغير ذلك.
الجزاء من جنس العمل.
الأمر بالاعتماد على الله، والتوكل عليه دون غيره، وهو نعم الوكيل.
الإيمان بالقضاء والقدر والرضا به، وأن الله قدر كل شيء.
من أضاع أمر الله فإن الله يُضَيِّعُه ولا يَحفظُه.', 'خلف النبي -صلى الله عليه وسلم-: أي على دابته رديفًا.
غلام: الصبي من حين يولد إلى أن يقارب سنَّ البلوغ.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4811', false),
(20063, 2, 201, 63, 'hadith', 'عن أنس رضي الله عنه قال: «إنكم لتعملون أعمالاً هي أدق في أعينكم من الشعر، كنا نعدها على عهد رسول الله صلى الله عليه وسلم من الموبقات» ((رواه البخاري )) ''وقال : الموبقات المهلكات ''.', 'You indulge in (bad) actions which are more insignificant to you than a hair while we considered them at the time of Messenger of Allah (ﷺ) to be great destroying sins"..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) said:', 'صحيح وهو موقوف هلى أنس بن مالك', 'رياض الصالحين 63', 'Riyad as-Salihin 63', 'ریاض الصالحین 63', null, 'خاطب الصحابي الجليل أنس بن مالك رضي الله عنه جماعة من المتساهلين في الأعمال قائلا: إنكم تستهينون ببعض المعاصي لعدم نَظَرِكم إلى عظم المعصي بها، فهي عندكم صغيرة جدا، أما عند الصحابة فكانوا يعدونها من المهلكات لعظم من يعصونه، ولشدة خوفهم ومراقبتهم ومحاسبتهم لأنفسهم.', 'الاستخفاف بالذنب يدل على قلة الخشية من الله تعالى، على العكس من استعظامه؛ فإنه يدل على كمال الخشية وعظيم المراقبة لله تعالى.
أعلم الناس بالله تعالى بعد الأنبياء وأكملهم ورعا وأشدهم خشية هم أصحاب رسول الله صلى الله عليه وسلم ورضي الله عنهم، فلقد كانوا يرون الأمور التي استهان بها غيرهم من المهلكات؛ لعظم شهودهم جلال الله وكمال معرفتهم له.
التحذير من ركون المرء إلى أعماله فيعجب بها ويستخف بالمعاصي، فإن محقرات الذنوب تحيط به، فيلقى الله ولا يقدر على الفكاك منها فتوبقه وتهلكه.
فهم الصحابة لكتاب الله وسنة رسوله صلى اللله عليه وسلم هو المعتبر؛ لأنه سبيل المؤمنين، فمن سار على نهجهم نجا، ومن حاد هلك وأهلك.', 'أدق : أصغر.
الموبقات : المهلكات.', 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3300', false),
(20064, 2, 201, 64, 'hadith', 'عن أبي هريرة، رضي الله عنه ، عن النبي صلى الله عليه وسلم، قال: « إن الله تعالى يغار، وغيرة الله ، تعالى، أن يأتي المرء ما حرم الله عليه».', 'The Prophet (ﷺ) said, ''Verily, ''Allah, the Exalted, becomes angry, and His Anger is provoked when a person does what Allah has declared unlawful"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 64', 'Riyad as-Salihin 64', 'ریاض الصالحین 64', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20065, 2, 201, 65, 'hadith', 'عن أبي هريرة رضي الله عنه أنه سمع النبي صلى الله عليه وسلم يقول: « إن ثلاثة من بنى إسرائيل : أبرص ، وأقرع، وأعمى، أراد الله أن يبتليهم فبعث إليهم ملكاً، فأتى الأبرص فقال: أي شيء أحب إليك؟ قال : لون حسن، وجلد حسن ، ويذهب عني الذى قد قذرني الناس؛ فمسحه فذهب عنه قذره وأعطي لونا حسناً. قال: فأي المال أحب إليك؟ قال: الإبل-أو قال البقر-شك الرواي- فأعطي ناقة عشراء، فقال: بارك الله لك فيها. فأتى الأقرع فقال: أي شيء أحب إليك؟ قال: شعر حسن، ويذهب عني هذا الذى قذرني الناس ، فمسحه فذهب عنه وأعطي شعراً حسناً. قال: فأي المال أحب إليك؟ قال: البقر، فأعطي بقرة حاملاً،وقال بارك الله لك فيها. فأتي الأعمى فقال: أي شيء أحب إليك؟ قال: أن يرد الله إلي بصري فأبصر الناس، فمسحه فرد الله إليه بصره. قال: فأي المال أحب إليك؟ قال: الغنم، فأعطي شاة والداً. فأنتج هذان وولد هذا، فكان لهذا واد من الإبل، ولهذا واد من البقر، ولهذا واد من الغنم. ثم إنه أتى الأبرص في صورته وهيئته، فقال له: رجل مسكين وابن سبيل قد انقطعت بي الحبال في سفري، فلا بلاغ لي اليوم إلا بالله ثم بك، أسألك بالذي أعطاك اللون الحسن، والجلد الحسن، والمال، بعيراً أتبلغ به في سفري، فقال: الحقوق كثيرة. فقال : كأني أعرفك، ألم تكن أبرص يقذرك الناس فقيراً، فأعطاك الله ؟! فقال : إنما ورثت هذا المال كابراً عن كابر، فقال: إن كنت كاذباً فصيرك الله إلى ما كنت. وأتى الأقرع، فقال له مثل ما قال لهذا، ورد عليه مثل ما ردّ هذا، فقال إن كنت كاذبا فصيرك الله إلى ما كنت . وأتى الأعمى في صورته وهيئته، فقال: رجل مسكين وابن سبيل انقطعت بي الحبال في سفري، فلا بلاغ لي اليوم إلا بالله ثم بك، أسألك بالذي رد عليك بصرك شاة أتبلغ بها في سفري؟ فقال: قد كنت أعمى فرد الله بصري، فخذ ما شئت ودع ما شئت، فوالله ما أجهدك اليوم بشيء أخذته لله عز وجل فقال: أمسك عليك مالك فإنما ابتليتم، فقد رضي الله عنك، وسخط على صاحبيك».', 'He heard the Prophet (ﷺ) said: "There were three men among the Banu Israel, one leper, one bald and one blind. Allah wanted to test them. He therefore, sent to them an angel who came to the leper and asked him what he would like best. He replied: "A good colour, a good skin and to be rid of what makes me loathsome to people". He (the angel) rubbed him and his loathsomeness vanished and he was given a good colour and a good skin. He then asked him what type of property he would like best. The leper replied that he would like camels - .', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said that:', 'صحيح', 'رياض الصالحين 65', 'Riyad as-Salihin 65', 'ریاض الصالحین 65', 'متفق عليه', 'يُخْبِرُ صلى الله عليه وسلم عن ثلاثة من بني إسرائيل أُصِيب كلٌّ منهم بعَاهَةٍ في الجسم، وفقر من المال، وهم: أبرص: به مرض ولون مختلف في جلده، وأقرع: ذهب شعر رأسه أو بعضه، وأعمى؛ فأراد الله أن يختبرهم ويمتحن إيمانهم وشكرهم؛ فأرسل إليهم ملكاً في صورة إنسان.
فأتى الملك إلى الأبرص، وقدَّم الأبرص لأن داءه أقبح وأشنع وأعظم، فقال له: أي شيء أحبّ إليك؟ قال: لون حسن وجلد حسن، وأن يذهب عني الداء الذي قد تباعد عني الناس بسببه، ولم يقتصر على طلب اللون الحسن؛ لأن جلد البرص يحصل له من التقلص والتشنج والخشونة ما يزيد به قبح صاحبه وعارِهِ. قال: فأي المال أحب إليك؟ قال: الإبل أو قال البقر. شك الراوي هل سمع الإبل أو البقر، والمرجح الإبل لكونه اقتصر عليها في قوله: فأعطي ناقة حاملًا أتى عليها من حملها عشرة أشهر من يوم أحملها، وهي من أنفس الإبل، وقال: بارك الله لك فيها. وقد استجيب دعاؤه كما في تتمة الحديث.
قال: فأتى الأقرع فقال: أيّ شيء أحبّ إليك؟ قال: شعر حسن، ويذهب عني هذا القرع الذي قد كرهني الناس بسببه. قال: فمسحه الملك، إما محل الداء فقط وهو الأقرب، أو جميع بدنه لتعمه بركته؛ فذهب عنه القرع وأعطى شعراً حسناً، قال الملك له: فأيّ المال أحب إليك؟ قال: البقر. فأعطي بقرة حاملاً. وقال: بارك الله لك فيها. وقد استجيب دعاؤه كما في تتمة الحديث.
قال: فأتى الأعمى فقال: أيّ شيء أحبّ إليك؟ قال: أن يرد الله إليّ بصري فأُبصربه الناس، قال: فأمرّ يده على عينيه، ويحتمل على جميع بدنه، والأول أقرب كما تقدم، فردّ الله إليه بصره. قال: فأي المال أحب إليك؟ قال: الغنم. فأعطي شاة ذات ولد، وقيل حاملاً، فتولى صاحبا الإبل والبقر ولادتها، وكذلك صاحب الغنم.
فكان لهذا واد مليءٌ من الإبل، ولهذا واد من البقر، ولهذا واد من الغنم.
قال: ثم إن الملك أتى الأبرص متصوراً في صورته التي كان عليها، وهيئته من رذالة الملبس ونحوها، فجاءه بعد أن صار معافى غنياً في الصورة التي قد جاءه فيها أول مرة، فقال: رجل مسكين محتاج، قد انقطعت بي الأسباب والوسائل في طلب الرزق في سفري؛ فلا وصول لي للمكان الذي أريده اليوم إلا بالله ثم بك لكونك مظهراً للخير غنيًّا، وهذا من الملك من المعاريض التي يقصد بها التوصل إلى إفهام المقصود من غير أن يراد حقيقتها. وقال: أقسم عليك مستعطفاً بـالذي أعطاك اللون الحسن والجلد الحسن والمال بعد الابتلاء بالفقر والمرض بعيراً واحدًا أكتفي به في سفري. فقال الأبرص: الحقوق كثيرة عليَّ، فلا يوجد فاضل عن الحاجة لأعطيك إياه فانظر غيري. فقال الملك: كأني أعرفك، ألم تكن أبرص يكرهك الناس؛ فعافاك الله، فقيراً فأعطاك الله عز وجل المال؟ فقال: إنما ورثت هذا المال عن أبي وجدي. وحاصله إنكار تلك الحال السيئة ودعوى أنه نشأ في تلك الأحوال الحسنة، فهي غير متجددة عليه، وهذا من إنكار النعم وكفر المنعم، حمله عليه البخل. فقال الملك: إن كنت كاذباً في دعواك فصيَّرك الله وردك إلى الحالة التي كنت عليها.
قال: وأتى الأقرع في صورته التي يقذرها الناس وهيئته التي يحقرونها لرثاثتها، فإنه مع كونه أتى له في صورته وهيئته التي أتاه عليها أولاً وحصل له منه ما حصل من الشفاء والغنى أنكر معرفته وتجاهل به وتفاخر عليه بأنه إنما جاءه المال من أبيه، فضم إلى كذبه قبائح تنبىء عن أنه انتهى في اللؤم والحمق إلى غاية لم يصلها غيره. فقال له الملك مثل ما قال للأبرص وردّ الأقرع عليه مثل ما ردّ الأبرص. فقال الملك: إن كنت كاذباً فصيرك الله إلى ما كنت عليه من القرع والفقر.
قال: وأتى الأعمى متشكلاً في صورة آدمي أعمى وفي هيئته الأولى، فقال الملك: رجل مسكين وابن سبيل -أي: مسافر- انقطعت بي الحبال في سفري فلا بلاغ لي اليوم إلا بالله ثم بك، أسألك بالذي ردّ عليك بصرك شاةً أتبلغ -أي: أكتفي- بها في سفري. فقال ذلك الرجل متذكراً نعم الله تعالى عليه وحسن حاله بعد بؤسه: قد كنت أعمى فردّ الله إليّ بصري فخذ ما شئت من المال ودع ما شئت منه، فوالله لا أشق عليك اليوم في ردّ شيء أخذته، فقال الملك: أمسك مالك فإنما امتحنتم وعاملكم الله العالم بجميع الأمور معاملة المختبِر؛ ليترتب على عملكم أثره، إذ الجزاء إنما جعله الله مرتباً على ما يبدو في عالم الشهادة لا على ما سبق في علمه، فقد رضي عنك وسخط على صاحبيك الأبرص والأقرع.', 'وجوب شكر نعمة الله -تعالى- في المال وأداء حق الله -عز وجل- فيه.
أن الله -سبحانه- يختبر عباده بالنعم، (وَنَبْلُوكُمْ بِالشَّرِّ وَالْخَيْرِ فِتْنَةً وَإِلَيْنَا تُرْجَعُونَ).
تحريم كفر النعمة ومنع حق الله -تعالى- في المال.
جواز ذكر حال من مضى من الأمم؛ ليتعظ به من سمعه.
مشروعية قول: بالله ثم بك، فيكون العطف ب (ثم) لا بالواو في مثل هذا التعبير.
إثبات معجزة للنبي -صلى الله عليه وسلم- في الإخبار بمثل هذه القصص.
نسبة النعمة إلى الله شكر لها وسبب لبقائها، ونسبتها لغيره كفر بها وسبب لزوالها.
إثبات المشيئة للمخلوق ولكنها تابعة لمشيئة الله وإرادته.
إثبات صفة الرضا لله -تعالى-.
إثبات صفة السخط لله -تعالى-.', 'بني إسرائيل : هم أبناء يعقوب بن إسحاق بن إبراهيم الخليل -عليهم السلام-، أي من يرجع نسبه إليه، وإسرائيل لقب يعقوب -عليه السلام-.
أبرص : البرص مرض مُعْدٍ مزمن يظهر على شكل بُقَع بيضاء في الجسد، يؤذي الجهاز العصبيّ، أو هو مرض يُحْدِث في الجسم قِشْرًا أبيض، ويُسَبِّب حَكًّا مؤلمـًا.
أقرع : هو من زال شعر رأسه أو بعضه، ويُطْلَق عليه أيضا الأَصلع.
أن يبتليهم : يَخْتَبِرهم بنعمته.
قذرني الناس : كره الناس بسببه رؤياي والقرب مني.
فذهب عنه قذره : أي: شُفِيَ من برصه.
عُشَراء : الناقة الحامل التي أتى على حملها عشرة أشهر أو ثمانية.
والداً : ذات ولد في بطنها أو التي عُرف منها كثرة الولد والنِّتَاج.
أَنْتج : تولَّى صاحب النَّاقَة وصاحب البقرة نتاجهما وتوليدهما وإصلاحهما.
انقطعت بي الحِبال : الأسباب التي أطلب بها الرزق.
أتبلغ به : أتوصّل به إلى البلد الذي أريده.
كابراً عن كابر : وَرِثْتُه من أبي وأجدادي.
بلاغ : كفاية أتوصّل بها إلى البلد الذي أريده.
صيرك الله إلى ما كنت : ردَّك إلى حالك الأولى برجوع العاهة إليك.
ملكًا : واحد الملائكة، وهم عالم غيبي، خلقهم الله من نور، وجعلهم قائمين بطاعة الله، لا يأكلون، ولا يشربون، يسبحون الليل والنهار لا يفترون، لهم أشكال وأعمال ووظائف مذكورة في الكتاب والسنة، والإيمان بهم أحد أركان الإيمان الستة.
في صورته وهيئته : الصورة في الجسم، والهيئة في الشّكل واللباس، وهذا هو الفرق بينهما.
ابن السبيل : أي: مسافر، سمي بذلك لملازمته للطريق.
لا أجهدك : أي لا أشق عليك في رد ما أخذت.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5926', false),
(20066, 2, 201, 66, 'hadith', 'عن أبي يعلى شداد بن أوس رضي الله عنه عن النبي صلى الله عليه وسلم قال: « الكيس من دان نفسه، وعمل لما بعد الموت ، والعاجز من أتبع نفسه هواها، وتمنى على الله».', 'The Prophet (ﷺ) said, "A wise man is the one who calls himself to account (and refrains from doing evil deeds) and does noble deeds to benefit him after death; and the foolish person is the one who subdues himself to his temptations and desires and seeks from Allah the fulfillment of his vain desires"..', 'أبي يعلى شداد بن أوس رضي الله عنه', 'Shaddad bin Aus (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 66', 'Riyad as-Salihin 66', 'ریاض الصالحین 66', 'رواه الترمذي وقال حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(20067, 2, 201, 67, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : « من حسن إسلام المرء تركه ما لا يعنيه».', 'Messenger of Allah (ﷺ) said, "It is from the excellence of (a believer''s) Islam that he should shun that which is of no concern to him"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'قال النووي: حديث حسن', 'رياض الصالحين 67', 'Riyad as-Salihin 67', 'ریاض الصالحین 67', 'حديث حسن رواه الترمذي وغيره', 'بين النبي صلى الله عليه وسلم: أن من كمال محاسن إسلام المسلم وتمام إيمانه، ابتعاده عما لا يعنيه ولا يخصه ولا يهمه وما لا يفيده من الأقوال والأفعال، أو مما لا يعنيه من أمور الدين والدنيا، فالاشتغال بما ليس للإنسان ربما شغله عما يعنيه، أو أداه إلى ما يلزمه اجتنابه؛ فإن الإنسان مسؤول عن أعماله يوم القيامة.', 'الناس يتفاوتون في الإسلام، وأنه يزداد حسنًا ببعض الأعمال.
ترك اللغو والفضول من الأقول والأفعال دليل على كمال إسلام المرء.
الحث على الاشتغال فيما يعني المرءَ من شؤون دِينه ودنياه، فإذا كان مِن حُسن إسلام المرء تركه ما لا يعنيه، فمِن حُسنه إذًا اشتغالُه فيما يعنيه.
قال ابن القيم رحمه الله : وقد جمع النبي صلى الله عليه وسلم الورع كله في كلمة واحدة، فقال: «من حسن إسلام المرء: تركُه ما لا يعنيه»، فهذا يعم الترك لما لا يعني: من الكلام، والنظر، والاستماع، والبطش، والمشي، والفكر، وسائر الحركات الظاهرة والباطنة، فهذه كلمة شافية في الورع.
قال ابن رجب: هذا الحديث أصل من أصول الأدب.
الحث على طلب العلم؛ لأن به بعرف الإنسان ما يعنيه مما لا يعنيه.
الأمر بالمعروف والنهي عن المنكر والنصيحة مما تعني الإنسان؛ لأنه مأمور بها.
يدخل في عموم معنى الحديث: الابتعاد عما لا يعني مما حرم الله عزوجل وما كرهه النبي صلى الله عليه وسلم، وكذلك ما لا يحتاج إليه من أمور أخروية كحقائق الغيب وتفاصيل الحكم في الخلق والأمر، ومنها السؤال والبحث عن مسائل مقدرة ومفترضة لم تقع، أو لا تكاد تقع، أو لا يتصور وقوعها.', null, 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65255', false),
(20068, 2, 201, 68, 'hadith', 'عن عمر رضي الله عنه عن النبي صلى الله عليه وسلم قال: «لا يسأل الرجل فيم ضرب امرأته».', 'The Prophet (ﷺ) said, "No man shall be asked for the reason of beating his wife"..', 'عمر رضي الله عنه', '''Umar (May Allah be pleased with him) reported that:', null, 'رياض الصالحين 68', 'Riyad as-Salihin 68', 'ریاض الصالحین 68', 'رواه أبو دواد وغيره', null, null, null, 'sunnah.com', null, false, null, false),
(20069, 2, 201, 69, 'hadith', 'وأما الأحاديث فالأول: عن أبي هريرة رضي الله عنه قال: قيل : يا رسول الله من أكرم الناس؟ قال: "أتقاهم". فقالوا: ليس عن هذا نسألك، قال: " فيوسف نبي الله بن نبي الله بن نبي الله بن خليل الله" قالوا: ليس عن هذا نسألك، قال: "فعن معادن العرب تسألوني؟ خيارهم في الجاهلية خيارهم في الإسلام إذا فقهواً :.', 'It was asked, "O Messenger of Allah! Who is the most honourable amongst mankind?" He (ﷺ) said, "The most honourable of them is one who is the most pious of them." They said, "We are not asking about this". He said, "Then, the most honourable of men was Yusuf (Joseph), the Prophet of Allah, the son of Allah''s Prophet, who was the son of the Prophet of Allah, who was the son of the Khalil of Allah (i.e., Ibrahim (ﷺ))'' They said, "We are not asking you about this." He enquired, "Are you then asking me about the classes of the Arabs? The best of them in the Pre- Islamic Period of Ignorance are the best of them in Islam, provided they comprehend the religious knowledge"..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 69', 'Riyad as-Salihin 69', 'ریاض الصالحین 69', 'متفق عليه', 'في الحديث أنَّ أكرم الناس من حيث النسب والمعادن والأصول، هم الخيار في الجاهلية، لكن بشرط إذا فقهوا، فمثلا بنو هاشم من المعروف هم خيار قريش في الإسلام، لكن بشرط أن يفقهوا في دين الله، وأن يتعلموا أحكامه، فإن لم يحصل لهم الفقه في الدين، فإنَّ شَرَف النَّسب لا يشفع لصاحبه، وإن عَلاَ نسبه وكان من خيار العرب نسبا ومعدِنا، فإنَّه ليس مِن أكرم الخلق عند الله، وليس مِن خيار الخلق، وعليه فالإنسان يشرف بنسبه، لكن بشرط الفقه في الدين.', 'يشرف الإنسان بشرف آبائه وعشيرته إذا كانوا أتقياء، وكان هو على شاكلتهم وطريقتهم.
أصحاب المروءات ومكارم الأخلاق في الجاهلية هم أصحابها في الإسلام إذا علموا أحكام الشرع.
النَّسب له أثر في الفضل بالشرط السابق، ولهذا كان بنو هاشم أطيب الناس وأشرفهم نسبا، ومن ثم كان رسول الله -صلى الله عليه وسلَّم- الذي هو أشرف الخلق  من سُلالتِهم، فلولا أنَّ هذا البطن من بني آدم أشرف البطون، ما كان فيه النبي -صلى الله عليه وسلم-، فلا يبعث الرسول إِلاَّ في أشرف البطون وأعلى الأنساب.
بيَّن الحديث أقسام الناس وشرف انتسابهم وأنسابهم، وأن من الأنساب شريف ومنها دون ذلك.
شرف النسب يعتبر إذا انضم إليه التقوى والخوف من الله، وإلا فلا.
الإنسان يكرم ويشرف بتقوى الله -عز وجل-، وأنَّ من كان تقيًّا كان له الخير في الدنيا رفيع الدرجة في الآخرة.
بيان فضيلة نبي الله يوسف -عليه الصلاة والسلام-، فقد جمع مكارم الأخلاق مع شرف النبوة مع شرف النسب، وانضم إليه شرف العلم بتعبير الرؤيا وتَمَكُّنِه من سياسة التدبير.
بيان فضل العلم وأنّه أفضل من النسب والحسب والجاه والمال.', 'أكرم : اسم تفضيل من الكرم: أصله كثرة الخير، وهو ضد اللؤم، وقيل: إن الكريم هو المتقي.
ابن نبي : يعقوب -عليه السلام-.
بن نبي : إسحاق -عليه السلام-.
ابن خليل الله : إبراهيم عليه السلام، والخليل هو من كان في أعلى المحبة، فالخُلَّة أعلى أنواع المحبة، وليس فوق الخُلَّة شيء من أنواع المحبة أبداً.
مَعَادِن العَرَب : أصولها التي يُنسَبُون إليها ويتفاخرون بها.
معادن : جمع مَعدِن: وهو منبت الجواهر من ذهب ونحوه، والمراد به هاهنا قبائل العرب.
الجاهلية : الفترة التي عاشها الناس قبل الإسلام، وسُمِيَّت بذلك لكثرة جهالات الناس في تلك الفترة من الزمن.
خِيَارُهُم في الجاهِليَّة خِيَارُهُم في الإِسلام : أصحاب المروءات ومكارم الأخلاق في الجاهلية، هم كذلك في الإسلام إذا آمنوا واتقوا؛ لأن الإسلام جاء ليتمم مكارم الأخلاق، والعبد يسلم على ما أسلف من خير، وإذا انضم شرف التقوى إلى شرف النسب كان خيرا على خير، وفضلا على فضل.
فَقُهُوا : علموا أحكام الشرع.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3069', false),
(20070, 2, 201, 70, 'hadith', 'عن أبي سعيد الخدري رضي الله عنه عن النبي صلى الله عليه وسلم قال: « إن الدنيا حلوة خضرة، وإن الله مستخلفكم فيها فينظر كيف تعملون، فاتقوا الدنيا واتقوا النساء؛ فإن أول فتنة بني إسرائيل كانت في النساء».', 'The Prophet (ﷺ) said, "The life of the world is sweet and green. Allah makes you generations succeeding one another so that He may try you in respect of your actions. So beware of the beguilements of the world and those of women. The first trial of Banu Israel was through women"..', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 70', 'Riyad as-Salihin 70', 'ریاض الصالحین 70', 'رواه مسلم', 'يُبَيِّنُ النبيُّ صلى الله عليه وسلم أنَّ الدنيا حُلوةٌ في المذاق، خَضِرَةٌ في المَرْأَى، فيغتر الإنسان بها وينهمك فيها ويجعلها أكبرَ همه. 
وأنَّ الله سبحانه وتعالى جعل بعضَنا يَخلُف بعضًا في هذه الحياة الدنيا، لينظر كيف نعمل، أفنقوم بطاعته، أم نعصيه؟ 
ثم قال: احذروا أنْ يَخدَعَكم متاعُ الدنيا وزينتُها، فتحملكم على ترك ما أمركم الله به، والوقوع فيما نهاكم عنه. 
ومن أعظم ما يجب الحذر منه من فتن الدنيا فتنة النساء، وأنها كانت أول فتنة وقع فيها بنو إسرائيل.', 'الحثُّ على مُلازمة التقوى، وعدم الانشغال بظواهر الدنيا وزينتها.
الحذر من الافتتان بالنساء، مِن نَظَرٍ أو تساهُلٍ باختلاطِهن بالرجال الأجانب، أو غير ذلك.
فتنة النساء من أعظم الفتن في الدنيا.
الاتَّعاظ وأخذ العبرة من الأمم السالفة، فالذي حصل لبني إسرائيل قد يحصل لغيرهم.
فتنة النساء إذا كانت زوجة فإنها قد تُكَلِّفُ الرجلَ مِن النفقة ما لا يطيق، فتشغله عن طلب أمور الدِّين، وتحمله على التهالك على طلب الدنيا، وإن كانت أجنبيةً ففتنتُها بإغراء الرجال وإمالتِهم عن الحق إذا خَرَجْنَ واختلطْنَ بهم، خصوصًا إذا كُنَّ سافراتٍ متبرجاتٍ، وهذا قد يؤدِّي إلى الوقوع في الزنا بدرجاته، فينبغي للمؤمن الاعتصام بالله، والرغبة إليه في النجاة من فتنتهن.', 'خَضِرَة: غضة ناعمة طرية. فالدنيا تُشبِه في الميل إليها الفاكهة الحلوة الطرية في مذاقها، الخضرة في لونها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3053', false),
(20071, 2, 201, 71, 'hadith', 'عن ابن مسعود رضي الله عنه أن النبي صلى الله عليه وسلم كان يقول: «اللهم إني أسألك الهدى والتقى والعفاف والغنى».', '"Allahumma inni as''alukal-huda wat- tuqa wal-''afafa wal-ghina (O Allah! I ask You for guidance, piety, chastity and self- sufficiency)"..', 'ابن مسعود رضي الله عنه', '''Abdullah bin Mas''ud (May Allah be pleased with him) reported that the Prophet (ﷺ) used to say:', 'صحيح', 'رياض الصالحين 71', 'Riyad as-Salihin 71', 'ریاض الصالحین 71', 'رواه مسلم', 'سأل النبي صلى الله عليه وسلم ربه العلمَ والتوفيق للحق، وأن يُوفِّقه إلى امتثال ما أمر به وترك ما نهى عنه، وأن يعفه عن كل ما حرَّم عليه فيما يتعلق بجميع المحارم التي حرَّمها عز وجل ، وسأله كذلك الغنى عن الخلق، بحيث لا يفتقر إلى أحد سوى ربَّه عز وجل .', 'الخضوع إلى الله واللجوء إليه في كل الأحوال.
أن النبي -صلى الله عليه وسلم- لا يملك لنفسه نفعًا ولا ضرًّا، وأن الذي يملك ذلك هو الله.
إبطال التعلَّق بالأولياء والصالحين في جلب المنافع ودفع المضار.
حاجة النفس إلى مكارم الأخلاق؛ لتستقيم على أمر الله، ولتخاف عقابه وترجو رحمته.
وجوب التزام التقوى.
الكف عن مباشرة المعصية، وإن كان المكلف قد عزم على فعلها.
شرف هذه الخصال: الهدى والتقى والعفاف والغنى.', 'الهُدَى : الدلالة والرشاد، والعلم.
التُّقَى : التقوى: وهي فعل الأوامر واجتناب النواهي.
العَفَاف : الكف عما لا يحل ولا يجمل من قول أو عمل.
الغِنَى : ضد الفقر، والمراد به: غنى النفس، والاغتناء عن الناس وعما في أيديهم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3057', false),
(20072, 2, 201, 72, 'hadith', 'عن أبي ظريف عدي بن حاتم الطائي رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «من حلف على يمين ثم رأى أتقى لله منها فليأت التقوى».', 'I heard the Messenger of Allah (ﷺ) say: "He who has taken an oath (to do something) but found something else better than that (which brings him closer to Allah), then he should do that which is better in piety (and he should expiate for the breaking of oath)"..', 'أبي ظريف عدي بن حاتم الطائي رضي الله عنه', '''Adi bin Hatim At-Ta''i (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 72', 'Riyad as-Salihin 72', 'ریاض الصالحین 72', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20073, 2, 201, 73, 'hadith', 'عن أبي أمامة صدي بن عجلان الباهلي رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يخطب في حجة الوداع فقال : اتقوا الله ، وصلوا خمسكم، وصوموا شهركم، وأدوا زكاة أموالكم، وأطيعوا أمراءكم، تدخلوا جنة ربكم".', 'I heard Messenger of Allah (ﷺ) during the sermon of the Farewell Pilgrimage saying, "Be mindful of your duty to Allah; perform your five daily Salat, observe Saum during the month (of Ramadan) , pay the Zakat on your properties and obey your leaders; (if you do so) you will enter the Jannah of your Rubb"..', 'أبي أمامة صدي بن عجلان الباهلي رضي الله عنه', 'Abu Umamah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 73', 'Riyad as-Salihin 73', 'ریاض الصالحین 73', 'رواه الترمذي، في آخر كتاب الصلاة وقال : حديث حسن صحيح', 'هذا الحديث من جملة الأحاديث التي فيها الحث على تقوى الله تعالى ، بفعل أوامره واجتناب نواهيه، وكان هذا الحديث في آخر أيامه -عليه الصلاة والسلام- عندما خطب الناس في حجة الوداع خطبة بليغة وأوصاهم بوصايا كثيرة وذكرهم بما لهم وعليهم ومن جملة ما جاء فيها تقوى الله تعالى ، حيث قال: (يا أيها الناس اتقوا ربكم) وهذه كقوله تعالى : (يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ)، (النساء: من الآية1)، فأمر الرسول صلى الله عليه وسلم الناس جميعا أن يتقوا ربهم الذي خلقهم، وأمدهم بنعم لا تُعدُّ ولا تحصى.
وفي الحديث الآخر، عن أبي سعيد الخدري رضي الله عنه قال: جاء رجل إلى النبي صلى الله عليه وسلم ، فقال: يا رسول الله أوصني: قال (عليك بتقوى الله، فإنها جماع كل خير..).
وقال صلى الله عليه وسلم : (أكثر ما يدخل الناس الجنة تقوى الله وحسن الخلق).
وقوله: (وصلوا خمسكم) أي: صلوا الصلوات الخمس التي فرضها الله عز وجل على رسوله صلى الله عليه وسلم ، فإن أول ما يحاسب عليه العبد يوم القيامة صلاته.
وقوله: (وصوموا شهركم) أي: شهر رمضان، وأضيف للأمة لما يسبغ عليهم فيه من النعم والرحمة والكرم من عتق الرقاب وجزيل الثواب. 
وقوله: (وأدوا زكاة أموالكم) أي: أعطوها مستحقيها ولا تبخلوا بها. 
فاشتمل الحديث على الثلاثة من أركان الإِسلام، ولم يذكر الحج؛ لأن هذه الأمور تتكرر كل يوم، وكل عام ويثقل أداؤها، فخصّها بالأمر والتوصية. 
وقوله: (أطيعوا أمراءكم) أي: الخليفة والسلطان وغيرهما من الأمراء، والعلماء، إلا أنه لا طاعة لمخلوق في معصية الخالق، وفي الحديث الآخر: (أوصيكم بتقوى الله والسمع والطاعة..) رواه أبو داود والترمذي، وصححه الشيخ الألباني في مشكاة المصابيح (1/185).', 'الوصية بتقوى الله -تعالى-.
أن التزام هذه الأعمال من تقوى الله -عز وجل-، وأن تقوى الله -تعالى- طريق الجنة وشرط دخولها والاستقامة في الدنيا سبب النجاة في الآخرة.
وجوب طاعة الولاة والحكام وشرط طاعتهم ألا يأمروا بما فيه معصية الله -عز وجل-.
جواز تسمية الحجة التي حجها -صلى الله عليه وسلم- بحجة الوادع من غير كراهة.', 'حجة الوداع : آخر حجة حجها النبي -صلى الله عليه وسلم-.
الوداع : سميت بذلك: لأنه -صلى الله عليه وسلم- ودع الناس فيها.
خمسكم : أي: الصلوات الخمس المفروضة.
شهركم : أي: شهر رمضان.
أمراءكم : أولياء الأمور منكم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3725', false),
(20074, 2, 201, 74, 'hadith', 'فالأول عن ابن عباس رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم : عرضت علي الأمم، فرأيت النبي ومعه الرهيط، والنبي ومعه الرجل والرجلان، والنبي وليس معه أحد إذ رفع لي سواد عظيم فظننت أنهم أمتي، فقيل لى : هذا موسى وقومه، ولكن انظر إلى الأفق، فنظرت فإذا سواد عظيم، فقيل لى، انظر إلى الأفق الآخر، فإذا سواد عظيم، فقيل لي: هذه أمتك، ومعهم سبعون ألفاً يدخلون الجنة بغير حساب ولا عذاب" ثم نهض فدخل منزله، فخاض الناس في أولئك الذين يدخلون الجنة بغير حساب ولا عذاب، فقال بعضهم: فلعلهم الذين صحبوا رسول الله صلى الله عليه وسلم ، وقال بعضهم: فلعلهم الذين ولدوا في الإسلام، فلم يشركوا بالله شيئاً- وذكروا أشياء- فخرج عليهم رسول الله صلى الله عليه وسلم فقال: "ما الذي تخوضون فيه؟" فأخبروه فقال: "هم الذين لا يرقون ، ولا يسترقون ولا يتطيرون، وعلى ربهم يتوكلون" فقام عكاشة بن محصن فقال: ادع الله أن يجعلني منهم، فقال: "أنت منهم" ثم قام رجل آخر فقال: ادع الله أن يجعلني منهم فقال: "سبقك بها عكاشة".', 'Messenger of Allah (ﷺ) said, "I was shown the past nations. I saw a Prophet who had a very small group (less than ten in total) with him, another Prophet who was accompanied by only one or two men and some did not have even one. Suddenly I was shown a huge crowd and I thought that they were my Ummah, but I was told: ''This is Musa (Moses) and his people, but look towards the other side.'' I looked and beheld a great assemblage. I was told: ''These are your people and amongst them there are seventy thousand who shall enter Jannah without being taken to account or torment". Then the Prophet (ﷺ) stood up and went into his apartment, and the Companions began to guess who may be those people who would enter Jannah without any accounting or torment. Some said: "Probably, they are the ones who kept company with Messenger of Allah (ﷺ)". Others said: "Probably, they are the ones who have been born as Muslims and have never associated anyone with Allah in worship". Then Messenger of Allah (ﷺ) came out and asked, "What are you discussing?" So they told him. He then said, "They are those who do not make Ruqyah (blowing over themselves after reciting the Qur''an or some prayers and supplications the Prophet (ﷺ) used to say) nor seek it, nor perceive omens (i.e., they are not pessimistic) but keep trust in their Rubb (Allah)." On this ''Ukashah bin Mihsan stood up and asked: "Pray to Allah to make me one of them." The Prophet (ﷺ) said, "You are one of them." Then another man stood up and asked the same thing. The Prophet (ﷺ) answered, "''Ukashah has surpassed you"..', null, 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 74', 'Riyad as-Salihin 74', 'ریاض الصالحین 74', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20075, 2, 201, 75, 'hadith', 'عن ابن عباس رضي الله عنهما أيضاً أن رسول الله صلى الله عليه وسلم كان يقول: «اللهم لك أسلمت وبك آمنت، وعليك توكلت، وإليك أنبت ، وبك خاصمت. اللهم أعوذ بعزتك، لا إله إلا أنت أن تضلني، أنت الحي الذي لا تموت، والجن والإنس يموتون».', '"O Allah! To You I have submitted, and in You do I believe, and in You I put my trust, to You do I turn, and for You I argued. O Allah, I seek refuge with You through Your Power; there is none worthy of worship except You Alone; that You safeguard me against going astray. You are the Ever Living, the One Who sustains and protects all that exists; the One Who never dies, whereas human beings and jinn will all die"..', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them) reported that the Messenger of Allah (ﷺ) used to supplicate:', 'صحيح', 'رياض الصالحين 75', 'Riyad as-Salihin 75', 'ریاض الصالحین 75', 'متفق عليه)) . ((وهذا لفظ مسلم، واختصره البخاري', 'عن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم كان يقول: (اللهم لك أسلمت) أي: انقيادا ظاهرا لا لغيرك، (وبك آمنت) أي: تصديقا باطنا، (وعليك توكلت) أي: أسلمت جميع أموري لتدبرها، فإني لا أملك نفعها ولا ضرها، (وإليك أنبت) أي: رجعت من المعصية إلى الطاعة أو من الغفلة إلى الذكر، (وبك) بإعانتك (خاصمت) أي: حاربت أعداءك، (اللهم إني أعوذ بعزتك) أي: بغلبتك فإن العزة لله جميعا. (لا إله إلا أنت) لا معبود بحق سواك ولا سؤال إلا منك ولا استعاذة إلا بك. 
(أن تضلني) أي: أعوذ من أن تضلني بعد إذ هديتني ووفقتني للانقياد الظاهر والباطن في حكمك وقضائك وللإنابة إلى جنابك والمخاصمة مع أعدائك والالتجاء في كل حال إلى عزتك ونصرتك، (أنت الحي الذي لا يموت والجن والإنس يموتون).', 'وجوب التوكل على الله -تعالى- وحده وطلب الحفظ منه؛ لأنه متصف بصفات الكمال، فهو وحده الذي يعتمد عليه، والخلق كلهم عاجزون ومنتهون إلى الموت، فهم ليسوا أهلاً للاعتماد عليهم.
كل ما سوى الله هالك، فلا يعتمد عليهم.
التأسي بالنبي -صلى الله عليه وسلم- بهذه الكلمات الجامعة لمعاني الخير، التي تعبر عن صدق الإيمان وغاية اليقين.
كمال الرجوع إلى الله تعالى والركون إليه في الأحوال كلها، والاعتصام بحبله، والتوكل عليه.
الالتجاء إلى الله والاعتصام به، فمن اعتزَّ بغير الله ذلّ، ومن اهتدى بغير هدايته ضلّ، ومن اعتصم بالله -تعالى- وتوكَّل عليه عظُم وجلّ.
إظهار النبي -صلى الله عليه وسلم- افتقاره لربه .
فناء كل المخلوقات إلا ما شاء الله -تعالى-.
الإشارة إلى الفرق بين الإسلام والإيمان.', 'أسلمت : استسلمت لأمرك ورضيت بحكمك.
توكلت : اعتمدت على تدبيرك في جميع الأمور.
أنبت : أقبلت ورجعت إليك بالتوبة.
خاصمت : نازعت، والمراد: خاصمت ثقة في نصرك ومؤازرتك لي.
أعوذ : ألتجئ.
بعزتك : بقوتك وسلطانك.
الإيمان : إقرار القلب المستلزم للقول والعمل، فهو اعتقاد وقول وعمل، اعتقاد القلب، وقول اللسان، وعمل القلب والجوارح.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3598', false),
(20076, 2, 201, 76, 'hadith', 'عن ابن عباس رضي الله عنهما أيضاً قال: "حسبنا الله ونعم الوكيل، قالها إبراهيم صلى الله عليه وسلم حين ألقي في النار، وقالها محمد صلى الله عليه وسلم حين قالوا: إن الناس قد جمعوا لكم فاخشوهم فزادهم إيمانا وقالوا: حسبنا الله ونعم الوكيل:.', 'When (Prophet) Ibrahim (Abraham) was thrown into the fire, he said: "Allah (Alone) is sufficient for us, and, He is the Best Disposer of affairs." So did Messenger of Allah Muhammad (ﷺ) when he was told: "A great army of the pagans had gathered against him, so fear them". But this (warning) only increased him and the Muslims in Faith and they said: "Allah (Alone) is sufficient for us, and He is the Best Disposer of affairs (for us)"..', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 76', 'Riyad as-Salihin 76', 'ریاض الصالحین 76', 'رواه البخاري', 'أخبر ابن عباس رضي الله عنهما أنه قال: في قوله تعالى: {حسبنا الله ونعم الوكيل} أنه قالها إبراهيم عليه السلام حين أُلقي في النار، وقالها محمد صلى الله عليه وسلم حين قالوا له عليه الصلاة والسلام: {إن الناس} أبا سفيان وأصحابه {قد جمعوا لكم} يقصدون غزوكم، وكان أبو سفيان نادى عند انصرافه من أحد في السنة الثالثة: يا محمد موعدنا موسم بدر لقابل إن شئت، فقال عليه الصلاة والسلام: إن شاء الله، فلما كان العام القابل خرج في أهل مكة حتى نزل مَرَّ الظهران، فأنزل الله الرعب في قلبه، وبدا له أن يرجع فمر به ركب من عبد قيس ويريدون المدينة للميرة، فشرط لهم حمل بعير من زبيب إن ثبطوا المسلمين، وقيل: لقي نعيم بن مسعود وقد قدم معتمرًا فسأله ذلك، والتزم له عشرًا من الإبل، فخرج نعيم فوجد المسلمين يتجهزون، فقال لهم: إن أتوكم في دياركم فلم يفلت أحد منكم إلا شريد، أفترون أن تخرجوا وقد جمعوا لكم؟ {فاخشوهم} ولا تخرجوا إليهم {فزادهم} أي المقول {إيمانًا} فلم يلتفتوا إليه ولم يضعفوا، بل ثبت به يقينهم بالله وأخلصوا النية في الجهاد، وفي ذلك دليل على أن الإيمان يزيد وينقص، {وقالوا حسبنا الله} كافينا الله {ونعم الوكيل} وهو نعم المعتمد عليه.', 'فضل قول حسبنا الله ونعم الوكيل.

الدلالة على أن الإيمان يزيد وينقص.

ثبات الصحابة رضي الله عنهم وإخلاصهم في الجهاد.', 'فاخشوهم: خافوهم.

حسبنا: كافينا.

الوكيل: هو القيم الكفيل بأرزاق العباد، وحقيقته أن يستقل بأمر الموكول إليه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65287', false),
(20077, 2, 201, 77, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «يدخل الجنة أقوام أفئدتهم مثل أفئدة الطير».', 'The Prophet (ﷺ) said, "A group of people (both men and women) whose hearts will be like the hearts of birds, will enter Jannah"..It has been interpreted that such people are those who put their trust in Allah; another interpretation is that these people are tender- hearted.', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 77', 'Riyad as-Salihin 77', 'ریاض الصالحین 77', 'رواه مسلم', 'قال أبو هريرة رضي الله عنه: قال رسول الله صلى الله عليه وسلم: يدخل الجنة أقوام، أفئدتهم مثل أفئدة الطير، والأفئدة جمع فؤاد، والفؤاد هو القلب، والتشبيه في رقتها وخفتها وخوفها وتوكلها على الله عز وجل، والمعلوم أن أهل الجنة هم أهل الخوف من الله عز وجل، وهم أهل الرجاء، وأهل التوكل على الله عز وجل، وإذا كان معنى الحديث الخوف من الله فإن الطير معروفة بأنها أشد المخلوقات خوفاً فهي تطير بمجرد اقتراب أي شخصٍ منها.', 'من أسباب دخول الجنة تحقيق الخوف والرجاء لله عز وجل.

القلب يلين ويرق ويقسو ويغلظ.

أهمية الخوف والرجاء في قلب المسلم.', 'أفئدتهم: قلوبهم.

مثل أفئدة الطير: في رقتها وخفتها وخوفها وتوكلها على الله عزوجل.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65184', false),
(20078, 2, 201, 78, 'hadith', 'عن جابر رضي الله عنه أنه غزا مع النبي صلى الله عليه وسلم قبل نجد، فلما قفل رسول الله صلى الله عليه وسلم قفل معهم، فأدركتهم القائلة في واد كثير العضاه، فنزل رسول الله صلى الله عليه وسلم، وتفرق الناس يستظلون بالشجر، ونزل رسول الله صلى الله عليه وسلم تحت سمرة، فعلق بها سيفه، ونمنا نومة، فإذا رسول الله صلى الله عليه وسلم يدعونا، وإذا عنده أعرابي فقال: «إن هذا اختراط علي سيفي وأنا نائم، فاسيقظت وهو في يده صلتا، قال: من يمنعك منى؟ قلت: الله-ثلاثا» ولم يعاقبه وجلس. ((متفق عليه)) . وفي رواية : قال جابر: كنا مع رسول الله صلى الله عليه وسلم بذات الرقاع: فإذا أتينا على شجرة ظليلة تركناها لرسول الله صلى الله عليه وسلم، فجاء رجل من المشركين، وسيف رسول الله صلى الله عليه وسلم معلق بالشجرة، فاخترطه فقال : تخافني؟ قال: لا قال : فمن يمنعك مني ؟ قال: الله . وفي رواية أبي بكر الإسماعيلى في صحيحه: قال: من يمنعك مني؟ قال : الله قال: فسقط السيف من يده، فأخذ رسول الله صلى الله عليه وسلم السيف فقال: من يمنعك مني؟ فقال كن خير آخذ، فقال تشهد أن لا إله إلا الله ، وأني رسول الله؟ قال: لا، ولكني أعاهدك أن لا أقاتلك ولا أكون مع قوم يقاتلونك، فخلى سبيله، فأتى أصحابه فقال: جئتكم من عند خير الناس.', 'I went in an expedition along with the Prophet (ﷺ) in the direction of  Najd. When Messenger of Allah (ﷺ) returned, I also returned with him. Then the mid-day sleep overtook us in a valley full of prickly shrubs. Messenger of Allah (ﷺ) got down and the people scattered around seeking shade under the trees. Messenger of Allah (ﷺ) hang up his sword on the branch of a tree. We were enjoying a sleep when Messenger of Allah (ﷺ) called us, and lo! There was a desert Arab bedouin near him. He (ﷺ) said, "This man brandished my sword over me while I was asleep. I woke up and saw it in his hand unsheathed. He asked: `Who will protect you from me?'' I replied: ''Allah'' - thrice". He did not punish him and sat down.

.

In another narration, Jabir (May Allah be pleased with him) said: We accompanied Messenger of Allah (ﷺ) in the campaign of Dhat-ur-Riqa`. We left Messenger of Allah (ﷺ) to take rest under a shady tree. One of the polytheists came to him. The sword of Messenger of Allah (ﷺ) was hanging on a tree. He drew it and said: "Are you afraid of me?'''' Messenger of Allah (ﷺ) said, "No". Then he said: "Who will then protect you from me?'''' Messenger of Allah (ﷺ) replied, "Allah".

And in a narration of Abu Bakr Al-Isma`ili, the polytheist asked: "Who will protect you from me?'''' Messenger of Allah (ﷺ) replied, "Allah.'''' As soon as he said this, the sword fell down from his hand and Messenger of Allah (ﷺ) catching the sword, asked him, "Who will protect you from me.'''' He said, "Please forgive me.'''' Messenger of Allah (ﷺ) said, "On condition you testify that there is none worthy of worship but Allah and that I am His Messenger.'''' He said, "No, but I promise you that I shall not fight against you, nor shall I be with those who fight with you". The Prophet (ﷺ) let him go. He then went back to his companions and said: "I have come to you from one of the best of mankind".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 78', 'Riyad as-Salihin 78', 'ریاض الصالحین 78', null, 'في هذا الحديث: يخبر جابر بن عبد الله رضي الله عنهما أنه غزا مع النبي صلى الله عليه وسلم وكانت هذه الغزوة معروفة عند أهل السير بعزوة ذات الرقاع، وفي أثناء رجوعهم من غزوتهم نزل النبي صلى الله عليه وسلم في وقت الظهيرة في موضع تكثر فيه أشجار الشوك، وتفرق الناس عن النبي صلى الله عليه وسلم يبحثون عن أماكن يستظلون بها من حر الشمس، ونزل -عليه الصلاة والسلام- تحت شجرة ظليلة يقال لها: السمرة، فعلَّق بها سيفه، ثم نام ونام الناس، ثم تسلل إليهم أعرابي، ممن قاتلهم النبي صلى الله عليه وسلم في هذه الغزوة ولم يشعروا به، فأخذ سيف النبي صلى الله عليه وسلم على وجه الخفية، فاستيقظ -عليه الصلاة والسلام-، فأخذ الأعرابي السيف وصار يتقوى به على النبي صلى الله عليه وسلم ، وهو يقول: "من يمنعك مني إذا أردت قتلك؟ فرد عليه النبي صلى الله عليه وسلم "الله"، فكررها ثلاث مرات، والمعنى: أن الله تعالى سيحمينا منك، فقالها -عليه الصلاة والسلام-، وهو الواثق بالله، المتوكل عليه، المتيقن لوعده، فسقط السيف من يد الكافر، فأخذه رسول الله صلى الله عليه وسلم ، فقال له -عليه الصلاة والسلام-: "من يمنعك مني؟" أي: إذا أردت قتلك، فرد الكافر بقوله: (كنْ خير آخذ)، والمراد به العفو والصفح ومقابل السيئة بالحسنة.
فقال له النبي صلى الله عليه وسلم : (تشهد أن لا إله إلا الله وأني رسول الله) فقال: لا، لكنه عاهد النبي صلى الله عليه وسلم بعدم مقاتلته ولا يكون مع قوم يقاتلونه، فخلى -عليه الصلاة والسلام- سبيله، فعاد هذا الرجل إلى أصحابه، فقال: (جئتكم من عند خير الناس)، والأمر على ما قاله هذا الكافر، فإن النبي صلى الله عليه وسلم أفضل الناس خلقًا، ويكفي ذلك تزكية الله له بقوله: (وإنك لعلى خلق عظيم).', 'شجاعة النبي -صلى الله عليه وسلم- وثبات قلبه أمام المخاطر، وثقته بالله -تعالى- وصدق توكله عليه وحسن الالتجاء إليه.
أثر التوكل على الله -تعالى- في الخلاص من الشدائد.
عفو النبي -صلى الله عليه وسلم- وكرم خُلُقه، وعدم انتقامه لنفسه، وبُعْدِ نظره في الأمور، وحسن معالجته للنفوس لجلبها إلى الحق.
الخروج للجهاد في سبيل الله -تعالى-؛ امتثالاً لأمر الله -تعالى-.
جواز تفرق العسكر في النزول وعند النوم ما لم يخافوا من أمر.
حراسة الإمام في القائلة والليل من الواجب على الناس، وأن تضييعه من المنكر والخطأ.
حسن التوكل على الله -تعالى-.
حماية الله -تعالى- لنبيه -صلى الله عليه وسلم-.
جواز إخبار الأصحاب بما يحدث معه، وأن ذلك لا يُعدُّ من الرياء.
جواز تعليق السلاح إذا ائتمن عليه.
سرعة استجابة الصحابة رضي الله عنهم للرسول -صلى الله عليه وسلم-.
مشاركة الأمير والقائد الجند في القتال.
الإشارة إلى استحباب تثليث لفظ الجلالة حالة الاستغاثة والاستعانة.
استحباب النوم في وسط النهار، للراحة.
فقر الصحابة -رضي الله عنهم- فقد خرجوا في خِفَاف لا بديل لهم عنها.
إيثار الصحابة النبي -صلى الله عليه وسلم-، بالشجرة الظليلة.
حب النبي -صلى الله عليه وسلم- وأصحابه للجهاد.', 'نَجْد : النَّجد في اللغة: ما ارتفع من الأرض، والمراد به هنا: ما دون الحجاز.
قَفَل : رجع من سفره.
القَائِلَة : وقت القيلولة، وهي: النوم في الظهيرة.
العِضَاه : الشجر الذي له شوك.
السَّمُرَة : الشجرة من الطَّلْح، وهي العِظام من شجر العِضَاه.
اخْتَرَط : سَلّه، وهو في يده.
صَلتًا : مَسْلُولاً مُنتزعا من غَمْده أو جِرَابه برفق.
ذات الرِّقاَع : سُميت بذلك: لعَصب المسلمين أرجُلَهم بالخِرَق.
ظَلِيلَةٍ : كثيرة الظِّل.
كُنْ خَيرَ آخِذٍ : بأن تَعفو وتصفح وتقابل السيئة بالحسنة.
خَلَّى سبيله : مَنَّ عليه وأطلقه.
الأَعْرَاب : من العَرَب سكان البَادِيَة خَاصَّة يتتبعون أماكن الغَيْث ومنابت الكلإ الوَاحِد أَعْرَابِي.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6967', false),
(20079, 2, 201, 79, 'hadith', 'عن عمر رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول : «لو أنكم تتوكلون على الله حق توكله لرزقكم كما يرزق الطير ، تغدو خماصاً وتروح بطاناً».', 'I heard Messenger of Allah (ﷺ) saying: "If you all depend on Allah with due reliance, He would certainly give you provision as He gives it to birds who go forth hungry in the morning and return with full belly at dusk"..', 'عمر رضي الله عنه', '''Umar (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 79', 'Riyad as-Salihin 79', 'ریاض الصالحین 79', 'رواه الترمذي ، وقال حديث حسن', 'يَحُثُّنا النبيُّ صلى الله عليه وسلم أن نَعتَمِد على الله عز وجل في استجلاب المنافع ودفع المضار في أمور الدنيا والدين، فإنه لا يُعطي ولا يَمنع ولا يَضر ولا يَنفع إلا هو سبحانه وتعالى، 
وأن نفعل الأسباب التي تَجْلُب المنافع وتدفع المضار مع صدق الاعتماد على الله، فمتى فعلنا ذلك رزَقَنا اللهُ كما يرزق الطير التي تخرج صباحًا وهي جياع، ثم تعود مساءً وهي ممتلئة البطون، وهذا الفعلُ من الطير نوعٌ من الأسباب في السعي لطلب الرزق، دون التواكل والتكاسل.', 'فضيلة التوكل، وأنه من أعظم الأسباب التي يُسْتَجْلَبُ بها الرزق.
التوكل لا ينافي فعل الأسباب، فإنه أخبر أن التوكل الحقيقي لا يضادُّه الغدوُّ والرَّوَاحُ في طلب الرزق.
اهتمام الشريعة بأعمال القلوب؛ لأن التوكل عمل قلبيٌّ.
التعلق بالأسباب فقط نقصٌ في الدين، وترك الأسباب نقصٌ في العقل.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4721', false),
(20080, 2, 201, 80, 'hadith', 'عن أبي عمارة البراء بن عازب رضي الله عنهما قال : قال رسول الله صلى الله عليه وسلم : « يا فلان إذا أويت إلى فراشك فقل: اللهم أسلمت نفسي إليك، ووجهت وجهي إليك: وفوضت أمري إليك ، وألجأت ظهري إليك، رغبة ورهبة إليك، لا ملجأ ولا منجى منك إلا إليك ، آمنت بكتابك الذي أنزلت، ونبيك الذي أرسلت؛ فإنك إن مت من ليلتك مت على الفطرة، وإن أصبحت أصبت خيراً».', 'Messenger of Allah (ﷺ) asked me to recite whenever I go to bed: "Allahumma aslamtu nafsi ilaika, wa wajjahtu wajhi ilaika, wa fawwadtu amri ilaika, wal-ja''tu zahri ilaika, raghbatan wa rahbatan ilaika, la malja wa la manja minka illa ilaika. Amantu bikitabikal-ladhi anzalta, wa nabiyyikal-ladhi arsalta (O Allah! I have submitted myself to You, I have turned my face to You, entrusted my affairs to You; and committed my back to You out of desire for You and fear of You; expecting Your reward and fearing Your punishment). There is no refuge and no place of safety from You but with You. I believe in the Book You have revealed and in the Prophet You have sent." Messenger of Allah (ﷺ) said that if anyone recited these words and died that night, he would die in the true religion. In case he remains alive till morning, he will obtain good. and let these words be your last".', 'أبي عمارة البراء بن عازب رضي الله عنهما', 'Al-Bara'' bin ''Azib (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 80', 'Riyad as-Salihin 80', 'ریاض الصالحین 80', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false)
on conflict (id) do update set collection_id = excluded.collection_id, chapter_id = excluded.chapter_id, number_in_book = excluded.number_in_book, kind = excluded.kind, arabic = excluded.arabic, translation_en = excluded.translation_en, narrator_ar = excluded.narrator_ar, narrator_en = excluded.narrator_en, grade_ar = excluded.grade_ar, reference_ar = excluded.reference_ar, reference_en = excluded.reference_en, reference_ur = excluded.reference_ur, full_ref_ar = excluded.full_ref_ar, explanation_ar = excluded.explanation_ar, benefits_ar = excluded.benefits_ar, word_meanings_ar = excluded.word_meanings_ar, source = excluded.source, source_ref = excluded.source_ref, daily_ok = excluded.daily_ok, review_note = excluded.review_note, deleted = false;

insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(20081, 2, 201, 81, 'hadith', 'عن أبي بكر الصديق رضي الله عنه عن عبد الله بن عثمان بن عامر بن عمر بن كعب بن سعد بن تيم بن مرة بن كعب بن لؤي بن غالب القرشي التيمي رضي الله عنه - وهو وأبوه وأمه صحابة، رضي الله عنهم- قال: نظرت إلى أقدام المشركين ونحن في الغار وهم على رؤوسنا فقلت يارسول الله لو أن أحدهم نظر تحت قدمية لأبصرنا. فقال: « ما ظنك يا أبا بكر باثنين الله ثالثهما».', 'When Messenger of Allah (ﷺ) and I were in the cave of Thaur and I saw the feet of the polytheists who were above us at the mouth of the cave (on the eve of the Emigration), I submitted: "O Messenger of Allah! If one of them were to look down below his feet, he would see us". He (ﷺ) said, "O Abu Bakr! What do you think of two whose third is Allah"..', 'أبي بكر الصديق رضي الله عنه', 'Abu Bakr As-Siddiq (May Allah bepleased with him) said:', 'صحيح', 'رياض الصالحين 81', 'Riyad as-Salihin 81', 'ریاض الصالحین 81', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20082, 2, 201, 82, 'hadith', 'عن أم المؤمنين أم سلمة، واسمها هند بنت أبي أمية حذيفة المخزومية، رضي الله عنها أن النبي صلى الله عليه وسلم كان إذا خرج من بيته قال: «بسم الله، توكلت على الله ، اللهم إني أعوذ بك أن أضل أو أضل، أو أذل أو أذل، أو أظلم أو أظلم ، أو أجهل أو يجهل علي».', 'Whenever the Prophet (ﷺ) stepped out of his house, he would say, "Bismillah, tawakkaltu ''alallah. Allahumma inni a''udhu bika an adilla aw udalla, aw azilla aw uzalla, aw azlima aw uzlama, aw ajhala aw yujhala ''alayya". ".', 'أم المؤمنين أم سلمة، واسمها هند بنت أبي أمية حذيفة المخزومية رضي الله عنها', 'Umm Salamah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 82', 'Riyad as-Salihin 82', 'ریاض الصالحین 82', 'حديث صحيح رواه أبو داود، والترمذي وغيرهما بأسانيد صحيحة)) . ((قال الترمذي: حديث حسن صحيح، وهذا لفظ أبي داود', null, null, null, 'sunnah.com', null, false, null, false),
(20083, 2, 201, 83, 'hadith', 'عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "من قال-يعني إذا خرج من بيته-: بسم الله توكلت على الله، ولا حول ولا قوة إلا بالله ، يقال له: هديت وكفيت ووقيت، وتنحى عنه الشيطان". رواه أبو داود والترمذي، والنسائي وغيرهم. وقال الترمذي: حديث حسن، زاد أبو داود: "فيقول :-يعني الشيطان-لشيطان آخر: كيف لك برجل قد هدي وكفي ووقيّ ؟', 'Messenger of Allah (ﷺ) said, "Whoever says (upon leaving his house): ''Bismillah, tawakkaltu ''alallah, wa la hawla wa la quwwata illa billah .Abu Dawud reported it with this addition: "One devil will say to another: ''How can you deal with a man who has been guided, defended and protected?".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 83', 'Riyad as-Salihin 83', 'ریاض الصالحین 83', null, 'أخبر رسول الله صلى الله عليه وسلم أن الرجل إذا خرج من بيته فقال: باسم الله، توكلت على الله، لا حول ولا قوة إلا بالله، يناديه ملك يا عبد الله هديت إلى طريق الحق، وكفيت همك، وحفظت من الأعداء؛ فيبتعد عنه الشيطان الموكل عليه، فيقول شيطان آخر لهذا الشيطان: كيف لك بإضلال رجل قد هدي، وكفي، ووقي من الشياطين أجمعين؟ لأنه قال هذه الكلمات فإنك لا تقدر عليه.', 'استحباب هذا القول عند الخروج من المنزل؛ ليحصل ما فيه من خير.
فضل التوكل على الله -عز وجل-، والالتجاء إليه بالقول والفعل، وأن ذلك حصن للمؤمن من كل شر.
لا حول ولا قوة للعبد في كافة أموره إلا بالله.
عجز الشيطان عن غواية من هداه الله، وحبَّب إليه الإيمان وزينه في قلبه.
تعاون الشياطين لإضلال العباد.', 'تَوَكَّلت : التوكل هو: الاعتماد على الله -سبحانه وتعالى- في حصول المطلوب، ودفع المكروه ، مع الثقة به وفعل الأسباب المأذون فيها.
لاَ حول ولا قُوَّة إِلاَّ بالله : لا انتقال ولا تحول من حال إلى حال، ولا قوة على شيء من الأشياء إلا بعون من الله.
يُقَال له : يحتمل القائل هو الباري -جل في علاه-، أو ملك يأمره الله -عز وجل-.
هُدِيتَ وَكُفِيتَ : أي: باستعانتك باسمه -تعالى- وتحصنك به هديت للصراط المستقيم، وكفيت كل مهم دنيوي وأخروي.
وُقِيتَ : حُفِظت من كل مكروه.
تَنَحَّى : مَال عن جهته، وابتعد عن طريقه.
الشَّيطَان : من الشَطَن: البُعد، أي البعد عن كل خير، والشيطان معروف، وكل عات متمرد من الجن والإنس والدواب يقال له شيطان.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3504', false),
(20084, 2, 201, 84, 'hadith', 'عن أنس رضي الله عنه قال: كان أخوان على عهد النبي صلى الله عليه وسلم، وكان أحدهما يأتي النبي صلى الله عليه وسلم ، والآخر يحترف، فشكا المحترف آخاه للنبي صلى الله عليه وسلم فقال : «لعلك ترزق به».', 'There were two brothers in the days of the Prophet (ﷺ). One of them used to attend the Prophet''s circle (to acquire knowledge) and the other used to earn their living). Once the latter complained to the Prophet (ﷺ) against the former (for not earning his living). He (ﷺ) replied, "Perhaps you are being provided because of him"..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 84', 'Riyad as-Salihin 84', 'ریاض الصالحین 84', 'رواه الترمذي بإسناد صحيح على شرط مسلم', 'حدَّث أنس رضي الله عنه فقال: كان أخوان على زمن رسول الله صلى الله عليه وسلم ، فكان أحدهما يأتي مجلس النبي صلى الله عليه وسلم ويلازمه ليتلقى من معارفه ويأخذ من أقواله وأفعاله، وأمَّا الآخر فيحترف الصناعة ويسعى في الكسب، فشكا المحترف أخاه في ترك الاحتراف إلى النبي صلى الله عليه وسلم ، فقال صلى الله عليه وسلم مسليًا له: لعل قيامك بأمره سبب لتيسير رزقك؛ لأن الله في عون العبد ما كان العبد في عون أخيه.', 'جواز إظهار الشكوى لولي الأمر.
تعظيم أمر الدين أكثر من أمر الدنيا.
من انقطع لطلب العلم والتفقه في أحكام الدين؛ لحفظ شريعة الله، فإن الله يهيء له من يقوم بشؤونه ويكفيه حاجاته.
الترغيب في مساعدة أهل العلم.
يُرزق الإنسان بسبب من يعيلهم.
تنبيه على أنَّ العبد يرزق بغيره، كما في الحديث الآخر: «وهل ترزقون - أو قال: تنصرون - إلا بضعفائكم».', 'يأتي النبي -صلى الله عليه وسلم- : يلازمه ليتلقى من علومه، ويتعلم أحكام الدين.
يَحتَرِف : يعمل ويكتسب ويتسَبَّب.
فَشَكَا : أي المحترف للنبي -صلى الله عليه وسلم- أخاه في ترك الاحتراف.
تُرزَقُ بِهِ : أي بسببه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3126', false),
(20085, 2, 201, 85, 'hadith', 'عن أبي عمرو، وقيل: أبي عمرة سفيان بن عبد الله رضي الله عنه قال: قلت: يا رسول الله قل لي في الإسلام قولاً لا أسأل عنه أحداً غيرك. قال: «قل آمنت بالله: ثم استقم».', 'I said, "O Messenger of Allah, tell me something of Islam which I will not ask anyone else about it." He (ﷺ) said, "Say, ''I believe in Allah'' and then be steadfast"..', 'أبي عمرو، وقيل: أبي عمرة سفيان بن عبد الله رضي الله عنه', 'Sufyan bin ''Abdullah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 85', 'Riyad as-Salihin 85', 'ریاض الصالحین 85', 'رواه مسلم', 'سَأَلَ الصحابيُّ سفيانُ بنِ عبدِ الله رضي الله عنه النبيَّ صلى الله عليه وسلم أنْ يُعَلِّمَه قولًا جامِعًا لمعاني الإسلام يَتَمَسَّكُ به ولا يَسأل عنه غيرَه؟ فقال له صلى الله عليه وسلم: قل: وَحَّدْتُ اللهَ، وآمنتُ أنه ربي وإلهي وخالقي ومعبودي الحق لا شريك له، ثم ينقاد لطاعة الله بأداء فرائض الله وترك محارم الله ويستمر عليها.', 'أصلُ الدين هو الإيمان بالله بروبيته وألوهيته وأسمائه وصفاته.
أهمية الاستقامة بعد الإيمان، والاستمرار في العبادة، والثبات على ذلك.
الإيمان شرط لقبول الأعمال .
الإيمان بالله، يشمل ما يجب اعتقادُه من عقائد الإيمان وأصوله، وما يتبع ذلك من أعمال القلوب، والانقياد والاستسلام لله باطنًا وظاهرًا.
الاستقامةُ مُلازَمَةُ الطريق، بفعل الواجبات وترك المنهيات.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66524', false),
(20086, 2, 201, 86, 'hadith', 'عن أبي هريرة رضي الله عنه : قال: قال رسول الله صلى الله عليه وسلم قاربوا وسددوا، واعلموا أنه لن ينجو أحد منكم بعمله" قالوا: ولا أنت يا رسول الله ؟ قال: "ولا أنا إلا أن يتغمدنى الله برحمة منه وفضل".', 'Messenger of Allah (ﷺ) said, "Follow the Right Path of Faith strictly, and be steadfast; and keep in mind that none of you can achieve salvation through his (good) actions." Someone asked, "Not even you, O Messenger of Allah?" He (ﷺ) said, "Not even me, unless Allah grants me His Mercy and Grace"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 86', 'Riyad as-Salihin 86', 'ریاض الصالحین 86', 'رواه مسلم', 'يَحُثُّ النبيُّ صلى الله عليه وسلم الصحابة على أنْ يعملوا، وأنْ يتقوا الله ما استطاعوا، دون غُلُوٍّ ولا تَقصير، وأن يقصِدوا بعملهم الصواب بالإخلاص لله واتّباع السنة لِيُقبَل عملُهم فتكون سببًا لنزول الرحمة عليهم.

ثم أَخبرَهم بأنه لن يُنجيَ أحدًا منكم عملُه فقط؛ بل لا بد من رحمة الله.

قالوا: حتى أنت يا رسول الله لا ينجيك عملُك مع عِظَمِ قدره؟ 

فقال: حتى أنا، إلّا أن يَستُرَني اللهُ بفضل رحمته.', 'قال النووي: (سدِّدوا وقاربوا): اطلبوا السدادَ، واعملوا به، وإن عَجَزْتُم عنه، فقارِبُوه؛ أي: اقربوا منه، والسداد: الصوابُ، وهو بين الإفراط والتفريط، فلا تَغْلُوا ولا تُقصِّروا.
قال ابن باز: الأعمال الصالحة هي أسباب دخول الجنة، كما أنّ الأعمال الخبيثة هي أسباب دخول النار، والحديث يُبيِّنُ أنّ دخولَهم الجنة ليس بمجرَّد العمل، بل لا بد من عفو الله ورحمته سبحانه وتعالى، فهم دخلوها بأسباب أعمالهم، ولكن الذي أوجب ذلك رحمته سبحانه، وعفوه ومغفرته.
العبد لا يَغتر ويُعجَب بعمله مهما بلغ؛ لأنّ حقَّ الله أعظم من عمله، فلا بد للعبد من الخوف والرجاء جميعًا.
فضل الله ورحمته على عباده أوسع من أعمالهم.
الأعمال الصالحة سبب لدخول الجنة، والفوز بها إنما هو بفضلِ الله ورحمة منه.
قال الكرماني: "إذا كان كلُّ الناس لا يدخلون الجنة إلا برحمة الله، فوجْه تخصيص رسول الله صلى الله عليه وسلم بالذِّكْر هو أنه إذا كان مقطوعًا له بأنه يدخل الجنة، ولا يدخلها إلا برحمة الله؛ فغيرُه يكون في ذلك بطريق الأَولى.
 قال النووي: في معنى قوله تعالى: ﴿ادْخُلُوا الْجَنَّةَ بِمَا كُنْتُمْ تَعْمَلُونَ﴾ [النحل: 32]، ﴿وَتِلْكَ الْجَنَّةُ الَّتِي أُورِثْتُمُوهَا بِمَا كُنْتُمْ تَعْمَلُونَ﴾ [الزخرف: 72]، ونحوهما من الآيات الدالة على أن الأعمال يُدخَل بها الجنة، فلا يُعارِض هذه الأحاديثَ، بل معنى الآيات أن دخول الجنة بسبب الأعمال، ثم التوفيق للأعمال، والهداية للإخلاص فيها، وقَبُولها برحمة الله تعالى وفضله، فيصح أنه لم يدخل بمجرَّد العمل، وهو مراد الأحاديث، ويصح أنه دخل بالأعمال؛ أي: بسببها، وهي من الرحمة.
قال ابن الجوزي: يتحصل عن ذلك أربعة أجوبة؛ الأول: أنَّ التوفيق للعمل من رحمة الله، ولولا رحمة الله السابقة ما حصل الإيمان ولا الطاعة التي يحصل بها النجاة، الثاني: أنّ منافع العبد لسيده فعمله مُستَحَقٌّ لمولاه، فمهما أنعم عليه من الجزاء فهو من فضله، الثالث: جاء في بعض الأحاديث أنّ نفس دخول الجنة برحمة الله، واقتسام الدرجات بالأعمال، الرابع: أنّ أعمال الطاعات كانت في زمن يسير، والثواب لا ينفد فالإنعام الذي لا ينفد في جزاء ما ينفد بالفضل لا بمقابلة الأعمال.
قال الرافعي: أنّ العامل لا ينبغي أنْ يَتَّكِلَ على عَمَلِهِ في طلب النجاة ونيل الدرجات؛ لأنه إنما عَمل بتوفيق الله وإنما ترك المعصية بعصمة الله فكل ذلك بفضله ورحمته.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3469', false),
(20087, 2, 201, 87, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: « بادروا بالأعمال فتناً كقطع الليل المظلم يصبح الرجل مؤمنا ويمسي كافراً ويمسي مؤمنا ويصبح كافراً، يبيع دينه بعرض من الدنيا».', 'Messenger of Allah (ﷺ) said, "Be prompt in doing good deeds (before you are overtaken) by turbulence which would be like a part of the dark night. A man would be a believer in the morning and turn to disbelief in the evening, or he would be a believer in the evening and turn disbeliever in the morning, and would sell his Faith for worldly goods.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 87', 'Riyad as-Salihin 87', 'ریاض الصالحین 87', 'رواه مسلم', 'يَحُثُّ النبيُّ صلى الله عليه وسلم المؤمنَ بالمسارعة والإكثار من الأعمال الصالحة قبل تعذُّرِها والاشتغال عنها بمجيء الفتن والشبهات التي تمنع منها، وتصد عنها، وهي مظلمة كقطع الليل، يختلط فيها الحق بالباطل، فيصعب على الناس التمييز بينهما، ومن شدتها يتخبط الإنسان حتى إنه يصبح مؤمنًا ويمسي كافرًا، ويمسي مؤمنًا ويصبح كافرًا، يترك دينه بمتاع من الدنيا زائل.', 'وجوب التمسُّك بالدين، والمبادرة إلى العمل الصالح قبل أن تَحوْل الموانع دونه.
الإشارة إلى تتابع الفتن المضلة آخر الزمان، وأنه كلما ذهبت فتنة أعقبتها فتنة أخرى.
إذا ضَعُف دين الإنسان وتنازل عنه مقابل الأمور الدنيوية من مال أو غيره كان ذلك سببًا في انحرافه وتركه للدين وانسياقه مع الفتن.
في الحديث دليل على أن الأعمال الصالحة سبب للنجاة من الفتن.
الفتن قسمان: فتن شبهات وعلاجها العلم، وفتن شهوات وعلاجها الإيمان والصبر.
في الحديث إشارة إلى أن مَن قلَّ عمله كانت الفتنة إليه أسرع، وأن من كثر عمله ينبغي ألّا يغتر بما عنده بل يستزيد.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3138', false),
(20088, 2, 201, 88, 'hadith', 'الثاني عن أبي سروعة -بكسر السين المهملة وفتحها- عقبة ابن الحارث رضي الله عنه قال: صليت وراء النبي صلى الله عليه وسلم بالمدينة العصر، فسلم ثم قام مسرعاً فتخطى رقاب الناس إلى بعض حجر نسائه، ففزع الناس من سرعته، فخرج عليهم، فرأى أنهم قد عجبوا من سرعته، قال «ذكرت شيئاً من تبر عندنا فكرهت أن يحبسنى، فأمرت بقسمته» ((رواه البخاري)). وفي رواية للبخاري : كنت خلفت في البيت تبراً من الصدقة، فكرهت أن أبيته . ((التبر)) قطع ذهب أو فضة', 'Once I performed the ''Asr prayer in Al-Madinah behind the Prophet (ﷺ). He (ﷺ) got up quickly after finishing the prayer with Taslim, and stepping over the people, went to one of the rooms of his wives. The people were startled at his haste, and when he came out and saw their astonishment at his urgency he said, "I recalled that there was left with me some gold which was meant for charity; I did not like to keep it any longer, so I gave orders that it should be distributed"..In another narration, Messenger of Allah said, "I had left some gold for Sadaqah in the house, and did not wish to keep it overnight".', null, '''Uqbah bin Al-Harith (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 88', 'Riyad as-Salihin 88', 'ریاض الصالحین 88', null, 'قال عقبة بن الحارث رضي الله عنه أنه صلَّى مع النبي صلى الله عليه وسلم ذات يوم صلاة العصر، فقام النبي صلى الله عليه وسلم حين انصرف من صلاته مسرعاً، يَتخَطَّي رقاب الناس متوجهاً إلى بعض حجرات زوجاته؛ فخاف الناس من ذلك، ثم خرج فرأى الناس قد عجبوا من ذلك؛ فبين لهم النبي صلى الله عليه وسلم سبب هذا، وأخبر أنه تذكر شيئًا من ذهب غير مضروب مما تجب قسمته، فكره أن يمنعه ويشغله التفكير فيه عن التوجه والإقبال على الله تعالى .', 'جواز قيام الإمام بعد الفراغ من الصلاة دون أن يقول أذكار دبر الصلاة إذا أتاه ما يشغله، ويؤخر الأذكار.
أن رسول الله -صلى الله عليه وسلم- أسرع الناس مبادرة إلى الخير.
جواز تخطي الرقاب بعد السلام من الصلاة، ولا سيما إذا كان لحاجة.
جواز التعجب ممن فعل فعلاً ليس من عادته.
أن رسول الله -صلى الله عليه وسلم- كغيره من البشر يلحقه النسيان، وأنه ينسى كما ينسى غيره.
انشغال الفكر في الصلاة لا يبطلها، ولكن يُخشى أن يذهب بالخشوع.
استحباب التخلص مما يشغل القلب عن الله -تعالى-، واستحباب المبادرة إلى عمل الخير.
شدة الأمانة وعظمها، وأن الإنسان إذا لم يبادر بأدائها فإنها قد تحبسه.
جواز الاستنابة والتوكيل في صرف الصدقات مع القدرة على المباشرة.', 'فَتَخَطَّى : قَطَع الصفوف حال جلوس الناس.
حُجَر : جمع حُجْرة، اسم للمنزل.
فَفَزِعَ : خاف الناس؛ لأنه خالف عادته؛ لأنَّ عادته أن يمشي بتأن.
يَحْبِسَنِي : يشغلني التفكير فيه عن التوجه والإقبال على الله -تعالى-.
التِبر : الذهب والفضة قبل أن يضربا دنانير ودراهم، ويطلق على الذهب تغليبًا، كما يطلق على غيره من المعادن.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3483', false),
(20089, 2, 201, 89, 'hadith', 'عن جابر رضي الله عنه قال: قال رجل للنبي صلى الله عليه وسلم يوم أحد: : رَأيتَ إنْ قُتِلتُ فَأَيْنَ أَنَا ؟ قَالَ : « في الجنَّةِ » فَأَلْقَى تَمَرَاتٍ كُنَّ في يَدِهِ ، ثُمَّ قَاتَلَ حَتَّى قُتِلَ . مُتَّفَقٌ عَلَيهِ .', 'A man, said to the Prophet (ﷺ) during the battle of Uhud: "Tell me where I shall be if I am killed". When he (ﷺ) replied that he would be in Jannah, the man threw away some dates which he had in his hand and fought until he was killed..', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 89', 'Riyad as-Salihin 89', 'ریاض الصالحین 89', null, 'أخبر جابر رضي الله عنه أن رجلًا -قيل: اسمه عُمير بن الحُمَام وقيل: غيره- قال للنبي صلى الله عليه وسلم يوم غزوة أحد: يا رسول الله! أرأيتَ إن قاتلتُ حتى قُتلتُ، يعني جاهدت المشركين وقتلت في هذه الوقعة ما مصيري؟ قال: "أنت في الجنة"، فألقى تمرات كانت معه، وقال: (إنها لحياة طويلة إن بقيت حتى آكل هذه التمرات) ثم تقدم فقاتل حتى قتل رضي الله عنه .', 'يفيد هذا الحديث المسارعة بفعل الخيرات.
جزاء من قتل في سبيل الله الجنة.
استحباب أن يسأل الإنسان عما لا يعلم.
ما كان الصحابة عليه من حب نصر الإسلام، والرغبة في الشهادة ابتغاء مرضاة الله وثوابه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3194', false),
(20090, 2, 201, 90, 'hadith', 'عن أبي هريرة ، قَالَ : جاءَ رَجُلٌ إِلَى النَّبيِّ فَقَالَ : يَا رسولَ الله ، أيُّ الصَّدَقَةِ أعْظَمُ أجْرَاً ؟ قَالَ : « أنْ تَصَدَّقَ وَأنتَ صَحيحٌ شَحيحٌ ، تَخشَى الفَقرَ وتَأمُلُ الغِنَى ، وَلا تُمهِلْ حَتَّى إِذَا بَلَغتِ الحُلقُومَ قُلْتَ لِفُلان كذا ولِفُلانٍ كَذا ، وقَدْ كَانَ لِفُلانٍ » . مُتَّفَقٌ عَلَيهِ .', 'There came a man to the Prophet (ﷺ) and said, "O Messenger of Allah, which charity is the most rewardable?" He (ﷺ) said, "That you should give charity (in a state when you are) healthy and stingy and fear poverty, hoping to become rich (charity in such a state of health and mind is the best). And you must not defer (charity to such a length) that you are about to die and would be saying: ''This is for so-and-so, and this for so-and-so.'' Lo! It has already come into (the possession of) so-and- so"..', null, 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 90', 'Riyad as-Salihin 90', 'ریاض الصالحین 90', null, 'جاء رجل إلى النبي صلى الله عليه وسلم يسأله أفضل الصدقة، فقال له: أن تتصدق وأنت صحيح البدن شحيح النفس، تخاف من الفقر إن طالت بك حياتك، وتطمع في الغِنى؛ ولا تؤخر الصدقة حتى إذا جاءك الموت وعلمت أنك خارج من الدنيا قلت لفلان كذا من المال صدقة أو وصية، ولفلان كذا من المال صدقة أو وصية؛ وقد كان المال لغيرك الذي يرثك.', 'صدقة الصحة أفضل من صدقة المرض؛ لأن الشح غالب على الإنسان في حال الصحة، فإذا سمح بها وتصدق دل ذلك على صدق نيته وعظيم محبته لله -تعالى-.
الترغيب في المسارعة إلى الخيرات، وأداء الصدقات قبل نزول بوادر الموت بالإنسان.', 'تَصَدَّقَ : أصلها: تتصدق.
الشح : البخل مع شدة الحرص.
تخشى : تخاف.
تأْمَل : تَطْمَع.
بلغت الحلقوم : أي: قاربت الروح بلوغ الحلقوم.
الحلقوم : مجرى النفس.
قلت لفلان كذا : المراد: الإقرار بالحقوق، أو الوصية، أو الميراث.
وقد كان لفلان : قد صار له ذلك.
تُمْهِل : تؤخر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4252', false),
(20091, 2, 201, 91, 'hadith', 'عن أنس رضي الله عنه، أن رسول الله صلى الله عليه وسلم أخذ سيفاً يوم أحد فقال: " من يأخذ مني هذا؟ فبسطوا أيديهم، كل إنسان منهم يقول: أنا أنا. قال: "فمن يأخذه بحقه؟" فأحجم القوم، فقال أبو دجانة رضي الله عنه: أنا آخذه بحقه، فأخذه ففلق به هام المشركين.', 'Messenger of Allah (ﷺ) took up a sword on the day of the battle of Uhud and said, "Who will take this sword from me?" Everyone stretched forth his hand saying: "I will take it; I will take it". He (the Prophet (ﷺ)) said, "Who will take it with its full responsibility (i.e., to use it to fight Allah''s enemies with it)?" The Companions hesitated. Abu Dujanah (May Allah be pleased with him) said: "I shall take it;" and with it he cracked the skulls of the pagans..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 91', 'Riyad as-Salihin 91', 'ریاض الصالحین 91', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20092, 2, 201, 92, 'hadith', 'عن الزبير بن عدي قال: أتينا أنس بن مالك رضي الله عنه فشكونا إليه ما نلقى من الحجاج. فقال: «اصبروا فإنه لا يأتي زمان إلا والذي بعده شر منه حتى تلقوا ربكم» سمعته من نبيكم صلى الله عليه وسلم.', 'We went to Anas bin Malik (May Allah be pleased with him) and complained to him of suffering at the hands of Al-Hajjaj. He replied: "Show endurance, for no time will come but will be followed by one worse (than the present one) till you meet your Rubb. I heard this from your Prophet (ﷺ)"..', 'الزبير بن عدي قال: أتينا أنس بن مالك رضي الله عنه', 'Az-Zubair bin ''Adi said:', 'صحيح', 'رياض الصالحين 92', 'Riyad as-Salihin 92', 'ریاض الصالحین 92', 'رواه البخاري', 'جاء الزبير بن عدي ومعه جماعة إلى أنس بن مالك رضي الله عنه خادم رسول الله صلى الله عليه وسلم ، يشكون إليه ما يجدون من الحجاج بن يوسف الثقفي، أحد الأمراء لخلفاء بني أمية، وكان جبارًا عنيدًا معروفًا بالظلم وسفك الدماء، فأمرهم أنس رضي الله عنه بالصبر على جور ولاة الأمور، وأخبرهم أنه لا يأتي على الناس زمان إلا والذي بعده أشر منه حتى يلقوا ربهم، وأنه سمعه من رسول الله صلى الله عليه وسلم .
والشر ليس شرًّا مطلقًا عامًّا، بل قد يكون شرًّا في بعض المواضع، ويكون خيرًا في مواضع أخرى.', 'جواز شكوى الإمام أو الحاكم لأهل العلم.
القيادة الحقيقية للناس كامنة في أهل العلم.
ولاية الحجاج بن يوسف الثقفي ظالمة.
استحباب الصبر على المحن، والمبادرة بالأعمال الصالحة.
انتشار الفساد في آخر الزمان.
عدم الخروج على ولاة الأمور وإن ظلموا وجاروا.
في الحديث دليل على دفع المفسدة الكبرى بالمفسدة الصغرى، فالصبر على ظلم الحاكم خير من سفك دماء المسلمين.', 'اصبروا : أي: على ما تلقون منه.
تلقوا ربكم : يدرككم الموت.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4953', false),
(20093, 2, 201, 93, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: « بادروا بالأعمال سبعاً. هل تنتظرون إلا فقراً منسياً، أو غنى مطغياً، أو مرضاً مفسداً، أو هرماً مفنداً أو موتاً مجهزاً أو الدجال فشر غائب ينتظر، أو الساعة فالساعة أدهى وأمر!».', 'Messenger of Allah (ﷺ) said, "Hasten to do good deeds before you are overtaken by one of the seven afflictions." Then (giving a warning) he said, "Are you waiting for such poverty which will make you unmindful of devotion; or prosperity which will make you corrupt, or disease as will disable you, or such senility as will make you mentally unstable, or sudden death, or Ad-Dajjal who is the worst expected absent, or the Hour, and the Hour will be most grievous and most bitter"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 93', 'Riyad as-Salihin 93', 'ریاض الصالحین 93', 'رواه الترمذي وقال: حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(20094, 2, 201, 94, 'hadith', 'عنه أن رسول الله صلى الله عليه وسلم قال يوم خيبر: "لأعطين هذه الراية رجلا يحب الله ورسوله، يفتح الله على يديه" قال عمر رضي الله عنه: ما أحببت الإمارة إلا يؤمئذ، فتساورت لها رجاء أن أدعى لها، فدعا رسول الله صلى الله عليه وسلم عليّ بن أبي طالب رضي الله عنه فأعطاه إياها وقال: " أمش ولا تلتفت حتى يفتح الله عليك" فسار علي شيئاً، ثم وقف ولم يلتفت، فصرخ: يا رسول الله، على ماذا أقاتل الناس؟ قال: " قاتلهم حتى يشهدوا أن لا إله إلا الله، وأن محمداً رسول الله، فإذا فعلوا ذلك فقد منعوا منك دماءهم وأموالهم إلا بحقها، وحسابهم على الله" ((رواه مسلم)): (14)', 'On the day of the battle of Khaibar, Messenger of Allah (ﷺ) said, "I shall hand over this banner to one who loves Allah and His Messenger, and Allah will give us victory through him." ''Umar (May Allah be pleased with him) said: "I had never longed for leadership but that day I expected that I might be called for. However, Messenger of Allah (ﷺ) called ''Ali bin Abu Talib (May Allah be pleased with him) and handed the banner to him and said, "Go forth and do not turn around till Allah bestows victory upon you". (On hearing this) ''Ali proceeded a little and then halted and without turning around inquired in a loud voice: "O Messenger of Allah, for what shall I fight them?" He (ﷺ) replied, "Go on fighting till they affirm that none has the right to be worshiped but Allah and that Muhammad is the Messenger of Allah. If they admit that, their lives and their properties will be secured, subject to their obligations according to Islam, and they will be answerable to Allah"..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 94', 'Riyad as-Salihin 94', 'ریاض الصالحین 94', null, 'أَخْبَرَ النبيُّ صلى الله عليه وسلم الصحابةَ بانتصار المسلمين مِن الغَد على يهود خيبر مَدينة قُرْبَ المدينة، وذلك على يَد رجل يعطيه الراية، وهو العَلَم الذي يَتخذه الجيش شعارًا له، وهذا الرجل مِن صفاته أنه يحب الله ورسوله، ويحبه الله ورسوله.

وقد ذَكَرَ عُمرُ بن الخطاب رضي الله عنه أنه ما أحبَّ الإمارةَ وأن يكون هو المقصود إلا يومئذ؛ رجاء أن يصيبه ما قاله النبي صلى الله عليه وسلم من حُبِّ الله ورسوله، ومدَّ عمر رضي الله عنه جسده ليراه النبي صلى الله عليه وسلم رجاء أن يُدْعَى لها، وحرصًا وطمعًا في أخذ تلك الراية.

فدعا صلى الله عليه وسلم عليَّ بن أبي طالب رضي الله عنه فأعطاه الراية، وأمره النبي صلى الله عليه وسلم أن يَتحرَّك بالجيش، وألَّا ينصرف عن القتال بعد لقاء عدوه براحة أو توقف أو هدنة حتى يفتح الله عليه هذه الحصون بالنصر والغلبة. 

فسار عليٌّ رضي الله عنه، ثم وَقَفَ إلا أنه لم يلتفت؛ لئلا يخالِف أمرَ النبيِّ صلى الله عليه وسلم، فرفع عليٌّ رضي الله عنه صوته: يا رسول الله، على ماذا أقاتل الناس؟ 

فقال صلى الله عليه وسلم: قاتلهم حتى يشهدوا أن لا إله إلا الله وأن محمدًا رسول الله، فإذا استجابوا، ودخلوا في الإسلام؛ فقد منعوا منك دماءهم وأموالهم وحَرُمَت عليك، إلا بحقِّها يعني إلا إذا ارتكبوا جريمة أو جناية يستحقون عليها القتل بموجب أحكام الإسلام، وحسابهم على الله.', 'الصحابة كانوا يَكرهون الإمارة لما فيها من عِظَم المسؤولية.
جواز التطلُّع والاستشراف لأمر تأكَّد خيرُه.
توجيه الإمام لقائد الجيش في كيفية التصرّف في ساحة المعركة.
التزام أصحاب الرسول صلى الله عليه وسلم لوصاياه والمبادرة إلى تنفيذها.
مَن أَشْكَلَ عليه شيء فيما طُلب منه سأل عنه.
من دلائل نبوته صلى الله عليه وسلم إخباره بالنصر على اليهود، حيث أخبر عن فتح خيبر فكان كما أخبر.
الحث على الإقدام والمبادرة إلى ما أمر به رسول الله صلى الله عليه وسلم.
لا يجوز قتل من نطق بالشهادتين إلا إذا ظهر منه ما يستوجب القتل.
تجري أحكام الإسلام على ما يظهر من الناس والله يتولى سرائرهم.
 المقصود الأعظم من الجهاد هو دخول الناس في الإسلام.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4958', false),
(20095, 2, 201, 95, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إن الله تعالى قال: من عادى لي وليا فقد آذنته بالحرب. وما تقرب إلي عبدي بشيء أحب إلي مما افترضت عليه، وما يزال عبدي يتقرب إلي بالنوافل حتى أحبه، فإذا أحببته كنت سمعه الذي يسمع به، وبصره الذي يبصر به، ويده التي يبطش بها، ورجله التي يمشي بها، وإن سألني أعطيته؛ ولئن استعاذني لأعيذنه».', 'Messenger of Allah (ﷺ) said, "Allah the Exalted has said: ''I will declare war against him who shows hostility to a pious worshipper of Mine. And the most beloved thing with which My slave comes nearer to Me is what I have enjoined upon him; and My slave keeps on coming closer to Me through performing Nawafil (prayer or doing extra deeds besides what is obligatory) till I love him. When I love him I become his hearing with which he hears, his seeing with which he sees, his hand with which he strikes, and his leg with which he walks; and if he asks (something) from Me, I give him, and if he asks My Protection (refuge), I protect him"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 95', 'Riyad as-Salihin 95', 'ریاض الصالحین 95', 'رواه البخاري', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم في الحديثِ القُدْسِيِّ أنَّ الله عز وجل قال: مَن آذى وَليًّا من أوليائي وأغضبَه وأبغضَه فقد أَعْلمتُه وأعلنتُ له العداوة.
والوليُّ هو: المؤمنُ التَّقي، وعلى قدر ما للعبد من الإيمان والتقوى يكون نصيبُه من ولاية الله. وما تقرَّب المسلم إلى ربِّه بشيء أحب إليه مما افترضه وأوجبه عليه من فعل الطاعات وترك المحرمات، وما يزال المسلم يتقرّب إلى ربه بالنوافل مع الفرائض؛ حتى ينال محبة الله. فإذا أحبه الله كان الله مُسددًا له في هذه الأعضاء الأربعة:
يُسدِّدُه في سمعه، فلا يسمع إلا ما يرضي الله.
ويُسدده في بصره، فلا ينظر إلا إلى ما يحب الله النظر إليه ويرضاه.
ويُسدده في يده، فلا يعمل بيده إلا ما يرضي الله.
ويُسدده في رجله، فلا يمشي إلا إلى ما يرضي الله، ولا يسعى إلا إلى ما فيه الخير.
ومع هذا إنْ سأل اللهَ شيئًا فإنَّ الله يعطيه ما سأل، فيكون مجابَ الدعوة، ولئن استعاذ بالله ولجأ إليه طلبًا للحماية، فإن الله سبحانه يُعيذه ويحميه مما يخاف.', 'هذا الحديث ممّا يَرويه النبيُّ صلى الله عليه وسلم عن ربه، ويُسمّى بالحديث القُدْسِي أو الإلهي، وهو الذي لَفْظُه ومعناه مِن الله، غير أنه ليست فيه خصائصُ القرآن التي امتاز بها عما سواه، من التعبُّدِ بتلاوتِه والطهارة له والتَّحَدِّي والإعجاز، وغير ذلك.
النهي عن إيذاء أولياء الله والترغيب في حُبِّهم، والاعتراف بفضلهم.
الأمر بمعاداة أعداء الله وتحريم موالاتهم.
مَن ادَّعَى ولايةَ اللهِ بدون اتّباع شرعِه فهو كاذبٌ في دعواه.
تُنالُ ولايةُ الله بفعل الواجبات وترك المحرمات.
مِن أسباب محبة الله للعبد وإجابة دعوته فِعْلُ النوافل بعد القيام بالواجبات وترك المحرمات.
الدلالة على شرف الأولياء ورفعة منزلتهم.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66534', false),
(20096, 2, 201, 96, 'hadith', 'عن أنس رضي الله عنه عن النبي صلى الله عليه وسلم فيما يرويه عن ربه عز وجل قال: « إذا تقرب العبد إلي شبراً تقربت إليه ذراعاً، وإذا تقرب إلي ذراعاً تقربت منه باعاً، وإذا أتاني يمشي أتيته هرولة».', 'The Prophet (ﷺ) said, "Allah says: '' When a slave of Mine draws near to Me a span, I draw near to him a cubit; and if he draws near to Me a cubit, I draw near to him a fathom. And if he comes to Me walking, I go to him running."''..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 96', 'Riyad as-Salihin 96', 'ریاض الصالحین 96', 'رواه البخاري', 'من تقرَّب إلى الله بشيء من الطاعات ولو قليلًا قابله الله بأضعاف من الإِثابة والإِكرام، وكلما زاد في الطاعة زاده في الثواب، وأسرع برحمته وفضله، وهذا التفسير بناءً على أن الحديث ليس من أحاديث الصفات كما هو مذهب جمع من أهل السنة والجماعة المثبتين للصفات، ومنهم ابن تيمية، وعند طائفة أخرى إثبات صفة الهرولة لله تعالى دون الخوض في كيفيتها.', 'الدلالة على كرم الله عز وجل حيث يُعطِي الكثير في مقابلة القليل.
إثبات صفة المجيء والإتيان، ونحن نؤمن بها دون تكييف أو تحريف أو تعطيل أو تمثيل، وهي صفة ثابتة بالكتاب والسنة.', 'شبرا : الشِّبر: مَا بَين طرفِي الْخِنْصر والإبهام بالتفريج الْمُعْتَاد.
ذراعا : الذراع: هو الساعد إلى المرفق.
باعًا : الباع: قدر مدِّ اليدين وما بينهما من البدن.
هرولة : نوع من العَدْوِ فيه مسارعة الخُطا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6461', false),
(20097, 2, 201, 97, 'hadith', 'عن ابن عباس رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: « نعمتان مغبون فيهما كثير من الناس: الصحة، والفراغ».', 'Messenger of Allah (ﷺ) said, "There are two blessings in which many people incur loss. (They are) health and free time (for doing good)".', 'ابن عباس رضي الله عنهما', 'Ibn Abbas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 97', 'Riyad as-Salihin 97', 'ریاض الصالحین 97', 'رواه البخاري', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم عن نعمتين عظيمتين من نعم الله على الإنسان يَخْسَر فيهما كثيرٌ من الناس حيث يَصرفونها في غير محلها؛ فإن الإنسان إذا اجتمع له نعمة الصحة مع الفراغ، فغَلَبَ عليه الكسل عن الطاعة فهو الخاسر؛ وهي حال أكثر الناس، وإن استعمل فراغَه وصحتَه في طاعة الله فهو الرابح؛ حيث أن الدنيا مزرعة الآخرة، وفيها التجارة التي يظهر ربحُها في الآخرة، والفراغ يَعْقُبُه الشُّغْل، والصحة يعقبها السَّقَم، ولو لم يكن إلا الهَرَم لَكَفى.', 'تشبيه المكلَّف بالتاجر، والصحة والفراغ برأس المال؛ فمن أحسن استخدام رأس ماله نال وربح، ومن ضيَّعه خَسِر ونَدِم.
قال ابن الخازن: النعمة ما يتنعّم به الإنسان ويَستَلِذُّه، والغَبْنُ أنْ يشتري بأضعاف الثمن، أو يبيع بدون ثمن المِثْل؛ فمن صحَّ بدنه وتَفَرّغ من الأشغال العاتقة ولم يَسْعَ لصلاح آخرته فهو كالمغبون في البيع.
الحرص على الاستفادة من الصحة والفراغ للتقرب إلى الله عز وجل، وفعل الخيرات قبل فواتهما.
شكر نعم الله يكون باستخدامها في طاعة الله تعالى.
قال القاضي وأبو بكر بن العربي: اختلف في أول نعمة الله على العبد، فقيل: الإيمان، وقيل: الحياة، وقيل: الصحة، والأول أولى فإنه نعمة مُطْلَقة، وأما الحياة والصحة فإنهما نعمة دنيوية، ولا تكون نعمة حقيقة إلا إذا صاحبت الإيمانَ، وحينئذ يُغْبَنُ فيها كثير من الناس، أي يذهب رِبْحُهم أو يَنْقُص، فمَن استرسل مع نفسه الأمّارة بالسوء الخالدة إلى الراحة فترك المحافظة على الحدود، والمواظبة على الطاعة فقد غُبِنَ، وكذلك إذا كان فارغًا، فإنّ المشغول قد يكون له مَعذِرة بخلاف الفارغ؛ فإنه يرتفع عنه المعذرة وتقوم عليه الحجة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5449', false),
(20098, 2, 201, 98, 'hadith', 'عن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان يقوم من الليل حتى تنفطر قدماه، فقلت له: لم تصنع هذا يا رسول الله، وقد غفر الله لك ما تقدم من ذنبك وما تأخر؟! قال: « أفلا أحب أن أكون عبداً شكوراً؟».', 'The Prophet (ﷺ) would stand (in prayer) so long that the skin of his feet would crack. I asked him, "Why do you do this while your past and future sins have been forgiven?" He said, "Should I not be a grateful slave of Allah?".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 98', 'Riyad as-Salihin 98', 'ریاض الصالحین 98', 'متفق عليه. هذا لفظ البخاري، ونحوه في الصحيحين من رواية المغيرة بن شعبة', 'كان النبي صلى الله عليه وسلم يقوم بالتهجد من الليل حتى تتشقق قدماه، فقالت له عائشة رضي الله عنها ، -ظنا منها أنه إنما يعبد الله خوفًا من الذنب وطلبًا للمغفرة والرحمة، وهو قد تحقق له غفران الله تعالى فلا يحتاج لذلك-: لِمَ تصنع هذا يا رسول الله وقد غفر الله لك ما تقدم من ذنبك وما تأخر، فقال لها النبي صلى الله عليه وسلم : أفلا أحب أن أكون عبدا شكورا، فهذه العبادة سببها الشكر على المغفرة.', 'كثرة اجتهاد رسول الله -صلى الله عليه وسلم- في عبادة الله -تعالى-.
من أنعم الله عليه بنعمة وخَصَّهُ بفضيلة يجب عليه شكرها.
يجب أن تكون النعمة سببا لزيادة الشكر.
أن من شكر الله -تعالى- قيام الليل.', 'يقوم : أي: بالتهجد.
تتفطَّر : تتشقق.
شكورًا : الشكر: الاعتراف بالنعمة وفعل ما يجب من الطاعات وترك المعصية، وشكورًا: كثير الشكر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4830', false),
(20099, 2, 201, 99, 'hadith', 'عن عائشة رضي الله عنها أنها قالت: « كان رسول الله صلى الله عليه وسلم إذا دخل العشر أحيا الليل، وأيقظ أهله، وجد وشد المئزر».', 'With the start of the last ten days of Ramadan, Messenger of Allah (ﷺ) would pray all the night, and would keep his family awake for the prayers. He tied his lower garment (i.e., avoided sleeping with his wives) and devoted himself entirely to prayer and supplication..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 99', 'Riyad as-Salihin 99', 'ریاض الصالحین 99', 'متفق عليه', 'كَانَ النبيُّ صلى الله عليه وسلم إذا دخل العشر الأواخر من رمضان أحيا الليل كلَّه بأنواع الطاعات، وأيقظ أهلَه للصلاة، واجتهد في العبادة زيادة على عادته، وتَفَرَّغ لها واعتزل نساءه.', 'الترغيب باغتنام الأوقات الفاضلة بالأعمال الصالحة.
قال النووي: ففي هذا الحديث: أنه يستحب أنْ يُزاد من العبادات في العشر الأواخر من رمضان، واستحباب إحياء لياليه بالعبادات.
ينبغي على العبد أن يكون حريصًا على أهلِه بأمرِهم بالعبادة، ويَصْطَبِر عليهم.
فعل الخيرات يحتاج إلى حَزْم وصبر ومصابرة.
قال النووي: اختلف العلماء في معنى (شدّ المِئزر) فقيل: هو الاجتهاد في العبادات زيادة على عادته صلى الله عليه وسلم في غيره، ومعناه: التشمير في العبادات، يقال: شَدَدْتُ لهذا الأمر مِئزري، أي: تَشَمَّرتُ له وتَفَرّغت، وقيل: هو كناية عن اعتزال النساء للاشتغال بالعبادات.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4944', false),
(20100, 2, 201, 100, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: « المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف وفي كل خير. احرص على ما ينفعك، واستعن بالله ولا تعجز. وإن أصابك شيء فلا تقل: لو أني فعلت كان كذا وكذا، ولكن قل: قدر الله، وما شاء فعل؛ فإن لو تفتح عمل الشيطان».', 'Messenger of Allah (ﷺ) said, "A strong believer is better and dearer to Allah than a weak one, and both are good. Adhere to that which is beneficial for you. Keep asking Allah for help and do not refrain from it. If you are afflicted in any way, do not say: ''If I had taken this or that step, it would have resulted into such and such,'' but say only: ''Allah so determined and did as He willed.'' The word ''if'' opens the gates of satanic thoughts"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 100', 'Riyad as-Salihin 100', 'ریاض الصالحین 100', 'رواه مسلم', 'يُبَيِّنُ النبيُّ صلى الله عليه وسلم أنَّ المؤمنَ خيرٌ كلُّه، ولكن المؤمن القوي في إيمانِهِ وعزيمتِهِ ومالِهِ وغيرِها مِن أوجه القوة خيرٌ وأحبُّ إلى الله عز وجل من المؤمن الضعيف. 
ثم أوصى النبيُّ صلى الله عليه وسلم المؤمنَ بالأخذِ بالأسبابِ فيما ينفعه من أمور الدنيا والآخرة، مع الاعتماد على الله سبحانه وتعالى، والاستعانة به، والتوكل عليه. 
ثم نَهى صلى الله عليه وسلم عن العَجْزِ والكَسَلِ والتَّثَاقُلِ عن فِعْلِ ما ينفع في الدارين. 
فإذا اجتهد المؤمن في العمل، وأخذ بالأسباب، مستعينًا بالله، وطلب الخير من الله، فلا عليه بعدها إلا أنْ يُفَوِّضَ أمرَه كلَّه لله، وليعلم أنَّ اختيار الله عز وجل هو الخير، 
فإذا أصابته بعد ذلك مصيبة، فلا يقل: 
"لو أني فعلتُ كان كذا وكذا"؛ 
"فإن (لو) تفتح عمل الشيطان" في الاعتراض على القدر، والتَّحَسُّرِ على ما فات، ولكن يقول مستسلمًا وراضيًا: "قَدر الله، وما شاء فعل"،
فما وقع إنما هو بمقتضى ما أراده الله، فإنه فعَّالٌ لما يريد، ولا رادّ لقضائه، ولا مُعَقِّب لحُكْمِهِ.', 'تَفاوُت الناس في الإيمان.
استحباب القوة في الأعمال؛ لأنه يحصل بها من الفائدةِ ما لا يحصل بالضعف.
الإنسانُ ينبغي أنْ يحرصَ على ما ينفعُه، ويترك ما لا ينفعه.
يجب على المؤمن أنْ يَطلُبَ معونةَ الله له في كل أموره، ولا يعتمد على نفسه.
إثبات القضاء والقدر، وأنه لا ينافي بَذْلَ الأسباب والسعي في طلب الخيرات.
النهي عن قول «لو» على وجه التَّسَخُّطِ عند نزول المصائب، وتحريم الاعتراض على القضاء والقدر لله تعالى.', 'قَدّر الله: قدر: بتشديد الدال وفتح القاف، أي قدَّر الله هذا الشيء وقضاه، ورويت بفتح الدال مخففة، والمعنى هذا الحاصل قَدَر الله وقضائه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5493', false),
(20101, 2, 201, 101, 'hadith', 'عنه أن رسول الله صلى الله عليه وسلم قال: « حجبت النار بالشهوات، وحجبت الجنة بالمكاره».', 'Messenger of Allah (ﷺ) said. "The (Hell) Fire is surrounded with all kinds of desires and passions, while Jannah is surrounded with adversities.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 101', 'Riyad as-Salihin 101', 'ریاض الصالحین 101', 'متفق عليه', 'يُبيِّنُ النبيُّ صلى الله عليه وسلم أنَّ النارَ مَحفوفةٌ مُحاطةٌ بالأمور التي تَشتَهيها النفس مِن فِعْل المحرّمات أو التقصير في الواجبات، فمن أَتْبعَ نفسَه هواها في ذلك استحقَّ النار.

 
وأنَّ الجنةَ محفوفةٌ محاطةٌ بالأمور التي تَكرهها النفس؛ كالمُواظَبةِ على المأمورات وترك المحرمات والصبر على ذلك، فإذا صبر وجاهد نفسه على فعل الطاعة وترك المعصية؛ دخل الجنة.', 'من أسباب الوقوع في الشهوات تزيينُ الشيطانِ المنكرَ والقبيحَ، حتى تراه النفس حسنًا فتَميلُ إليه.
الأمر بالابتعاد عن الشهوات المحرمة؛ لأنها الطريق إلى النار، والصبر على المكاره؛ لأنها الطريق إلى الجنة.
فضل مجاهدة النفس والاجتهاد في العبادة والصبر على المكاره والمشاق التي تحيط بالطاعات.', 'حُجبت: حُفت وأُحيطت.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3702', false),
(20102, 2, 201, 102, 'hadith', 'عن أبي عبد الله حذيفة بن اليمان، رضي الله عنهما، قال: صليت مع النبي صلى الله عليه وسلم ذات ليلة، فافتتح البقرة، فقلت يركع عند المائة، ثم مضى؛ فقلت يصلي بها في ركعة، فمضى؛ فقلت يركع بها، ثم افتتح النساء؛ فقرأها، ثم افتتح آل عمران فقرأها، يقرأ مترسلاً إذا مر بآية فيها تسبيح سبح، وإذا مر بسؤال سأل، وإذا مر بتعوذ تعوذ، ثم ركع فجعل يقول: " سبحان ربي العظيم" فكان ركوعه نحواً من قيامه ثم قال: " سمع الله لمن حمده، ربنا لك الحمد" ثم قام قياماً طويلاً قريباً مما ركع، ثم سجد فقال: " سبحان ربي الأعلى" فكان سجوده قريباً من قيامه" ((رواه مسلم).', 'I offered Salat (Tahajjud - optional night prayer) with the Prophet (ﷺ) one night, and he started reciting (Surat) Al-Baqarah. I thought that he would bow at the end of one hundred Verses, but he continued reciting; I, then, thought that he would perhaps recite the whole (Surah) in a Rak''ah, but he proceeded on, and I thought he would perhaps bow on completing (this Surah); he then started (reciting Surat) An-Nisa''; he then started (Surat) Al-''Imran and his recitation was unhurried. And when he recited the Verses which referred to the Glory of Allah, he glorified Him (by saying Subhan Allah - My Rubb, the Supreme is far removed from every imperfection), the Great, and when he recited the Verses that mention supplication, he supplicated, and when he recited the Verses that mention seeking Refuge of the Rubb, he sought (His) Refuge. Then he bowed and said: "My Rubb, the Supreme is far removed from every imperfection (Subhana Rabbiyal-Azim);" his bowing lasted about the same length of time as his standing (and then on returning to the standing posture after Ruku'') he said: "Allah listened to him who praised Him (Sami'' Allahu liman hamidah, Rabbana wa lakal hamd)." Then he stood about the same length of time as he had spent in bowing. He then prostrated himself and said: "My Rubb, the Supreme is far removed from every imperfection (Subhana Rabbiyal-A''la)," and his prostration lasted nearly the same length of time as his standing..', 'أبي عبد الله حذيفة بن اليمان رضي الله عنهما', 'Hudhaifah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 102', 'Riyad as-Salihin 102', 'ریاض الصالحین 102', null, 'قام حذيفة مع النبي صلى الله عليه وسلم في قيام الليل فأطال الصلاة، قرأ في ركعة واحدة البقرة ثم النساء ثم آل عمران، وكان إذا مر بآية سؤال سأل وإذا مر بآية تسبيح سبح وإذا مر بآية تعوذ تعوذ، في أثناء قراءته، وكانت صلاته متناسقة في الطول، الركوع قريبا من القيام، والسجود قريبا من الركوع.', 'جواز صلاة الليل في جماعة، لا على وجه المداومة.
يستحب تطويل القيام في صلاة الليل.
استحباب تطويل الركوع والاعتدال والسجود وجعله نحوا من القيام.
جواز القراءة في صلاة الليل على غير ترتيب سور المصحف.
استحباب تكرار التسبيح في الركوع والسجود ولا حصر له في صلاة الليل.
قراءة القرآن تكون بتدبر لآياته وفهم لمعانيه.
يستحب تسبيح الله -تعالى- إذا مر بآية فيها تسبيح.
يستحب أن يكون القيام والركوع والاعتدال والسجود قريبا من السواء.
جواز إطلاق البقرة وآل عمران دون إضافة سورة كذا.
اجتهاد النبي -صلى الله عليه وسلم- في العبادة، ومجاهدته لنفسه في طاعة الله.
فيه فضيلة حذيفة بن اليمان -رضي الله عنهما- حيث قام مع رسول الله -صلى الله عليه وسلم-.', 'صليت مع النبي -صلى الله عليه وسلم- : أي: صلاة التهجد.
مترسلًا : متأنيًا غير مستعجل.
سبحَّ الله : قال: سبحان الله، أي نزهه وقدسه.
تعوذ : التجأ إلى ملجأ ولاذ بملاذ.
نحوا : مثلاً.
الصلاة : التعبد لله تعالى بأقوال وأفعال معلومة، مفتتحة بالتكبير، مختتمة بالتسليم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3727', false),
(20103, 2, 201, 103, 'hadith', 'عن ابن مسعود رضي الله عنه قال: صليت مع النبي صلى الله عليه وسلم ليلة، فأطال القيام حتى هممت بأمر سوء! قيل: وما هممت به؟ قال: هممت أن أجلس وأدعه.', 'One night I joined the Prophet (ﷺ) in his (optional) Salat. He prolonged the standing so much that I thought of doing something evil. He was asked: "What did you intend to do?" He replied: "To sit down and leave him"..', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 103', 'Riyad as-Salihin 103', 'ریاض الصالحین 103', 'متفق عليه', 'صلى ابن مسعود رضي الله عنه مع النبي صلى الله عليه وسلم ذات ليلة، فقام النبي صلى الله عليه وسلم ، قياما طويلا، وهذا هو دأبه -صلى الله عليه سلم- فشق عليه رضي الله عنه طول القيام، حتى هَمَّ بأمر ليس يسر المرء فعله، فسئل رضي الله عنه : ما هَمَمْت به؟ قال: هَمَمْتُ أن أجلس وأدعه قائما؛ مما لحقه من المشقة.', 'استحباب تطويل القراءة في صلاة الليل.
اختيار النبي -صلى الله عليه وسلم- تطويل صلاة الليل.
مخالفة الإمام في أفعاله معدودة في العمل السيء.
استحسان السؤال في حال لم يتضح الكلام.
اجتهاد النبي -صلى الله عليه وسلم- في العبادة، ومجاهدته نفسه في طاعة الله.
لا أحد يطيق ما كان -عليه الصلاة والسلام- في العبادة.
فضيلة ابن مسعود -رضي الله عنه-، وجلده في العبادة وحرصه على المحافظة على الاقتداء بالنبي -صلى الله عليه وسلم-، وإن خالف هوى النفس وما تحب.
الهم في الخروج من الصلاة لا يعد خروجا منها ما لم يقترن بنية وجزم.
تأدب ابن مسعود -رضي الله عنه- مع النبي -صلى الله عليه وسلم-.
حسن معاملة النبي -صلى الله عليه وسلم- لأصحابه.', 'صليت : أي: صلاة التهجد.
هَمَمْتُ : الهم: العزم على الشيء.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4226', false),
(20104, 2, 201, 104, 'hadith', 'العاشر عن أنس رضي الله عنه عن رسول الله صلى الله عليه وسلم قال: « يتبع الميت ثلاثة: أهله وماله وعمله؛ فيرجع اثنان ويبقى واحد: يرجع أهله وماله، ويبقى عمله».', 'Messenger of Allah (ﷺ) said, "Three follow a dead body: members of his family, his possessions and his deeds. Two of them return and one remains with him. His family and his possessions return; his deeds remain with him"..', null, 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 104', 'Riyad as-Salihin 104', 'ریاض الصالحین 104', 'متفق عليه', 'معنى الحديث: إذا مات الإنسان تبعه المشيعون له؛ فيتبعه أهله يشيعونه إلى قبره، ويتبعه ماله: أي عبيده وخدمه المماليك له، ويتبعه عمله معه، فيرجع اثنان، ويبقى معه عمله، فإن كان خيرًا فخير وإن كان شرًّا فشر.', 'الحث على فعل ما يبقى مع الإنسان، وهو العمل الصالح ليكون أنيسه في قبره، إذا رجع أهله وماله.', 'يَتْبَعُ الميت : أي: يلحقه إلى قبره.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4240', false),
(20105, 2, 201, 105, 'hadith', 'الحادي عشر: عن ابن مسعود رضي الله عنه قال: قال النبي صلى الله عليه وسلم: « الجنة أقرب إلى أحدكم من شراك نعله، والنار مثل ذلك».', 'The Prophet (ﷺ) said, "Jannah is nearer to anyone of you than your shoe-lace, and so is the (Hell) Fire"..', null, 'Ibn Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 105', 'Riyad as-Salihin 105', 'ریاض الصالحین 105', 'رواه البخاري', 'أَخبَرَ النبيُّ صلى الله عليه وسلم أنَّ الجنة والنار قريبتان من الإنسان كقُربِ سَيْرِ الحِذاء الذي يكون على ظَهر القَدَم؛ لأنه قد يفعل طاعةً من رضوان الله عز وجل يدخل بها الجنة، أو معصيةً تكون سببًا لدخول النار.', 'الترغيب في الخير وإن قلَّ، والترهيب عن الشر وإن قلَّ.
لا بد للمسلم في حياته من الجمع بين الرجاء والخوف، وسؤال الله سبحانه دومًا الثبات على الحق حتى يَسْلَمَ ولا يَغْتَرَّ بحالِه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3581', false),
(20106, 2, 201, 106, 'hadith', 'الثاني عشر: عن أبي فراس ربيعة بن كعب الأسلمى خادم رسول الله صلى الله عليه وسلم، ومن أهل الصفة رضي الله عنه قال: " كنت أبيت مع رسول الله صلى الله عليه وسلم، فآتيه بوضوئه، وحاجته فقال: "سلني" فقلت: أسألك مرافقتك في الجنة. فقال: { أوغير ذلك؟" قلت: هو ذاك قال: " فأعني على نفسك بكثرة السجود".', 'I used to spend my night in the company of Messenger of Allah (ﷺ) and used to put up water for his ablutions. One day he said to me, "Ask something of me." I said: "I request for your companionship in Jannah". He inquired, "Is there anything else?" I said, "That is all." He said, "Then help me in your request by multiplying your prostrations"..', null, 'Rabi''ah bin Ka''b Al-Aslami (May Allah be pleased with him (a servant of the Messenger of Allah and also one of the people of As-Suffah) said:', 'صحيح', 'رياض الصالحين 106', 'Riyad as-Salihin 106', 'ریاض الصالحین 106', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20107, 2, 201, 107, 'hadith', 'الثالث عشر: عن أبي عبد الله- ويقال: أبو عبد الرحمن- ثوبان مولى رسول الله صلى الله عليه وسلم قال: سمعت رسول الله صلى الله عليه وسلم يقول: « عليك بكثرة السجود، فإنك لن تسجد لله سجدة إلا رفعك الله بها درجة، وحط عنك بها خطيئة».', 'I heard Messenger of Allah (ﷺ) saying, "Perform Salah more often. For every prostration that you perform before Allah will raise your position one degree and will remit one of your sins"..', null, 'Thauban (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 107', 'Riyad as-Salihin 107', 'ریاض الصالحین 107', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20108, 2, 201, 108, 'hadith', 'الرابع عشر: عن أبي صفوان عبد الله بن بسر الأسلمي، رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم: « خير الناس من طال عمره وحسن عمله».', 'Messenger of Allah (ﷺ) said, "The best of people is one whose life is long and his conduct is good"..', null, '''Abdullah bin Busr Al-Aslami (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 108', 'Riyad as-Salihin 108', 'ریاض الصالحین 108', 'رواه الترمذي، وقال: حديث حسن. "بسر": بضم الياء وبالسين المهملة', 'معنى هذا الحديث : أن الإنسان كلما طال عمره في طاعة الله ازداد قربا من الله؛ لأن كل عمل يعمله فيما زاد فيه عمره، فإنه يقربه إلى ربه -عز وجل - فخير الناس من وفق لهذين الأمرين: طول العمر وحسن العمل.
فطول العمر ليس خيرًا للإنسان إلا إذا حسن عمله في طاعة الله؛ لأنه أحيانًا يكون طول العمر شرًا للإنسان وضررًا عليه، كما في الحديث الآخر، أي الناس خير، قال: « من طال عمره، وحسن عمله »، قال: فأي الناس شر؟ قال: « من طال عمره وساء عمله »، رواه أبو داود والترمذي.
وقال الله -تبارك وتعالى-: (ولا يحسبن الذين كفروا أنما نملي لهم خير لأنفسهم إنما نملي لهم ليزدادوا إثمًا ولهم عذاب مهين)، فهؤلاء الكفار يملى الله لهم، أي يمدهم بالرزق والعافية وطول العمر والبنين والزوجات، لا لخير لهم ولكنه شر لهم، والعياذ بالله لأنهم سوف يزدادون بذلك إثمًا.
قال الطيبي -رحمه الله -: إن الأوقات والساعات كرأس المال للتاجر، فينبغي أن يتجر فيما يربح فيه، وكلما كان رأس المال كثيرا كان الربح أكثر، فمن مضى لطيبه فاز وأفلح، ومن أضاع رأس ماله لم يربح وخسر خسرانا مبينا".', 'فضل طول العمر إذا اقترن بحسن العمل، فإنه يتزود من الطاعات التي تقربه إلى الله، وشر الناس من طال عمره وساء عمله.', 'حسن عمله : أتى به مستوفيا للشروط والأركان والآداب قاصدا به وجه الله تعالى.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3710', false),
(20109, 2, 201, 109, 'hadith', 'الخامس عشر: عن أنس رضي الله عنه، قال: غاب عمي أنس ابن النضر رضي الله عنه، عن قتال بدر، فقال: يارسول الله غبت عن أول قتال قاتلت المشركين، لئن الله أشهدني قتال المشركين ليرين الله ما أصنع. فلما كان يوم أحد انكشف المسلمون، فقال اللهم أعتذر إليك مما صنع هؤلاء - يعني أصحابه- وأبرأ إليك مما صنع هؤلاء- يعني المشركين- ثم تقدم فاستقبله سعد بن معاذ، فقال: ياسعد بن معاذ الجنة ورب الكعبة، إني أجد ريحها من دون أحد. قال سعد: فما استطعت يا رسول الله ما صنع! قال أنس: فوجدنا به بضعاً وثمانين ضربة بالسيف، أو طعنة برمح ، أو رمية بسهم، ووجدناه قد قتل ومثل به المشركون فما عرفه أحد إلا أخته ببنانه. قال أنس: كنا نرى أو نظن أن هذه الآيه نزلت فيه وفي أشباهه: {من المؤمنين رجال صدقوا ما عهدوا الله عليه}.', 'My uncle Anas bin An-Nadr (May Allah be pleased with him) was absent from the battle of Badr and he said: "O Messenger of Allah! I was absent from the first battle you fought against the pagans, and if Allah let me participate in a battle against the pagans, Allah will see what I do." So he encountered the day of Uhud Battle. The Muslims left the positions (the Prophet (ﷺ) told them to keep) and were defeated, he said: "O Allah! excuse these people (i.e., the Muslims) for what they have done, and I am clear from what the pagans have done". Then he went forward with his sword and met Sa''d bin Mu''adh (fleeing) and said to him: "By the Rubb of the Ka''bah! I can smell the fragrance of Jannah from a place closer than Uhud Mount". Sa''d said: "O Messenger of Allah, what he did was beyond my power". Anas said: "We saw over eighty wounds on his body caused by stabbing, striking and shooting of arrows and spears. We found that he was killed, and mutilated by the polytheists. Nobody was able to recognize him except his sister who recognized him by the tips of his fingers." Anas (May Allah be pleased with him) said: "We believe that the Ayah ''Among the believers are men who have been true to their covenant with Allah .', null, 'Anas (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 109', 'Riyad as-Salihin 109', 'ریاض الصالحین 109', 'الأحزاب: 23)) إلى آخرها. ((متفق عليه', 'يحكي أنس بن مالك أن أنس بن النَّضْرِ -عمه- لم يكن مع الرسول صلى الله عليه وسلم في بدر، وذلك لأن غزوة بدر خرج إليها النبي صلى الله عليه وسلم وهو لا يريد القتال، وإنما يريد عِير قريش وليس معه إلا ثلاثمائة وبضعة عشر رجلًا، معهم سبعون بعيرا وفرسان يتعاقبون عليها، قال أنس بن النضر للنبي -عليه الصلاة والسلام- يبين له أنه لم يكن معه في أول قتال قاتل فيه المشركين، وقال: "لئن أدركت قتالًا ليُرينَّ الله ما أصنع".
فلما كانت غزوة أحد، وهي بعد غزوة بدر بسنة وشهر، خرج الناس وقاتلوا مع النبي صلى الله عليه وسلم ، وصارت الدائرة في أول النهار للمسلمين، ولكن ترك الرماة منازلهم التي أنزلهم النبي صلى الله عليه وسلم فيها حال لقاء العدو ونهاهم عن التحول عنها ، فلما انكسر المشركون وانهزموا نزل بعض أولئك القوم عن تلك المنازل ، فهجم فرسان المشركين على المسلمين من تلك الناحية ، واختلطوا بهم، انكشف المسلمون وفرَّ من فرَّ منهم، إلا أن أنسا رضي الله عنه تقدم إلى جهة الكفار وقال: (اللهم إني أعتذر إليك مما صنع هؤلاء) يعني أصحابه الذين فروا ، (وأبرأ إليك مما صنع هؤلاء)، يعني المشركين من قتال النبي ومن معه من المؤمنين. 
وعندما تقدم رضي الله عنه استقبله سعد بن معاذ، فسأله إلى أين؟
قال: يا سعد، إني لأجد ريح الجنة دون أحد، وهذا وجدان حقيقي، ليس تخيلا أو توهما، ولكن من كرامة الله لهذا الرجل شم رائحة الجنة قبل أن يستشهد رضي الله عنه من أجل أن يقدم ولا يحجم، فتقدم فقاتل ، حتى قتل رضي الله عنه.
قال سعد رضي الله عنه : فما استطعت يا رسول الله ما صنع! أي: أنه رضي الله عنه بذل مجهودا لا أقدر على مثله. 
ووجد فيه بضع وثمانون، ما بين ضربة بسيف، أو برمح، أو بسهم، حتى إنه قد تمزق جلده، فلم يعرفه أحد إلا أخته، لم تعرفه إلا ببنانه أي إصبعه ـ رضي الله عنه. 
فكان المسلمون يرون أن الله قد أنزل فيه وفي أشباهه هذه الآية: (من المؤمنين رجال صدقوا ما عاهدوا الله عليه فمنهم من قضى نحبه ومنهم من ينتظر وما بدلوا تبديلا) (الأحزاب: 23)، ولا شك أن هذا وأمثاله رضي الله عنهم يدخلون دخولا أوليا في هذه الآية، فإنهم صدقوا ما عاهدوا الله عليه، حيث قال أنس رضي الله عنه : والله ليُرينَّ الله ما أصنع، ففعل، فصنع صنعا لا يصنعه أحد إلا من مَنَّ الله عليه بمثله حتى استشهد.', 'جواز الوعد الحسن، وإلزام النفس بما هو خير.
صدق أصحاب رسول الله -صلى الله عليه وسلم- في طلب الشهادة وتشوقهم إلى الجنة.
استحباب بذل النفس في الجهاد في سبيل الله وإشهاد الله على ذلك.
شدة يقين أنس بن النضر وكمال إيمانه.
المجاهد الصادق المقبل على الله الحريص على بلوغ منازل الشهداء، قد يشم رائحة الجنة؛ فيكون أدعى لمواصلة الجهاد، وهذا تثبيت من الله لعباده المخلصين.
جواز الحكم بالقرائن، وهذا تجده في تعرف أخت أنس بن النضر عليه ببنانه.
فضيلة أنس بن النضر -رضي الله عنه-.
جواز الأخذ بالشدة في الجهاد.', 'قتال بدر : أي: غزوة بدر
ليرين الله : أي: ليظهرن عملي لله فيراه كما أنه علمه من قبل، ويظهره للناس أيضًا، وهذا من باب الفأل وتمني الخير.
انكشف المسلمون : تركوا أماكنهم وانهزموا.
يوم أحد : غزوة أحد
أحد : جيل قريب من المدينة.
ريحها : رائحتها
أبرأ : أتخلى وأتخلص
بضعا : ما بين الثلاثة والعشرة.
مثل به : نكل به: بجدع أنفه أو قطع أذنه ، أو غيرهما من الأعضاء.
بنانه : أطراف الأصابع.
أشباهه : الشبه: هو المثل.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3855', false),
(20110, 2, 201, 110, 'hadith', 'السادس عشر: عن أبي مسعود عقبة بن عمرو الأنصاري البدري رضي الله عنه قال: لما نزلت آيه الصدقة كنا نحامل على ظهورنا. فجاء رجل فتصدق بشيء كثير فقالوا: مراءٍ، وجاء رجل آخر فتصدق بصاع فقالوا: إن الله لغني عن صاع هذا! فنزلت { الذين يلمزون المطوعين من المؤمنين في الصدقات والذين لا يجدون إلا جهدهم} الآية.', 'When the Ayah enjoining Sadaqah (charity) was revealed,* we used to carry loads on our backs to earn something that we could give away in charity. One person presented a considerable amount for charity and the hypocrites said: "He has done it to show off." Another one gave away a few Sa'' of dates and they said: "Allah does not stand in need of this person''s dates". Thereupon, it was revealed:"Those who defame such of the believers who give charity (in Allah''s Cause) voluntarily, and such who could not find to give charity (in Allah''s Cause) except what is available to them..." (9:79).* This is the version of Al-Bukhari.', null, 'Abu Mas''ud ''Uqbah bin ''Amr Al-Ansari (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 110', 'Riyad as-Salihin 110', 'ریاض الصالحین 110', 'التوبة:79)). ((متفق عليه', 'قال أبو مسعود رضي الله عنه لما نزلت آية الصدقة: يعني الآية التي فيها الحث على الصدقة قال الحافظ: كأنه يشير إلى قوله تعالى : (خُذْ مِنْ أَمْوَالِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا) جعل الصحابة رضي الله عنهم يبادرون ويسارعون في بذل الصدقات إلى رسول الله صلى الله عليه وسلم ، كل واحد يحمل بقدرته من الصدقة إلى رسول الله صلى الله عليه وسلم ، فجاء رجل بصدقة كثيرة، وجاء رجل بصدقة قليلة، فكان المنافقون إذا جاء الرجل بالصدقة الكثيرة؛ قالوا: هذا مُراءٍ، ما قصد به وجه الله، وإذا جاء الرجل بالصدقة القليلة؛ قالوا: إن الله غني عنه، وجاء رجل بصاع، قالوا: إن الله غني عن صاعك هذا.
فأنزل الله عز وجل : (الذين يلمزون المطوعين من المؤمنين في الصدقات والذين لا يجدون إلا جهدهم) أي: يعيبون المتطوعين المتصدقين، والذين لا يجدون إلا جهدهم، فهم يلمزون هؤلاء وهؤلاء، (فيسخرون منهم سخر الله منهم ولهم عذاب أليم)، فهم سخروا بالمؤمنين؛ فسخر الله منهم، والعياذ بالله.', 'مسارعة الصحابة إلى فعل الطاعات، ومجاهدة أنفسهم على ذلك مع قلة ما في أيديهم.
على المسلم أن يعمل ويخلص عمله لله، ولا يلتفت بعد ذلك إلى المُثَبِّطِين.
الحث على الصدقة ولو بالشيء اليسير.
عدم احتقار المعروف وإن كان قليلًا.
على الإنسان أن يطيع ربه قدر استطاعته، ويتصدق بما يقدر عليه وإن قل، وعليه ألا يلتفت إلى الآخرين من المنافقين وأصحاب الدعايات السيئة.
فيه ضيق أحوال بعض الصحابة -رضي الله عنهم-.
مُدافعة الله -عزو جل- للمؤمنين.
شِدَّة عداوة المنافقين للمؤمنين.', 'نُحَامِلُ : أي: يحمل أحدنا على ظهره بالأجرة ويتصدق بها.
مُراءٍ : من الرياء، وهو أن يظهر الإنسان في نفسه خلاف ما هو عليه؛ ليراه الناس من أجل السمعة والشهرة.
صَاع : الصاع: مكيال يبلغ وزنه أربعة أمداد، والمد: ملء كفَّي الرجُل المتوسط، ويقدر بثلاثة كيلو تقريبًا.
يَلْمِزُونَ : يعيبون.
الْمُطَّوِّعِينَ : الْمُتَنَفِّلِينَ.
جُهْدَهُمْ : طاقتهم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4245', false),
(20111, 2, 201, 111, 'hadith', 'السابع عشر: عن سعيد بن عبد العزيز، عن ربيعة بن يزيد، عن أبي إدريس الخولاني، عن أبي ذر جندب بن جنادة، رضي الله عنه، عن النبي صلى الله عليه وسلم فيما يروى عن الله تبارك وتعالى أنه قال: « ياعبادي إني حرمت الظلم على نفسي وجعلته بينكم محرماً فلا تظالموا، يا عبادي كلكم ضال إلا من هديته؛ فاستهدوني أهدكم، يا عبادي كلكم جائع إلا من أطعمته؛ فاستطعموني أطعمكم،يا عبادي كلكم عارٍ إلا من كسوته، فاستكسوني أكسكم، يا عبادي إنكم تخطئون بالليل والنهار وأنا أغفر الذنوب جميعا، فاستغفروني أغفرلكم، ياعبادي إنكم لن تبلغوا ضري فتضروني، ولن تبلغوا نفعي فتنفعوني، يَا عِبَادي ، لَوْ أنَّ أوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجنَّكُمْ كَانُوا عَلَى أتْقَى قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ مَا زَادَ ذلِكَ في مُلكي شيئاً . يَا عِبَادي ، لَوْ أنَّ أوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجنَّكُمْ كَانُوا عَلَى أفْجَرِ قَلْبِ رَجُلٍ وَاحِدٍ مَا نَقَصَ ذلِكَ من مُلكي شيئاً، يا عبادي لو أن أولكم وآخركم، وإنسكم وجنكم قاموا في صعيد واحد، فسألوني فأعطيت كل إنسان مسألته، ما نقص ذلك مما عندي إلا كما ينقص المخيط إذا أدخل البحر، يا عبادي إنما هي أعمالكم أحصيها لكم، ثم أوفيكم إياها، فمن وجد خيراً فليحمد الله، ومن وجد غير ذلك فلا يلومن إلا نفسه». قال سعيد: كان أبو إدريس إذا حدث بهذا الحديث جثا على ركبتيه. رواه مسلم. (20).', 'The Prophet (ﷺ) said, "Allah, the Exalted, and Glorious, said; ''O My slaves, I have prohibited Myself injustice; and have made oppression unlawful for you, so do not oppress one another. O My slaves, all of you are liable to err except the one whom I guide on the Right Path, so seek guidance from Me so that I will guide you to the Right Path. O My slaves, all of you are hungry except the one whom I feed, so ask food from Me, I will feed you. O My slaves, all of you are naked except those whom I clothe, so ask clothing of Me and I shall clothe you. O My slaves, you commit sins night and day and I forgive all sins, so seek My forgiveness and I shall forgive you. O My slaves, you can neither do Me any harm nor can you do Me any good. O My slaves, were the first of you and the last of you, the human of you and jinn of you to be as pious as the most pious heart of any man of you, that would not increase My domain a thing. O My slaves, were the first of you, and the last of you, the human of you and the jinn of you to be as wicked as the most wicked heart of any man of you, that would not decrease My domain in a thing. O My slaves, were the first of you and the last of you, the human of you and the jinn of you to stand in one place and make a request of Me, and were I to give everyone what he requested, that would not decrease what I have, any more than a needle decrease the sea if put into it. O My slaves, it is but your deeds that I reckon for you and then recompense you for, so let him who finds good (i.e., in the Hereafter) praise Allah and let him who finds other than that blame no one but himself."''..', null, 'Abu Dharr (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 111', 'Riyad as-Salihin 111', 'ریاض الصالحین 111', null, 'يُبيِّنُ النبيُّ صلى الله عليه وسلم أنَّ الله سبحانه وتعالى قال بأنه حَرَّم الظلم على نفسه، وجعل الظلم محرّمًا بين خلقِه فلا يَظلم أحد أحدًا، 
وأن الخلقَ كلَّهم ضالون عن طريق الحق إلا بهداية الله وتوفيقه، ومن سَألَها اللهَ وفقَه وهداه، 
وأن الخلق فقراء إلى الله محتاجون إليه في جميع حوائجهم، ومن سأل الله قضى حاجته وكفاه، 
وأنهم يذنبون بالليل والنهار، والله تعالى يستر ويتجاوز عند سؤال العبد المغفرة، 
وأنهم لا يستطيعون أن يضروا الله أو ينفعوه بشيء، 
وأنهم لو كانوا على أتقى قلب رجل واحد ما زادت تقواهم في ملك الله، 
ولو كانوا على أفجر قلب رجل واحد ما نقص فجورهم من ملكه شيئًا؛ لأنهم ضعفاء فقراء إلى الله، محتاجون إليه في كل حال وزمان ومكان، وهو الغني سبحانه، 
وأنهم لو قاموا في مقام واحد إنسُهم وجنُّهم، أولُهم وآخِرُهم يسألون اللهَ فأعطى كلَّ واحد منهم ما سأل، ما نقص ذلك مما عند الله شيئًا، كالإبرة لو أُدْخِلت البحرَ ثم أُخْرِجت لم يَنقص البحر بذلك شيء، وهذا لكمال غناه سبحانه.

وأن الله سبحانه يحفظ أعمالَ العبادِ ويُحصيها عليهم، ثم يُوفِّيهم إياها يوم القيامة، فمن وجد جزاء عمله خيرًا فليحمد الله على توفيقه لطاعته، ومن وجد جزاء عمله شيئًا غير ذلك فلا يلومَنَّ إلا نفسَه الأمارةَ بالسوءِ التي قادتْه إلى الخُسران.', 'هذا الحديث مما يرويه النبي صلى الله عليه وسلم عن ربه، ويسمى بالحديث القدسي أو الإلهي، وهو الذي لفظه ومعناه من الله، غير أنه ليست فيه خصائص القرآن التي امتاز بها عما سواه ، من التعبد بتلاوته والطهارة له والتحدي والإعجاز وغير ذلك.
ما يحصل للعباد من علم أو اهتداء، فبهداية الله وتعليمه.
ما أصاب العبد من خير فمن فضل الله تعالى، وما أصابه من شر فمن نفسه وهواه.
من أحسن فبتوفيق الله، وجزاؤه فضل من الله فله الحمد، ومن أساء فلا يلومن إلا نفسه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4810', false),
(20112, 2, 201, 112, 'hadith', 'وأما الأحاديث فالأول: عن أبي هريرة رضي الله عنه، عن النبي صلى الله عليه وسلم قال: « أعذر الله إلى امرئ أخر أجله حتى بلغ ستين سنة».', 'The Prophet (ﷺ) said, "Allah excuses and grants forgiveness to a person until he attains the age of sixty years"..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 112', 'Riyad as-Salihin 112', 'ریاض الصالحین 112', 'رواه البخاري', 'قال النبي صلى الله عليه وسلم: إذا أطال الله حياة شخص حتى بلغ عمره ستين سنة، لم يَبق له موضعٌ للاعتذار، حيث أمهله إلى طول هذه المدة ولم يعتذر لالتوبة والإنابة، فقد بلغ أقصى الغاية في الإمهال، وإنما كانت الستون حدًّا لهذا؛ لأنها قريبة من المَنَايا، وهي سن الإنابة والخشوع وترقب الأجل، فهذا إعذار بعد إعذار؛ لطفًا من الله تعالى بعباده حتى نقلهم من حالة الجهل إلى حالة العلم، ثم أعذر إليهم فلم يعاقبهم إلا بعد الحجج الواضحة، وإن كانوا فطروا على حب الدنيا وطول الأمل، لكنهم أُمِروا بمجاهدة النفس في ذلك ليمتثلوا ما أمروا به من الطاعة، وينزجروا عما نهوا عنه من المعصية، فحينئذ يظهر ضعف القوة بالنقص والانحطاط، فينبغي له الإقبال على الآخرة بالكلية لاستحالة أن يرجع إلى الحالة الأولى من النشاط والقوة.', 'يعذر الله تعالى من بلغ من العمر ستين سنة.

ينبغي لمن بلغ الستين سنة وما بعدها كثرة الإنابة والرجوع إلى الله تعالى والاستغفار لقرب المنية منه.', '-', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66223', false),
(20113, 2, 201, 113, 'hadith', 'عن ابن عباس، رضي الله عنهما، قال: كان عمر رضي الله عنه يدخلني مع أشياخ بدر، فكأن بعضهم وجد في نفسه فقال: لم يدخل هذا معنا ولنا أبناء مثله!؟ فقال عمر: إنه من حيث علمتم! فدعاني ذات يوم فأدخلني معهم، فما رأيت أنه دعانى يومئذ إلا ليريهم قال: ما تقولون في قول الله تعالى: {إذا جاء نصر الله والفتح؟).', '''Umar (May Allah be pleased with him) used to make me sit with the noble elderly men who had participated in the battle of Badr. Some of them disliked it and said to ''Umar: "Why do you bring in this boy to sit with us when we have sons like him?" ''Umar replied: "Because of the status he has, which you already know about (i.e., belongs to the source of knowledge and the house of the Prophet (ﷺ))." One day, ''Umar called me and seated me in the gathering of those people; and I think that he called me just to show them (of my religious knowledge). ''Umar then questioned them (in my presence). "How do you interpret the ayah of Allah: ''When there comes the Help of Allah (to you, O Muhammad (ﷺ) against your enemies) and the Conquest (of Makkah)."'' Someone said that when Allah''s Help and the Conquest (of Makkah) came to us, we were called upon to celebrate the Praise of Allah and ask for His forgiveness. Some others remained silent and did not utter a word. Thereupon ''Umar asked me: "Ibn ''Abbas! Do you say the same." I replied: "No". He said: "What do you say then?" I replied: "That is the sign of the Prophet''s death about which he had been informed. Allah, the Exalted, says:''When there comes the help of Allah (to you, O Muhammad (ﷺ) against your enemies) and the Conquest (of Makkah)''.So declare the remoteness of your Rubb from every imperfection, and ask for His forgiveness. Verily, He is the One Who accepts the repentance and Who forgives".On that ''Umar (May Allah be pleased with him) said: "I do not know anything about it other than what you have said".', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 113', 'Riyad as-Salihin 113', 'ریاض الصالحین 113', 'النصر:1)) فقال بعضهم: أمرنا نحمد الله ونستغفره إذا نصرنا وفتح علينا. وسكت بعضهم فلم يقل شيئاً. فقال لي: أكذلك تقول يا ابن عباس؟ فقلت: لا. قال فما تقول؟ قلت: هو أجل رسول الله صلى الله عليه وسلم، أعلمه له قال: {إذاجاء نصر الله والفتح} وذلك علامة أجلك {فسبح بحمد ربك واستغفره إنه كان تواباً} ((الفتح: 3)) فقال عمر رضي الله عنه: ما أعلم منها إلا ما تقول. ((رواه البخاري', 'كان من هدي عمر رضي الله عنه أنه يشاور الناس ذوي الرأي فيما يُشكِلُ عليه، وكان يُدخل مع أشياخ بدر وكبار الصحابة عبد الله بن عباس وكان صغير السن بالنسبة لهؤلاء، فغضبوا من ذلك، كيف يُدخل ابن عباس رضي الله عنهما ولا يُدخل أبناؤهم، فأراد عمرُ أن يريهم مكانة عبد الله بن عباس رضي الله عنهما من العلم والذكاء والفطنة، فجمعهم ودعاه، فعرض عليهم هذه السورة: {إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجاً فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا}، فانقسموا إلى قسمين لما سألهم عنها ما تقولون فيها؟ قسمٌ سكت، وقسمٌ قال: إن الله أمرنا إذا جاء النصر والفتح، أن نستغفر لذنوبنا، وأن نحمده ونسبح بحمده؛ ولكن عمر رضي الله عنه أراد أن يعرف ما مغزى هذه السورة، ولم يرد أن يعرف معناها من حيث الألفاظ والكلمات.
فسأل ابن عباس رضي الله عنهما قال: ما تقول في هذه السورة؟ قال: هو أجل رسول الله صلى الله عليه وسلم ، يعني علامة قرب أجله، أعطاه الله آية: {إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ} يعني فتح مكة، فإن ذلك علامة أجلك؛ {فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا} فقال: ما أعلم فيها إلا ما علمت. 
وظهر بذلك فضل عبد الله بن عباس رضي الله عنهما .', 'جواز تحدث المرء بنعمة الله عليه.
جواز إدخال الصغار على الكبار إذا كان في ذلك منفعة.
التنبيه على الاستغفار عند دنو الأجل؛ لأنه يكون في خواتم الأمور.
بشرى للنبي -صلى الله عليه وسلم- بفتح مكة.
يتقدم المرء على أقرانه بحسن فهمه وسعة علمه.
فضل عبد الله بن عباس -رضي الله عنهما-، وفهمه لكتاب الله -تعالى- حتى لُقِّبَ ترجمان القرآن.
فضل العلم والعلماء.
ينبغي على الحاكم والأمير مشاورة أهل العلم والفضل في مهمات الأمور.', 'أشياخ بدر : أشياخ: جمع شيخ، وهو من أدرك الشيخوخة وهي غالبا عند الخمسين، أو هو ذو المكانة من علم أو فضل أو رياسة، وأشياخ بدر: أي من شهد بدرا من المهاجرين والأنصار.
وجد : غضب.
من حيث علمتم : أي: من بيت النبوة ومنبع العلم.
ليريهم : أي: يعلمهم.
والفتح : أي: فتح مكة.
ورأيت : أبصرت.
علامة أجلك : أي: قرب انتهاء عمرك.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3377', false),
(20114, 2, 201, 114, 'hadith', 'عن عائشة رضي الله عنها قالت: ما صلى رسول الله صلى الله عليه وسلم صلاة بعد أن نزلت عليه { إذا جاء نصر الله والفتح} إلا يقول فيها: " سبحانك ربنا وبحمدك، اللهم اغفر لي" ((متفق عليه)). وفي رواية في الصحيحين" عنها: كان رسول الله صلى الله عليه وسلم يكثر أن يقول في ركوعه وسجوده: "سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي" يتأول القرآن. وفي رواية لمسلم: كان رسول الله صلى الله عليه وسلم يكثر أن يقول قبل أن يموت: "سبحانك اللهم وبحمدك، أستغفرك وأتوب إليك". قالت عائشة: قلت: يا رسول الله ما هذه الكلمات التي أراك أحدثتها تقولها؟ قال: "جعلت لي علامة في أمتي إذا رأيتها قلتها {إذا جاء نصر الله والفتح} إلى آخر السورة". وفي رواية له: كان رسول الله صلى الله عليه وسلم يكثر من قول: "سبحان الله وبحمده، أستغفر الله وأتوب إليه". قالت: قلت: يا رسول الله! أراك تكثر من قول: سبحان الله وبحمده، أستغفر الله وأتوب إليه؟ فقال: "أخبرني ربي أني سأرى علامة في أمتي فإذا رأيتها أكثرت من قول: سبحان الله وبحمده، أستغفر الله وأتوب إليه، فقد رأيتها: {إذا جاء نصر الله والفتح} فتح مكة، {ورأيت الناس يدخلون في دين الله أفواجاً، فسبح بحمد ربك واستغفره إنه كان تواباً}.', 'After the revelation of (the Surah) "When the Help of Allah comes (to you, O Muhammad (ﷺ) against your enemies) and the Conquest (of Makkah)" (110:1), Messenger of Allah (ﷺ) used to recite in every prayer: "Subhanaka Rabbana wa bihamdika, Allahum-maghfir li (Far removed You are from every imperfection, our Rubb, and all praise is for You, forgive me, O Allah)"..Another narration is: Messenger of Allah (ﷺ) recited frequently in bowing and prostration: "Subhanaka Rabbana wa bihamdika, Allahum-maghfir li. (Far removed You are from every imperfection, our Rubb, and all praise is for You, forgive me, O Allah)". He elucidated that it has been commanded in the Noble Qur''an to recite: "So glorify the Praises of your Rubb, and ask for His forgiveness. Verily, He is the One Who accepts the repentance and Who forgives". (V.110:1) And he (the Messenger of Allah) acted upon it.According to the narration in Muslim, Messenger of Allah (ﷺ) frequently recited these words just before he passed away: "Subhanaka Rabbana wa bihamdika. Astaghfiruka wa atubu ilaika." I (''Aishah (May Allah be pleased with her) asked him: "O Messenger of Allah! What are these new words which I hear from you repeatedly." He replied, "A sign has been appointed for me relating to my people that I should repeat these words at the sight of that sign". Then he recited Surat An-Nasr.Another narration in Muslim related from ''Aishah (May Allah be pleased with her) is: Messenger of Allah (ﷺ) often recited, "Glory be to Allah and praise be to Him; I seek forgiveness of Allah and turn to Him in repentance." I said to him: "O Messenger of Allah, I hear you recite frequently: ''O Allah, You are free from every imperfection our Rubb and all praise is for You; I seek forgiveness of Allah and turn to Him in repentance."'' He replied, "My Rubb has informed me that I would soon see a sign regarding my people, whenever I see it, I repeat this statement more often (of His Glorification and Praise and beg pardon of Him and turn to Him). Now I have witnessed the sign. The revelation of Surat An-Nasr and the victory is the conquest of Makkah.""When there comes the Help of Allah (to you, O Muhammad (ﷺ) against your enemies) and the Conquest (of Makkah). And you see that the people enter Allah''s religion (Islam) in crowds. So glorify the Praises of your Rubb, and ask His forgiveness. Verily, He is the One Who accepts the repentance and Who forgives." (110:1-3)', 'عائشة رضي الله عنها', ''' Aishah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 114', 'Riyad as-Salihin 114', 'ریاض الصالحین 114', null, 'قالت عائشة رضي الله عنها : ما صلى رسول الله صلى الله عليه وسلم صلاةً بعد أن نزلت سورة النصر إلا وقال في ركوعها وسجودها: سبحانك اللهم وبحمدك اللهم اغفر لي، يعمل بما أُمِرَ به في القرآن في قوله (فسبح بحمد ربك واستغفره).
وأخبرت رضي الله عنها أنها سألت النبي صلى الله عليه وسلم عن هذه الكلمات التي أصبح يقولها في الركوع والسجود فأخبرها أن الله تبارك وتعالى أخبره أنه سيرى علامة في أمته، فإذا رآها أكثر من قول: سبحان الله وبحمده أستغفر الله وأتوب إليه.
وهذه العلامة: (إذا جاء نصر الله والفتح –فتح مكة- ورأيت الناس يدخلون في دين الله أفواجاً فسبح بحمد ربك واستغفره إنه كان تواباً).', 'زيادة استغفار رسول الله -صلى الله عليه وسلم- وتضرعه وإقباله على الله -تعالى- قبل موته.
الشكر لله -تعالى- عند حصول النعم.
استحباب الاستغفار والدعوات اقتداء بالرسول -صلى الله عليه وسلم-.
وقوع ما بشر الله به رسوله لأن وعده -سبحانه- حق.', 'سبحانك : تنزيها ًلك عما لا يليق بك من كل نقص.
اللهم : يا الله.
يتأول القرآن : يعمل ما أُمرَ به في القرآن.
رأيتها : أبصرتُها أو عرفتُها.
واستغفره : أي: اطْلُبْ منه المغفرة، والمغفرة: هي التجاوز عن الذنب والستر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4826', false),
(20115, 2, 201, 115, 'hadith', 'الرابع؛: عن أنس رضي الله عنه قال: إن الله عز وجل تابع الوحي على رسول الله صلى الله عليه وسلم قبل وفاته، حتى توفي أكثر ما كان الوحي".', 'Allah the Rubb of honour and glory sent Revelation to His Messenger (ﷺ) more frequently before his death than at any other time..', null, 'Anas (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 115', 'Riyad as-Salihin 115', 'ریاض الصالحین 115', 'متفق عليه', 'أكثر الله عز وجل من إنزال الوحي على رسول الله صلى الله عليه وسلم قبل وفاته؛ حتى تكمل الشريعة؛ حتى توفي الرسول صلى الله عليه وسلم في وقت كثرة نزوله.', 'تكامل نزول الوحي قبل وفاته -صلى الله عليه وسلم-.
تتابع الوحي في آخر الرسالة بخلاف أولها حين انقطع فترة.', 'تابع الوحي : أي: أكثر إنزال ما يوحى إلى النبي -صلى عليه وسلم- من قرآن وشرائع قُرب وفاته.
حتى توفي أكثر ما كان الوحي : أي: توفي النبي -صلى الله عليه وسلم- وقت نزول الوحي بكثرة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4217', false),
(20116, 2, 201, 116, 'hadith', 'عن جابر رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «يبعث كل عبد على ما مات عليه».', 'The Prophet (ﷺ) said, "Every one will be raised in the condition in which he dies"..', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 116', 'Riyad as-Salihin 116', 'ریاض الصالحین 116', 'رواه مسلم', 'يُبعث كل عبد يوم القيامة على الحالة التي مات عليها.', 'ينبغي ملازمة سنة النبي -صلى الله عليه وسلم- في عباداته وأخلاقه وسائر أحواله.
الازدياد من الطاعات في سائر الأوقات؛ لاحتمال قُرب الموت.
حث الإنسان على حسن العمل ليكون أنيسه يوم المحشر؛ لأنه يُبعث على ما مات عليه.', 'يُبعث كل عبد : يقوم بعد موته يوم القيامة.
كل عبد : أي: كل مكَلَّفٍ حرا كان أو عبدا، رجلا او امرأة.
على ما مات عليه : أي: على الحالة التي مات عليها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5459', false),
(20117, 2, 201, 117, 'hadith', 'عن أبي ذر جندب بن جنادة رضي الله عنها قال: قلت يا رسول الله، أي الأعمال أفضل؟ قال: "الإيمان بالله، والجهاد في سبيله". قلت: أي الرقاب أفضل؟ قال: "أنفسها عند أهلها، وأكثرها ثمناً" قلت: فإن لم أفعل؟ قال: "تعين صانعاً أو تصنع لأخرق" قلت: يا رسول الله أرأيت إن ضعفت عن بعض العمل؟ قال: تكف شرك عن الناس فإنها صدقة منك على نفسك".', 'I asked: "O Messenger of Allah! Which action is the best?" He (ﷺ) said, "Faith in Allah and Jihad in the way of Allah." I asked: "Which neck (slave) is best (for emancipation)?" He said, "That which is dearest of them in price and most valuable of them to its masters". I asked: "If I cannot afford (it)?" He said, "Then help a labourer or work for one who is disabled". I asked: "If I cannot do (it)?" He said, "You should restrain yourself from doing wrong to people, because it (serves as) charity which you bestow upon yourself"..', 'أبي ذر جندب بن جنادة رضي الله عنها', 'Abu Dharr (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 117', 'Riyad as-Salihin 117', 'ریاض الصالحین 117', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20118, 2, 201, 118, 'hadith', 'عن أبي ذر أيضاً رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: « يصبح على كل سلامى من أحدكم صدقة، فكل تسبيحة صدقة، وكل تحميدة صدقة، وكل تهليلة صدقة، وكل تكبيرة صدقة، وأمر بالمعروف صدقة، ونهى عن المنكر صدقة، ويجزيء من ذلك ركعتان يركعهما من الضحى» ((رواه مسلم)) السلامى بضم السين المهملة وتخفيف اللام وفتح الميم: المفصل.', 'Messenger of Allah (ﷺ) said, "When you get up in the morning, charity is due from every one of your joints. There is charity in every ascription of glory to Allah; there is charity in every declaration of His Greatness; there is charity in every utterance of praise of Him; there is charity in every declaration that He is the only true God (worthy of worship); there is charity in enjoining good; there is charity in forbidding evil. Two Rak''ah of Duha (Forenoon prayer) is equal to all this (in reward)"..', 'أبي ذر أيضاً رضي الله عنه', 'Abu Dharr (May Allah be pleased with him)', null, 'رياض الصالحين 118', 'Riyad as-Salihin 118', 'ریاض الصالحین 118', null, null, null, null, 'sunnah.com', null, false, null, false),
(20119, 2, 201, 119, 'hadith', 'الثالث عنه قال: قال النبي صلى الله عليه وسلم : « عرضت علي أعمال أمتي حسنها وسيئها، فوجدت في محاسن أعمالها الأذى يماط عن الطريق، ووجدت في مساوىء أعمالها النخاعة تكون في المسجد لا تدفن».', 'The Prophet (ﷺ) said, "The deeds of my people, good and bad, were presented before me, and I found the removal of harmful objects from the road among their good deeds, and phlegm which might be in a mosque left unburied among their evil deeds"..', null, 'Abu Dharr (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 119', 'Riyad as-Salihin 119', 'ریاض الصالحین 119', 'رواه مسلم', 'عرض الله عز وجل أعمال الأمة على نبينا صلى الله عليه وسلم ، فوجد من محاسنها: إزالة ما يؤذي المارة من الطريق، ووجد من سيئها أن يبصق الإنسان في المسجد ولا يزيلها بالدفن أو بغيره.', 'إطلاعُ الله -سبحانه وتعالى- رسولَه -صلى الله عليه وسلم- على أعمال أمته.
الأعمال تنقسم إلى حسن وسيء.
الأعمال الحسنة كل عمل فيه خير وإن دَقَّ، والسيئة التي فيها شر وإن دقَّ.
ينبغي الإكثار من وجوه الخير؛ إذ من جملتها ما يظنه الناس لا شأن له، كإماطة الأذى عن الطريق.
الحث على فعل ما ينفع الناس ويجلب لهم مصلحة، والبعد عن كل ما يضر بهم ويجلب لهم مفسدة.
وجوب احترام المساجد والمحافظة على آدابها وإخراج الأوساخ منها.', 'عُرضت علي : بُيِّنتْ لي.
فوجدت : أي: رأيت.
الأذى : كل ما يضر بالمارة من حجر أو شوك أو غيره.
يُماط : يُنَحَّى ويبعد.
مساوئ : سيئات.
النخاعة : البزقة التي تخرج من الفم وتصعد من الحلق.
لا تدفن : أي: لا تُزال بالدفن.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4813', false),
(20120, 2, 201, 120, 'hadith', 'الرابع عنه: أن ناساً قالوا: يارسول الله، ذهب أهل الدثور بالأجور، يصلون كما نصلي، ويصومون كما نصوم، ويتصدقون بفضول أموالهم قال: " أو ليس قد جعل الله لكم ما تصدقون به: إن بكل تسبيحة صدقة، وكل تكبيرة صدقة، وكل تحميدة صدقة، وكل تهليلة صدقة، وأمر بالمعروف صدقة، ونهي عن المنكر صدقة وفي بضع أحدكم صدقة قالوا: يارسول الله أيأتى أحدنا شهوته، ويكون له فيها أجر؟! قال: " أرأيتم لو وضعها في حرام أكان عليه وزر؟ فكذلك إذا وضعها في الحلال كان له أجر".', 'Some people said to Messenger of Allah (ﷺ): "O Messenger of Allah, the rich have taken away (all the) reward. They observe Salat (prayers) as we do; and give Sadaqah (charity) out of their surplus wealth." Upon this he (the Prophet (ﷺ)) said, "Has Allah not prescribed for you (a course) following which you can (also) give Sadaqah? In every declaration of the glorification of Allah (i.e., saying Subhan Allah) there is a Sadaqah, and in every Takbir (i.e., saying Allahu Akbar) is a Sadaqah, and in every celebration of praise (saying Al-hamdu lillah) is a Sadaqah, and in every declaration that He is One (La ilaha illallah) is a Sadaqah, and in enjoining of good is a Sadaqah, and in forbidding evil is a Sadaqah, and in man''s sexual intercourse (with his wife) there is a Sadaqah." They (the Companions) said: "O Messenger of Allah, is there reward for him who satisfies his sexual need among us?" He said, "You see, if he were to satisfy it with something forbidden, would it not be a sin on his part? Similarly, if he were to satisfy it legally, he should be rewarded"..', null, 'Abu Dharr (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 120', 'Riyad as-Salihin 120', 'ریاض الصالحین 120', 'رواه مسلم', 'اشْتَكَى بعضُ فقراء الصحابة حالَهم وفقرَهم للنبيِّ صلى الله عليه وسلم وعَدَم تَصَدُّقِهم بالأموال لِيَحصلوا على الأجور الكثيرة كما حصل عليها إخوانُهم أصحاب المال الكثير وليفعلوا الخير مثلهم؛ حيث إنهم يُصلُّون كما نصلِّي، ويصومون كما نصوم، ويتصدقون بفضول أموالهم ولا نتصدق! 

فَدَلَّهم النبيُ صلى الله عليه وسلم على ما يقدرون عليه من الصدقات،‏ فقال صلى الله عليه وسلم: 

أَوَلَيس قد جعل الله لكم ما تَصدّقون به على أنفسكم؟! فإنّ قولَكم: (سبحان الله) يكون لكم أجر صدقة، وكذا قول: (الله أكبر) صدقة، وقول: (الحمد لله) صدقة، وقول: (لا إله إلا الله) صدقة، و(الأمر بالمعروف) صدقة، و(النهي عن المنكر) صدقة، بل ‏وفي جماع أحدكم لزوجته صدقة.

فتعجَّبوا، وقالوا: يا رسول الله، أيأتي أحدُنا شهوتَه ويكونُ له فيها أجر؟! 

قال: أرأيتم لو وَضعها في حرامٍ مِن زنى أو غيره أكان عليه فيها إثم؟ فكذلك إذا وضعها في الحلال كان له أجر.', 'تنافُس الصحابة على فعل الخيرات، وحرصهم في نيل عظيم الأجر والفضل من عند الله تعالى.
كثرة وجوه أعمال الخير، وأنها تشمل كلَّ عمل يقوم به المسلم بنية صالحة وقَصْد حَسَن.
يسر الإسلام وسهولته، فكل مسلم يجد ما يَعمله ليطيع الله به.
قال النووي: وفي هذا دليل على أنَّ المباحات تصير طاعات بالنيات الصادقات، فالجماع يكون عبادة إذا نَوَى به قضاء حقّ الزوجة ومعاشرتها بالمعروف الذي أمر الله تعالى به، أو طلب ولد صالح، أو إعفاف نفسه أو إعفاف الزوجة ومنعهما جميعًا من النظر إلى حرام، أو الفكر فيه، أو الهم به، أو غير ذلك من المقاصد الصالحة.
ضرب المثل والقياس؛ ليكون أوضح وأوقع في نفس السامع.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4558', false)
