insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(20201, 2, 201, 201, 'hadith', 'عن حذيفة، وأبي هريرة، رضي الله عنهما ، قالا: قال رسول الله، صلى الله عليه وسلم: "يجمع الله، تبارك وتعالى الناس، فيقوم المؤمنون حتى تزلف لهم الجنة، فيأتون آدم، صلوات الله عليه، فيقولون: يا أبانا استفتح لنا الجنة، فيقول: وهل أخرجكم من الجنة إلا خطيئة أبيكم ! لست بصاحب ذلك، اذهبوا إلى ابني إبراهيم خليل الله، قال: فيأتون إبراهيم، فيقول إبراهيم: لست بصاحب ذلك ، اذهبوا إلى موسى الذي كلمه الله تكليمًا، فيأتون موسى، فيقول: لست بصاحب ذلك؛ اذهبوا إلى عيسى كلمة الله وروحه. فيقول عيسى: لست بصاحب ذلك. فيأتون محمدًا صلى الله عليه وسلم، فيقوم فيؤذن له، وترسل الأمانة والرحم فتقومان جنبتي الصراط يمينًا وشمالاً، فيمر أولكم كبالبرق" قلت: بأبي وأمي، أي شيء كمر البرق؟ قال: "ألم تروا كيف يمر ويرجع في طرفة عين؟ ثم كمر الريح، ثم كمر الطير، وأشد الرجال تجري بهم أعمالهم، ونبيكم قائم على الصراط يقول:" رب سلم سلم، حتى تعدز أعمال العباد، حتى يجيء الرجل لا يستطيع السير إلا زحفاً، وفي حافتي الصراط كلاليب معلقة مأمورة بأخذ من أمرت به، فمخدوش ناج، ومكردس في النار" والذي نفس أبي هريرة بيده إن قعر جهنم لسبعون خريفًا.', '`There was nothing that put you out of Jannah except your father''s sin. I am not the one to do that, go to my son Ibrahim (Abraham), the beloved man of Allah.'' Then Ibrahim (ﷺ) when approached, will say: `I am not the one to do that, for I was only a friend; and that is not a lofty status but ask Musa (Moses) to whom Allah spoke.'' They will then go to Musa (ﷺ) but he will say: `I am not the one to do that; go to `Isa (Jesus), Allah''s Word and spirit.'' `Isa (ﷺ) will say: `I am not the one to do that.'' So they will come to me; and I will stand and be given permission. Amanah and ties of relationship will be sent forth and will stand on the sides of the Sirat (that is, the Bridge set over Hell-fire) right and left, and the first of you will pass like lightning.'''' I said (that is Abu Hurairah (May Allah be pleased with him)" :I ransom you with my father and mother, what is like the movement of lightning?'''' The Messenger of Allah replied, "Have you not seen how the lightning goes and returns in the twinkling of an eye? Next (group will pass) like the passing of the breeze, next like the passing of a bird, and the next with the speed of a running man, according to the quality of their deeds. (During all this time) your Prophet (ﷺ) will remain standing on the Bridge saying: `O my Rubb, keep (them) safe, keep (them) safe,'' till men''s deeds are so weak that a man comes who will be able only to crawl. On both sides of the Bridge pronged flesh hooks, placed under command will be hung and will seize those about whom they receive command, some people being lacerated and escaping and others being thrown violently into Hell.'''' Abu Hurairah added: By Him in Whose Hand Abu Hurairah''s soul is, the pit of Jahannam (Hell) is seventy years in depth.', 'حذيفة، وأبي هريرة رضي الله عنهما', 'Hudhaifah and Abu Hurairah (May Allah be pleased with them) reported that they heard Messenger of Allah (ﷺ) saying, "Allah will assemble mankind, and the believers will stand till Jannah will be brought near them. They will then go to Adam (ﷺ) and say, `O our father, ask (Allah (SWT), that Jannah may be opened for us, but he will reply:', 'صحيح', 'رياض الصالحين 201', 'Riyad as-Salihin 201', 'ریاض الصالحین 201', 'رواه مسلم', 'يجمع الله الناس يوم القيامة للحساب والجزاء فيقوم المؤمنون حتى تُقرب لهم الجنة، ولا تفتح لهم لطول الموقف يوم القيامة، فيذهبون لآدم -عليه السلام- يطلبون منه أن يسأل الله أن يفتح الجنة، لهم فيردهم بأنه ليس أهلا لذلك؛ وذلك بسبب ذنبه الذي كان سببا في خروجهم جميعاً من الجنة، فيرسلهم إلى إبراهيم -عليه السلام-؛ لأنه خليل الله والخلة أعلى مراتب المحبة فيذهبون إلى إبراهيم فيقول لهم: لست بتلك الدرجة الرفيعة اذهبوا لموسى فإن الله سبحانه قد كلمه مباشرة من غير واسطة، فيذهبون لموسى -عليه السلام- فيقول لهم: لست أهلاً لذلك اذهبوا لعيسى فإن الله خلقه بكلمة منه، فيذهبون لعيسى -عليه السلام- فيقول لهم: لست أهلاً لذلك، فيذهبون لنبينا -محمد صلى الله عليه وسلم- فيطلبون منه أن يسأل الله أن يفصل بينهم ويفتح لهم الجنة فيجيبهم ويستأذن فيؤذن له، وتأتي الأمانة والرحم فتقفان على جانبي الصراط، وهو جسر ممدود فوق جهنم ويمر الناس عليه على قدر أعمالهم، فمن كان في الدنيا مسارعا للعمل الصالح فهو مسرع على هذا الصراط، وكذلك العكس فمنهم الناجي ومنهم من يسقط في جهنم وإن قعر جهنم لا يصله إلا بعد سبعين سنة، لبعده والعياذ بالله.', 'أصل البشر من آدم -عليه السلام-.
تواضع الأنبياء فكل يحيل الأمر إلى الآخر.
إخبار عن مصير الناس وأن الله جامعهم إليه يوم القيامة ليحاسبهم.
الجنة لا تفتح إلا باستفتاح من نبينا محمد -صلى الله عليه وسلم-.
رسول الله -صلى الله عليه وسلم- هو الشافع المشفع يوم القيامة.
تعظيم شأن الأمانة والرحم، حيث يقومان على جانبي الصراط.
أحوال الناس على الصراط وأنهم ينجون من العذاب بأعمالهم ويدخلون الجنة برحمة الله -سبحانه-.
شدة هول جهنم وبعد قعرها وأنها دار الكافرين والمنافقين.', 'تزلف : تقرب.
لست بصاحب ذلك : أي: لست صاحب التشريف بهذا المقام.
خليل الله : أصل الخلة الإختصاص, وهي هنا أعلى درجات المحبة.
من وراء وراء : أي: لست بتلك الدرجة الرفيعة، وهذا تواضعا منه -عليه السلام-.
اعمدوا : اذهبوا واقصدوا.
كلمة الله وروحه : أطلق على عيسى -عليه السلام- لأنه خلق بأمره -تعالى-، روحه: أي: ذو روح من الله لا بتوسط أب.
وترسل الأمانة والرحم : الله أعلم كيف يكون ذلك.
كالبرق : أي: مثل البرق والبرق هو شرارة كهربائية تظهر في السماء.
طرفة عين : أي: مدة وقوع الجفن على الجفن.
أشد الرجال : أي: أقوى الرجال في جريهم السريع.
تجري بهم أعمالهم : أي: أنهم في سرعة السير على حسب أعمالهم.
تعجز أعمال العباد : أي: تضعف أعمالهم الصالحة عن سرعة المرور على الصراط.
زحفا : المراد هنا المشي على الاسْتِ وهي المؤخرة وذلك لعجزهم عن المشي المعتاد.
كلاليب : جمع كَلُّوب, وهو حديدة معطوفة الرأس يعلق عليها اللحم.
فمخدوش : أي: مجروح وممزق.
مكردس : أي: يقاد بعنف إلى جهنم ويرمى فيها.
قعر جهنم : أي: أسفل جهنم، وآخرها.
خريفا : المراد بالخريف هنا السَّنَة، مثل قولهم للأسبوع: سبتا أو جمعة.
استفتح : اسأل لنا فتحها.
الصراط : جسر ممدود على متن جهنم يمر عليه أهل الناس.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5865', false),
(20202, 2, 201, 202, 'hadith', 'عن أبي خُبيب -بضم الخاء المعجمة- عبد الله بن الزبير، رضي الله عنهما، قال: لما وقف الزبير يوم الجمل دعاني فقمت إلى جنبه، فقال: يا بني إنه لا يقتل اليوم إلا ظالم أو مظلوم ،وإني لا أرانى إلا سأقتل اليوم مظلوما، وإن من أكبر همي لديني، أفترى ديننا يبقي من مالنا شيئًا؟ ثم قال: يا بني بع مالنا واقض ديني، وأوصى بالثلث وثلثه لبنيه، يعني لبني عبد الله بن الزبير ثلث الثلث. قال فإن فضل من مالنا بعد قضاء الدين شيء فثلثه لبنيك ، قال هشام : وكان بعض ولد عبد الله قد وازى بعض بني الزبير خبيب وعباد، وله يومئذ تسعة بنين وتسع بنات. قال عبد الله : فجعل يوصيني بدينه ويقول: يا بنى إن عجزت عن شيء منه فاستعن عليه بمولاي. قال فوالله ما دريت ما أراد حتى قلت: يا أبت من مولاك؟ قال: الله. قال: فوالله ما وقعت في كربةٍ من دينه إلا قلت: يا مولى الزبير اقض عنه دينه، فيقضيه. قال: فقتل الزبير ولم يدع دينارًا ولا درهمًا إلا أرضين، منهما الغابة وإحدى عشرة دارًا بالمدينة، ودارين بالبصرة، ودارًا بالكوفة ودارًا بمصر. قال: وإنما كان دينه الذي كان عليه أن الرجل كان يأتيه بالمال، فيستودعه إياه، فيقول الزبير: لا ولكن هو سلف إني أخشى عليه الضيعة. وما ولي إمارة قط ولا جباية ولا خراجًا ولا شيئًا إلا أن يكون في غزو مع رسول الله صلى الله عليه وسلم، أو مع أبي بكر وعمر وعثمان رضي الله عنهم، قال عبد الله: فحسبت ما كان عليه من الدين فوجدته ألفي ألف ومائتي ألف! فلقى حكيم بن حزام عبد الله بن الزبير فقال: يا ابن أخي كم على أخي من الدين؟ فكتمته وقلت : مائة ألف. فقال حكيم: والله ما أرى أموالكم تسع هذه ! فقال عبد الله: أرأيتك إن كانت ألف ألف؟ ومائتي ألف؟ قال: ما أراكم تطيقون هذا، فإن عجزتم عن شيء منه فاستعينوا بي. قال: وكان الزبير قد اشترى الغابة بسبعين ومائة ألف، فباعها عبد الله بألف ألف وستمائة ألف ، ثم قام فقال: من كان له على الزبير شيء فليوافنا بالغابة، فأتاه عبد الله بن جعفر، وكان له على الزبير أربعمائة ألف، فقال لعبد الله: إن شئتم تركتها لكم؟ قال عبد الله: لا، قال: فإن شئتم جعلتموها فيما تؤخرون إن أخرتم، فقال عبد الله: لا قال: فاقطعوا لي قطعة، قال عبد الله: لك من ههنا إلى ههنا. فباع عبد الله منها، فقضى عنه دينه، وأوفاه وبقي منها أربعة أسهم ونصف، فقدم على معاوية وعنده عمرو بن عثمان، والمنذر بن الزبير، وابن زمعة فقال له معاوية: كم قومت الغابة؟ قال : كل سهم بمائة ألف قال: كم بقي منها؟ قال: أربعة أسهم ونصف، فقال المنذر ابن الزبير: قد أخذت منها سهمًا بمائة ألف، قال عمرو بن عثمان: قد أخذت منها سهمًا بمائة ألف. وقال ابن زمعة: قد أخذت سهمًا بمائة ألف، فقال معاوية: كم بقي منها؟ قال: سهم ونصف سهم، قال: قد أخذته بخمسين ومائة ألف . قال: وباع عبد الله بن جعفر نصيبه من معاوية بستمائة ألف. فلما فرغ ابن الزبير من قضاء دينه قال بنو الزبير : اقسم بيننا ميراثنا. قال: : والله لا أقسم بينكم حتى أنادي بالموسم أربع سنين : ألا من كان له على الزبير دين فليأتنا فلنقضه. فجعل كل سنة ينادي في الموسم، فلما مضى أربع سنين قسم بينهم ودفع الثلث. وكان للزبير أربع نسوة، فأصاب كل امراةٍ ألف ألف ومائتا ألف، فجميع ماله خمسون ألف ألف ومائتا ألف، رواه البخاري.', 'When Az-Zubair, got ready to fight in the battle of Al- Jamal, he called me and said: "My son, whoever is killed today will be either a wrongdoer or a wronged one. I expect that I shall be the the wronged one today. I am much worried about my debt. Do you think that anything will be left over from our property after the payment of my debt? My son, sell our property and pay off my debt." Az-Zubair then willed one-third of that portion to his sons; namely ''Abdullah''s sons. He said, "One-third of the one-third. If any property is left after the payment of debts, one-third (of the one-third of what is left is to be given to your sons." (Hisham, a subnarrator added: "Some of the sons of ''Abdullah were equal in age to the sons of Az-Zubair, e.g., Khubaib and Abbad. ''Abdullah had nine sons and nine daughters at that time)". (The narrator ''Abdullah added:) He kept on instructing me about his debts and then said: "My son, should you find yourself unable to pay any portion of my debt then beseech my Master for His help." By Allah, I did not understand what he meant and asked: "Father, who is your Master?" He said: "Allah." By Allah! Whenever I faced a difficulty in discharging any portion of his debt; I would pray: "O Master of Zubair, discharge his debt," and He discharged it. Zubair was martyred. He left no money, but he left certain lands, one of them in Al-Ghabah, eleven houses in Al-Madinah, two in Basrah, one in Kufah and one in Egypt. The cause of his indebtedness was that a person would come to him asking him to keep some money of his in trust for him. Zubair would refuse to accept it as a trust, fearing it might be lost, but would take it as a loan. He never accepted a governorship, or revenue office, or any public office. He fought along with Messenger of Allah (ﷺ) and Abu Bakr, ''Umar and ''Uthman (May Allah be pleased with them).''Abdullah added: I prepared a statement of his debts and they amounted to two million and two hundred thousand! Hakim bin Hizam met me and asked me: "Nephew, how much is due from my brother as debt?" I kept it as secret and said: "A hundred thousand." Hakim said: "By Allah! I do not think your assets are sufficient for the payment of these debts." I said: "What would you think if the amount were two million and two hundred thousand?" He said: "I do not think that you would be able to clear off the debts. If you find it difficult let me know."Az-Zubair (May Allah bepleased with him) had purchased the land in Al-Ghabah for a hundred and seventy thousand. ''Abdullah sold it for a million and six hundred thousand, and declared that whosoever had a claim against Az-Zubair (May Allah bepleased with him) should see him in Al-Ghabah. ''Abdullah bin Ja''far (May Allah bepleased with him) came to him and said: "Az- Zubair (May Allah bepleased with him) owed me four hundred thousand, but I would remit the debt if you wish." ''Abdullah (May Allah bepleased with him) said: "No." Ibn Ja''far said: ''''If you would desire for postponement I would postpone the recovery of it." ''Abdullah said: "No." Ibn Ja''far then said: "In that case, measure out a plot for me." ''Abdullah marked out a plot. Thus he sold the land and discharged his father''s debt. There remained out of the land four and a half shares. He then visited Mu''awiyah who had with him at the time ''Amr bin ''Uthman, Al-Mundhir bin Az-Zubair and Ibn Zam''ah (May Allah bepleased with them). Mu''awiyah (May Allah bepleased with him) said: "What price did you put on the land in Al-Ghabah?" He said: "One hundred thousand for a each share. Mu''awiyah inquired: "How much of it is left?" ''Abdullah said: "Four and a half shares." Al-Mundhir bin Az-Zubair said: "I will buy one share for a hundred thousand". ''Amr bin ''Uthman said: "I will buy one share for a hundred thousand". Ibn Zam''ah said: "I will buy one share for a hundred thousand." Then Mu''awiyah asked: "How much of it is now left?" ''Abdullah said: "One and a half share. Mu''awiyah said: "I will take it for one hundred and fifty thousand." Later ''Abdullah bin Ja''far sold his share to Mu''awiyah for six hundred thousand.When ''Abdullah bin Az-Zubair (May Allah bepleased with him) finished the debts, the heirs of Az-Zubair (May Allah bepleased with him) asked him to distribute the inheritance among them. He said: "I will not do that until I announce during four successive Hajj seasons: ''Let he who has a claim against Az-Zubair come forward and we shall discharge it."'' He made this declaration on four Hajj seasons and then distributed the inheritance among the heirs of Az-Zubair (May Allah bepleased with him) according to his will. Az- Zubair (May Allah bepleased with him) had four wives. Each of them received a million and two hundred thousand. Thus Az-Zubair''s total property was amounted to fifty million and two hundred thousand.', 'أبي خُبيب -بضم الخاء المعجمة- عبد الله بن الزبير رضي الله عنهما', 'Abu Khubaib ''Abdullah bin Az-Zubair (May Allah bepleased with them)', 'صحيح', 'رياض الصالحين 202', 'Riyad as-Salihin 202', 'ریاض الصالحین 202', null, 'قال الزبير بن العوام لابنه عبدالله لما كان يوم الجمل وهو قتال جرى بسبب تسليم قتلة عثمان: ما أراني إلا سأقتل شهيدًا مظلومًا، وإنَّ ما يهمني ديوني التي ركبتني، فاقْضِها عني. وكانت ديونُه مستغرقةً لجميع ماله، ومع ذلك أَوْصى لبني ابنه. لأنه كان يَعْلم أنهم ليس لهم في الإِرث نصيبٍ، لكون ابنه حيًا، فجعل لهم ثُلْثَ ثُلُثِ الوصية، وتسع الكل، وكان الناسُ يستودِعون أموالَهم عنده، فيأبى أن يأخذها وديعةً مخافةَ الضياع، ويقول: ليست تلك وديعةً، ولكنها سَلَفٌ وقَرْضُ عليّ، وكان رَجُلا زاهِدًا أمينًا، لم يلِ الإِمارةَ، ولا شيئًا مطلقاً، فلما تُوفي، وقضى عنه ابنُه دَيْنه، وفَضَل مِن ماله فاضل، طلب منه الورثة أن يَقْسِمه بينهم، فأبى أن يفعله، إلا بعد أن يُنادي في موسم الحج، فإِنْ ظهر أنه لم يبق أحدٌ مِمَّن يكون له دينٌ عليه يَقسِمه بينهم، ففعل، ولما لم يَبْقَ من دَيْنه شيءٌ إلا وقد قضاه، أعطى الثَّمن لأزواجه، وذلك نصيبُهنَّ من التركة، وله يومئذٍ أربعُ نسوةٍ.', 'مشروعية الوصية عند الحرب لأنه قد يفضي إلى الموت.
كمال الوثوق بالله عز وجل والاستعانة به في كل حال.
جواز الاستقراض.
وجوب وفاء الدين من ورثة الميت قبل تنفيذ الوصية وقبل قسمة التركة.
جواز ملك الدور والأرض مهما كثرت إذا كان ذلك من وجه شرعي.
المحافظة على الأمانات.
البركة إذا وضعت في شيء جعلت القليل كثيراً وإذا نزعت من شيء كان وبالاً خطيراً.', 'اقض : وفِّي.
وازى : ساوى.
استعن : الاستعانة هي طلب العون.
كربة : حزن يأخذ بالنفس.
يدع : يترك.
الغابة : أرض عظيمة من عوالي المدينة النبوية.
سلف : أي: قرض.
أخشى عليه الضيعة : أي: يخاف عليه الضياع.
ولي إمارة قط : أي: ولاية. وقط: معناه مطلقًا.
جِباية : استخراج الأموال من مظانها.
خراجاً : أي: خراج الأرض من الثمار.
غزو : الخروج مع النبي -صلى الله عليه وسلم- للقتال.
فكتمته : أخفيت عنه الحقيقة.
تطيقون : تستطيعون.
يوافنا : فليأتنا.
قومت الغابة : أي: ثمنها الذي تستحقه.
كل سهم : أي: قسم الأرض لأقسام وكل قسم منها يسمى سهم.
فرغ : انتهى.
الموسم : مأخوذ من الوسم وهو العلامة, والمراد موسم الحج.
دفع الثلث : أعطى الثلث.
للزبير أربع نسوة : أي: زوجاته التي مات عنهن.
أصاب كل امرأة : أي: كان من نصيب كل امرأة وحظها .
أرأيتك : لو أخبرتك.
أفترى : أي: تظن.
عجزت : لم تستطع.
مولاي : كلمة المولى تطلق على معان مختلفة منها الرب والمالك والسيد والمنعم، والمراد الرب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5864', false),
(20203, 2, 201, 203, 'hadith', 'عن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «اتقوا الظلم، فإن الظلم ظلمات يوم القيامة، واتقوا الشح فإن الشح أهلك من كان قبلكم، حملهم على أن سفكوا دماءهم واستحلوا محارمهم».', 'Messenger of Allah (ﷺ) said, "Beware of injustice, for oppression will be darkness on the Day of Resurrection; and beware of stinginess because it doomed those who were before you. It incited them to shed blood and treat the unlawful as lawful."', 'جابر رضي الله عنه', 'Jabir bin ''Abdullah (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 203', 'Riyad as-Salihin 203', 'ریاض الصالحین 203', 'رواه مسلم', 'حَذَّرَ النبيُّ صلى الله عليه وسلم من الظلم، ومنه: ظلم الناس وظلم النفس والظلم في حق الله تعالى، 
وهو تَرْكُ إعطاءِ كلِّ ذِي حقٍّ حقَّه، وأنَّ الظلم ظلمات على أصحابِه يوم القيامة من حصول الشدائد والأهوال، 
ونهى عن الشح الذي هو شدة البخل مع الحرص، ومنه التقصير في أداء الحقوق المالية وشدة الحرص على الدنيا، 
وهذا النوع من الظلم أَهْلَكَ من كان قبلنا من الأمم، حيث حَمَلَهم على قتل بعضهم، وإباحة ما حرم الله من المحرمات.', 'بذل المال ومواساة الإخوان من أسباب التَّحَابِّ والتواصل.
البخل والشح يَجُرُّ إلى المعاصي والفواحش والآثام.
الاعتبار بأحوال الأمم السابقة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5787', false),
(20204, 2, 201, 204, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «لتؤدن الحقوق إلى أهلها يوم القيامة حتى يقاد للشاة الجلحاء من الشاة القرناء».', 'Messenger of Allah (ﷺ) said, "On the Resurrection Day, the rights will be paid to those to whom they are due so much so that a hornless sheep will be retaliated for by punishing the horned sheep which broke its horns"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 204', 'Riyad as-Salihin 204', 'ریاض الصالحین 204', 'رواه مسلم', 'المظلوم يقتص من ظالمه يوم القيامة حتى الشاة التي ليس لها قرن تقتص من التي لها قرن ولا يظلم ربك أحداً.', 'عدل الله -تعالى- وأنه يقاص عباده يوم القيامة، والتقاص يكون بأخذ حسنات الظالم وطرح سيئات المظلوم.
يحشر الله -تعالى- الحيوانات ليقتص منها إقامة للعدل.
الحث على المبادرة لأداء الحقوق إلى أصحابها.', 'يقاد : يُقْتَص.
الجلحاء : التي لا قرن لها.
القرناء : التي لها قرن.
أهلها : أي: أصحابها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5824', false),
(20205, 2, 201, 205, 'hadith', 'عن ابن عمر رضي الله عنهما قال: كنا نتحدث عن حجة الوداع، والنبي صلى الله عليه وسلم بين أظهرنا، ولا ندري ما حجة الوداع، حتى حمد الله رسول الله صلى الله عليه وسلم، وأثنى عليه، ثم ذكر المسيح الدجال فأطنب في ذكره، وقال: " ما بعث الله من نبي إلا أنذره أمته: أنذره نوح والنبيون من بعده، وإنه إن يخرج فيكم فما خفي عليكم من شأنه فليس يخفى عليكم، إن ربكم ليس بأعور، وإنه أعور عين اليمنى، كأن عينه عنبة طافية. ألا إن الله حرم عليكم دماءكم وأموالكم ، كحرمة يومكم هذا، في بلدكم هذا، في شهركم هذا، ألا هل بلغت؟" قالوا: نعم، قال: "اللهم اشهد -ثلاثًا- ويلكم، أو ويحكم، انظروا، لا ترجعوا بعدي كفارًا يضرب بعضكم رقاب بعض".', 'We were talking about the Farewell Pilgrimage without knowing what was it when Messenger of Allah (ﷺ) was also present. He (ﷺ) stood up and recited the Praise and Glorification of Allah. He then gave a detailed account of Ad-Dajjal and said, ''Every Prophet sent by Allah had warned his people against his mischief. Nuh (ﷺ) )warned his nation and so did all the Prophets after him. If he (i.e., Ad-Dajjal) appears among you, his condition will not remain hidden from you. Your Rubb is not one-eyed, but Ad-Dajjal is. His right eye is protruding like a swollen grape. Listen, Allah has made your blood, and your properties as inviolable as of this day of yours (i.e., the Day of Sacrifice), in this city of yours (i.e., Makkah), in this month of yours (i.e., Dhul -Hijjah). Listen, have I conveyed Allah''s Message to you?'''' The people replied in affirmative. There upon he said, "O Allah, bear witness.'''' And he repeated it thrice. He (ﷺ) concluded: "Do not revert after me as infidels killing one another".', 'ابن عمر رضي الله عنهما', 'Ibn `Umar (May Allah bepleased with them)', 'صحيح', 'رياض الصالحين 205', 'Riyad as-Salihin 205', 'ریاض الصالحین 205', 'رواه البخاري ، وروي مسلم بعضه', 'عن عبد الله بن عمر رضي الله عنهما قال: كنا نقول والنبي صلى الله عليه وسلم حي: ما حجة الوداع؟ ولا ندري ما حجة الوداع. وحجة الوداع هي الحجة التي حجها النبي صلى الله عليه وسلم في السنة العاشرة من الهجرة، وودعّ الناس فيها، وذكر المسيح الدجال، وعظّم من شأنه، وبالغ في التحذير منه، ثم أخبر -عليه الصلاة والسلام- أن كل الأنبياء ينذرون قومهم من الدجال، يخوفونهم ويعظمون شأنه عندهم.
وإنه لا يخفى عليكم لأن ربكم ليس بأعور، أما هو فإنه أعور عينه اليمنى كأنها عنبة بارزة.
ثم قال صلى الله عليه وسلم : إن الله حرم عليكم سفك دمائكم وأخذ أموالكم بغير حق، كحرمة يوم النحر وحرمة مكة وحرمة ذي الحجة.
ثم قال صلى الله عليه وسلم : هل بلغتكم ما أُمرت بتبليغه إليكم؟ قالوا: نعم، قال: اللهم فاشهد على شهادتهم بالتبليغ إليهم. قالها ثلاث مرات.
ثم أمرهم أن لا يكونوا بعده كالكفار يقتل بعضهم بعضًا.', 'من منهج الأنبياء في الدعوة إلى الله -تعالى- معرفة سبيل المجرمين للتحذير منهم.
الحذر من الفتن بمعرفة صفات أهلها.
شفقة رسول الله -صلى الله عليه وسلم- على أمته بتحذيره لها من الوقوع في الظلم والفتن.
إثبات صفة العين لله -تعالى-، وهي تليق به -سبحانه-، وأنها عينان إذ الأعور له عين واحدة فقط.
النهي عن الاقتتال وأن ذلك من أعمال الكفار.
دماء المسلمين وأموالهم وأعراضهم حرام عليهم.', 'حجة الوداع : الحجة التي حجها النبي -صلى الله عليه وسلم- سنة 10 هـ، وودعهم فيها.
بين أظهرنا : جالس بيننا.
المسيح : ممسوح العين.
الدجال : المبالغ في الكذب.
أطنب : بالغ.
أنذره أمته : حذرها منه وبين لها بعض صفاته.
عنبة طافية : بارزة ولبروزها شبهها بالعنبة البارزة عن غيرها.
ويلكم - ويحكم : كلمتان استعملتهما العرب بمعنى التعجب والتوجع.
يضرب بعضكم رقاب بعض : يقتل بعضكم بعضًا.
يومكم هذا : يوم النحر.
شهركم هذا : شهر ذي الحجة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5829', false),
(20206, 2, 201, 206, 'hadith', 'عن عائشة رضي الله عنها أن رسول الله صلى الله عليه وسلم قال: «من ظلم قيد شبر من الأرض طوقه من سبع أرضين».', 'Messenger of Allah (ﷺ) said, "Whoever usurps unlawfully even a hand span of land a collar measuring seven times (this) land will be placed around his neck on the Day of Resurrection"..', 'عائشة رضي الله عنها', '''Aishah (May Allah bepleased with her)', 'صحيح', 'رياض الصالحين 206', 'Riyad as-Salihin 206', 'ریاض الصالحین 206', 'متفق عليه', 'مال الإنسان على الإنسان حرام، فلا يحل لأحد أخذ شيء من حق أحد، إلا بطيبة نفسه، وأشد ما يكون ذلك ظلم الأرض، لطول مدة استمرار الاستيلاء عليها ظلماً.
ولذا فإن النبي صلى الله عليه وسلم أخبر أن من ظلم قليلا أو كثيراً من الأرض جاء يوم القيامة بعذاب شديد، بحيث تغلظ رقبته، وتطول، ثم يطوق الأرض التي غصبها وما تحتها، إلى سبع أرضين، جزاء له على ظلمه صاحب الأرض بالاستيلاء عليها.
ولا يدخل في الوعيد استعمال الأراضي العامة دون تملك واستيلاء.', 'تحريم الغصب، لأنه من الظلم الذي حرمه الله على نفسه، وجعله بيننا محرماً.
أن الظلم حرام، في القليل والكثير، وهنا فائدة ذكر الشبر.
أن من ملك ظاهر أرض، ملك باطنها وما فيها، فلا يجوز أن ينقب أحد من تحته، أو يجعل نفقا أو سرباً ونحو ذلك إلا بإذنه.', 'ظلم : الظلم:  وضع الشيء في غير موضعه.
قِيد : بكسر القاف وسكون الياء، أي قَدْرَ.
طُوِّقه : بضم الطاء وتشديد الواو المكسورة، مبنى للمجهول، بمعنى أن يجعل طوقاً في عنقه.
أرضين : بفتح الراء ويجوز إسكانها, جمع أرْض.
شِبْر : الشبر: ما بين أعلى الإبهام وأعلى الخنصر, وذكر الشبر في الحديث إشارة إلى استواء القليل والكثير في الوعيد.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5843', false),
(20207, 2, 201, 207, 'hadith', 'عن أبي موسى رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "إن الله ليملي للظالم فإذا أخذه لم يفلته ثم قرأ: {وكذلك أخذ ربك إذا أخذ القرى وهي ظالمة إن أخذه أليم شديد}.', 'Messenger of Allah (ﷺ) said, "Verily, Allah gives respite to the oppressor. But when He seizes him, He does not let him escape." Then he (ﷺ)) recited, "Such is the Seizure of your Rubb when He seizes the (population of) towns while they are doing wrong. Verily, His Seizure is painful (and) severe". (11:102)..', 'أبي موسى رضي الله عنه', 'Abu Musa (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 207', 'Riyad as-Salihin 207', 'ریاض الصالحین 207', 'هود : 102)) ((متفق عليه', 'يُحَذِّرُ النبيُّ صلى الله عليه وسلم من التَّمادِي في الظلم بالمعاصي والشرك وظلم الناس في حقوقهم، فإن الله تعالى يُمْهِلُ الظالمَ ويؤخِّرُه ويُطيل له في عُمُرِه ومالِه فلا يُعاجِلُه العقوبةَ؛ فإنْ لم يتب أَخَذَه ولم يُطْلِقْه ولم يَتْرُكْه لكثرة ظلمه.

ثم قرأ صلى الله عليه وسلم: {وكذلك أخذ ربك إذا أخذ القرى وهي ظالمة إن أخذه أليم شديد} [هود: 102].', 'على العاقل المبادرة إلى التوبة، وأن لا يَأمَنْ من مَكْرِ الله إذا كان مُقيمًا على الظلم.
إمهال الله عز وجل للظالمين وعدم مُعاجَلتِهم بالعقوبة استدراجًا لهم ومضاعفة للعذاب إن لم يتوبوا.
الظلم من أسباب عقوبة الله للأمم.
إذا أهلك الله قرية فقد يكون فيها صالحون، فهؤلاء يُبعثون يوم القيامة على ما ماتوا عليه من الصلاح، ولا يضرهم أنْ شَمِلَتْهم العقوبةُ.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5811', false),
(20208, 2, 201, 208, 'hadith', 'عن معاذ رضي الله عنه قال : بعثني رسول الله صلى الله عليه وسلم فقال: «إنك تأتي قومًا من أهل الكتاب، فادعهم إلى شهادة أن لا إله إلا الله، وأني رسول الله ، فإن هم أطاعوا لذلك، فأعلمهم أن الله قد افترض عليهم خمس صلوات في كل يوم وليلة، فإن هم أطاعوا لذلك، فإياك وكرائم أموالهم. واتق دعوة المظلوم فإنه ليس بينها وبين الله حجاب».', '"You will go to the people of the Book. First call them to testify that ''there is no true god except Allah, that I am (Muhammad (ﷺ)) the Messenger of Allah.'' If they obey you, tell them that Allah has enjoined upon them five Salat (prayers) during the day and night; and if they obey you, inform them that Allah has made Zakat obligatory upon them; that it should be collected from their rich and distributed among their poor; and if they obey you refrain from picking up (as a share of Zakat) the best of their wealth. Beware of the supplication of the oppressed, for there is no barrier between it and Allah"..', 'معاذ رضي الله عنه', 'Mu''adh (May Allah bepleased with him) reported that Messenger of Allah (ﷺ) sent me (as a governor of Yemen) and instructed me thus:', 'صحيح', 'رياض الصالحين 208', 'Riyad as-Salihin 208', 'ریاض الصالحین 208', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20209, 2, 201, 209, 'hadith', 'عن أبي حميد عبد الرحمن بن سعد الساعدي رضي الله عنه قال: استعمل النبي رجلاً من الأزد يقال له: ابن اللتبية على الصدقة، فلما قدم قال : هذا لكم، وهذا أهدي إلي، فقام رسول الله صلى الله عليه وسلم على المنبر، فحمد الله وأثنى عليه، ثم قال: "أما بعد فإني أستعمل الرجل منكم على العمل مما ولاني الله، فيأتي فيقول: هذا لكم، وهذا هدية أهديت إلي، أفلا جلس في بيت أبيه وأمه حتى تأتيه هديته إن كان صادقًا، والله لا يأخذ أحد منكم شيئًا بغير حقه إلا لقى الله تعالى، يحمله يوم القيامة، فلا أعرفن أحدًا منكم لقي الله يحمل بعيرًا له رغاء، أو بقرة لها خوار، أو شاة تيعر" ثم رفع يديه حتى رؤي بياض إبطيه فقال : "اللهم هل بلغت" ثلاثا.', 'The Prophet (ﷺ) employed a man from the tribe of Al-Azd named Ibn Lutbiyyah as collector of Zakat. When the employee returned (with the collections) he said: "(O Prophet (ﷺ)!) This is for you and this is mine because it was presented to me as gift." Messenger of Allah (ﷺ) rose to the pulpit and praised Allah and extolled Him. Then he said, "I employ a man to do a job and he comes and says: ''This is for you and this has been presented to me as gift''? Why did he not remain in the house of his father or the house of his mother and see whether gifts will be given to him or not? By Allah in Whose Hand is the life of Muhammad, if any one of you took anything wrongfully, he will bring it on the Day of Resurrection, carrying it on (his back), I will not recognize anyone of you, on the Day of Resurrection with a grunting camel, or a bellowing cow, or a bleating ewe." Then he raised his hands till we could see the whiteness of his armpits. Then he said thrice, ''''O Allah ! have I conveyed (Your Commandments)"..', 'أبي حميد عبد الرحمن بن سعد الساعدي رضي الله عنه', 'Abu Humaid bin Sa''d As-Sa''idi (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 209', 'Riyad as-Salihin 209', 'ریاض الصالحین 209', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20210, 2, 201, 210, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: « من كانت عنده مظلمة لأخيه، من عرضه أو من شيء، فليتحلله منه اليوم قبل أن لا يكون دينار ولا درهم ، إن كان له عمل صالح أخذ منه بقدر مظلمته، وإن لم يكن له حسنات أخذ من سيئات صاحبه فحمل عليه».', 'The Prophet (ﷺ) said, "He who has done a wrong affecting his brother''s honour or anything else, let him ask his forgiveness today before the time (i.e., the Day of Resurrection) when he will have neither a dinar nor a dirham. If he has done some good deeds, a portion equal to his wrong doings will be subtracted from them; but if he has no good deeds, he will be burdened with the evil deeds of the one he had wronged in the same proportion"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 210', 'Riyad as-Salihin 210', 'ریاض الصالحین 210', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20211, 2, 201, 211, 'hadith', 'عن عبد الله بن عمرو بن العاص رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «المسلم من سلم المسلمون من لسانه، ويده، والمهاجر من هجر ما نهى الله عنه».', 'The Prophet (ﷺ) said, "A Muslim is the one from whose tongue and hands the Muslims are safe; and a Muhajir (Emigrant) is the one who refrains from what Allah has forbidden"..', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-''as (May Allah bepleased with them)', 'صحيح', 'رياض الصالحين 211', 'Riyad as-Salihin 211', 'ریاض الصالحین 211', 'متفق عليه', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أنَّ المسلمَ كاملَ الإسلامِ هو مَن سَلِم المسلمون من لسانه فلا يَسُبُّهم، ولا يَلعنُهم، ولا يغتابهم، ولا يسعى بينهم بأيِّ نوع من أنواع الأذى بلسانه، 
وسلِموا مِن يده فلا يَعتدي عليهم، ولا يأخذ أموالَهم بغير حق، وما أشبه ذلك، 
والمهاجر من ترك ما حرَّم الله تعالى.', 'كمال الإسلام لا يكون إلا بِعَدَم إِلْحاقِ الأذى بالآخرين ماديًّا كان أو معنويًّا.
خص اللسان واليد بالذكر؛ لكثرة أخطائهما وأضرارهما، فإنَّ معظم الشرور تصدر عنهما.
الحث على ترك المعاصي والتزام ما أمر الله تعالى به.
أفضل المسلمين مَن أدَّى حقوق الله تعالى وحقوق المسلمين.
الاعتداء قد يكون قولًا أو فعلًا.
الهجرة الكاملة هي هَجْرُ ما حرَّم الله تعالى.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10101', false),
(20212, 2, 201, 212, 'hadith', 'وعنه رضي الله عنه قال: كان على ثقل النبي صلى الله عليه وسلم رجل يقال له كركرة، فمات، فقال رسول الله صلى الله عليه وسلم : "هو في النار" فذهبوا ينظرون إليه فوجدوا عباءة قد غلها".', 'A man named Kirkirah, who was in charge of the personal effects of Messenger of Allah (ﷺ) passed away and the Prophet (ﷺ) said, "He is in the (Hell) Fire." Some people went to his house looking for its cause and found there a cloak that he had stolen.', null, '''Abdullah bin ''Amr bin Al-''as (May Allah bepleased with them)', 'صحيح', 'رياض الصالحين 212', 'Riyad as-Salihin 212', 'ریاض الصالحین 212', 'رواه البخاري', 'كان المسؤول عن أمتعة النبي صلى الله عليه وسلم رجل اسمه كركرة فمات؛ فأخبر رسول الله صلى الله عليه وسلم أنه في النار يعذب على معصيته، أو أنه في النار إن لم يعف الله عنه، فذهب الصحابة يبحثون عن السبب في ذلك؛ فوجدوا عباءة قد سرقها من الغنيمة.', 'الخيانة في الأموال العامة من الكبائر التي يعاقب مرتكبها في النار.
تحريم قليل الغلول وكثيره.', 'ثَقَل : الثَّقَل: ما يثقل حمله من الأمتعة والعيال.
كِركرَة : اسم رجل كان أسود يمسك دابة النبي -صلى الله عليه سلم- في القتال.
عباءة : كساء فيه خطوط سود
غلَّها : من الغلول، وهو الأخذ من الغنائم قبل قسمتها على وجه السرقة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4945', false),
(20213, 2, 201, 213, 'hadith', 'عن أبي بكرة نفيع بن الحارث رضي الله عنه عن النبي صلى الله عليه وسلم قال: "إن الزمان قد استدار كهيئته يوم خلق الله السموات والأرض: السنة اثنا عشر شهرًا، منها أربعة حرم: ثلاث متواليات: ذو القعدة، وذو الحجة، والمحرم، ورجب مضر الذي بين جمادى وشعبان، أي شهر هذا؟" قلنا: الله ورسوله أعلم، فسكت حتى ظننا أنه سيسميه بغير اسمه، قال: أليس ذا الحجة؟ قلنا بلى. قال: "فأي بلد هذا؟" قلنا : الله ورسوله أعلم فسكت حتى ظننا أنه سيسميه بغير اسمه. قال:"أليس البلدة" قلنا: بلى . قال: "فأي يوم هذا؟" قلنا: الله ورسوله أعلم، فسكت حتى ظننا أن سيسميه بغير اسمه. قال: "أليس يوم النحر؟" قلنا بلى. قال "فإن دماءكم وأموالكم وأعراضكم عليكم حرام، كحرمة يومكم هذا في بلدكم هذا في شهركم هذا، وستلقون ربكم فيسألكم عن أعمالكم، ألا فلا ترجعوا بعدي كفارًا يضرب بعضكم رقاب بعض، ألا ليبلغ الشاهد الغائب، فلعل بعض من يبلغه أن يكون أوعى له من بعض من سمعه" ثم قال: " ألا هل بلغت، ألا هل بلغت؟" قلنا : نعم. قال: " اللهم اشهد".', 'The Prophet (ﷺ) said, "Time has completed its cycle and has come to the state of the day when Allah created the heavens and the earth. The year consists of twelve months of which four are inviolable; three of them consecutive - Dhul-Qa''dah, Dhul-Hijjah and Muharram and Rajab, the month of Mudar (tribe), which comes between Jumada and Sha''ban. What month is this?" We said, "Allah and His Messenger (ﷺ) know better". The Prophet (ﷺ) remained silent for some time until we thought that he would give it a name other than its real name. Then asked, "Is it not (the month of) Dhul-Hijjah?". We replied in the affirmative. He asked, "Which city is this?". We replied: "Allah and His Messenger know better". He remained silent until we thought that he would give it another name. He (ﷺ) asked, "Is it not Al-Baldah (Makkah)?" We said: "Yes". He (ﷺ) asked, "What day is this?". We said: "Allah and His Messenger know better." He (ﷺ) remained silent until we thought that he would give it another name. He asked, "Is it not the day of An-Nahr (the sacrifice)?". We replied in the affirmative. Thereupon he said, "Your blood, your property and your honour are inviolable to you all like the inviolablity of this day of yours, in this city of yours and in this month of yours. You will soon meet your Rubb and He will ask you about your deeds. So do not turn to disbelief after me by striking the necks of one another. Behold! Let him who is present here convey (this message ) to him who is absent; for many a person to whom a message is conveyed has more retentive memory than the one who hears it." He (ﷺ) again said, "Have I conveyed the message to you? Behold! Have I conveyed the Commandments (of Allah) to you." We submitted: "Yes". He then said, "O Allah, bear witness (to this)"..', 'أبي بكرة نفيع بن الحارث رضي الله عنه', 'Abu Bakrah (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 213', 'Riyad as-Salihin 213', 'ریاض الصالحین 213', 'متفق عليه', 'خطب النبي صلى الله عليه وسلم يوم النحر، وذلك في حجة الوداع، فأخبر أن الزمان صادف في تلك السنة أن النسيء صار موافقًا لما شرعه الله عزّ وجلّ في الأشهر الحرم؛ لأنه كان قد غير وبدل في الجاهلية، حين كانوا يفعلون النسيء فيحلون الشهر الحرام، ويحرمون الشهر الحلال، ولكن لما بيّن عليه الصلاة والسلام أن عدة الشهور اثنا عشر شهرًا هي: المحرم، وصفر، وربيع الأول، وربيع الثاني، وجمادى الأولى، وجمادى الثانية، ورجب، وشعبان، ورمضان، وشوال، وذو القعدة، وذو الحجة، هذه هي الأشهر الاثنا عشر شهرًا، التي جعلها الله أشهرًا لعباده منذ خلق السموات والأرض.
وبين عليه الصلاة والسلام، أن هذه الاثنا عشر شهرًا منها أربعة حرم ثلاثة متوالية وواحد منفرد، الثلاثة المتوالية هي: ذو القعدة وذو الحجة والمحرم، جعلها الله تعالى أشهرا محرمة، يحرم فيها القتال، ولا يعتدي فيها أحد على أحد، لأن هذه الأشهر هي أشهر سير الناس إلى حج بيت الله الحرام، فجعلها الله عزّ وجلّ محرمة لئلا يقع القتال في هذه الأشهر والناس سائرون إلى بيت الله الحرام، وهذه من حكمة الله عزّ وجلّ.
ثم قال عليه الصلاة والسلام: "ورجب مضر الذي بين جمادى وشعبان" وهو الشهر الرابع، وكانوا في الجاهلية يؤدون العمرة فيه فيجعلون شهر رجب للعمرة، والأشهر الثلاثة للحج، فصار هذا الشهر محرمًا يحرم فيه القتال، كما يحرم في ذي القعدة وذي الحجة والمحرم.
ثم سألهم النبي عليه الصلاة والسلام: أي شهر هذا؟ وأي بلد هذا؟ وأي يوم هذا؟ سألهم عن ذلك من أجل استحضار هممهم، وانتباههم؛ لأن الأمر أمرٌ عظيمٌ فسألهم: "أي شهر هذا؟" قالوا: الله ورسوله أعلم؛ فإنهم استبعدوا أن يسأل النبي صلى الله عليه وسلم عن الشهر وهو معروف أنه ذو الحجة، ولكن من أدبهم رضي الله عنهم أنهم لم يقولوا: هذا شهر ذي الحجة؛ لأن الأمر معلوم، بل من أدبهم أنهم قالوا: الله ورسوله أعلم.
ثم سكت لأجل أن الإنسان إذا تكلم ثم سكت انتبه الناس، فسكت النبي عليه الصلاة والسلام، يقول أبو بكرة: حتى ظننا أنه سيسميه بغير اسمه، ثم قال: أليس ذا الحجة؟ " قالوا: بلى، ثم قال عليه الصلاة والسلام: "أي بلد هذا؟" قالوا: الله ورسوله أعلم، هم يعلمون أنه مكة، لكن لأدبهم واحترامهم لرسول الله صلى الله عليه وسلم لم يقولوا: هذا شيء معلوم يا رسول الله. كيف تسأل عنه؟ بل قالوا: الله ورسوله أعلم.
ثم سكت حتى ظنوا أنه سيسميه بغير اسمه، فقال: "أليس البلدة؟" والبلدة اسم من أسماء مكة. قالوا: بلى. ثم قال: "أي يوم هذا؟" قالوا: الله ورسوله أعلم، مثل ما قالوا في الأول، قال: "أليس يوم النحر؟" قالوا: بلى يا رسول الله، وهم يعلمون أن مكة حرام، وأن شهر ذي الحجة حرام، وأن يوم النحر حرامٌ، يعني كلها حرم محترمة.
فقال عليه الصلاة والسلام: "إن دماءكم وأموالكم وأعراضكم عليكم حرام، كحرمة يومكم هذا، في بلدكم هذا، في شهركم هذا" فأكد عليه الصلاة والسلام تحريم هذه الثلاثة: الدماء والأموال والأعراض، فكلها محرمة، والدماء تشمل النفوس وما دونها، والأموال تشمل القليل والكثير، والأعراض تشمل الزنا واللواط والقذف، وربما تشمل الغيبة والسب والشتم. فهذه الأشياء الثلاثة حرامٌ على المسلم أن ينتهكها من أخيه المسلم.
ثم قال: "ألا لا ترجعوا بعدي كفارًا يضرب بعضكم رقاب بعض". لأن المسلمين لو صاروا يضرب بعضهم رقاب بعض صاروا كفارًا؛ لأنه لا يستحل دم المسلم إلا الكافر.
ثم أمر عليه الصلاة والسلام أن يبلغ الشاهد الغائب، يعني يبلغ من شهده وسمع خطبته باقي الأمة، وأخبر عليه الصلاة والسلام أنه ربما يكون مبلغ أوعى للحديث من سامع، وهذه الوصية من الرسول عليه الصلاة والسلام، وصية لمن حضر في ذلك اليوم، ووصية لمن سمع حديثه إلى يوم القيامة.
ثم قال عليه الصلاة والسلام: "ألا هل بلغت؟ ألا هل بلغت؟". يسأل الصحابة رضي الله عنهم. قالوا: نعم، أي: بلغت.
فقال عليه الصلاة والسلام: "اللهم اشهد".', 'بطلان النسيء -أي التأخير، والمراد تأخير تحريم شهر من الشهور المحرمة إلى شهر آخر- وهو عادة جاهلية، كانوا إذا احتاجوا إلى الحرب في الأشهر الحرم استحلوها وأخروها إلى الأشهر التي تليها، وأخروا على ذلك الحج.
التأكيد على حرمة الدماء والأعراض والأموال والحث على صيانتها وعدم الاعتداء عليها.
وجوب تبليغ العلم ونقله بأمانة وصدق بعد فهمه وحفظه.
التأكيد على فهم ما يقال من التوجيه والعلم.
الناس متفاوتون في مراتب الفهم، ولذلك فقد يأتي من يكون أفهم وأفقه ممن تقدمه.', 'إن الزمان قد استدار : أي: إن الزمن عاد في انقسامه إلى الأعوام، والعام في انقسامه إلى الأشهر وإلى الوضع الذي اختار الله وضعه عليه.والاستدارة: الطواف حول الشيء والعودة إلى الموضع الذي ابتدأ منه.
كهيئته : الهيئة: الصورة والشكل والحال التي كان عليها.
حُرُم : أي: محرمة يحرم فيها ابتداء القتال.
رجب مُضر : أضيف رجب إلى قبيلة مضر؛ لأنها كانت تحافظ على حرمته أكثر من سائر العرب.
البلدة : المراد بها مكة.
يوم النحر : هو اليوم العاشر من ذي الحجة، ويسمى بذلك لأنه تذبح فيه الأضاحي وينحر الهدي.
أوعى : أفهم لمعناه.
كحرمة : كعظم الذنب في هذا اليوم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10104', false),
(20214, 2, 201, 214, 'hadith', 'عن أبي أمامة إياس بن ثعلبة الحارثي رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: " من اقتطع حق امرئ مسلم بيمينه فقد أوجب الله له النار، وحرم عليه الجنة" فقال رجل: وإن كان شيئًا يسيرًا يا رسول الله ؟ فقال: "وإن قضيبًا من أراك".', 'Messenger of Allah (ﷺ) said, "Allah decrees the (Hell) Fire and debars Jannah for the one who usurps the rights of a believer by taking a false oath." One man asked: "O Messenger of Allah! Even if it should be for an insignificant thing?" He said, "Even if it be a stick of the Arak tree (i.e., the tree from which Miswak sticks are taken)"..', 'أبي أمامة إياس بن ثعلبة الحارثي رضي الله عنه', 'Abu Umamah (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 214', 'Riyad as-Salihin 214', 'ریاض الصالحین 214', 'رواه مسلم', 'حَذَّرَ النبيُّ صلى الله عليه وسلم مِن الحَلِف بالله كاذبًا عالمًا وذلك لاقتطاع حقِّ امرئ مسلم، فإنّ جزاء ذلك استحقاق النار، والحِرْمان من الجنة، وهو من كبائر الذنوب.

فقال رجل يا رسول الله: وإن كان المَحْلُوف عليه شيئًا قليلًا؟ 

فقال صلى الله عليه وسلم: حتى لو كان ذلك في عُوْد السِّوَاك الذي يُؤخذ من شجرة الأراك.', 'الحذر من أخذ حقوق الآخرين، والحرص على أدائها لأصحابها مهما قَلَّتْ، وأنَّ حكم الحاكم بالخطأ لا يُبيح للإنسان ما لم يكن له.
قال النووي: غلظ تحريم حقوق المسلمين، وأنه لا فرق بين قليل الحق وكثيره؛ لقوله صلى الله عليه وسلم: "وإن قضيبًا من أراك".
قال النووي: هذه العقوبة لمن اقتطع حق المسلم ومات قبل التوبة، أما من تاب فندم على فعله وردَّ الحق إلى صاحبه وتَحَلَّل منه وعزم على أن لا يعود فقد سقط عنه الإثم.
قال القاضي: تخصيص المسلم لكونهم المخاطبين وعامة المتعاملين في الشريعة، لا أنَّ غير المسلم بخلافه، بل حُكمُه حُكمُه في ذلك.
قال النووي: الكذب هو الإخبار عن الشيء على خلاف ما هو، عمدًا كان أو سهوًا، سواء كان الإخبار عن ماض أو مستقبل.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5430', false),
(20215, 2, 201, 215, 'hadith', 'عن عدي ابن عميرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: "من استعملناه منكم على عمل، فكتمنا مخيطًا فما فوقه، كان غلولاً يأتي به يوم القيامة" فقام إليه رجل أسود من الأنصار، كأني أنظر إليه ، فقال: يا رسول الله اقبل عني عملك، قال: "ومالك؟" قال سمعتك تقول كذا وكذا، قال: "وأنا أقوله الآن: من استعملناه على عمل فليجئ بقليله وكثيره، فما أوتي منه أخذ، وما نهي عنه انتهى.', 'Messenger of Allah (ﷺ) said, "Whosoever among you is appointed by us to a position and he conceals from us even a needle or less, it will amount to misappropriation and he will be called upon to restore it on the Day of Resurrection". (''Adi bin ''Umairah added:) A black man from the Ansar stood up - I can see him still - and said: "O Messenger of Allah, take back from me your assignment." He (the Prophet (ﷺ)) said, "What has happened to you?" The man replied: "I have heard you saying such and such." He (ﷺ) said, "I say that even now: Whosoever from you is appointed by us to a position, he should render an account of everything, big or small, and whatever he is given therefrom, he should take and he should desist from taking what is unlawful"..', 'عدي ابن عميرة رضي الله عنه', '''Adi bin ''Umairah (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 215', 'Riyad as-Salihin 215', 'ریاض الصالحین 215', 'رواه مسلم', 'من استعملناه منكم على عمل من جمع مال الزكاة أو الغنائم أو غير ذلك، فأخفى منه إبرة فما أصغر منها كان غلولا يأتي به يوم القيامة، فقام إليه رجل من الأنصار يستأذنه في أن يترك العمل الذي كلفه صلى الله عليه وسلم به، فقال له النبي صلى الله عليه وسلم: وما لك. قال: سمعتك تقول: كذا وكذا. فقال: وأنا أقوله الآن، من استعملناه منكم على عمل فليأت بقليله وكثيره، فما أعطي من أجره أخذه، وما نهي عنه ولم يكن من حقه امتنع عن أخذه.', 'الوعيد الشديد لمن خان في عمله أو وظيفته في قليل أو كثير.
من اؤتمن على أموال الأمة عليه أن يصونها ويؤديها إلى مستحقيها ولا يختص نفسه بشيء منها، وإن حدثته نفسه بالخيانة وأَخَذَ شيئًا منها وجب عليه رده، وإلا افتضح يوم القيامة على رؤوس الأشهاد.
وجوب البعد عن الإمارة والوظيفة لمن لمس من نفسه عدم الثقة والقدرة على القيام بها بأمانة وإخلاص.
ولاة الأمور ينبغي أن يعرفوا الجهات التي يرد منها المال العام فيأخذوا ما هو حلال، وما لم يجز أخذه يرد إلى أهله.
جواز نعت الرجل بما فيه للمعرفة إذا لم يكن ذلك يغضبه، ولذلك قال في الحديث: فقام إليه رجل أسود من الأنصار.', 'كتمنا مخيطا : أي: أخفاه.
مخيطا فما فوقه : إبرة أو ما هو أصغر منها.
غلولا : الغلول: أخذ الشيء خُفية وخيانة.
اقبل عني عملك : ائذن لي أن أستقيل من العمل الذي وليتني عليه.
كذا وكذا : من ألفاظ الكنايات يكنى بها عن المجهول، وعما لا يراد التصريح به، وما سبق ذكره.
فليجئ : فليأت.
أوتي : أعطي أجره.
ما نهي عنه انتهى : ما بين له أن أخذه غير جائز انتهى من أخذه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5412', false),
(20216, 2, 201, 216, 'hadith', 'عن عمر بن الخطاب رضي الله عنه قال: لما كان يوم خيبر أقبل نفر من أصحاب النبي صلى الله عليه وسلم فقالوا فلان شهيد، وفلان شهيد، حتى مروا على رجل فقالوا : فلان شهيد. فقال النبي صلى الله عليه وسلم : كلا إني رأيته في النار في بردة غلها-أو عباءة-".', 'On the day (of the battle) of Khaibar, some Companions of the Prophet (ﷺ) came and remarked: "So-and-so is a martyr and so-and-so is a martyr". When they came to a man about whom they said: "So-and-so is a martyr," the Prophet (ﷺ) declared, "No. I have seen him in Hell for a mantle (or cloak) which he has stolen"..', 'عمر بن الخطاب رضي الله عنه', '''Umar bin Al-Khattab (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 216', 'Riyad as-Salihin 216', 'ریاض الصالحین 216', 'رواه مسلم', 'قال عمر بن الخطاب رضي الله عنه : لما كان يوم غزوة خيبر أقبل أناس من أصحاب النبي صلى الله عليه وسلم على النبي صلى الله عليه وسلم وهم يقولون: فلان شهيد، فلان شهيد حتى مروا على رجل فقالوا: فلان شهيد، فقال النبي صلى الله عليه وسلم : كلا إني رأيته في النار بسبب عباءة قد كتمها يريد أن يختص بها لنفسه، فعُذب بها في نار جهنم، وانتفت عنه هذه الصفة العظيمة وهي الشهادة في سبيل الله عز وجل .', 'عِظم ذنب الخيانة في الأموال العامة وشدة عقابها.
الشهادة في سبيل الله -تعالى- لا تكفر حقوق العباد.
إكرام الله -تعالى- لرسوله -صلى الله عليه وسلم- حيث أطلعه على خواتيم بعض العباد.', 'نفر : اسم يُطلق على الناس كلهم، وعلى دون العشرة من الرجال خاصة.
كلا : أداة ردع وزجر؛ أي: انتهوا.
رأيته : الظاهر أنه -صلى الله عليه سلم- اطلع على ما يكون من حاله يوم القيامة نتيجة خيانته.
بردة : ثوب مخطط.
عباءة : نوع من الملابس
غلَّها : من الغلول، وهو الأخذ من الغنائم قبل قسمتها على وجه السرقة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4238', false),
(20217, 2, 201, 217, 'hadith', 'عن أبي قتادة الحارث بن ربعي رضي الله عنه عن رسول الله صلى الله عليه وسلم أنه قام فيهم ، فذكر لهم أن الجهاد في سبيل الله، والإيمان بالله أفضل الأعمال، فقام رجل فقال: يا رسول الله أرأيت إن قتلت في سبيل الله، تكفر عني خطاياي؟ فقال له رسول الله صلى الله عليه وسلم: "نعم إن قتلت في سبيل الله وأنت صابر محتسب، مقبل غير مدبر" ثم قال رسول الله صلى الله عليه وسلم: "كيف قلت؟" قال: أرأيت إن قتلت في سبيل الله، أتكفر عني خطاياي؟ فقال رسول الله صلى الله عليه وسلم: "نعم وأنت صابر محتسب، مقبل غير مدبر، إلا الدين فإن جبريل قال لي ذلك".', 'Messenger of Allah (ﷺ) said, "Faith in Allah and striving in His Cause (Jihad) are the deeds of highest merit." A man stood up said: "O Messenger of Allah! Tell me if I am killed in the Cause of Allah, will all my sins be forgiven?" He (ﷺ) replied, "Yes, if you are killed in the Cause of Allah while you are patient, hopeful of your reward and marching forward not retreating." Then the Prophet (ﷺ) said to him, "Repeat what you have said." The man said: "Tell me if I am killed in the Cause of Allah, will all my sins be remitted?". He replied, "Yes, if you are martyred while you are patient, hopeful of your reward and march forward without retreating, unless, if you owe any debt, that will not be remitted. Angel Jibril told me that"..', 'أبي قتادة الحارث بن ربعي رضي الله عنه', 'Abu Qatadah Al-Harith bin Rib''i (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 217', 'Riyad as-Salihin 217', 'ریاض الصالحین 217', 'رواه مسلم', 'قام النبي صلى الله عليه وسلم في الصحابة خطيبًا، فذكر لهم أن الجهاد لإعلاء كلمة الله والإيمانَ بالله أفضل الأعمال، فقام رجل فسأل النبي صلى الله عليه وسلم : أرأيت إن قتلتُ لإعلاء كلمة الله أتغفر لي ذنوبي، فقال النبي صلى الله عليه وسلم : نعم، ولكن بشرط أن تكون قُتِلتَ صابرا مُتحملاً ما أصابك، مخلصا لله تعالى ، غير فارٍّ من ساحة الجهاد، ثم استدرك النبي صلى الله عليه وسلم شيئاً وهو الدَّين، منبها على أن الجهاد والشهادة لا تكفر حقوق الآدميين.', 'فضل الجهاد لإعلاء كلمة الله تعالى، وعظيم ثواب من يقتل وهو مجتهد في مقاتلة أعداء الله -عز وجل-.
الشهادة بشروطها تكفر الذنوب إلا الدَّين وغيره من حقوق الآدميين.
الإمام يحث أصحابه ويذكرهم بفضائل الأعمال وأفضلها ليقبلوا عليها.
حرص أصحاب النبي -صلى الله عليه وسلم- على طلب الأعمال المكفرة للذنوب.
جواز الاستفهام والاستدراك على الكلام إذا كان في ذلك زيادة فائدة أو بيان.
أن السنة النبوية وحي من الله -تعالى-.
تعظيم شأن الديون وأهمية سدادها سريعًا.', 'قام فيهم : أي: خطيبًا.
تكفر : تُغفَر.
خطاياي : ذنوبي.
صابر : متحمل ما أصابك من مكروه في القتال من جُرح وغيره.
محتسب : مخلص لله -تعالى- ترجو الثواب منه.
مقبل غير مدبر : مُقْدِم غير فار.
الدَّين : القرض المؤجل.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4227', false),
(20218, 2, 201, 218, 'hadith', 'عن أبي هريرة رضي الله عنه، أن رسول الله صلى الله عليه وسلم قال: ":أتدرون من المفلس؟" قالوا : المفلس فينا من لا درهم له ولا متاع فقال: "إن المفلس من أمتي يأتي يوم القيامة بصلاة وصيام وزكاة، ويأتي قد شتم هذا، وقذف هذا وأكل مال هذا، وسفك دم هذا، وضرب هذا، فيعطى هذا من حسناته، وهذا من حسناته، فإن فنيت حسناته قبل أن يقضي ما عليه، أخذ من خطاياهم فطرحت عليه، ثم طرح في النار".', 'Messenger of Allah (ﷺ) said, "Do you know who is the bankrupt?" They said: "The bankrupt among us is one who has neither money with him nor any property". He said, "The real bankrupt of my Ummah would be he who would come on the Day of Resurrection with Salat, Saum and Sadaqah (charity), (but he will find himself bankrupt on that day as he will have exhausted the good deeds) because he reviled others, brought calumny against others, unlawfully devoured the wealth of others, shed the blood of others and beat others; so his good deeds would be credited to the account of those (who suffered at his hand). If his good deeds fall short to clear the account, their sins would be entered in his account and he would be thrown in the (Hell) Fire"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 218', 'Riyad as-Salihin 218', 'ریاض الصالحین 218', 'رواه مسلم', 'سَألَ النبيُّ صلى الله عليه وسلم أصحابه: أتدرون من المفلس؟ قالوا: المفلس فينا من لا مال له ولا متاع، فقال: إن المفلس من أمتي يوم القيامة من يأتي بأعمال صالحة من صلاة وصيام وزكاة، ويأتي وقد شتم هذا وسبَّه، وقَذَفَ هذا في عرضه، وأكل مال هذا وجحده، وسَفَكَ دمَ هذا وظلمه، وضرب هذا وأهانه، فيعطى المظلوم من حسناته، فإن فنيت حسناته قبل أن يَقضيَ ما عليه من الحقوق والمظالم، أُخذ من ذنوب المظلوم فجُعلت في صحائف الظالم، ثم طُرح ورُمي في النار حيث لم يبقَ له حسنات.', 'التحذير من الوقوع في المُحرمات، وخاصة ما يتعلق بحقوق العباد المادية والمعنوية.
حقوق الخَلْق فيما بينهم مَبنية على المُشَاحّة، وحقوق الخالق سوى الشرك مبنية على المُسامحة.
استعمال طريقة المحاورة التي تُشوِّق السامع وتُلفتْ نظرَه وتثير اهتمامه، وخاصة في التربية والتوجيه.
بيان معنى المفلس الحقيقي، وهو من أخذ غرماؤه أعمالَه الصالحةَ يوم القيامة.
القصاص في الآخرة قد يأتي على جميع الحسنات، حتى لا يبقي منها شيئًا.
معاملة الله للخلق قائمة على العدل والحق.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6454', false),
(20219, 2, 201, 219, 'hadith', 'عن أم سلمة رضي الله عنها، أن رسول الله صلى الله عليه وسلم قال: «إنما أنا بشر، وإنكم تختصمون إلي، ولعل بعضكم أن يكون ألحن بحجته من بعض، فأقضي له بنحو ما أسمع ، فمن قضيت له بحق أخيه فإنما أقطع له قطعة من النار».', 'Messenger of Allah (ﷺ) said, "Verily, I am only a human and the claimants bring to me (their disputes); perhaps some of them are more eloquent than others. I judge according to what I hear from them). So, he whom I, by my judgment, (give the undue share) out of the right of a Muslim, I in fact give him a portion of (Hell) Fire"..', 'أم سلمة رضي الله عنها', 'Umm Salamah (May Allah bepleased with her)', 'صحيح', 'رياض الصالحين 219', 'Riyad as-Salihin 219', 'ریاض الصالحین 219', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20220, 2, 201, 220, 'hadith', 'عن ابن عمر رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: « لا يزال المؤمن في فسحة من دينه ما لم يصب دمًا حرًا».', 'Messenger of Allah (ﷺ) said, "A believer continues to guard his Faith (and thus hopes for Allah''s Mercy) so long as he does not shed blood unjustly"..', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah bepleased with them)', 'صحيح', 'رياض الصالحين 220', 'Riyad as-Salihin 220', 'ریاض الصالحین 220', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20221, 2, 201, 221, 'hadith', 'عن خولة بنت عامر الأنصاري ، وهي امرأة حمزة رضي الله عنه وعنها، قالت : سمعت رسول الله صلى الله عليه وسلم يقول: «إن رجالاً يتخوضون في مال الله بغير حق، فلهم النار يوم القيامة».', 'Messenger of Allah (ﷺ) said, "Many people misappropriate (acquire wrongfully) Allah''s Property (meaning Muslims'' property). These people will be cast in Hell on the Day of Resurrection"..', 'خولة بنت عامر الأنصاري ، وهي امرأة حمزة رضي الله عنه', 'Khaulah bint ''Thamir (May Allah bepleased with her)', 'صحيح', 'رياض الصالحين 221', 'Riyad as-Salihin 221', 'ریاض الصالحین 221', 'رواه البخاري', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم عن أناسٍ يَتَصَرَّفُون في أموال المسلمين بالباطل، ويأخذونها بغير حق، وهذا معنى عامٌّ في المال من حيث جَمْعِهِ وكسبِهِ من غير حِلِّه، وإنفاقه في غير مواضعه الصحيحة، ويدخل في ذلك أكل أموال اليتامى وأموال الوَقْف وجَحْد الأمانات والأخذ بغير استحقاق من الأموال العامة.

ثم أخبر صلى الله عليه وسلم أن جزاءهم النار يوم القيامة.', 'المال الذي بأيدي الناس هو مال الله، استَخْلَفَهم عليه لينفقوه بالطرق المشروعة، ويجتنبوا التصرف فيه بالباطل، وهذا عامٌّ في الولاة وغيرهم من سائر الناس.
تشديد الشرع في المال العام،  وأنه من ولي منه شيئًا فإنه سيحاسب يوم القيامة على جِبَايَتِه وإنفاقه.
يدخل في هذا الوعيد مَن يتصرَّفُ تصرُّفًا غير شرعي في المال سواء كان ماله أو مال غيره.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5331', false),
(20222, 2, 201, 222, 'hadith', 'عن أبي موسى رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم « المؤمن للمؤمن كالبنيان يشد بعضه بعضًا» وشبك بين أصابعه.', 'Messenger of Allah (ﷺ) said, "The relationship of the believer with another believer is like (the bricks of) a building, each strengthens the other." He (ﷺ) illustrated this by interlacing the fingers of both his hands..', 'أبي موسى رضي الله عنه', 'Abu Musa (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 222', 'Riyad as-Salihin 222', 'ریاض الصالحین 222', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20223, 2, 201, 223, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم : «من مر في شيء من مساجدنا، أو أسواقنا، ومعه نبل فليمسك، أو ليقبض على نصالها بكفه أن يصيب أحدًا من المسلمين منها بشيء».', 'Messenger of Allah (ﷺ) said, "Whoever enters our mosque or passes through our market with arrows with him, he should hold them by their heads lest it should injure any of the Muslims"..', null, 'Abu Musa (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 223', 'Riyad as-Salihin 223', 'ریاض الصالحین 223', 'متفق عليه', 'من مر في المساجد والأسواق وأماكن اجتماع المسلمين ومعه سلاح من نبل وغيره، فإنه يمسك به ويحكم قبضته عليه جيدا؛ لئلا يصيب به أحدا من المسلمين.', 'رحمة النبي صلى الله عليه وسلم بالمسلمين وشفقته عليهم.
حرص الإسلام على أمن المسلم وعدم أذيته، ولو بجُرح يسير؛ تعظيما لحرمته؛ وإعلاء لمنزلته.
أدب حمل السلاح في الإسلام.
جواز حمل السلاح في المسجد أو السوق ما لم يترتب على حمله مضرة.', 'نَبْلٌ : السهام العربية.
نِصالها : النِّصال: الحديدة التي في رأس السهم.
مساجدنا : المكان المهيأ للصلوات الخمس.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5442', false),
(20224, 2, 201, 224, 'hadith', 'عن النعمان بن بشير رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم « مثل المؤمنين في توادهم وتراحمهم وتعاطفهم، مثل الجسد إذا اشتكى منه عضو تداعى له سائر الجسد بالسهر والحمى».', 'Messenger of Allah (ﷺ) said, "The believers in their mutual kindness, compassion and sympathy are just like one body. When one of the limbs suffers, the whole body responds to it with wakefulness and fever"..', 'النعمان بن بشير رضي الله عنهما', 'Nu''man bin Bashir (May Allah bepleased with them)', 'صحيح', 'رياض الصالحين 224', 'Riyad as-Salihin 224', 'ریاض الصالحین 224', 'متفق عليه', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنّه يَجبُ أنْ تكونَ حالُ المسلمين بعضهم مع بعض من محبة الخير والرحمة والمساعدة والنصرة، والتأذِّي بما يحصل لهم من الضرر، كمثل الجسد الواحد، إذا مرض منه عضو، تفاعل معه الجسدُ كلُّه بالسهر والحُمّى.', 'ينبغي تعظيمُ حقوق المسلمين والحضُّ على تعاونهم وملاطفة بعضهم بعضًا.
ينبغي أن يكونَ بين أهلِ الإيمان المحبة والنصرة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4969', false),
(20225, 2, 201, 225, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قبل النبي الحسن بن علي رضي الله عنهما، وعنده الأقرع بن حابس، فقال الأقرع: إن لي عشرة من الولد ما قبلت منهم أحدًا. فنظر إليه رسول الله صلى الله عليه وسلم فقال: «من لا يرحم لا يرحم».', 'The Prophet (ﷺ) kissed his grandson Al-Hasan bin ''Ali (May Allah bepleased with them) in the presence of Al-Aqra'' bin Habis. Thereupon he remarked: "I have ten children and I have never kissed any one of them." Messenger of Allah (ﷺ) looked at him and said, "He who does not show mercy to others will not be shown mercy"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 225', 'Riyad as-Salihin 225', 'ریاض الصالحین 225', 'متفق عليه', 'أخبر أبو هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قبَّل الحسن بن علي وعنده الأقرع بن حابس التميمي جالساً، فقال الأقرع: إنَّ لي عشرة من الولد ما قبَّلتُ منهم أحداً، فنظر إليه رسول الله صلى الله عليه وسلم ثم قال: "من لا يرحم لا يُرحَم"، وفي رواية: "أوَ أملك أن نزع الله من قلبك الرحمة" أي ماذا أصنع إذا كان الله قد نزع من قلبك عاطفة الرحمة؟ فهل أملك أن أعيدها إليك؟.', 'تقبيل الأبوين لأولادهما مشروع مستحب.
العطف على الصغير دلالة الرحمة والشفقة عليه.
من أسباب رحمة الله للناس التراحم بينهم.
الجزاء من جنس العمل؛ فمن لا يَرحم لا يُرحم.
فيه دلالة على جفاء الأعراب سكان البادية.
فيه أن الشرع لا يؤخذ بالعقل، إنما بالوحي والاتباع.', 'من لا يرحم : أي: من لا يرحم الناس.والرحمة من الخلق بمعنى التلطف.
لا يُرحم : أي: لا يرحمه الله، والرحمة صفة فعلية تليق بجلال الله -تعالى- وليست كرحمة المخلوقين.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5440', false),
(20226, 2, 201, 226, 'hadith', 'عن عائشة رضي الله عنها قالت: قدم ناس من الأعراب على رسول الله صلى الله عليه وسلم، فقالوا : أتقبلون صبيانكم؟ فقال: "نعم" قالوا: لكنا والله ما نقبل ! فقال رسول الله صلى الله عليه وسلم : "أو أملك إن كان الله نزع من قلوبكم الرحمة؟".', 'Some bedouins came to Messenger of Allah (ﷺ) and asked: "Do you kiss your children?" He said, "Yes". They then said: "By Allah, we do not kiss them." The Prophet (ﷺ) replied, "I cannot help you if Allah has snatched kindness from your hearts"..', 'عائشة رضي الله عنها', '''Aishah (May Allah bepleased with her)', 'صحيح', 'رياض الصالحين 226', 'Riyad as-Salihin 226', 'ریاض الصالحین 226', 'متفق عليه', 'جاء قوم من الأعراب إلى النبي صلى الله عليه وسلم فسألوا: هل تقبلون صبيانكم؟ قال النبي صلى الله عليه وسلم : "نعم"، والأعراب عندهم غلظة وشدة؛ فقالوا: إنا لسنا نقبل صبياننا، فقال النبي -عليه الصلاة والسلام-: "إذا نزع الله من قلوبكم الرحمة فلا أملك وضعها في قلوبكم".', 'الرحمة غريزة في النفس الإنسانية أودعها الله عباده الرحماء.
جعل الله الرحمة في قلوب عباده ليعطف بعضهم على بعض، ولتستقيم أمور الحياة.
البيئة لها أثر في التكوين النفسي للإنسان.
مشروعية الشفقة على الأولاد وتقبيلهم ورحمتهم.', 'الأعراب : هم سكان البادية.
أملك : أقدر.
نزع : اقتلع.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4251', false),
(20227, 2, 201, 227, 'hadith', 'عن جرير بن عبد الله رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم « من لا يرحم الناس لا يرحمه الله ».', 'Messenger of Allah (ﷺ) said, "He who is not merciful to people Allah will not be merciful to him.".', 'جرير بن عبد الله رضي الله عنه', 'Jarir bin ''Abdullah (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 227', 'Riyad as-Salihin 227', 'ریاض الصالحین 227', 'متفق عليه', 'يُبَيِّنُ النبيُّ صلى الله عليه وسلم أنَّ الذي لا يرحمُ الناسَ لا يرحمُه اللهُ عز وجل، فرحمةُ العبد للخَلق من أكبر الأسباب التي تُنالُ بها رحمةُ الله تعالى.', 'الرحمة مطلوبة لسائر المخلوقات، لكن خص الناس بالذكر اهتمامًا بهم.
الله هو الرحيم ويرحم عبادَه الرُّحَماء، فالجزاء من جنس العمل.
الرحمة بالناس تشمل إيصال الخير لهم ودفع الشر عنهم ومعاملتهم بالحسنى.', '---', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5439', false),
(20228, 2, 201, 228, 'hadith', 'عن أبي هريرة رضي الله عنه ، أن رسول الله صلى الله عليه وسلم قال: «إذا صلى أحدكم للناس، فليخفف، فإن فيهم الضعيف والسقيم والكبير. وإذا صلى لنفسه فليطول ما شاء» ((متفق عليه)) . (10)', 'Messenger of Allah (ﷺ) said, "When one of you leads the Salat, he should not prolong it because the congregation includes those who are feeble, ill or old". One version adds: "those who have to attend to work") While offering prayers alone, you may pray as long as you like"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah bepleased with him)', null, 'رياض الصالحين 228', 'Riyad as-Salihin 228', 'ریاض الصالحین 228', null, null, null, null, 'sunnah.com', null, false, null, false),
(20229, 2, 201, 229, 'hadith', 'عن عائشة رضي الله عنها قالت: إن كان رسول الله صلى الله عليه وسلم ليدع العمل، وهو يحب أن يعمل به، خشية أن يعمل به الناس فيفرض عليهم".', 'Messenger of Allah (ﷺ) would sometimes abstain from doing something he wished to do, lest others should follow him and it might become obligatory upon them..', 'عائشة رضي الله عنها', '''Aishah (May Allah bepleased with her)', 'صحيح', 'رياض الصالحين 229', 'Riyad as-Salihin 229', 'ریاض الصالحین 229', 'متفق عليه', 'تذكر عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان يترك العمل وهو يحب أن يفعله، لئلا يعمل به الناس، فيفرض عليهم، فيشق عليهم أو يعجزوا عنه؛ ثم تذكر رضي الله عنها أن النبي صلى الله عليه وسلم لم يكن يصلي صلاة الضُّحى، وحمل العلماء هذا النَّفي على المُدَاومة، أي أنه صلى الله عليه وسلم : كان يصليها في بعض الأوقات، لفضلها ويتركها في بعض الأوقات، خشية أن تفرض على أمَّته، كما ذكرت رضي الله عنها في بداية الحديث.', 'استحباب صلاة الضحى والمداومة عليها مطلقا.
بيان كمال شَفقته -صلى الله عليه وسلم- ورأفته بأُمَّته، فإنه يَخشى أن تفرض عليهم الأحكام ويعجزوا عن القيام بها.
حرص عائشة -رضي الله عنها- على المحافظة على نوافل الطاعات .
أنه -صلى الله عليه وسلم- لا يعلم الغيب؛ وجه ذلك أن خشيته دليل على عدم علمه بما سيكون.
أنه إذا تعارضت المصالح قُدِّم أهمها .', 'لَيَدَعُ العمل : ليترك العمل.
سُبْحَة : السُّبحة: أي الصلاة، والصلاة تُسمى تسبيحا، قال تعالى: { وَسَبّحْ بِحَمْدِ رَبّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ}،[ق: 39].', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/11282', false),
(20230, 2, 201, 230, 'hadith', 'وعنها رضي الله عنها قالت: نهاهم النبي صلى الله عليه وسلم عن الوصال رحمة لهم، فقالوا: إنك تواصل؟ قال: «إني لست كهيئتكم، إني أبيت يطعمني ربي ويسقيني » ((متفق عليه)). معناه يجعل في قوة من أكل وشرب.', 'The Prophet (ﷺ) prohibited his Companions out of mercy for them, from observing continuous fasting without a break. They said: "But you observe fast continuously". He replied, "I am not like you. I spend the night while my Rubb provides me with food and drink"..(This means that Allah has bestowed upon him the power of endurance like that of a person who eats and drinks).', null, '''Aishah (May Allah bepleased with her)', null, 'رياض الصالحين 230', 'Riyad as-Salihin 230', 'ریاض الصالحین 230', null, null, null, null, 'sunnah.com', null, false, null, false),
(20231, 2, 201, 231, 'hadith', 'عن أبي قتادة الحارث بن ربعي رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إني لأقوم إلى الصلاة، وأريد أن أطول فيها ، فأسمع بكاء الصبي، فأتجوز في صلاتي كراهية أن أشق على أمه».', 'Messenger of Allah (ﷺ) said, "I stand up to lead Salat with the intention of prolonging it. Then I hear the crying of an infant and I shorten the Salat lest I should make it burdensome for his mother"..', 'أبي قتادة الحارث بن ربعي رضي الله عنه', 'Abu Qatadah Al-Harith bin Rib''i (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 231', 'Riyad as-Salihin 231', 'ریاض الصالحین 231', 'رواه البخاري', 'أن النبي صلى الله عليه وسلم يدخل في صلاة الجماعة إمامًا وهو يريد أن يطيل فيها، فإذا سمع بكاء الطفل خفف مخافة أن يشق التطويل على أمه؛ لانشغال قلبها بطفلها.', 'شفقة النبي -صلى الله عليه وسلم- على أصحابه، ومراعاة أحوال الكبار والصغار منهم.
حكمة الرسول -صلى الله عليه وسلم- فهو يضع الأمور في مواضعها.
الإمام هو الذي يقدر مقدار الصلاة، وله أن يتحول عن تقديره لعارض.
جواز إحضار الصغار إلى المسجد، وهذا إذا لم يكن إحضارهم مصدر إيذاء للمسجد والمصلين.
جواز حضور النساء إلى المساجد ليصلين مع الجماعة، وهذا ما لم تخرج المرأة على وجه لا يجوز، مثل أن تخرج متعطرة أو متبرجة.', 'الطفل : أي: المولود.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4249', false),
(20232, 2, 201, 232, 'hadith', 'عن جندب بن عبد الله قال: قال رسول الله صلى الله عليه وسلم : «من صلى صلاة الصبح فهو في ذمة الله فلا يطلبنكم الله من ذمته بشيء، فإنه من يطلبه من ذمته بشيء يدركه، ثم يكبه على وجهه في نار جهنم».', 'Messenger of Allah (ﷺ) said, "When anyone offers the Fajr (dawn) prayer, in congregation, he is in the Protection of Allah. So let not Allah call him to account, withdrawing, in any respect, His Protection. Because, He will get hold of him and throw him down on his face in the Hell-fire."', null, 'Jundub bin Abdullah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 232', 'Riyad as-Salihin 232', 'ریاض الصالحین 232', 'رواه مسلم', 'يُخْبِرُ النبيُّ صلى الله عليه وسلم أنَّ مَن صلى الفجر فهو في حِفْظ الله وحراستِه وحمايته، يدافع عنه، وينتصر له.

ثم حَذَّرَ عليه الصلاة والسلام مِن نَقْضِ هذا العهدِ وإبطاله، إما بترك صلاة الفجر، أو بالتعرُّض لمصليها والاعتداء عليه، فإنَّ مَن فَعَلَ ذلك فقد خَرَِقَ هذا الجِوار، واستحق الوعيد الشديد بأن يَطلُبَه الله بما فَرَّطَ في حقه، ومَن يطلبه الله يُدركه، ثم يلقيه على وجهه في النار.', 'بيان أهمية صلاة الفجر وفضيلتها.
التحذير الشديد من التعرض بسوء لمن صلى الفجر.
انتقام الله تعالى ممن يتعرض لعباده الصالحين.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5435', false),
(20233, 2, 201, 233, 'hadith', 'عن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: «المسلم أخو المسلم، لا يظلمه، ولايسلمه، من كان في حاجة أخيه كان الله في حاجته، ومن فرج عن مسلم كربة فرج الله عنه بها كربة من كرب يوم القيامة، ومن ستر مسلمًا ستره الله يوم القيامة».', 'Messenger of Allah (ﷺ) said, "A Muslim is a brother of another Muslim. So he should not oppress him nor should he hand him over to (his satan or to his self which is inclined to evil). Whoever fulfills the needs of his brother, Allah will fulfill his needs; whoever removes the troubles of his brother, Allah will remove one of his troubles on the Day of Resurrection; and whoever covers up the fault of a Muslim, Allah will cover up his fault on the Day of Resurrection"..', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah bepleased with them)', 'صحيح', 'رياض الصالحين 233', 'Riyad as-Salihin 233', 'ریاض الصالحین 233', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20234, 2, 201, 234, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «المسلم أخو المسلم لا يخونه ولا يكذبه ولا يخذله، كل المسلم على المسلم حرام عرضه وماله ودمه، التقوى ههنا، بحسب امرئ من الشر أن يحقر أخاه المسلم».', 'Messenger of Allah (ﷺ) said, "A Muslim is a brother to a Muslim. He should neither deceive him nor lie to him, nor leave him without assistance. Everything belonging to a Muslim is inviolable for a Muslim; his honour, his blood and property. Piety is here (and he pointed out to his chest thrice). It is enough for a Muslim to commit evil by despising his Muslim brother.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah bepleased with him)', 'حسن', 'رياض الصالحين 234', 'Riyad as-Salihin 234', 'ریاض الصالحین 234', 'رواه الترمذي وقال :حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(20235, 2, 201, 235, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم لا تحاسدوا، ولا تناجشوا، ولا تباغضوا، ولا تدابروا ولا يبع بعضكم على بيع بعض، وكونوا عباد الله إخوانًا. المسلم أخو المسلم: لا يظلمه ولا يحقره، ولا يخذله. التقوى ههنا- ويشير إلى صدره ثلاث مرات- بحسب امرئ من الشر أن يحقر أخاه المسلم كل المسلم على المسلم حرام دمه وماله وعرضه".', 'Messenger of Allah (ﷺ) said, "Do not envy one another; do not inflate prices by overbidding against one another; do not hate one another; do not harbour malice against one another; and do not enter into commercial transaction when others have entered into that (transaction); but be you, O slaves of Allah, as brothers. A Muslim is the brother of another Muslim; he neither oppresses him nor does he look down upon him, nor does he humiliate him. Piety is here, (and he pointed to his chest three times). It is enough evil for a Muslim to hold his brother Muslim in contempt. All things of a Muslim are inviolable for his brother-in-faith: his blood, his property and his honour"..', null, 'Abu Hurairah (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 235', 'Riyad as-Salihin 235', 'ریاض الصالحین 235', 'رواه مسلم', 'أَوْصَى النبيُّ صلى الله عليه وسلم المسلمَ بأخيه المسلم خيرًا، وبيَّن بعض ما يجب عليه من الواجبات والآداب نحوهم؛ ومن ذلك: 

الوصية الأولى: لا تحاسدوا بأن يتمَنَّى بعضكم زوال نعمة بعض. 

الثانية: لا تناجشوا بأن يزيد في ثمن السلعة وهو لا يريد شراءها؛ وإنما يريد نفع البائع، أو الإضرار بالمشتري. 

الثالثة: لا تباغضوا وهي إرادة المضرة وهي ضد المحبة؛ إلا إذا كان البغض في الله تعالى؛ فإنه واجب. 

الرابعة: لا تدابروا بأن يعطِيَ كل واحد منكم أخاه دبره وقفاه فيعرض عنه ويهجره. 

الخامسة: لا يبع بعضكم على بيع بعضٍ بأن يقول لمن اشترى سلعة: عندي مثلها بأقل منها أو أجود منها بسعرها. 

ثم أوصى عليه الصلاة والسلام بوصية جامعة فقال: وكونوا كالإخوة بترك ما ذُكِر من منهيات، وببذل المودة والرفق والشفقة والملاطفة والتعاون في الخير، مع صفاء القلوب والنصيحة بكل حال. 

ومن مقتضيات هذه الأخوة: 

ألّا يَظلم أخاه المسلم ويعتدي عليه. 

وألّا يترك أخاه المسلم يُظلم فيخذله في مقام يستطيع أن ينتصر له، ويرفع عنه الظلم. 

وألّا يحتقره ويستقله وينظر إليه بعين الاستنقاص والازدراء؛ وهو ناتج عن كِبر في القلب.

ثم بيَّن النبيُّ صلى الله عليه وسلم ثلاث مرات أن التقوى في القلب، ومن كان في قلبه التقوى التي تقتضي حسن الخلق، وخشية الله ومراقبته فإنه لا يحتقر مسلمًا، وكافيه من خصال الشر ورذائل الأخلاق احتقار أخيه المسلم؛ وذلك لكِبرٍ في قلبه. 

ثم أَكَّدَ صلى الله عليه وسلم على ما مضى بأنَّ كل المسلم على المسلم حرامٌ: دمُه: بأن يعتدي عليه بقتل أو ما دونه كجرح أو ضرب ونحوها، وكذا ماله: بأن يأخذ منه بغير حق، وكذا عِرضه: بأن يذمّه في نفسه أو حسبه.', 'الأمر بكلِّ ما تقتضيه الأخوة الإيمانية، والنهي عن ما يضادها من الأقوال والأعمال.
عمدة التقوى ما في القلب من معرفة الله، وخشيته ومراقبته، وهذه التقوى ينتج عنها الأعمال الصالحة.
الانحراف الظاهر يدلُّ على ضعف تقوى القلب.
النهي عن أذية المسلم بأي وجه من الوجوه من قول أو فعل.
ليس من الحسد أن يتمنى المسلم أن يكون مثل غيره، دون تمني زوالها عن الآخر، وهذا يسمى غبطة؛ وهي جائزة تعين على المسابقة إلى الخيرات.
الإنسان بطبعه يكره أن يفوقَه أحد في شيء من الفضائل، فإن أحب زوالها عن الآخر فهو الحسد المذموم، وإن أحب المسابقة فهي الغبطة الجائزة.
ليس من بيع المسلم عَلَى بَيْعِ أخيه أن يبيّن للمشتري أنه خدع في شرائه خداعًا فاحشًا؛ فهذا من مقتضيات النصيحة، بشرط أن تكون نيته نصح أخيه المشتري لا الإضرار بالبائع، والأعمال بالنيات.
ليس من بيع المسلم عَلَى بَيْعِ أخيه  إذا كان البائعان لم يتراضيا ولم يستقر الثمن.
ليس من التباغض المنهي عنه في الحديث: البغض في الله، فهو واجب، ومِن أوثق عرى الإيمان.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4706', false),
(20236, 2, 201, 236, 'hadith', 'عن أنس رضي الله عنه صلى الله عليه وسلم قال: « لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه».', 'The Prophet (ﷺ) said, "No one of you shall become a true believer until he desires for his brother what he desires for himself"..', 'أنس رضي الله عنه', 'Anas (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 236', 'Riyad as-Salihin 236', 'ریاض الصالحین 236', 'متفق عليه', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنّه لا يَتَحقّق الإيمانُ الكامل لأحدٍ من المسلمين حتى يُحبَّ لأخيه ما يحب لنفسه من الطاعات وأنواع الخيرات في الدين والدنيا، ويكره له ما يكره لنفسه، فإن رأى في أخيه المسلم نقصًا في دينه، اجتهد في إصلاحه، وإنْ رأى فيه خيرًا سدَّده وأعانه، ونصحَه في أمر دينِه أو دنياه.', 'وجوب محبة المرء لأخيه ما يحبُّ لنفسه؛ لأن نفي الإيمان عمن لا يحب لأخيه ما يحب لنفسه يدل على وجوب ذلك.
الأُخوّة في الله فوق أخوّة النسب، فحقُّها أوجب.
تحريم كل ما ينافي هذه المحبة من الأقوال والأفعال كالغش والغيبة والحسد والعدوان على نفس المسلم أو ماله أو عرضه.
استخدام بعض الألفاظ المحفِّزة على الفعل؛ لقوله "لأخيه".
قال الكِرْماني رحمه الله: ومن الإيمان أيضًا أنْ يُبغِضَ لأخيه ما يبغض لنفسه من الشر، ولم يذكره؛ لأنَّ حب الشيء مستلزم لبغض نقيضه، فترك التنصيص عليه اكتفاء.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4717', false),
(20237, 2, 201, 237, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم: "انصر أخاك ظالمًا أو مظلومًا" فقال رجل: يا رسول الله أنصره إذا كان مظلومًا أرأيت إن كان ظالمًا كيف أنصره؟ قال: "تحجزه -أو تمنعه- من الظلم فإن ذلك نصره".', 'Messenger of Allah (ﷺ) said, "Help your brother, whether he is an oppressor or is oppressed". A man enquired: "O Messenger of Allah! I help him when he is oppressed, but how can I help him when he is an oppressor?" He (ﷺ) said, "You can keep him from committing oppression. That will be your help to him"..', null, 'Anas (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 237', 'Riyad as-Salihin 237', 'ریاض الصالحین 237', 'رواه البخاري', 'أمر النبي صلى الله عليه وسلم المسلمَ بأن ينصر أخاه المسلم سواء كان ظالمًا أو مظلومًا، فقال رجل: 

يا رسول الله، أنصره إذا كان مظلومًا بأن ارفع الظلم عنه، أفرأيت إذا كان ظالمًا كيف تكون نصرتي له؟ 

قال: تنهاه وتأخذ بيديه وتحجزه وتمنعه من الظلم؛ فإن ذلك نصره على شيطانه ونفسه الأمارة بالسوء.', 'التنبيه على حق من حقوق الأخوة الإيمانية بين المسلمين.
الأخذ على يد الظالم، ومنعه من الظلم.
مخالفة الإسلام للمفاهيم الجاهلية، حيث كانوا يتناصرون سواء أكانوا مظلومين أو ظالمين لغيرهم.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4236', false),
(20238, 2, 201, 238, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: "حق المسلم على المسلم خمس: رد السلام، وعيادة المريض، واتباع الجنائز وإجابة الدعوة، وتشميت العاطس" ((متفق عليه)) . و في رواية لمسلم: "حق المسلم على المسلم ست: اذا لقيته فسلم عليه، و اذا دعاك فأجبه، و اذا استنصحك فانصح له، و اذا عطس فحمد الله فشمته، و اذا مرض فعده، و اذا مات فاتبعه."', 'Messenger of Allah (ﷺ) said, "A believer owes another believer five rights: responding to greetings, visiting him in illness, following his funeral, accepting his invitation, and saying ''Yarhamuk-Allah (May Allah have mercy on you),'' when he says ''Al-hamdu lillah (Praise be to Allah)'' after sneezing"..Muslim''s narration is, "There are six rights of a Muslim upon a Muslim: When you meet him, greet him; when he invites you, respond to him; when he seeks counsel, give him advice; when he sneezes and praises Allah, say to him: ''May Allah have mercy on you (Yarhamuk-Allah)''; when he is sick, visit him; and when he dies, follow his funeral".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 238', 'Riyad as-Salihin 238', 'ریاض الصالحین 238', null, 'يُبيِّنُ النبيُّ صلى الله عليه وسلم بعضَ حقوق المسلم على أخيه المسلم:


أول هذه الحقوق: ردُّ السلام لمن ألقى عليك السلام.

الحق الثاني: عيادة المريض وزيارته.

 الحق الثالث: اتباع الجنازة من بيته إلى المصلَّى إلى المقبرة حتى تُدفن.

 الحق الرابع: إجابة الدعوة إذا دعاه إلى وليمة عرس وغير ذلك.

 الحق الخامس: تَشميت العاطس، وهو أن يقول له إذا حَمِدَ الله: يرحمُك الله، ثم يقول العاطسُ: يهديكم الله ويُصلح بالَكم.', 'عظمة الإسلام في تأكيد الحقوق بين المسلمين وتوثيق الأُخوَّة والمحبة بينهم.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3706', false),
(20239, 2, 201, 239, 'hadith', 'عن أبي عمارة البراء بن عازب رضي الله عنهما قال: أمرنا رسول الله r بسبع، ونهانا عن سبع: أمرنا بعيادة المريض، واتباع الجنازة، وتشميت العاطس، وإبرار المقسم، ونصر المظلوم، وإجابة الداعي، وإفشاء السلام. ونهانا عن خواتيم أو تختم بالذهب ، وعن شرب بالفضة، وعن المياثر الحمر، وعن القسي، وعن لبس الحرير والإستبرق والديباج.', 'The Prophet (ﷺ) commanded us to observe seven things and forbade us seven. He ordered us to visit the sick; to follow funeral processions; to respond to a sneezer with ''Yarhamuk-Allah (May Allah have mercy on you)'' when he says ''Al-hamdu lillah (Praise be to Allah),'' to help the oppressed and to help others to fulfill their oaths, to accept invitation and to promote greeting. He forbade us to wear gold rings, to drink in silver utensils, to use Mayathir (silk carpets placed on saddles), to wear Al-Qassiy (a kind of silk cloth), and to wear fine silk brocade..', 'أبي عمارة البراء بن عازب رضي الله عنهما', 'Al-Bara'' bin ''Azib (May Allah bepleased with them)', 'صحيح', 'رياض الصالحين 239', 'Riyad as-Salihin 239', 'ریاض الصالحین 239', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20240, 2, 201, 240, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «لا يستر عبد عبدًا في الدنيا إلا ستره الله يوم القيامة».', 'The Prophet (ﷺ) said, "Allah will cover up on the Day of Resurrection the defects (faults) of the one who covers up the faults of the others in this world"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 240', 'Riyad as-Salihin 240', 'ریاض الصالحین 240', 'رواه مسلم', 'يُبَيِّنُ النبيُّ صلى الله عليه وسلم أنه لا يَستر مسلمٌ أخاه المسلم في أمر من الأمور، إلا سَتره الله عز وجل يوم القيامة؛ فالجزاء من جنس العمل، ويكون سِتْرُ اللهِ له بستر عيوبه ومعاصيه عن إذاعتها على أهل المحشر، وقد يكون بترك محاسبته عليها وذكرها له.', 'مشروعية السِّتْر على المسلم إذا فَعَلَ معصية، مع الإنكار عليه، والنصيحة له، وتخويفه بالله، أما إذا كان من أهل الشر والفساد المجاهرين بالمعاصي والفسق، فإنه لا ينبغي الستر عليهم؛ لأن الستر عليهم يُجَرِّئُهم على المعاصي، وإنما يُرْفَع أمرُه إلى ولاة الأمور، ولو كان في هذا ذكر له؛ لأنه مُعْلِن بفسقه ومعصيته.
الترغيب في ستر أخطاء الآخرين.
من فوائد الستر: إتاحة الفرصة للمذنب أن يراجِعَ نفسه ويتوب إلى الله؛ لأن إعلان العيوب والعورات من إشاعة الفاحشة، ويُفسِد الجَوَّ الاجتماعي، ويُغْرِي الناس بارتكابها.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3777', false)
